INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(4, 2, 'من نحن', '&lt;p&gt;\r\n	هذا النص يمكن ان يستبدل بنص اخر في نفس المساحة لقد تم توليد هذا&amp;nbsp; النص من مولد النص العربي , هذا النص هو مثال لنص يمكن ان يستبدل&lt;/p&gt;\r\n', 'من نحن', '', ''),
(5, 2, 'اتفاقية استخدام الموقع', '&lt;p&gt;\r\n	اتفاقية استخدام الموقع&lt;/p&gt;\r\n', 'اتفاقية استخدام الموقع', '', ''),
(5, 1, 'Terms of Use', '&lt;p&gt;\r\n	Terms of Use&lt;/p&gt;\r\n', 'Terms of Use', '', ''),
(3, 2, ' الخصوصية  ', '&lt;p&gt;&lt;span style=&quot;color: rgb(102, 102, 102); font-family: Tahoma, Geneva, sans-serif; font-size: 14px;&quot;&gt;الخصوصيّة والسريّة : إنّ موقعنا يحترم خصوصيّتك ويسعى لحماية بياناتك الشخصية. إن حماية بياناتك أمرٌ هامٌ جدًّا بالنسبة إلينا . يمكنك تصفح الموقع دون الحاجة إلى تقديم أيّة بيانات شخصيّة. وتبقى هويّتك الشخصية مجهولة طيلة زيارتك للموقع ولا يتم كشفها إلا إذا كنتَ تملك حسابًا إلكترونياً خاصًا على الموقع تدخل إليه بواسطة اسم المستخدم وكلمة السرّ.&lt;/span&gt;&lt;br&gt;&lt;/p&gt;\r\n', ' الخصوصية  الموقع', '', ''),
(4, 1, 'About Us', 'This text can be replaced by another text in the same space. This text was generated from the Arabic text generator. This text is an example of a text that can be replaced', 'About Us', '', ''),
(36, 1, 'Help', '&lt;p&gt;Help&lt;br&gt;&lt;/p&gt;', 'Help', '', ''),
(36, 2, 'مساعدة', '&lt;p&gt;مساعدة&lt;br&gt;&lt;/p&gt;', 'مساعدة', '', ''),
(3, 1, '   Privacy Policy ', '&lt;p&gt;&lt;span style=&quot;color: rgb(102, 102, 102); font-family: Tahoma, Geneva, sans-serif; font-size: 14px;&quot;&gt;Privacy and Confidentiality:&amp;nbsp; Our site respects your privacy and seeks to protect your personal data. To learn more, please read our privacy policy below. This privacy policy describes how we collect and use your personal data (under certain circumstances). It also mentions the procedures to ensure the privacy of your information. Finally, this policy outlines the options available to you regarding the collection, use and disclosure of personal data. By visiting the site directly or through another site, you agree to the practices described in this policy. Protecting your data is very important to us. Your name and other information about you is used in accordance with the privacy policy. We will collect information when necessary or if it is directly related to our transactions with you. We will retain your data in accordance with the law or use it for the purposes for which it was collected. You can browse the site without having to provide any personal data. Your personal identity remains anonymous throughout your visit to the site and is not disclosed unless you have a private online account accessed by username and password.&lt;/span&gt;&lt;br&gt;&lt;/p&gt;\r\n', 'Privacy Policy', '', '');
