INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(1, 3, 'letscms-fixoc3installer', 'letscms-fixoc3installer', 'letscms', '1.0', 'http://www.letscms.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n  <id>letscms-fixoc3installer</id>\n  <name>letscms-fixoc3installer</name>\n  <code>letscms-fixoc3installer</code>\n  <version>1.0</version>\n  <author>letscms</author>\n  <link>http://www.letscms.com</link>\n\n  <file path=\"admin/controller/marketplace/install.php\">\n  \n    <operation>\n      <search><![CDATA[$safe = false;]]></search>\n      <add position=\"replace\"><![CDATA[$safe = true;]]></add>\n    </operation>\n    \n    <operation>\n      <search><![CDATA[if (is_dir($file) && !is_dir($path)) {]]></search>\n      <add position=\"before\"><![CDATA[		\n        if ($path == \'\') {\n          $path = DIR_CATALOG . \'../\' . $destination;\n        }\n      ]]></add>\n    </operation>\n    \n    <operation>\n      <search><![CDATA[\'system/library/\',]]></search>\n      <add position=\"after\"><![CDATA[\'catalog/\',\n		  \'amin/\',\n		  \'image/\',]]></add>\n    </operation>\n    \n    \n  </file>\n  \n</modification>\n', 1, '2020-03-25 15:59:06'),
(2, 7, 'TMD News Letter', '#NLM', 'TMD(opencartextensions.in)', '1.0', 'http://opencartextensions.in/', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n	<name>TMD News Letter</name>\n	<id>TMD Newsletter</id>\n	<code>#NLM</code>\n	<version>1.0</version>\n	<author>TMD(opencartextensions.in)</author>\n	<link>http://opencartextensions.in/</link>\n	\n<file path=\"catalog/controller/common/footer.php\">\n		<operation error=\"log\">\n			<search><![CDATA[return $this->load->view(\'common/footer\', $data);\n]]></search>\n			<add position=\"before\"><![CDATA[\n				//newsletter 7-5-2019 code start\n			$data[\'tmdnewsletter\'] = $this->load->controller(\'extension/newsletter_popup\');\n\n		//newsletter 7-5-2019 code end\n	\n		]]></add>\n		</operation>\n	</file>\n\n	\n\n    <file path=\"catalog/view/theme/*/template/common/footer.twig\">\n		<operation error=\"skip\">\n			<search ><![CDATA[<footer>]]></search>\n			<add position=\"after\"><![CDATA[\n            <!--newsletter 7-5-2019 code start-->\n			    {{ tmdnewsletter }}\n            <!--newsletter 7-5-2019 code end-->]]></add>\n		</operation>\n        <operation error=\"skip\">\n			<search ><![CDATA[<div id=\"footer\">]]></search>\n			<add position=\"after\"><![CDATA[\n                <!--newsletter 7-5-2019 code start-->\n                  {{ tmdnewsletter }}\n                <!--newsletter 7-5-2019 code end-->\n			]]></add>\n		</operation>\n        <operation error=\"skip\">\n			<search ><![CDATA[</footer>]]></search>\n			<add position=\"after\"><![CDATA[\n                <link href=\"catalog/view/theme/default/stylesheet/newsletter.css\" rel=\"stylesheet\">\n                <style>\n                    footer{padding-top:0px;}\n                </style>\n			]]></add>\n		</operation>\n        <operation error=\"skip\">\n			<search ><![CDATA[<footer class=\"top-row\">]]></search>\n			<add position=\"after\"><![CDATA[\n                <!--newsletter 7-5-2019 code start-->\n                  {{ tmdnewsletter }}\n                <!--newsletter 7-5-2019 code end-->\n                <link href=\"catalog/view/theme/default/stylesheet/newsletter.css\" rel=\"stylesheet\">\n			]]></add>\n		</operation>\n	</file>\n\n	<file path=\"admin/controller/common/column_left.php\">\n		<operation error=\"log\">\n			<search><![CDATA[$design = array();]]></search>\n			<add position=\"before\"><![CDATA[\n\n			\n			//newsletter code start\n			\n			//newsletter\n			$newsletter = array();\n			\n			if ($this->user->hasPermission(\'access\', \'extension/module/tmdnewsletter\')) {\n				$newsletter[] = array(\n					\'name\'	   => $this->language->get(\'text_newslettersetting\'),\n					\'href\'     => $this->url->link(\'extension/module/tmdnewsletter\', \'user_token=\' . $this->session->data[\'user_token\'], true),\n					\'children\' => array()		\n				);\n			}	\n			\n			if ($this->user->hasPermission(\'access\', \'extension/subscriber\')) {\n				$newsletter[] = array(\n					\'name\'	   => $this->language->get(\'text_subscriber\'),\n					\'href\'     => $this->url->link(\'extension/subscriber\', \'user_token=\' . $this->session->data[\'user_token\'], true),\n					\'children\' => array()		\n				);\n			}\n\n			if ($this->user->hasPermission(\'access\', \'extension/mail\')) {\n				$newsletter[] = array(\n					\'name\'	   => $this->language->get(\'text_mailtemplate\'),\n					\'href\'     => $this->url->link(\'extension/mail\', \'user_token=\' . $this->session->data[\'user_token\'], true),\n					\'children\' => array()		\n				);\n			}\n			if ($this->user->hasPermission(\'access\', \'extension/quickemail\')) {\n				$newsletter[] = array(\n					\'name\'	   => $this->language->get(\'text_quickmail\'),\n					\'href\'     => $this->url->link(\'extension/quickemail\', \'user_token=\' . $this->session->data[\'user_token\'], true),\n					\'children\' => array()		\n				);\n			}\n			if ($this->user->hasPermission(\'access\', \'extension/newsletter_analytics\')) {\n				$newsletter[] = array(\n					\'name\'	   => $this->language->get(\'text_analytics\'),\n					\'href\'     => $this->url->link(\'extension/newsletter_analytics\', \'user_token=\' . $this->session->data[\'user_token\'], true),\n					\'children\' => array()		\n				);\n			}\n\n			\n			if ($newsletter) {\n				$data[\'menus\'][] = array(\n					\'id\'       => \'menu-newsletter\',\n					\'icon\'	   => \'fa fa-envelope fw\', \n					\'name\'	   => $this->language->get(\'text_newsletter\'),\n					\'href\'     => \'\',\n					\'children\' => $newsletter\n				);	\n			}\n			//newsletter code end\n		]]></add>\n		</operation>\n	</file>\n\n\n	<file path=\"admin/language/*/common/column_left.php\">\n		<operation error=\"skip\">\n			<search ><![CDATA[// Text]]></search>\n			<add position=\"after\"><![CDATA[\n            //newsletter code start\n			$_[\'text_subscriber\']              = \'Subscriber List\'; \n			$_[\'text_newsletter\']              = \'Newsletter\'; \n			$_[\'text_newslettersetting\']              = \'Newsletter Setting\'; \n			$_[\'text_mailtemplate\']              = \'Mail Template\'; \n			$_[\'text_quickmail\']              = \'Quick Send Mail\'; \n			$_[\'text_analytics\']              = \'Analytics\'; \n			//newsletter code end \n			]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/model/account/customer.php\">\n		<operation error=\"skip\">\n			<search ><![CDATA[if ($customer_group_info[\'approval\']) {]]></search>\n			<add position=\"before\"><![CDATA[\n            //newsletter code start\n			if(!empty($data[\'newsletter\'])){\n			$data[\'name\']=\'\';\n			if(isset($data[\'firstname\']))\n			{\n			$data[\'name\']=$data[\'firstname\'];\n			}\n			$this->load->model(\'extension/tmdnewsletter\');\n			$this->model_extension_tmdnewsletter->addSubscriber($data);\n			}			\n			//newsletter code end \n			]]></add>\n		</operation>\n		<operation error=\"skip\">\n			<search ><![CDATA[public function editNewsletter($newsletter) {]]></search>\n			<add position=\"after\"><![CDATA[\n            //newsletter code start\n			if(!empty($newsletter)){\n				$query=$this->db->query(\"select email from \" . DB_PREFIX . \"newsletter_subscribe where  email = \'\" .$this->customer->getEmail() . \"\'\");\n				if(empty($query->row[\'email\'])){\n				$data[\'name\']=$this->customer->getFirstName();\n				$data[\'email\']=$this->customer->getEmail();\n				\n				$this->load->model(\'extension/tmdnewsletter\');\n				$this->model_extension_tmdnewsletter->addSubscriber($data);\n			}else{\n			$query = $this->db->query(\"update \" . DB_PREFIX . \"newsletter_subscribe  set  status=\'2\' where  email = \'\" .$this->customer->getEmail() . \"\'\");\n			}\n			\n			}\n		    else{\n			\n			$query = $this->db->query(\"update \" . DB_PREFIX . \"newsletter_subscribe  set  status=\'2\'   where  email = \'\" .$this->customer->getEmail() . \"\'\");\n			}\n			//newsletter code end \n			]]></add>\n		</operation>\n	</file>\n</modification>', 1, '2021-07-05 16:32:35'),
(3, 8, 'Marketplace 1', 'Webkul Marketplace 1', 'Webkul', '2.0.0', 'http://webkul.com', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<modification>\r\n  <name>Marketplace 1</name>\r\n  <version>2.0.0</version>\r\n  <code>Webkul Marketplace 1</code>\r\n  <author>Webkul</author>\r\n  <link>http://webkul.com</link>\r\n\r\n  <file path=\"admin/controller/common/column_left.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        // Catalog\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        // marketplace code starts here\r\n\r\n        $marketplace = $this->load->controller(\'extension/module/marketplace/adminmenu\');\r\n\r\n        if ($marketplace) {\r\n						$data[\'menus\'][] = array(\r\n								\'id\'       => \'menu-marketplace\',\r\n								\'icon\'     => \'fa-users\',\r\n								\'name\'     => $this->language->get(\'text_marketplace\'),\r\n								\'href\'     => \'\',\r\n								\'children\' => $marketplace\r\n						);\r\n				}\r\n        // marketplace code ends here\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <!-- delete product from seller table if admin delete product -->\r\n  <file path=\"admin/model/catalog/product.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->db->query(\"DELETE FROM \" . DB_PREFIX . \"review WHERE product_id = \'\" . (int)$product_id . \"\'\");\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n        /**\r\n         * Marketplace code starts here\r\n         */\r\n        if ($this->config->get(\'module_marketplace_status\')) {\r\n            $this->db->query(\"DELETE FROM \" . DB_PREFIX . \"customerpartner_to_product WHERE product_id = \'\" . (int)$product_id . \"\'\");\r\n            //commented because it\'s also important for order\r\n            //$this->db->query(\"DELETE FROM \" . DB_PREFIX . \"customerpartner_sold_tracking WHERE product_id = \'\" . (int)$product_id . \"\'\");\r\n        }\r\n        /**\r\n         * Marketplace code Ends here\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        public function editProduct($product_id, $data) {\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n        /**\r\n         * Marketplace\r\n         */\r\n        if ($this->config->get(\'module_marketplace_status\')) {\r\n            $checkSellerProduct = $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"customerpartner_to_product WHERE product_id = \'\" . (int)$product_id.\"\' ORDER BY id ASC\")->row;\r\n            if ($checkSellerProduct) {\r\n                $updatePrice = $this->currency->convert($data[\'price\'],$this->config->get(\'config_currency\'),$checkSellerProduct[\'currency_code\']);\r\n\r\n                $this->db->query(\"UPDATE \" . DB_PREFIX . \"customerpartner_to_product SET price = \'\".(float)$data[\'price\'].\"\',seller_price = \'\".(float)$updatePrice.\"\'  WHERE product_id = \'\".$product_id.\"\' ORDER BY id ASC\");\r\n            }\r\n        }\r\n        /**\r\n         * Marketplace\r\n         */\r\n        ]]></add>\r\n    </operation>\r\n  </file>\r\n  <!--  display seller name with product in order info and after edit   -->\r\n  <file path=\"admin/controller/sale/order.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        $data[\'products\'][] = array(\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        /**\r\n         * Marketplace code starts here\r\n         */\r\n        if ($this->config->get(\'module_marketplace_status\')) {\r\n\r\n            $seller_details = $this->db->query(\"SELECT c.customer_id,CONCAT(c.firstname,\' \',c.lastname) name,c.email FROM \".DB_PREFIX.\"customerpartner_to_product c2p LEFT JOIN \".DB_PREFIX.\"customer c ON (c2p.customer_id = c.customer_id) WHERE c2p.product_id = \'\".(int)$product[\'product_id\'].\"\'\")->row;\r\n\r\n            if($seller_details AND isset($seller_details[\'name\']) AND $seller_details[\'name\'])\r\n              $product[\'name\'] = $product[\'name\'].\'</a> by Seller <a href=\"\'.$this->url->link(\'customerpartner/partner\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&view_all=1&filter_email=\' . $seller_details[\'email\'], true).\'\"><b>\'.$seller_details[\'name\'].\'</b></a>\';\r\n\r\n          }\r\n        /**\r\n         * Marketplace code ends here\r\n         */\r\n\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $data[\'order_products\'][] = array(\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        /**\r\n         * Marketplace code starts here\r\n         */\r\n        if ($this->config->get(\'module_marketplace_status\')) {\r\n            $seller_details = $this->db->query(\"SELECT c.customer_id,CONCAT(c.firstname,\' \',c.lastname) name,c.email FROM \".DB_PREFIX.\"customerpartner_to_product c2p LEFT JOIN \".DB_PREFIX.\"customer c ON (c2p.customer_id = c.customer_id) WHERE c2p.product_id = \'\".(int)$product[\'product_id\'].\"\'\")->row;\r\n\r\n            if($seller_details AND isset($seller_details[\'name\']) AND $seller_details[\'name\'])\r\n              $product[\'name\'] = $product[\'name\'].\' by Seller <b>\'.$seller_details[\'name\'].\'</b>\';\r\n         }\r\n        /**\r\n         * Marketplace code ends here\r\n         */\r\n\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n  <!-- code for custom field -->\r\n  <file path=\"admin/view/template/catalog/product_form.twig\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        <li><a href=\"#tab-design\" data-toggle=\"tab\">{{ tab_design }}</a></li>\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        <!-- Marketplace customfield -->\r\n        {% if module_marketplace_status is defined and module_marketplace_status %}\r\n          <li><a href=\"#tab-custom-field\" data-toggle=\"tab\">{{ \"Custom field\" }}</a></li>\r\n        {% endif %}\r\n        <!-- Marketplace customfield -->\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        <div class=\"tab-pane\" id=\"tab-design\">\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        {{ mpcustomfield }}\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"admin/controller/catalog/category.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->response->redirect($this->url->link(\'catalog/category\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\r\n      ]]></search>\r\n      <add position=\"replace\"><![CDATA[\r\n        if ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'mpcheck\'])) {\r\n            $this->response->redirect($this->url->link(\'customerpartner/sellercategory\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\r\n        } else {\r\n            $this->response->redirect($this->url->link(\'catalog/category\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\r\n        }\r\n      ]]></add>\r\n    </operation>\r\n\r\n    <operation>\r\n      <search><![CDATA[\r\n        $data[\'action\'] = $this->url->link(\'catalog/category/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&category_id=\' . $this->request->get[\'category_id\'] . $url, true);\r\n      ]]></search>\r\n      <add position=\"replace\"><![CDATA[\r\n        if (isset($this->request->get[\'mpcheck\']) && $this->request->get[\'mpcheck\']) {\r\n          $data[\'action\'] = $this->url->link(\'catalog/category/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&mpcheck=1&category_id=\' . $this->request->get[\'category_id\'] . $url, true);\r\n        } else {\r\n          $data[\'action\'] = $this->url->link(\'catalog/category/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&category_id=\' . $this->request->get[\'category_id\'] . $url, true);\r\n        }\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"admin/controller/catalog/product.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->response->setOutput($this->load->view(\'catalog/product_form\', $data));\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        /**\r\n         * Marketplace Code Starts Here\r\n         */\r\n        if($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'product_id\'])){\r\n            $data[\'product_id_text\'] = \'&product_id=\'.$this->request->get[\'product_id\'];\r\n        }else{\r\n            $data[\'product_id_text\'] = \'\';\r\n        }\r\n\r\n        if($this->config->get(\'module_marketplace_status\')){\r\n            $data[\'module_marketplace_status\'] = true;\r\n        }else{\r\n            $data[\'module_marketplace_status\'] = false;\r\n        }\r\n\r\n        /**\r\n         * Marketplace Code Ends Here\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->response->redirect($this->url->link(\'catalog/product\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\r\n      ]]></search>\r\n      <add position=\"replace\"><![CDATA[\r\n        /**\r\n         * Marketplace Code Starts Here\r\n         */\r\n        if ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'mpcheck\'])) {\r\n            $this->response->redirect($this->url->link(\'customerpartner/product\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\r\n        } else {\r\n            $this->response->redirect($this->url->link(\'catalog/product\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\r\n        }\r\n         /**\r\n         * Marketplace Code Ends Here\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $data[\'cancel\'] = $this->url->link(\'catalog/product\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n        /**\r\n         * Marketplace Code Starts Here\r\n         */\r\n        if ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'mpcheck\'])) {\r\n            if (!isset($this->request->get[\'product_id\'])) {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/add\', \'user_token=\' . $this->session->data[\'user_token\'] . $url . \'&mpcheck=1\', true);\r\n            } else {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&mpcheck=1&product_id=\' . $this->request->get[\'product_id\'] . $url, true);\r\n            }\r\n\r\n            $data[\'cancel\'] = $this->url->link(\'customerpartner/product\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\r\n        } else {\r\n            if (!isset($this->request->get[\'product_id\'])) {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/add\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\r\n            } else {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&product_id=\' . $this->request->get[\'product_id\'] . $url, true);\r\n            }\r\n\r\n            $data[\'cancel\'] = $this->url->link(\'catalog/product\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\r\n        }\r\n        if ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'topsearch\'])) {\r\n            if (!isset($this->request->get[\'product_id\'])) {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/add\', \'user_token=\' . $this->session->data[\'user_token\'] . $url . \'&mpcheck=1\', true);\r\n            } else {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&mpcheck=1&product_id=\' . $this->request->get[\'product_id\'] . $url, true);\r\n            }\r\n            $data[\'cancel\'] = $this->url->link(\'customerpartner/topsearch\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\r\n        } else {\r\n            if (!isset($this->request->get[\'product_id\'])) {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/add\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\r\n            } else {\r\n                $data[\'action\'] = $this->url->link(\'catalog/product/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&product_id=\' . $this->request->get[\'product_id\'] . $url, true);\r\n            }\r\n            $data[\'cancel\'] = $this->url->link(\'catalog/product\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\r\n        }\r\n         /**\r\n         * Marketplace Code Ends Here\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->model_catalog_product->editProduct($this->request->get[\'product_id\'], $this->request->post);\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        if($this->config->get(\'module_marketplace_status\')) {\r\n                $this->load->model(\"wkcustomfield/wkcustomfield\");\r\n                $wkcustomFields = array();\r\n                if(isset($this->request->post[\'product_custom_field\'])){\r\n                    $data = $this->request->post[\'product_custom_field\'];\r\n                }else{\r\n                    $data = \'\';\r\n                }\r\n                $this->model_wkcustomfield_wkcustomfield->editCustomFields($data,$this->request->get[\'product_id\']);\r\n        }\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->model_catalog_product->addProduct($this->request->post);\r\n      ]]></search>\r\n      <add position=\"replace\"><![CDATA[\r\n          /**\r\n           * Marketplace Code Starts Here\r\n           */\r\n          if($this->config->get(\'module_marketplace_status\')) {\r\n                  $product_id = $this->model_catalog_product->addProduct($this->request->post);\r\n                  $this->load->model(\"wkcustomfield/wkcustomfield\");\r\n                  $wkcustomFields = array();\r\n                  if(isset($this->request->post[\'product_custom_field\'])){\r\n                      $this->model_wkcustomfield_wkcustomfield->addCustomFields($this->request->post[\'product_custom_field\'],$product_id);\r\n                  }\r\n          }else{\r\n              $this->model_catalog_product->addProduct($this->request->post);\r\n          }\r\n          /**\r\n           * Marketplace Code Ends Here\r\n           */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->load->model(\'design/layout\');\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        /**Marketplace Code Starts Here\r\n         * customfield\r\n         */\r\n\r\n         $data[\'mpcustomfield\'] = $this->load->controller(\'extension/module/marketplace/customfield\');\r\n\r\n        /**Marketplace Code Ends Here\r\n         * customfield\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        if ($this->error && !isset($this->error[\'warning\'])) {\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        /**Marketplace Code Starts Here\r\n         * customfield\r\n         */\r\n        $customfielddata = array();\r\n        if(isset($this->request->post[\'product_custom_field\'])){\r\n            $customfielddata = $this->request->post[\'product_custom_field\'];\r\n        }\r\n        foreach ($customfielddata as $key => $value) {\r\n            if(isset($value[\'custom_field_is_required\']) && (($value[\'custom_field_is_required\'] == \'yes\' && isset($value[\'custom_field_value\']) && $value[\'custom_field_value\'][0] == \'\' ) || ($value[\'custom_field_is_required\'] == \'yes\' && !isset($value[\'custom_field_value\'])))) {\r\n                $this->error[\'customFieldError\'][] = $value[\'custom_field_id\'];\r\n            }\r\n        }\r\n        if(isset($this->error[\'customFieldError\'])) {\r\n            $this->error[\'warning\'] = $this->language->get(\'error_warning\');\r\n        }\r\n\r\n        /**Marketplace Code Ends Here\r\n         * customfield\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n  <!-- Sell Link in header -->\r\n  <file path=\"catalog/controller/common/header.php\">\r\n    <operation>\r\n      <search>\r\n        <![CDATA[\r\n        $this->load->language(\'common/header\');\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        $data[\'notification\'] = \'\';\r\n        $data[\'sellmenu\'] =  $this->load->controller(\'extension/module/marketplace/sellmenu\');\r\n        $this->load->model(\'account/customerpartner\');\r\n        $data[\'module_marketplace_status\'] = $this->config->get(\'module_marketplace_status\');\r\n        if($this->config->get(\'module_marketplace_status\')){\r\n    				$data[\'chkIsPartner\'] = $this->model_account_customerpartner->chkIsPartner();\r\n    				$data[\'marketplace_seller_mode\'] = isset($this->session->data[\'marketplace_seller_mode\']) ? $this->session->data[\'marketplace_seller_mode\'] : 1;\r\n    				if ($data[\'chkIsPartner\'] && $data[\'marketplace_seller_mode\']) {\r\n    					$data[\'notification\'] = $this->load->controller(\'account/customerpartner/notification/notifications\');\r\n\r\n    					$data[\'notification_total\'] = $this->model_account_notification->getTotalSellerActivity() + $this->model_account_notification->getSellerProductActivityTotal() + $this->model_account_notification->getSellerReviewsTotal()-$this->model_account_notification->getViewedNotifications();\r\n    				}\r\n    		}\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"catalog/view/theme/*/template/common/header.twig\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        <head>\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n      {% if module_marketplace_status is defined and module_marketplace_status %}\r\n      <script>\r\n        (function(i,s,o,g,r,a,m){i[\'GoogleAnalyticsObject\'] = r;i[r]=i[r]||function(){\r\n          (i[r].q=i[r].q||[]).push(arguments)},i[r].l=1*new Date();a=s.createElement(o),\r\n          m=s.getElementsByTagName(o)[0];a.async=1;a.src=g;m.parentNode.insertBefore(a,m)\r\n          })(window,document,\'script\',\'https://www.google-analytics.com/analytics.js\',\'ga\');\r\n      </script>\r\n      {% endif %}\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n          </head>\r\n      ]]></search>\r\n      <add position=\"before\">\r\n        <![CDATA[\r\n        <link href=\"https://gitcdn.github.io/bootstrap-toggle/2.2.2/css/bootstrap-toggle.min.css\" type=\"text/css\" rel=\"stylesheet\" media=\"screen\" />\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n          </head>\r\n      ]]></search>\r\n      <add position=\"after\" offset=\"1\"><![CDATA[\r\n          {% if notification is defined and notification %} {{ notification }} {% endif %}\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n          <li class=\"dropdown\"><a href=\"{{ account }}\"\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n       \r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n    <search><![CDATA[\r\n    <link href=\"catalog/view/javascript/bootstrap/css/bootstrap.min.css\" rel=\"stylesheet\" media=\"screen\" />\r\n    ]]></search>\r\n    <add position=\'before\'><![CDATA[\r\n    {% if (direction is defined and direction == \'rtl\') %}\r\n            <link \r\n  rel=\"stylesheet\"\r\n  href=\"https://cdn.rtlcss.com/bootstrap/3.3.7/css/bootstrap.min.css\"\r\n  integrity=\"sha384-cSfiDrYfMj9eYCidq//oGXEkMc0vuTxHXizrMOFAaPsLt1zoCUVnSsURN+nef1lj\"\r\n  crossorigin=\"anonymous\">\r\n<!-- compiled and minified theme CSS -->\r\n<link\r\n  rel=\"stylesheet\"\r\n  href=\"https://cdn.rtlcss.com/bootstrap/3.3.7/css/bootstrap-theme.min.css\"\r\n  integrity=\"sha384-YNPmfeOM29goUYCxqyaDVPToebWWQrHk0e3QYEs7Ovg6r5hSRKr73uQ69DkzT1LH\"\r\n  crossorigin=\"anonymous\">\r\n\r\n<!-- compiled and minified JavaScript -->\r\n<script\r\n  src=\"https://cdn.rtlcss.com/bootstrap/3.3.7/js/bootstrap.min.js\"\r\n  integrity=\"sha384-B4D+9otHJ5PJZQbqWyDHJc6z6st5fX3r680CYa0Em9AUG6jqu5t473Y+1CTZQWZv\"\r\n  crossorigin=\"anonymous\"></script>\r\n\r\n            {% else %}\r\n    ]]></add>\r\n    </operation>\r\n    <operation>\r\n    <search><![CDATA[\r\n    <script src=\"catalog/view/javascript/bootstrap/js/bootstrap.min.js\" type=\"text/javascript\"></script>\r\n    ]]></search>\r\n    <add position=\'after\'><![CDATA[\r\n    {% endif %}\r\n    ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"catalog/controller/account/seller.php\">\r\n  <operation>\r\n      <search><![CDATA[\r\n        $data[\'column_left\'] = $this->load->controller(\'common/column_left\');\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n                $data[\'marketplace_becomepartnerregistration\'] = false;\r\n       $data[\'marketplace_status\'] = false;\r\n        if($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_becomepartnerregistration\')){\r\n            $data[\'marketplace_becomepartnerregistration\'] = $this->config->get(\'marketplace_becomepartnerregistration\');\r\n            $data[\'marketplace_status\'] = $this->config->get(\'marketplace_status\');\r\n            $this->language->load(\'account/customerpartner/become_partner\');\r\n\r\n            $data[\'text_register_becomePartner\'] = $this->language->get(\'text_register_becomePartner\');\r\n            $data[\'text_register_douwant\'] = $this->language->get(\'text_register_douwant\');\r\n            $data[\'text_shop_name\'] = $this->language->get(\'text_shop_name\');\r\n            $data[\'text_avaiable\'] = $this->language->get(\'text_avaiable\');\r\n            $data[\'text_no_avaiable\'] = $this->language->get(\'text_no_avaiable\');\r\n\r\n            if (isset($this->request->post[\'shoppartner\'])) {\r\n                $data[\'shoppartner\'] = $this->request->post[\'shoppartner\'];\r\n            } else {\r\n                $data[\'shoppartner\'] = \'\';\r\n            }\r\n\r\n            if (isset($this->request->post[\'tobecomepartner\'])) {\r\n                $data[\'tobecomepartner\'] = $this->request->post[\'tobecomepartner\'];\r\n            } else {\r\n                $data[\'tobecomepartner\'] = \'\';\r\n            }\r\n\r\n            if (isset($this->error[\'errshoppartner\'])) {\r\n                $data[\'error_shoppartner\'] = $this->error[\'errshoppartner\'];\r\n            } else {\r\n                $data[\'error_shoppartner\'] = \'\';\r\n            }\r\n\r\n        }\r\n		if ($this->config->get(\'module_marketplace_status\') && $this->config->get(\'module_wk_seller_group_status\') && $this->config->get(\'marketplace_becomepartnerregistration\') && $this->config->get(\'module_wk_seller_group_membership_on_registration\')) {\r\n			$this->load->language(\'account/customerpartner/wk_membership_catalog\');\r\n		$membershipgroups = $this->load->controller(\'account/customerpartner/wk_membership_catalog/getMembershipGroups\');\r\n		  $data[\'group_list\'] = isset($membershipgroups[\'group_list\']) ? $membershipgroups[\'group_list\'] : array();\r\n		  $data[\'button_cart\'] = $this->language->get(\'button_cart\');\r\n		  $data[\'text_view_membership\'] = $this->language->get(\'text_view_membership\');\r\n		  $data[\'register_view\'] = true;\r\n		  $data[\'membership_groups\'] = $this->load->view(\'account/customerpartner/wk_membership_groups\', $data);\r\n		}\r\n      ]]></add>\r\n    </operation>\r\n    <!-- <operation>\r\n      <search><![CDATA[\r\n        $data[\'column_left\'] = $this->load->controller(\'common/column_left\');\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        $data[\'mpregisterseller\'] = $this->load->controller(\'extension/module/marketplace/registerseller\');\r\n      ]]></add>\r\n    </operation> -->\r\n    <operation>\r\n      <search><![CDATA[\r\n        function validate() {\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n        if($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_becomepartnerregistration\') AND isset($this->request->post[\'tobecomepartner\'])){\r\n\r\n            $this->load->language(\'account/customerpartner/become_partner\');\r\n\r\n            if(utf8_strlen($this->request->post[\'shoppartner\'])<=3 && $this->request->post[\'tobecomepartner\']==1){\r\n                $this->error[\'errshoppartner\'] = $this->language->get(\'error_validshop\');\r\n            }else if(utf8_strlen($this->request->post[\'shoppartner\']) >1 && $this->request->post[\'tobecomepartner\']==1){\r\n                $this->load->model(\'customerpartner/master\');\r\n                if($this->model_customerpartner_master->getShopData($this->request->post[\'shoppartner\'])){\r\n                  $this->error[\'errshoppartner\'] = $this->language->get(\'error_noshop\');\r\n                }\r\n            }\r\n\r\n            $this->load->language(\'account/seller\');\r\n        }\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        unset($this->session->data[\'guest\']);\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n            if($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_becomepartnerregistration\')){\r\n                if ($this->request->post[\'tobecomepartner\']==\'1\' && $this->request->post[\'shoppartner\']) {\r\n                    $this->load->model(\'account/customerpartner\');\r\n                    $this->model_account_customerpartner->becomePartner($this->request->post[\'shoppartner\'],0,$customer_id);\r\n                }\r\n            }\r\n\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"catalog/view/theme/*/template/account/seller.twig\">\r\n  <operation>\r\n      <search><![CDATA[\r\n        {% if text_agree %}\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        {% if marketplace_status is defined and marketplace_becomepartnerregistration is defined and marketplace_becomepartnerregistration != null %}\r\n\r\n        <fieldset>\r\n          <legend>{{ text_register_becomePartner }}</legend>\r\n          <div class=\"form-group hide\">\r\n            <label class=\"col-sm-2 control-label\">{{ text_register_douwant }}</label>\r\n            <div class=\"col-sm-10\">\r\n              {% if tobecomepartner is defined %}\r\n              <label class=\"radio-inline\">\r\n                <input type=\"radio\" name=\"tobecomepartner\" value=\"1\" checked=\"checked\" />\r\n                {{ text_yes }}</label>\r\n              <label class=\"radio-inline\">\r\n                <input type=\"radio\" name=\"tobecomepartner\" value=\"0\"  />\r\n                {{ text_no }}</label>\r\n              {% else %}\r\n              <label class=\"radio-inline\">\r\n                <input type=\"radio\" name=\"tobecomepartner\" value=\"1\"  checked=\"checked\"/>\r\n                {{ text_yes }}</label>\r\n              <label class=\"radio-inline\">\r\n                <input type=\"radio\" name=\"tobecomepartner\" value=\"0\" />\r\n                {{ text_no }}</label>\r\n              {% endif %}\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"form-group required\" id=\"fg-shoppartner\">\r\n          <div class = \"row col-md-12\">\r\n            <label class=\"col-sm-2 control-label\" for=\"input-shop\">{{ text_shop_name }}</label>\r\n            <div class=\"col-sm-10\">\r\n              <div class=\"input-group\">\r\n                <span class=\"input-group-addon\"><i class=\"fa fa-search\"></i></span>\r\n                <input type=\"text\" name=\"shoppartner\" value=\"{{ shoppartner }}\" placeholder=\"{{ text_shop_name }}\" id=\"input-shop\" class=\"form-control\" />\r\n              </div>\r\n              {% if error_shoppartner  is defined %}\r\n              <div class=\"text-danger\">{{ error_shoppartner }}</div>\r\n              {% endif %}\r\n            </div>\r\n          </div>\r\n          \r\n         {% if membership_groups is defined  and membership_groups %}\r\n       \r\n            {{ membership_groups }}\r\n         \r\n        {% endif %}\r\n       </div>\r\n        </fieldset>\r\n\r\n        <script>\r\n   \r\n            $( \"#input-shop\" ).change(function() {\r\n              thisshop = this;\r\n              shop = $(thisshop).val();\r\n\r\n              if(shop){\r\n\r\n                jQuery(thisshop).prev().html(\'<i class=\"fa fa-spinner fa-spin\"></i>\');\r\n\r\n                $.ajax({\r\n                       type: \'POST\',\r\n                       data: ({shop: shop}),\r\n                       dataType: \'json\',\r\n                       url: \'index.php?route=customerpartner/sell/wkmpregistation\',\r\n                       success: function(data){\r\n                        $(\'.text-danger\').remove();\r\n                          if(data[\'success\']){\r\n                            jQuery(thisshop).prev().html(\'<span data-toggle=\"tooltip\" class=\"text-success\" title=\"{{ text_avaiable }}\"><i class=\"fa fa-thumbs-o-up\"></i></span>\');\r\n                          }else if(data[\'error\']){\r\n                            jQuery(thisshop).prev().html(\'<span data-toggle=\"tooltip\" class=\"text-danger\" title=\"{{ text_no_avaiable }}\"><i class=\"fa fa-thumbs-o-down\"></i></span>\');\r\n                          }\r\n\r\n                        }\r\n                    });\r\n             } else {\r\n               jQuery(thisshop).prev().html(\'<span data-toggle=\"tooltip\" class=\"text-danger\" title=\"<?php echo $text_no_avaiable; ?>\"><i class=\"fa fa-thumbs-o-down\"></i></span>\');\r\n            }\r\n            });\r\n        </script>\r\n     {% endif %}\r\n      ]]></add>\r\n    </operation>\r\n    <!-- <operation>\r\n      <search><![CDATA[\r\n        {% if text_agree %}\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        {{ mpregisterseller }}\r\n      ]]></add>\r\n    </operation> -->\r\n    <operation>\r\n      <search><![CDATA[\r\n        <div id=\"account-seller\" class=\"container\">\r\n      ]]></search>\r\n      <add position=\"replace\"><![CDATA[\r\n    {{ separate_column_left }}\r\n{% if separate_view is defined and separate_view %}\r\n  <div class=\"container-fluid\" id=\"content\" style=\"margin-left: 18%\">\r\n{% else %}\r\n  <div id=\"account-seller\" class=\"container\">\r\n{% endif %}\r\n\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n  <!-- code for unset session variable on logout for pop-up modal with information -->\r\n  <file path=\"system/library/cart/customer.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        unset($this->session->data[\'customer_id\']);\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n        unset($this->session->data[\'openModal\']);\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n  <!-- send mail to seller after product sold -->\r\n  <file path=\"catalog/model/checkout/order.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->cache->delete(\'product\');\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n            /**\r\n             * Marketplace Code Starts here\r\n             */\r\n\r\n             $order_status_query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"order_status WHERE order_status_id = \'\" . (int)$order_status_id . \"\' AND language_id = \'\" . (int)$order_info[\'language_id\'] . \"\'\");\r\n\r\n       				if ($order_status_query->num_rows) {\r\n       					$order_status = $order_status_query->row[\'name\'];\r\n       				} else {\r\n       					$order_status = \'\';\r\n       				}\r\n\r\n              if ($this->config->get(\'module_marketplace_status\')){\r\n                 $this->load->model(\'account/customerpartnerorder\');\r\n                 $this->model_account_customerpartnerorder->customerpartner($order_info,$order_status, $comment,$order_status_id);\r\n              }\r\n            /**\r\n             * Marketplace Code Ends here\r\n             */\r\n      ]]></add>\r\n    </operation>\r\n\r\n    <operation>\r\n      <search><![CDATA[\r\n        $customer_info = $this->model_account_customer->getCustomer($order_info[\'customer_id\']);\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n            /**\r\n             * Marketplace Code Starts here\r\n             */\r\n                if ($this->config->get(\'module_marketplace_status\')){\r\n                $toAdmin = false;\r\n                if(isset($comment) && $comment) {\r\n                    $get_comment = explode(\'___\',$comment);\r\n                    if($get_comment[0] == \'wk_admin_comment\' ) {\r\n                        $comment = ($get_comment[1]);\r\n                        $toAdmin = true;\r\n                        $this->config->set(\'config_email\',$this->customer->getEmail());\r\n                        if($this->config->get(\'marketplaceadminmail\')) {\r\n                            $order_info[\'email\'] = $this->config->get(\'marketplace_adminmail\');\r\n                        } else {\r\n                            $order_info[\'email\'] = $this->config->get(\'config_email\');\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n            /**\r\n             * Marketplace Code Ends here\r\n             */\r\n      ]]></add>\r\n    </operation>\r\n\r\n    <operation>\r\n      <search><![CDATA[\r\n        $message .= $language->get(\'text_update_order_status\') . \"\\n\\n\";\r\n      ]]></search>\r\n      <add position=\"replace\"><![CDATA[\r\n            /**\r\n             * Marketplace Code Starts here\r\n             */\r\n                    if($this->config->get(\'module_marketplace_status\') && isset($toAdmin) && $toAdmin) {\r\n                        $message .= $language->get(\'text_update_order_status_admin\') . \"\\n\\n\";\r\n                    } else {\r\n                        $message .= $language->get(\'text_update_order_status\') . \"\\n\\n\";\r\n                    }\r\n            /**\r\n             * Marketplace Code Ends here\r\n             */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $message .= $language->get(\'text_update_comment\') . \"\\n\\n\";\r\n      ]]></search>\r\n      <add position=\"replace\"><![CDATA[\r\n        /**\r\n         * Marketplace Code Starts here\r\n         */\r\n                if($this->config->get(\'module_marketplace_status\') && isset($toAdmin) && $toAdmin) {\r\n                    $message .= $language->get(\'text_update_comment_admin\') . \"\\n\\n\";\r\n                } else {\r\n                    $message .= $language->get(\'text_update_comment\') . \"\\n\\n\";\r\n                }\r\n        /**\r\n         * Marketplace Code Ends here\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $message .= $language->get(\'text_update_link\') . \"\\n\";\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n        /**\r\n         * Marketplace Code Starts here\r\n         */\r\n                if($this->config->get(\'module_marketplace_status\') && isset($toAdmin) && !$toAdmin) {\r\n        /**\r\n         * Marketplace Code Ends here\r\n         */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[\r\n        $message .= $language->get(\'text_update_link\') . \"\\n\";\r\n      ]]></search>\r\n      <add position=\"after\" offset=\"1\"><![CDATA[\r\n            /**\r\n             * Marketplace Code Starts here\r\n             */\r\n                    }\r\n            /**\r\n             * Marketplace Code Ends here\r\n             */\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"catalog/language/*/mail/order.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        $_[\'text_update_footer\']        = \'Please reply to this email if you have any questions.\';\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n        $_[\'text_update_order_status_admin\']  = \'Order has been updated to the following status:\';\r\n        $_[\'text_update_comment_admin\']       = \'The comments for above order are:\';\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"catalog/controller/checkout/success.php\">\r\n    <operation>\r\n      <search><![CDATA[\r\n        $this->cart->clear();\r\n      ]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n        if ($this->customer->isLogged()) {\r\n\r\n  			  $this->load->model(\'account/notification\');\r\n\r\n  			  $activity_data = array(\r\n  			    \'customer_id\' => $this->customer->getId(),\r\n  			    \'name\'        => $this->customer->getFirstName() . \' \' . $this->customer->getLastName(),\r\n  			    \'order_id\'    => $this->session->data[\'order_id\']\r\n  			  );\r\n\r\n  			  $this->model_account_notification->addActivity(\'order_account\', $activity_data);\r\n  			}\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n  <!-- end here -->\r\n</modification>\r\n', 0, '2021-07-11 15:41:32');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(4, 9, 'Marketplace 2', 'Webkul Marketplace 2', 'Webkul', '2.0.0', 'http://webkul.com', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<modification>\n  <name>Marketplace 2</name>\n  <version>2.0.0</version>\n  <code>Webkul Marketplace 2</code>\n  <author>Webkul</author>\n  <link>http://webkul.com</link>\n\n  <file path=\"catalog/controller/product/product.php\">\n      <operation>\n              <search><![CDATA[\n              $data[\'tags\'] = array();\n              ]]></search>\n              <add position=\"before\"><![CDATA[\n                if($this->config->get(\'module_marketplace_status\')) {\n\n                                $this->load->model(\'account/customerpartner\');\n\n                                $this->load->language(\'customerpartner/profile\');\n\n                                if(isset($this->request->get[\'product_id\']) && $this->request->get[\'product_id\']) {\n									                $check_seller = $this->model_account_customerpartner->getProductSellerDetails($this->request->get[\'product_id\']);\n								                } else {\n									                $check_seller = array();\n                                }\n\n                                if ($this->config->get(\'wk_custom_shipping_status\') && isset($this->session->data[\'shipping_address\'][\'postcode\'])) {\n\n                                    $seller_id = 0;\n\n                                    if (isset($check_seller[\'customer_id\']) && $check_seller[\'customer_id\']) {\n                                        $seller_id = $check_seller[\'customer_id\'];\n                                    }\n\n                                    $data[\'text_seller_information\'] = $this->language->get(\'text_seller_information\');\n\n                                    $this->load->model(\'customerpartner/information\');\n\n                                    $data[\'informations\'] = array();\n\n                                    $informations = $this->model_customerpartner_information->getSellerInformations($seller_id);\n\n                                    if ($informations) {\n                                      $count = 0;\n\n                                      foreach ($informations as $result) {\n                                        $data[\'informations\'][] = array(\n                                          \'title\' => $result[\'title\'],\n                                          \'href\'  => $this->url->link(\'information/information\', \'information_id=\' . $result[\'information_id\'])\n                                        );\n\n                                        $count++;\n\n                                        if ($count == 3) {\n                                          break;\n                                        }\n                                      }\n                                    }\n\n                                    $weight = 0;\n\n                                    if (isset($product_info[\'weight\']) && $product_info[\'weight\']) {\n                                        $weight = $product_info[\'weight\'];\n                                    }\n\n                                    $max_days = $this->model_account_customerpartner->getMinDays($seller_id,$this->session->data[\'shipping_address\'][\'postcode\'],$weight);\n\n                                    if (isset($max_days[\'max_days\']) && $max_days[\'max_days\']) {\n                                        $date = new DateTime(date(\'Y-m-d\', strtotime(\"+\".$max_days[\'max_days\'].\" days\")));\n\n                                        $data[\'delivery_date\'] = $date->format(\'Y-m-d\');\n\n                                        $data[\'text_delivery_date\'] = $this->language->get(\'text_delivery_date\');\n                                    }\n                                }\n\n                                if(isset($check_seller) && isset($check_seller[\'customer_id\'])) {\n                                  $this->load->model(\'customerpartner/master\');\n									                $partner = $this->model_customerpartner_master->getProfile($check_seller[\'customer_id\']);\n									                if(isset($partner[\'google_analytic_id\']) && $partner[\'google_analytic_id\']) {\n									                 	$data[\'seller_analytic_id\'] = $partner[\'google_analytic_id\'];\n									                } else {\n										                $data[\'seller_analytic_id\'] = \'\';\n                                  }\n								                } 								\n\n								                $data[\'admin_analytic_id\'] = $this->config->get(\'marketplace_google_analytic_id\');				\n								\n								                $data[\'product_analytic\'] = false;\n								                if($this->config->get(\'marketplace_google_analytic_allowed_page\')) {\n									                $analytic_allowed_pages = $this->config->get(\'marketplace_google_analytic_allowed_page\');\n									                if(isset($analytic_allowed_pages[\'product\']) && $analytic_allowed_pages[\'product\']) {\n										                $data[\'product_analytic\'] = true;\n									                }									\n								                }\n                                    $data[\'showSellerInfo\'] = false;\n                                    $data[\'wk_custome_field_wkcustomfields\'] = true;\n                                    $customFields = array();\n                                    $data[\'customFields\'] = array();\n\n                                    $customFields = $this->model_catalog_product->getProductCustomFields($this->request->get[\'product_id\']);\n\n                                    foreach ($customFields as $key => $value) {\n                                        $customFieldsName = $this->model_catalog_product->getCustomFieldName($value[\'fieldId\']);\n\n                                        $customFieldsOptionId = $this->model_catalog_product->getCustomFieldOptionId($this->request->get[\'product_id\'],$value[\'fieldId\']);\n\n                                        $customFieldValue = \'\';\n                                        $result = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"wk_custom_field_product_options WHERE fieldId = \'\".(int)$value[\'fieldId\'].\"\' \")->row;\n\n																				if(isset($result[\'option_id\']) && $result[\'option_id\']) {\n																					$customFieldValue =$result[\'option_id\'];\n																				}\n                                        foreach ($customFieldsOptionId as $key => $option) {\n                                                if(is_numeric($option[\'option_id\'])){\n                                                    $customFieldValue .= $this->model_catalog_product->getCustomFieldOption($option[\'option_id\']).\", \";\n                                                }else{\n                                                    $customFieldValue = $option[\'option_id\'];\n                                                }\n                                        }\n                                        $data[\'customFields\'][] = array(\n                                            \'fieldName\' =>  $customFieldsName,\n                                            \'fieldValue\'    =>  trim($customFieldValue,\', \'),\n                                        );\n                                    }\n\n                                    $checkSellerOwnProduct = $this->model_account_customerpartner->checkSellerOwnProduct($this->request->get[\'product_id\']);\n\n                                    $this->load->language(\'extension/module/marketplace\');\n                                    if ($checkSellerOwnProduct && !$this->config->get(\'marketplace_sellerbuyproduct\')) {\n                                        $data[\'allowedProductBuy\'] = false;\n                                        $data[\'error_own_product\'] = $this->language->get(\'error_own_product\');\n                                    }else{\n                                        $data[\'allowedProductBuy\'] = true;\n                                        $data[\'error_own_product\'] = false;\n                                    }\n\n                                    /**\n                                     * add seller information on the product page through code end\n                                     */\n\n                                    if (!$this->config->get(\'marketplace_seller_info_by_module\') && !$this->config->get(\'marketplace_seller_info_hide\')) {\n\n                                        $check_seller = $this->model_account_customerpartner->getProductSellerDetails($this->request->get[\'product_id\']);\n\n                                        $this->load->model(\'customerpartner/master\');\n\n                                        if ($check_seller) {\n\n                                            $this->load->model(\'customerpartner/master\');\n\n                                            $partner = $this->model_customerpartner_master->getProfile($check_seller[\'customer_id\']);\n\n                                            switch ($this->config->get(\'marketplace_product_name_display\')) {\n                                                case \'sn\':\n                                                    $data[\'info_name\'] = $partner[\'firstname\']. \' \' .$partner[\'lastname\'];\n                                                    break;\n\n                                                case \'cn\':\n                                                    $data[\'info_name\'] = $partner[\'companyname\'];\n                                                    break;\n\n                                                case \'sncn\':\n                                                    $data[\'info_name\'] = $partner[\'firstname\']. \' \' .$partner[\'lastname\'].\' \'.\'And\'.\' \'.$partner[\'companyname\'];\n                                                    break;\n                                            }\n\n                                            switch ($this->config->get(\'marketplace_product_image_display\')) {\n                                                case \'avatar\':\n                                                    if ($partner[\'avatar\'] && file_exists(DIR_IMAGE . $partner[\'avatar\'])) {\n                                                        $data[\'info_image\'] = $this->model_tool_image->resize($partner[\'avatar\'], 80, 80);\n                                                    } else if($this->config->get(\'marketplace_default_image_name\') && file_exists(DIR_IMAGE . $this->config->get(\'marketplace_default_image_name\'))) {\n                                                        if($partner[\'avatar\'] != \'removed\') {\n                                                            $data[\'info_image\'] = $this->model_tool_image->resize($this->config->get(\'marketplace_default_image_name\'), 80, 80);\n                                                        } else {\n                                                            $data[\'info_image\'] = \'\';\n                                                        }\n                                                    }else{\n                                                        $data[\'info_image\'] = $this->model_tool_image->resize($this->config->get(\'config_logo\'), 80, 80);\n                                                    }\n                                                    break;\n\n                                                case \'companylogo\':\n                                                    if ($partner[\'companylogo\'] && file_exists(DIR_IMAGE . $partner[\'companylogo\'])) {\n                                                        $data[\'info_image\'] = $this->model_tool_image->resize($partner[\'companylogo\'], 80, 80);\n                                                    } else if($this->config->get(\'marketplace_default_image_name\') && file_exists(DIR_IMAGE . $this->config->get(\'marketplace_default_image_name\'))) {\n                                                        if($partner[\'companylogo\'] != \'removed\') {\n                                                            $data[\'info_image\'] = $this->model_tool_image->resize($this->config->get(\'marketplace_default_image_name\'), 80, 80);\n                                                        } else {\n                                                            $data[\'info_image\'] = \'\';\n                                                        }\n                                                    }else{\n                                                        $data[\'info_image\'] = $this->model_tool_image->resize($this->config->get(\'config_logo\'), 80, 80);\n                                                    }\n                                                    break;\n\n                                                case \'companybanner\':\n                                                    if ($partner[\'companybanner\'] && file_exists(DIR_IMAGE . $partner[\'companybanner\'])) {\n                                                        $data[\'info_image\'] = $this->model_tool_image->resize($partner[\'companybanner\'], 80, 80);\n                                                    } else if($this->config->get(\'marketplace_default_image_name\') && file_exists(DIR_IMAGE . $this->config->get(\'marketplace_default_image_name\'))) {\n                                                        if($partner[\'companybanner\'] != \'removed\') {\n                                                            $data[\'info_image\'] = $this->model_tool_image->resize($this->config->get(\'marketplace_default_image_name\'), 80, 80);\n                                                        } else {\n                                                            $data[\'info_image\'] = \'\';\n                                                        }\n                                                    }else{\n                                                        $data[\'info_image\'] = $this->model_tool_image->resize($this->config->get(\'config_logo\'), 80, 80);\n                                                    }\n                                                    break;\n                                            }\n\n                                            $data[\'review_fields\'] = $this->model_customerpartner_master->getAllReviewFields();\n\n																						foreach ($data[\'review_fields\'] as $key => $review_field) {\n																							$data[\'review_fields\'][$key][\'field_value\'] = $this->model_customerpartner_master->getAllAverageFeedback($check_seller[\'customer_id\'],$review_field[\'field_id\']);\n																						}\n\n                                            $data[\'info_feedback_total\'] = round($this->model_customerpartner_master->getAverageFeedback($check_seller[\'customer_id\']));\n\n                                            $data[\'info_total_products\'] = $this->model_customerpartner_master->getPartnerCollectionCount($check_seller[\'customer_id\']);\n\n                                            $data[\'info_heading_text\'] = $this->language->get(\'text_seller_info_heading\');\n                                            $data[\'info_price_text\']   = $this->language->get(\'text_seller_info_price\');\n                                            $data[\'info_value_text\']   = $this->language->get(\'text_seller_info_value\');\n                                            $data[\'info_quality_text\'] = $this->language->get(\'text_seller_info_quality\');\n                                            $data[\'info_product_text\'] = $this->language->get(\'text_seller_info_product\');\n                                            $data[\'showSellerRating\']  = $this->config->get(\'text_seller_info_product\');\n                                            $data[\'loadProfile\'] = $this->url->link(\'customerpartner/profile&id=\'.$check_seller[\'customer_id\'],\'\',true);\n\n                                            $data[\'showSellerInfo\'] = true;\n                                        }\n                                    }\n                            }else{\n                                $data[\'wk_custome_field_wkcustomfields\'] = false;\n                                $data[\'allowedProductBuy\'] = true;\n                                $data[\'showSellerInfo\'] = false;\n                            }\n              ]]></add>\n      </operation>\n  </file>\n  <file path=\"catalog/model/catalog/product.php\">\n  <operation>\n      <search><![CDATA[\n          \'price\'            => ($query->row[\'discount\'] ? $query->row[\'discount\'] : $query->row[\'price\']),\n      ]]></search>\n      <add position=\"replace\"><![CDATA[\n          \'price\'            => ($query->row[\'discount\'] ? $query->row[\'discount\'] : $query->row[\'price\'])+$commission_amount,\n      ]]></add>\n  </operation>\n\n  <operation>\n      <search><![CDATA[\n          \'viewed\'           => $query->row[\'viewed\']\n      ]]></search>\n      <add position=\"before\"><![CDATA[\n          \'commission_amount\' => $commission_amount,\n      ]]></add>\n  </operation>\n  <operation>\n          <search><![CDATA[\n          class ModelCatalogProduct extends Model {\n          ]]></search>\n          <add position=\"after\"><![CDATA[\n              public function  getCustomFieldOptionId($pro_id,$id){\n                  $result = $this->db->query(\"SELECT option_id FROM \".DB_PREFIX.\"wk_custom_field_product_options WHERE fieldId = \'\".(int)$id.\"\' AND product_id = \'\".(int)$pro_id.\"\' \")->rows;\n                  return $result;\n              }\n\n              public function getProductCustomFields($id){\n                  $result = $this->db->query(\"SELECT fieldId FROM \".DB_PREFIX.\"wk_custom_field_product WHERE productId = \'\".(int)$id.\"\' \")->rows;\n                  return $result;\n              }\n\n              public function getCustomFieldName($id){\n                  $result = $this->db->query(\"SELECT fieldName FROM \".DB_PREFIX.\"wk_custom_field_description WHERE fieldId = \'\".(int)$id.\"\' AND language_id = \'\".(int)$this->config->get(\'config_language_id\').\"\' \")->row;\n                  if (isset($result[\'fieldName\'])) {\nreturn $result[\'fieldName\'];\n}\n              }\n\n              public function getCustomFieldOption($id){\n                  $result = $this->db->query(\"SELECT optionValue FROM \".DB_PREFIX.\"wk_custom_field_option_description WHERE optionId = \'\".(int)$id.\"\' AND language_id = \'\".(int)$this->config->get(\'config_language_id\').\"\' \")->row;\n                  if (isset($result[\'optionValue\'])) {\nreturn $result[\'optionValue\'];\n}\n              }\n                ]]></add>\n  </operation>\n                <operation>\n                    <search><![CDATA[\n                        public function getProduct($product_id) {\n                    ]]></search>\n                    <add position=\"after\"><![CDATA[\n                      $product_status = 1;\n\n$commission_amount = 0;\n\n                        if (($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'user_token\']) && isset($this->session->data[\'user_token\']) && isset($this->session->data[\'user_id\']) && $this->request->get[\'user_token\'] == $this->session->data[\'user_token\']) || ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'product_token\']) && isset($this->session->data[\'product_token\']) && $this->request->get[\'product_token\'] == $this->session->data[\'product_token\'])){\n                            $product_status_array = $this->db->query(\"SELECT status FROM \".DB_PREFIX.\"product WHERE product_id = \" . (int)$product_id)->row;\nif (isset($product_status_array[\'status\'])) {\n  $product_status = $product_status_array[\'status\'];\n}\n                            if (!$product_status) {\n                                $this->db->query(\"UPDATE \".DB_PREFIX.\"product SET status = \'1\' WHERE product_id = \".$product_id);\n                            }\n                        }\n                    ]]></add>\n                </operation>\n\n                <operation>\n                        <search><![CDATA[\n                        ->get(\'config_language_id\') . \"\' AND p.status = \'1\' AND p.date_available <= NOW() AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\");\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                                 /**\n                                  * Marketplace Code Starts Here\n                                  */\n                                 if ($this->config->get(\'module_marketplace_status\') && $query->num_rows) {\n                                    $check_seller_product = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"customerpartner_to_product WHERE product_id = \'\" . (int)$product_id.\"\'\")->row;\n\n                                   if ($check_seller_product) {\n\n  $this->load->model(\'account/customerpartnerorder\');\n\n  if ($this->config->get(\'marketplace_commission_tax\')) {\n\n    $commission_array = $this->model_account_customerpartnerorder->calculateCommission(array(\'product_id\'=> $product_id, \'product_total\'=> $this->tax->calculate($query->row[\'price\'], $query->row[\'tax_class_id\'], $this->config->get(\'config_tax\'))),$check_seller_product[\'customer_id\']);\n  }else{\n    $commission_array = $this->model_account_customerpartnerorder->calculateCommission(array(\'product_id\'=>$product_id, \'product_total\'=>$query->row[\'price\']),$check_seller_product[\'customer_id\']);\n\n  }\n\n  if($commission_array && isset($commission_array[\'commission\']) && $this->config->get(\'marketplace_commission_unit_price\')){\n        $commission_amount = $commission_array[\'commission\'];\n  }\n\n                                        $check_seller_status = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"customerpartner_to_customer WHERE customer_id = \'\" . (int)$check_seller_product[\'customer_id\'].\"\' AND is_partner = \'1\'\")->row;\n\n                                       if ($this->config->get(\'module_marketplace_status\') && !$this->config->get(\'marketplace_sellerproductshow\') && !$check_seller_status) {\n\n                                             return false;\n                                        }\n                                    }\n\n                                }\n\n                                if (!$product_status) {\n                                    $this->db->query(\"UPDATE \".DB_PREFIX.\"product SET status = \'0\' WHERE product_id = \".$product_id);\n                                }\n                             /**\n                              * Marketplace Code Ends Here\n                              */\n                              ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                       $product_data[$result[\'product_id\']] = $this->getProduct($result[\'product_id\']);\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                          /**\n                          * Marketplace Code Starts Here\n                          */\n                            if ($this->config->get(\'module_marketplace_status\') && !$product_data[$result[\'product_id\']]) {\n\n                                unset($product_data[$result[\'product_id\']]);\n                            }\n                          /**\n                          * Marketplace Code Ends Here\n                          */\n                              ]]></add>\n                </operation>\n                <operation>\n                    <search><![CDATA[\n                        $product_option_value_data[] = array(\n                    ]]></search>\n                    <add position=\"before\"><![CDATA[\n                        /**\n                        * Marketplace Code Starts Here\n                        */\n                        if ($this->config->get(\'module_marketplace_status\')) {\n                        $check_seller_product = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"customerpartner_to_product WHERE product_id = \'\" . (int)$product_id.\"\'\")->row;\n\n                        if ($check_seller_product) {\n\n                            $this->load->model(\'account/customerpartnerorder\');\n\n                            if ($this->config->get(\'marketplace_commission_tax\')) {\n\n                            $tax_class_id = $this->db->query(\"SELECT tax_class_id FROM \".DB_PREFIX.\"product WHERE product_id = \'\" . (int)$product_id.\"\'\")->row;\n\n                            $commission_array = $this->model_account_customerpartnerorder->calculateCommission(array(\'product_id\'=> $product_id, \'product_total\'=> $this->tax->calculate($product_option_value[\'price\'], $tax_class_id[\'tax_class_id\'], $this->config->get(\'config_tax\'))),$check_seller_product[\'customer_id\']);\n                            }else{\n                            $commission_array = $this->model_account_customerpartnerorder->calculateCommission(array(\'product_id\'=>$product_id, \'product_total\'=>$product_option_value[\'price\']),$check_seller_product[\'customer_id\']);\n\n                            }\n\n                            if($commission_array && isset($commission_array[\'commission\']) && $this->config->get(\'marketplace_commission_unit_price\')){\n                            $product_option_value[\'price\'] = $product_option_value[\'price\'] + $commission_array[\'commission\'];\n                            }\n                        }\n                        }\n\n                        /**\n                        * Marketplace Code End Here\n                        */\n                    ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/view/theme/*/template/product/product.twig\">\n            <operation>\n            <search><![CDATA[\n            {{ header }}\n            ]]></search>\n            <add position=\"after\"><![CDATA[\n            <script>\n              var base_url = location.origin;\n              var current_url = location.href;\n              {% if admin_analytic_id is defined and admin_analytic_id and product_analytic is defined and product_analytic %}\n  \n                ga(\'create\', \'{{ admin_analytic_id }}\', \'auto\', \'AdminTracker\');\n                ga(\'AdminTracker.set\', \'page\', current_url.replace(base_url,\'\'));\n                ga(\'AdminTracker.send\', \'pageview\');\n              {% endif %}\n              {% if seller_analytic_id is defined and seller_analytic_id and product_analytic is defined and product_analytic %}\n                ga(\'create\', \'{{ seller_analytic_id }}\', \'auto\', \'SellerTracker\');\n                ga(\'SellerTracker.set\', \'page\', current_url.replace(base_url,\'\'));\n                ga(\'SellerTracker.send\', \'pageview\');\n              {% endif %}\n            </script>\n            ]]></add>\n            </operation>\n            <operation>\n                    <search><![CDATA[\n                        {% if price %}\n                    ]]></search>\n                    <add position=\"before\"><![CDATA[\n                        {% if delivery_date is defined and delivery_date %}\n                            <ul class=\"list-unstyled\">\n                              <li>{{ text_delivery_date  ~ \' : \' ~ delivery_date }}</li>\n                            </ul>\n                        {% endif %}\n                    ]]></add>\n                </operation>\n\n                <operation>\n                        <search><![CDATA[\n                        {{ text_stock }}\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                            {% if wk_custome_field_wkcustomfields %}\n                                     {% if customFields is not empty %}\n                                      {% for key, value in customFields %}\n                                            <div><span>{{ value[\'fieldName\'] }}</span>{{ value[\'fieldValue\'] }}</div>\n                                      {% endfor %}\n                                    {% endif %}\n                            {% endif %}\n                              ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                        <div class=\"row\">{{ column_left }}\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                            {% if not allowedProductBuy %}\n                                <div class=\"alert alert-danger\">\n                                  <i class=\"fa fa-exclamation-circle\"></i>\n                                    {{ error_own_product }}\n                                </div>\n                              {% endif %}\n                              ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                        {% if products %}\n                        ]]></search>\n                        <add position=\"before\" offset=\"2\"><![CDATA[\n                          {{ sellerprofile }}\n                              ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/controller/common/cart.php\">\n                <operation>\n                        <search><![CDATA[\n                        foreach ($this->cart->getProducts() as $product) {\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n                             /**\n                             * Marketplace Code Starts Here\n                             */\n                              $this->load->model(\'account/customerpartner\');\n                              $data[\'text_bySeller\'] = $this->language->get(\'text_bySeller\');\n                              $data[\'marketplace_seller_name_cart_status\'] = $this->config->get(\'marketplace_seller_name_cart_status\');\n                              $data[\'marketplace_seller_info_hide\'] = $this->config->get(\'marketplace_seller_info_hide\');\n                              $data[\'module_marketplace_status\'] = $this->config->get(\'module_marketplace_status\');\n                            /**\n                             * Marketplace Code Ends Here\n                             */\n                              ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                        \'total\'     => $total,\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                             \'seller_name\'     => $checkSellerProduct ? $checkSellerProduct[\'firstname\'].\' \'.$checkSellerProduct[\'lastname\']: \'\',\n                             \'seller_href\'      =>$checkSellerProduct ? $this->url->link(\'customerpartner/profile\', \'id=\' . $checkSellerProduct[\'customer_id\']): \'\',\n                              ]]></add>\n                </operation>\n                  <operation>\n                        <search><![CDATA[\n                        $data[\'products\'][] = array(\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n                            /**\n                             * Marketplace Code Starts Here\n                             */\n                            if ($this->config->get(\'module_marketplace_status\')) {\n                                $checkSellerProduct = $this->model_account_customerpartner->getProductSellerDetails($product[\'product_id\']);\n                            }else{\n                                 $checkSellerProduct = \'\';\n                            }\n                            /**\n                             * Marketplace Code Ends Here\n                             */\n                              ]]></add>\n                </operation>\n\n                <operation>\n                  <search><![CDATA[\n                    $unit_price = $this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\'));\n                  ]]></search>\n                  <add position=\"before\"><![CDATA[\n                    if(isset($product[\'commission_amount\']) && $product[\'commission_amount\']){\n                      $product[\'price\'] += $product[\'commission_amount\'];\n                    }\n                  ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/language/*/checkout/cart.php\">\n            <operation>\n                <search><![CDATA[\n                    $_[\'error_stock\']\n                ]]></search>\n                <add position=\"before\"><![CDATA[\n                    $_[\'error_min_cart_value\']     = \'You can not proceed to checkout, minimum cart total should be %s!\';\n$_[\'error_product_quantity_restriction\']     = \'Your product quantity limit(%s) already exceeded for product %s!\';\n                ]]></add>\n            </operation>\n        </file>\n\n        <file path=\"catalog/language/*/common/cart.php\">\n\n            <operation>\n                <search><![CDATA[\n                    $_[\'text_recurring\'] = \'Payment Profile\';\n                ]]></search>\n                <add position=\"after\"><![CDATA[\n                    $_[\'text_bySeller\']  = \'By Seller\';\n                ]]></add>\n            </operation>\n        </file>\n        <file path=\"catalog/view/theme/*/template/common/cart.twig\">\n                <operation>\n                        <search><![CDATA[\n                        <td class=\"text-left\"><a href=\"{{ product.href }}\">{{ product.name }}</a>\n                        ]]></search>\n                        <add position=\"replace\"><![CDATA[\n                            {% if module_marketplace_status is defined and module_marketplace_status and marketplace_seller_name_cart_status and product[\'seller_name\'] is defined and product[\'seller_name\'] and not marketplace_seller_info_hide %}\n                              <td class=\"text-left\"><a href=\"{{ product.href }}\">{{ product.name }}</a> {{ text_bySeller }} <a href=\"{{ product.seller_href }}\" target=\"_blank\">{{ product[\'seller_name\'] }}</a>\n                            {% else %}\n                              <td class=\"text-left\"><a href=\"{{ product.href }}\">{{ product.name }}</a>\n                            {% endif %}\n                              ]]></add>\n                </operation>\n                 <operation>\n                        <search><![CDATA[\n                        <table class=\"table table-striped\">\n                        ]]></search>\n                        <add position=\"replace\"><![CDATA[\n                         <table class=\"table table-striped\" style=\"font-size: 12px;\">     \n                        ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                        <table class=\"table table-bordered\">\n                        ]]></search>\n                        <add position=\"replace\"><![CDATA[\n                            <table class=\"table table-bordered\" style=\"font-size: 12px;\">   \n                        ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/controller/checkout/checkout.php\">\n\n          <operation>\n              <search><![CDATA[\n                  // Validate minimum quantity requirements.\n              ]]></search>\n              <add position=\"before\"><![CDATA[\n                $this->load->model(\'account/customerpartner\');\n\n                if ($this->config->get(\'module_marketplace_status\') && (((int)$this->config->get(\'marketplace_min_cart_value\') && (int)$this->config->get(\'marketplace_min_cart_value\') > $this->cart->getTotal()) || ($this->model_account_customerpartner->getProductRestriction()))) {\n                  $this->response->redirect($this->url->link(\'checkout/cart\'));\n                }\n              ]]></add>\n          </operation>\n\n             <operation>\n                        <search><![CDATA[\n                      foreach ($products as $product) {\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n                                       if($this->config->get(\'module_marketplace_status\')) {\n                                            $productName = \'\';\n                                        }\n                              ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                      foreach ($products as $product_2) {\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n                                        if($this->config->get(\'module_marketplace_status\')) {\n\n                                             $this->load->model(\'account/customerpartner\');\n\n                                             $checkSellerOwnProduct = $this->model_account_customerpartner->checkSellerOwnProduct($product[\'product_id\']);\n\n                                            if ($checkSellerOwnProduct && !$this->config->get(\'marketplace_sellerbuyproduct\')) {\n                                                $allowedProductBuy = false;\n                                            }else{\n                                                $allowedProductBuy = true;\n                                            }\n\n                                            if(!$allowedProductBuy) {\n                                                $productName .= $product[\'name\'].\', \';\n                                                $this->session->data[\'sellerProducts\'] = $productName;\n                                                $this->response->redirect($this->url->link(\'checkout/cart\'));\n                                            }\n                                        }\n                              ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/controller/checkout/cart.php\">\n\n          <operation>\n            <search><![CDATA[\n              $unit_price = $this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\'));\n            ]]></search>\n            <add position=\"before\"><![CDATA[\n              if(isset($product[\'commission_amount\']) && $product[\'commission_amount\']){\n                $product[\'price\'] += $product[\'commission_amount\'];\n              }\n            ]]></add>\n          </operation>\n\n          <operation>\n              <search><![CDATA[\n                if ($this->config->get(\'config_customer_price\') && !$this->customer->isLogged()) {\n              ]]></search>\n              <add position=\"before\"><![CDATA[\n                $this->load->model(\'account/customerpartner\');\n\n                $product_quantity_restriction = $this->model_account_customerpartner->getProductRestriction();\n                if ($this->config->get(\'module_marketplace_status\') && $product_quantity_restriction) {\n                  $data[\'error_warning\'] = sprintf($this->language->get(\'error_product_quantity_restriction\'),(int)$this->config->get(\'marketplace_product_quantity_restriction\'), $product_quantity_restriction[\'name\']);\n                }\n\n                if ($this->config->get(\'module_marketplace_status\') && (int)$this->config->get(\'marketplace_min_cart_value\') && (int)$this->config->get(\'marketplace_min_cart_value\') > $this->cart->getTotal()) {\n                    $data[\'error_warning\'] = sprintf($this->language->get(\'error_min_cart_value\'), $this->currency->format($this->config->get(\'marketplace_min_cart_value\'), $this->session->data[\'currency\']));\n                }\n              ]]></add>\n          </operation>\n\n                <operation>\n                        <search><![CDATA[\n                      if ($this->cart->hasProducts() || !empty($this->session->data[\'vouchers\'])) {\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n                           if($this->config->get(\'module_marketplace_status\')) {\n                                $data[\'module_marketplace_status\'] = $this->config->get(\'module_marketplace_status\');\n                                if(isset($this->session->data[\'sellerProducts\'])) {\n                                    $data[\'error_warning_seller_product\'] = \" Warning: Please remove \".trim($this->session->data[\'sellerProducts\'],\', \').\" from cart to checkout!\";\n                                    unset($this->session->data[\'sellerProducts\']);\n                                } else {\n                                    $data[\'error_warning_seller_product\'] = false;\n                                }\n                            }\n                              ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/view/theme/*/template/checkout/cart.twig\">\n                <operation>\n                        <search><![CDATA[\n                      {% if error_warning %}\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n                           {% if module_marketplace_status is defined and module_marketplace_status %}\n                            {% if error_warning_seller_product %}\n                              <div class=\"alert alert-danger\"><i class=\"fa fa-exclamation-circle\"></i> {{ error_warning_seller_product }}\n                                  <button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button>\n                                </div>\n                            {% endif %}\n                          {% endif %}\n\n                              ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/controller/account/order.php\">\n                <operation>\n                        <search><![CDATA[\n                      if (isset($this->session->data[\'error\'])) {\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n                          // marketplace\n                          $this->load->model(\'account/customerpartner\');\n                          $data[\'button_order_detail\'] = $this->language->get(\'button_order_detail\');\n                          $data[\'text_tracking\'] = $this->language->get(\'text_tracking\');\n                          $data[\'module_marketplace_status\'] = $this->config->get(\'module_marketplace_status\');\n                          // marketplace\n                              ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                      \'reorder\'\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                           // marketplace\n                          \'order_detail\'   => $this->url->link(\'account/customerpartner/order_detail\', \'order_id=\' . $order_info[\'order_id\'] . \'&product_id=\' . $product[\'product_id\'], true),\n                          \'order_id\' => $product[\'order_id\'],\n                          \'product_id\' => $product[\'product_id\'],\n                           // marketplace\n                              ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/language/*/account/order.php\">\n                <operation>\n                        <search><![CDATA[\n                      $_[\'error_reorder\']\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n// marketplace\n$_[\'button_order_detail\']   = \'Track Order\';\n$_[\'text_tracking\']         = \'Product Tracking Details\';\n                              ]]></add>\n                </operation>\n        </file>\n        <file path=\"catalog/view/theme/*/template/account/order_info.twig\">\n                <operation>\n                        <search><![CDATA[\n                     <a href=\"{{ product.return }}\" data-toggle=\"tooltip\" title=\"{{ button_return }}\" class=\"btn btn-danger\"><i class=\"fa fa-reply\"></i></a>\n                        ]]></search>\n                        <add position=\"replace\"><![CDATA[\n                        <!-- marketplace -->\n                {% if module_marketplace_status is defined and module_marketplace_status %}\n                <a onclick = \"getProductOrderStatus({{ product[\'order_id\'] }},{{ product[\'product_id\'] }})\" data-toggle=\"tooltip\" title=\"{{ button_order_detail }}\" class=\"btn btn-primary\"><i class=\"fa fa-truck\"></i></a>\n                 <button class=\"hide\" href=\"#orderProductStatusModal\" data-toggle=\"modal\" id=\"statusButton\"></button>\n                 {% endif %}\n                 <a href=\"{{ product.return }}\" data-toggle=\"tooltip\" title=\"{{ button_return }}\" class=\"btn btn-danger\"><i class=\"fa fa-reply\"></i></a>\n                              ]]></add>\n                </operation>\n                                 <operation>\n                        <search><![CDATA[\n                    {{ footer }}\n                        ]]></search>\n                        <add position=\"before\"><![CDATA[\n<!-- marketplace -->\n{% if module_marketplace_status is defined and module_marketplace_status %}\n<div id=\"orderProductStatusModal\" class=\"modal fade bs-example-modal-sm\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"mySmallModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-content\">\n        <div class=\"modal-header\">\n            <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\">×</button>\n            <h3 class=\"modal-title\">{{ text_tracking }}</h3>\n        </div>\n        <div class=\"modal-body\" id=\"orderProductStatusModalBody\">\n\n        </div>\n        <div class=\"modal-footer\">\n          <button class=\"btn closebtn\" data-dismiss=\"modal\" aria-hidden=\"true\" id=\"closeButton\">Close</button>\n        </div>\n      </div>\n  </div>\n</div>\n<script>\n  function getProductOrderStatus (order_id,product_id) {\n          $.ajax({\n            url: \'index.php?route=account/customerpartner/order_detail&order_id=\'+order_id+\'&product_id=\'+product_id,\n            type: \'get\',\n            methodType: \'html\',\n            success: function(html) {\n              $(\'#orderProductStatusModalBody\').html(html);\n              $(\'#statusButton\').click();\n            }\n          });\n  }\n</script>\n{% endif %}\n<!-- marketplace -->\n                              ]]></add>\n                </operation>\n        </file>\n        <file path=\"admin/controller/customer/customer.php\">\n            <operation>\n                    <search><![CDATA[\n                  $this->model_customer_customer->addCustomer($this->request->post);\n                    ]]></search>\n                    <add position=\"before\"><![CDATA[\n            // Marketplace Code Starts Here\n            if ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'create_seller\'])) {\n                $this->model_customer_customer->addCustomer($this->request->post, $create_seller = 1);\n\n                $this->session->data[\'success\'] = $this->language->get(\'text_success\');\n\n                $url = \'\';\n\n                if (isset($this->request->get[\'filter_name\'])) {\n                    $url .= \'&filter_name=\' . urlencode(html_entity_decode($this->request->get[\'filter_name\'], ENT_QUOTES, \'UTF-8\'));\n                }\n\n                if (isset($this->request->get[\'filter_email\'])) {\n                    $url .= \'&filter_email=\' . urlencode(html_entity_decode($this->request->get[\'filter_email\'], ENT_QUOTES, \'UTF-8\'));\n                }\n\n                if (isset($this->request->get[\'filter_customer_group_id\'])) {\n                    $url .= \'&filter_customer_group_id=\' . $this->request->get[\'filter_customer_group_id\'];\n                }\n\n                if (isset($this->request->get[\'filter_status\'])) {\n                    $url .= \'&filter_status=\' . $this->request->get[\'filter_status\'];\n                }\n\n                if (isset($this->request->get[\'filter_approved\'])) {\n                    $url .= \'&filter_approved=\' . $this->request->get[\'filter_approved\'];\n                }\n\n                if (isset($this->request->get[\'filter_ip\'])) {\n                    $url .= \'&filter_ip=\' . $this->request->get[\'filter_ip\'];\n                }\n\n                if (isset($this->request->get[\'filter_date_added\'])) {\n                    $url .= \'&filter_date_added=\' . $this->request->get[\'filter_date_added\'];\n                }\n\n                if (isset($this->request->get[\'sort\'])) {\n                    $url .= \'&sort=\' . $this->request->get[\'sort\'];\n                }\n\n                if (isset($this->request->get[\'order\'])) {\n                    $url .= \'&order=\' . $this->request->get[\'order\'];\n                }\n\n                if (isset($this->request->get[\'page\'])) {\n                    $url .= \'&page=\' . $this->request->get[\'page\'];\n                }\n\n                if (isset($this->request->get[\'view_all\'])) {\n                    $url .= \'&view_all=\' . $this->request->get[\'view_all\'];\n                }\n\n                $this->response->redirect($this->url->link(\'customerpartner/partner\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\n\n            }else{ // Marketplace Code Ends Here\n\n                          ]]></add>\n            </operation>\n            <operation>\n                    <search><![CDATA[\n                  $this->model_customer_customer->addCustomer($this->request->post);\n                    ]]></search>\n                    <add position=\"after\"><![CDATA[\n            // Marketplace Code Starts Here\n            }\n            // Marketplace Code Ends Here\n\n                          ]]></add>\n            </operation>\n            <operation>\n                    <search><![CDATA[\n                   $data[\'action\'] = $this->url->link(\'customer/customer/add\',\n                    ]]></search>\n                    <add position=\"before\"><![CDATA[\n            // Marketplace Code Starts Here\n            if ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'create_seller\'])) {\n\n                if (isset($this->request->get[\'filter_name\'])) {\n                    $url .= \'&filter_name=\' . urlencode(html_entity_decode($this->request->get[\'filter_name\'], ENT_QUOTES, \'UTF-8\'));\n                }\n\n                if (isset($this->request->get[\'filter_email\'])) {\n                    $url .= \'&filter_email=\' . urlencode(html_entity_decode($this->request->get[\'filter_email\'], ENT_QUOTES, \'UTF-8\'));\n                }\n\n                if (isset($this->request->get[\'filter_customer_group_id\'])) {\n                    $url .= \'&filter_customer_group_id=\' . $this->request->get[\'filter_customer_group_id\'];\n                }\n\n                if (isset($this->request->get[\'filter_status\'])) {\n                    $url .= \'&filter_status=\' . $this->request->get[\'filter_status\'];\n                }\n\n                if (isset($this->request->get[\'filter_approved\'])) {\n                    $url .= \'&filter_approved=\' . $this->request->get[\'filter_approved\'];\n                }\n\n                if (isset($this->request->get[\'filter_ip\'])) {\n                    $url .= \'&filter_ip=\' . $this->request->get[\'filter_ip\'];\n                }\n\n                if (isset($this->request->get[\'filter_date_added\'])) {\n                    $url .= \'&filter_date_added=\' . $this->request->get[\'filter_date_added\'];\n                }\n\n                if (isset($this->request->get[\'sort\'])) {\n                    $url .= \'&sort=\' . $this->request->get[\'sort\'];\n                }\n\n                if (isset($this->request->get[\'order\'])) {\n                    $url .= \'&order=\' . $this->request->get[\'order\'];\n                }\n\n                if (isset($this->request->get[\'page\'])) {\n                    $url .= \'&page=\' . $this->request->get[\'page\'];\n                }\n\n                if (isset($this->request->get[\'view_all\'])) {\n                    $url .= \'&view_all=\' . $this->request->get[\'view_all\'];\n                }\n\n                $data[\'action\'] = $this->url->link(\'customer/customer/add\', \'user_token=\' . $this->session->data[\'user_token\'] . $url. \'&create_seller\', true);\n            }else{  // Marketplace Code Ends Here\n\n                          ]]></add>\n            </operation>\n            <operation>\n                    <search><![CDATA[\n                  $data[\'action\'] = $this->url->link(\'customer/customer/add\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\n                    ]]></search>\n                    <add position=\"after\"><![CDATA[\n            // Marketplace Code Starts Here\n            }\n            // Marketplace Code Ends Here\n\n                    ]]></add>\n            </operation>\n        </file>\n        <file path=\"admin/model/customer/customer.php\">\n                <operation>\n                        <search><![CDATA[\n                      public function deleteCustomer($customer_id) {\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                           /**\n                             * Marketplace\n                             */\n                            if ($this->config->get(\'module_marketplace_status\')) {\n\n                                $this->load->model(\'customerpartner/partner\');\n                                $this->model_customerpartner_partner->deleteCustomer($customer_id);\n                            }\n                             /**\n                             * Marketplace\n                             */\n\n                              ]]></add>\n                </operation>\n                <operation>\n                        <search><![CDATA[\n                      public function addCustomer($data) {\n                        ]]></search>\n                        <add position=\"replace\"><![CDATA[\n                           public function addCustomer($data, $create_seller = \'\') {\n\n                              ]]></add>\n                </operation>\n                 <operation>\n                        <search><![CDATA[\n                      $customer_id = $this->db->getLastId();\n                        ]]></search>\n                        <add position=\"after\"><![CDATA[\n                            if ($this->config->get(\'module_marketplace_status\') && $create_seller) {\n\n                                $this->load->model(\'customerpartner/partner\');\n                                $this->model_customerpartner_partner->approve($customer_id, $setstatus = 1);\n                            }\n\n                              ]]></add>\n                </operation>\n                <operation>\n                <search><![CDATA[\n                public function editCustomer($customer_id, $data) {\n                ]]></search>\n                <add position=\"after\"><![CDATA[\n                if ($this->config->get(\'module_marketplace_status\') && !$this->config->get(\'marketplace_sellerproductshow\')) {\n\n			$this->load->model(\'customerpartner/partner\');\n			$this->model_customerpartner_partner->approve($customer_id, $setstatus = 0);\n		}\n                ]]></add>\n                </operation>\n        </file>\n\n        <file path=\"catalog/controller/account/account.php\">\n            <operation>\n                <search><![CDATA[$this->document->setTitle($this->language->get(\'heading_title\'));]]></search>\n                <add position=\"after\"><![CDATA[\n                    /**\n                    * Marketplace\n                    */\n\n                    $this->load->model(\'account/customerpartner\');\n\n                    $data[\'is_seller\'] = 0;\n\n                    $data[\'marketplace_seller_mode\'] = 0;\n\n                    if ($this->config->get(\'module_marketplace_status\') && $this->model_account_customerpartner->chkIsPartner()) {\n\n                        $data[\'is_seller\'] = 1;\n\n                        $data[\'action\'] = $this->url->link(\'account/account\', \'\', true);\n\n                        if (($this->request->server[\'REQUEST_METHOD\'] == \'POST\')) {\n\n                            if (isset($this->request->post[\'marketplace_seller_mode\']) && $this->request->post[\'marketplace_seller_mode\']) {\n                                $this->session->data[\'marketplace_seller_mode\'] = $this->request->post[\'marketplace_seller_mode\'];\n                            } else {\n                                $this->session->data[\'marketplace_seller_mode\'] = 0;\n                            }\n                        }\n\n                        if(isset($this->session->data[\'marketplace_seller_mode\'])){\n                            $data[\'marketplace_seller_mode\'] = $this->session->data[\'marketplace_seller_mode\'];\n                        } else {\n                            $data[\'marketplace_seller_mode\'] = 1;\n                            $this->session->data[\'marketplace_seller_mode\'] = 1;\n                        }\n\n                        $this->load->language(\'extension/module/marketplace\');\n\n                        $data[\'text_mode_seller\'] = $this->language->get(\'text_mode_seller\');\n\n                        $data[\'text_mode_customer\'] = $this->language->get(\'text_mode_customer\');\n\n                        $this->document->addScript(\"https://gitcdn.github.io/bootstrap-toggle/2.2.2/js/bootstrap-toggle.min.js\");\n\n                        $this->document->addStyle(\"https://gitcdn.github.io/bootstrap-toggle/2.2.2/css/bootstrap-toggle.min.css\");\n                    }\n                    /**\n                    * Marketplace\n                    */\n                ]]></add>\n            </operation>\n        </file>\n\n        <file path=\"catalog/view/theme/*/template/account/account.twig\">\n            <operation>\n                <search><![CDATA[\n                    {{ header }}\n                ]]></search>\n                <add position=\"after\"><![CDATA[\n                    <style type=\"text/css\">\n                      .btn-success{\n                        background-image: linear-gradient(to bottom, #62c462, #51a351);\n                      }\n                    </style>\n                ]]></add>\n            </operation>\n\n            <operation>\n                <search><![CDATA[\n                    <div id=\"content\" class=\"{{ class }}\">{{ content_top }}\n                ]]></search>\n                <add position=\"after\"><![CDATA[\n                    {% if is_seller is defined and is_seller %}\n                        <form class=\"form-horizontal\" action=\"{{ action }}\" method=\"post\" id=\"form-mode\">\n                            <div>\n                              {% if marketplace_seller_mode is defined and marketplace_seller_mode %}\n                               <input value=\"1\" name=\"marketplace_seller_mode\" data-toggle=\"toggle\" data-on=\"{{ text_mode_seller }}\" data-off=\"{{ text_mode_customer }}\" data-onstyle=\"success\" data-offstyle=\"danger\" type=\"checkbox\" class=\"form-control hide\" checked>\n                              {% else %}\n                               <input value=\"1\" name=\"marketplace_seller_mode\" data-toggle=\"toggle\" data-on=\"{{ text_mode_seller }}\" data-off=\"{{ text_mode_customer }}\" data-onstyle=\"success\" data-offstyle=\"danger\" type=\"checkbox\" class=\"form-control hide\">\n                              {% endif %}\n                            </div>\n                        </form>\n                        <br/>\n                    {% endif %}\n                ]]></add>\n            </operation>\n\n            <operation>\n                <search><![CDATA[\n                    {{ footer }}\n                ]]></search>\n                <add position=\"before\"><![CDATA[\n                    <script type=\"text/javascript\">\n                      $(\'input[name=\\\'marketplace_seller_mode\\\']\').on(\'change\',function() {\n                        $(\"#form-mode\").submit();\n                      });\n                    </script>\n                ]]></add>\n            </operation>\n        </file>\n    <file path=\"catalog/controller/checkout/confirm.php\">\n        <operation>\n            <search><![CDATA[\n                $data[\'products\'][] = array(\n            ]]></search>\n            <add position=\"before\"><![CDATA[\n                if ($this->config->get(\'module_marketplace_status\') && $this->config->get(\'shipping_wk_custom_shipping_status\') && isset($this->session->data[\'shipping_address\'][\'postcode\']) && isset($this->session->data[\'shipping_method\'][\'code\']) && $this->session->data[\'shipping_method\'][\'code\'] == \'shipping_wk_custom_shipping.shipping_wk_custom_shipping\' && isset($product[\'product_id\']) && $product[\'product_id\']) {\n\n                    $this->load->model(\'account/customerpartner\');\n\n                    $this->load->language(\'customerpartner/profile\');\n\n                    $check_seller = $this->model_account_customerpartner->getProductSellerDetails($product[\'product_id\']);\n\n                    $seller_id = 0;\n\n                    if (isset($check_seller[\'customer_id\']) && $check_seller[\'customer_id\']) {\n                        $seller_id = $check_seller[\'customer_id\'];\n                    }\n\n                    $weight = 0;\n\n                    if (isset($product_info[\'weight\']) && $product_info[\'weight\']) {\n                        $weight = $product_info[\'weight\'];\n                    }\n\n                    $max_days = $this->model_account_customerpartner->getMinDays($seller_id,$this->session->data[\'shipping_address\'][\'postcode\'],$weight);\n\n                    if (isset($max_days[\'max_days\']) && $max_days[\'max_days\']) {\n                        $date = new DateTime(date(\'Y-m-d\', strtotime(\"+\".$max_days[\'max_days\'].\" days\")));\n\n                        $data[\'delivery_date\'] = $date->format(\'Y-m-d\');\n\n                        $data[\'text_delivery_date\'] = $this->language->get(\'text_delivery_date\');\n                    }\n                }\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[\n                $data[\'products\'][] = array(\n            ]]></search>\n            <add position=\"after\"><![CDATA[\n                \'delivery_date\'   => isset($data[\'delivery_date\']) && $data[\'delivery_date\'] ? $data[\'delivery_date\'] : \'\',\n            ]]></add>\n        </operation>\n\n\n    </file>\n    <file path=\"catalog/view/theme/*/template/checkout/confirm.twig\">\n        <operation>\n            <search><![CDATA[\n                <td class=\"text-right\">{{ column_price }}</td>\n            ]]></search>\n            <add position=\"before\"><![CDATA[\n                {% if delivery_date is defined and delivery_date %}\n                  <td class=\"text-right\">{{ text_delivery_date }}</td>\n                {% endif %}\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[\n                <td class=\"text-right\">{{ product.price }}</td>\n            ]]></search>\n            <add position=\"before\"><![CDATA[\n                {% if delivery_date is defined and delivery_date %}\n                  <td class=\"text-right\">{{ product[\'delivery_date\'] }}</td>\n                {% endif %}\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[\n                <td colspan=\"4\" class=\"text-right\"><strong>{{ total.title }}:</strong></td>\n            ]]></search>\n            <add position=\"replace\"><![CDATA[\n                {% if delivery_date is defined and delivery_date %}\n                  <td colspan=\"5\" class=\"text-right\"><strong>{{ total[\'title\'] }}:</strong></td>\n                {% else %}\n                  <td colspan=\"4\" class=\"text-right\"><strong>{{ total.title }}:</strong></td>\n                {% endif %}\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/model/account/activity.php\">\n      <operation>\n        <search><![CDATA[\n          $this->db->query(\"INSERT INTO `\" . DB_PREFIX . \"customer_activity` SET `customer_id` = \'\" . (int)$customer_id . \"\', `key` = \'\" . $this->db->escape($key) . \"\', `data` = \'\" . $this->db->escape(json_encode($data)) . \"\', `ip` = \'\" . $this->db->escape($this->request->server[\'REMOTE_ADDR\']) . \"\', `date_added` = NOW()\");\n        ]]></search>\n        <add position=\"after\"><![CDATA[\n          $this->load->model(\'account/notification\');\n          $this->model_account_notification->addSellerOrderActivity($this->db->getLastId(),$key, $data);\n        ]]></add>\n      </operation>\n    </file>\n\n    <file path=\"admin/controller/common/header.php\">\n      <operation>\n        <search><![CDATA[\n          return $this->load->view(\'common/header\', $data);\n        ]]></search>\n        <add position=\"before\"><![CDATA[\n          if (isset($this->session->data[\'user_token\'])) {\n						$data[\'user_token\'] = $this->session->data[\'user_token\'];\n            if ($this->user->hasPermission(\'access\', \'customerpartner/notification\')) {\n							$data[\'notification_access\'] = 1;\n						}\n					}\n        ]]></add>\n      </operation>\n    </file>\n\n    <file path=\"admin/view/template/common/header.twig\">\n      <operation>\n        <search><![CDATA[\n          <ul class=\"nav navbar-nav navbar-right\">\n        ]]></search>\n        <add position=\"after\"><![CDATA[\n          <li class=\"dropdown\" id=\"wk-notify\"></li>\n          {% if notification_access is defined and notification_access %}\n            <script type=\"text/javascript\">\n              $(document).ready(function () {\n                function wk_notify(){\n                  $.ajax({\n                    url: \'index.php?route=customerpartner/notification/notifications&user_token={{ user_token }}\',\n                    method: \'post\',\n                    dataType: \'json\',\n                    success: function(json) {\n                      $(\'#wk-notify\').html(json);\n                    },\n                  });\n               }\n                setInterval(wk_notify, 30000);\n                wk_notify();\n              });\n            </script>\n          {% endif %}\n        ]]></add>\n      </operation>\n    </file>\n\n      <file path=\"catalog/view/theme/*/template/common/header.twig\">\n      <operation>\n        <search><![CDATA[\n          </head>\n        ]]></search>\n        <add position=\"before\"><![CDATA[\n          {% if lang != \'en\' %}\n          <style>\n            #top{\n              margin-top: -20px;\n            }\n          </style>\n        {% endif %}\n        ]]></add>\n      </operation>\n    </file>\n\n    <file path=\"catalog/model/catalog/review.php\">\n      <operation>\n        <search><![CDATA[\n          $review_id = $this->db->getLastId();\n        ]]></search>\n        <add position=\"after\"><![CDATA[\n          $this->load->model(\'account/notification\');\n          $this->model_account_notification->productReviewActivity($product_id, $review_id, $data[\'name\']);\n        ]]></add>\n      </operation>\n    </file>\n\n    <file path=\"catalog/model/checkout/order.php\">\n      <operation>\n        <search><![CDATA[\n          $this->db->query(\"UPDATE \" . DB_PREFIX . \"product SET quantity = (quantity - \" . (int)$order_product[\'quantity\'] . \") WHERE product_id = \'\" . (int)$order_product[\'product_id\'] . \"\' AND subtract = \'1\'\");\n        ]]></search>\n        <add position=\"after\"><![CDATA[\n          $this->load->model(\'account/notification\');\n          $this->model_account_notification->productStockActivity($order_product[\'product_id\']);\n        ]]></add>\n      </operation>\n\n      <operation>\n        <search><![CDATA[\n          $this->cache->delete(\'product\');\n        ]]></search>\n        <add position=\"before\"><![CDATA[\n          if ($order_id && $order_status_id && $order_info[\'order_status_id\']) {\n            $this->load->model(\'account/notification\');\n            $activity_data = array(\n              \'id\' => $order_info[\'customer_id\'],\n              \'status\'        => $order_status_id,\n              \'order_id\'    => $order_id\n            );\n\n            $this->model_account_notification->addActivity(\'order_status\', $activity_data);\n          }\n        ]]></add>\n      </operation>\n    </file>\n\n\n    <file path=\"catalog/controller/customerpartner/sell.php\">\n      <operation>\n        <search><![CDATA[\n          \'href\'        => $this->url->link(\'product/product\', \'product_id=\' . $result[\'product_id\'],true)\n        ]]></search>\n        <add position=\"after\"><![CDATA[\n          ,\'quick_view\'  => $this->config->get(\'config_ssl\').\'index.php?route=extension/soconfig/quickview&product_id=\'.$result[\'product_id\']\n        ]]></add>\n      </operation>\n    </file>\n      <file path=\"catalog/model/extension/total/reward.php\">\n      <operation>\n        <search><![CDATA[\n            $discount = 0;\n        ]]></search>\n        <add position=\"after\"><![CDATA[\n            if(!$product[\'points\']){\n						    $product[\'points\'] = $this->session->data[\'reward\'];\n					  }\n        ]]></add>\n      </operation>\n    </file>\n     <file path=\"catalog/language/en-gb/api/customer.php\">\n        <operation>\n          <search><![CDATA[\n              $_[\'error_firstname\']    = \'First Name must be between 1 and 32 characters!\';\n          ]]></search>\n          <add position=\"before\"><![CDATA[\n              $_[\'error_seller\']    = \'Warning: Seller can not allow to buy their own products\';\n          ]]></add>\n        </operation>\n      </file>\n        <!-- end here -->\n</modification>\n', 0, '2021-07-11 15:41:47');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(5, 10, 'Change-MP-Paths', 'All SEF urls', 'Webkul', '1.0.0', 'http://webkul.com', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\n<modification>\n    <name>Change-MP-Paths</name>\n    <version>1.0.0</version>\n    <code>All SEF urls</code>\n    <author>Webkul</author>\n    <link>http://webkul.com</link>\n\n    <file path=\"catalog/controller/startup/seo_url.php\">\n        <operation>\n            <search><![CDATA[\n                $this->request->get[\'route\'] = \'error/not_found\';\n                ]]></search>\n            <add position=\"before\" offset=\"1\"><![CDATA[\n                }elseif($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_useseo\') AND $this->request->get[\'_route_\']==\'Marketplace-Collection\'){\n                    $this->request->get[\'route\'] =  \'customerpartner/profile/collection\';\n                }elseif ($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_useseo\') AND is_array($this->config->get(\'marketplace_SefUrlsvalue\')) AND (in_array($this->request->get[\'_route_\'],$this->config->get(\'marketplace_SefUrlsvalue\')) || in_array(current(explode(\'/\',$this->request->get[\'_route_\'])),$this->config->get(\'marketplace_SefUrlsvalue\')) )) {\n                    $_route_ = explode(\'/\',$this->request->get[\'_route_\']);\n\n                    $sefKey = array_search($_route_[0],$this->config->get(\'marketplace_SefUrlsvalue\'));\n\n                    $wkSefUrlspath = $this->config->get(\'marketplace_SefUrlspath\');\n\n                    if(isset($wkSefUrlspath[$sefKey])) {\n\n                        if($wkSefUrlspath[$sefKey]==\'customerpartner/profile\' AND isset($_route_[1])) {\n\n                            $query = $this->db->query(\"SELECT customer_id FROM \" . DB_PREFIX . \"customerpartner_to_customer WHERE `screenname` = \'\" . $this->db->escape($_route_[1]) . \"\'\");\n                            if ($query->num_rows) {\n                                if($query->row[\'customer_id\']){\n                                   $this->request->get[\'id\'] = $query->row[\'customer_id\'];\n                                }\n                            }\n                        $this->request->get[\'route\'] = \'customerpartner/profile\';\n\n                    } elseif($wkSefUrlspath[$sefKey]==\'product/product\' && in_array(\'product/product\',$this->config->get(\'marketplace_SefUrlspath\'))) {\n                    $new_route = str_replace($this->config->get(\'marketplace_product_seo_page_ext\'),\'\',$this->request->get[\'_route_\']);\n                    $product_name = false;\n                    if($this->config->get(\'marketplace_product_seo_format\')) {\n                        if($this->config->get(\'marketplace_product_seo_format\')==\'1\') {\n                            $mpparts = explode(\'/\', $new_route);\n                            if(isset($mpparts[1]) ) {\n                                $product_name = $mpparts[1];\n                            }\n                        } else if($this->config->get(\'marketplace_product_seo_format\')==\'2\') {\n                           $mpparts = explode($this->config->get(\'marketplace_product_seo_default_name\').\'-\',$new_route,2);\n                             if (!isset($mpparts[1])) {\n                              $mpparts = explode(\'/\',$mpparts[0],2);\n\n                              if (isset($mpparts[1])) {\n                                $mpparts = explode(\'-\',$mpparts[1],2);\n                              }\n                             }\n\n                            if(isset($mpparts[1]))\n                                $product_name = $mpparts[1];\n                        } else if($this->config->get(\'marketplace_product_seo_format\')==\'3\') {\n                            $mpparts = explode(\'/\',$new_route);\n                            if($mpparts[1])\n                                $product_name = $mpparts[1];\n                        }\n                    }\n                    if ($product_name) {\n                        $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url WHERE keyword = \'\" . $this->db->escape($product_name) . \"\'\");\n\n                        if ($query->num_rows) {\n                            $url = explode(\'=\', $query->row[\'query\']);\n\n                            if ($url[0] == \'product_id\') {\n                                $this->request->get[\'product_id\'] = $url[1];\n                            }\n                        }\n\n                        if(!$query->num_rows AND $this->config->get(\'marketplace_product_seo_product_name\')) {\n                            $product_name = str_replace(\'-\', \' \', $product_name);\n                            $query = $this->db->query(\"SELECT pd.product_id FROM \".DB_PREFIX.\"product_description pd WHERE pd.name = \'\".$this->db->escape($product_name).\"\' AND pd.language_id = \'\".$this->config->get(\'config_language_id\').\"\'\");\n\n                            if ($query->num_rows)\n                                $this->request->get[\'product_id\'] = $query->row[\'product_id\'];\n                        }\n\n                        $this->request->get[\'route\'] = \'product/product\';\n\n                    }\n\n                }else{\n                    $this->request->get[\'route\'] =  $wkSefUrlspath[$sefKey];\n                }\n\n            }\n            ]]></add>\n        </operation>\n\n        <operation>\n\n            <search><![CDATA[} elseif ($key == \'path\') {]]></search>\n            <add position=\"before\"><![CDATA[\n\n                }elseif($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_useseo\') AND $data[\'route\'] == \'customerpartner/profile/collection\'){\n\n                    $url .= \'/Marketplace-Collection\' ;\n                    unset($data[$key]);\n                }elseif($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_useseo\') AND $data[\'route\'] == \'product/product\' AND isset($data[\'product_id\']) AND is_array($this->config->get(\'marketplace_SefUrlspath\')) AND in_array($data[\'route\'],$this->config->get(\'marketplace_SefUrlspath\')) ) {\n                    $sellerDetail = \'\';\n                    $sellerDetails = $this->db->query(\"SELECT c2c.screenname,c2c.companyname,c.firstname as sellername FROM \".DB_PREFIX.\"customerpartner_to_product c2p LEFT JOIN \".DB_PREFIX.\"product p ON (p.product_id=c2p.product_id) LEFT JOIN \".DB_PREFIX.\"customerpartner_to_customer c2c ON (c2p.customer_id=c2c.customer_id) LEFT JOIN \".DB_PREFIX.\"customer c ON (c.customer_id=c2c.customer_id) WHERE c2p.product_id = \'\".$data[\'product_id\'].\"\' \")->row;\n\n                    if(isset($sellerDetails[$this->config->get(\'marketplace_product_seo_name\')]) && $sellerDetails[$this->config->get(\'marketplace_product_seo_name\')] ) {\n                        $sellerDetail = $sellerDetails[$this->config->get(\'marketplace_product_seo_name\')];\n                    } else {\n                        $sellerDetail = $this->config->get(\'marketplace_product_seo_default_name\');\n                    }\n                    $keyword = $this->db->query(\"SELECT keyword FROM \" . DB_PREFIX . \"seo_url WHERE `query` = \'product_id=\" . (int)$data[\'product_id\'] .  \"\' AND store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\' AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\")->row;\n\n                    if(isset($keyword[\'keyword\']) && $keyword[\'keyword\']) {\n                        $keyword = $keyword[\'keyword\'];\n                        unset($data[\'product_id\']);\n                    } else if($this->config->get(\'marketplace_product_seo_name\')) {\n\n                        $key_word = $this->db->query(\"SELECT name FROM \".DB_PREFIX.\"product_description pd WHERE product_id = \'\".$data[\'product_id\'].\"\' AND language_id = \'\".$this->config->get(\'config_language_id\').\"\' \")->row;\n\n                        if(isset($key_word[\'name\'])) {\n                            $keyword = str_replace(\' \',\'-\',$key_word[\'name\']);\n                        } else {\n                            $keyword = \'\';\n                        }\n                    }\n                    $sefKey = array_search($data[\'route\'],$this->config->get(\'marketplace_SefUrlspath\'));\n                    $wkSefUrlsvalue = $this->config->get(\'marketplace_SefUrlsvalue\');\n                    if(isset($wkSefUrlsvalue[$sefKey]) && $wkSefUrlsvalue[$sefKey]) {\n                        $url .= \'/\'.$wkSefUrlsvalue[$sefKey];\n                    } else {\n                        $url .= \'\';\n                    }\n                    if($sellerDetail) {\n                        if($this->config->get(\'marketplace_product_seo_format\') == \'1\') {\n                            $url .= \'/\'.$keyword;\n                        } else if($this->config->get(\'marketplace_product_seo_format\') == \'2\') {\n                            $url .= \'/\'.str_replace(array(\' \', \'-\'),\'_\',$sellerDetail).\'-\'.$keyword;\n                        } else if ($this->config->get(\'marketplace_product_seo_format\') == \'3\') {\n                            $url .= \'/\'.$keyword.\'/\'.str_replace(\' \',\'-\',$sellerDetail);\n                        }\n                        if($this->config->get(\'marketplace_product_seo_page_ext\')) {\n                            $url .= $this->config->get(\'marketplace_product_seo_page_ext\');\n                        }\n                        unset($data[$key]);\n                    } else {\n\n                        $sefKey = array_search($data[\'route\'],$this->config->get(\'marketplace_SefUrlspath\'));\n                        $wkSefUrlsvalue = $this->config->get(\'marketplace_SefUrlsvalue\');\n\n                        if(isset($wkSefUrlsvalue[$sefKey])){\n                            if($keyword){\n                                $url .=  \'/\'.$keyword;\n                            }\n                            if($this->config->get(\'marketplace_product_seo_page_ext\')) {\n                                $url .= $this->config->get(\'marketplace_product_seo_page_ext\');\n                            }\n                            unset($data[$key]);\n                        }\n                    }\n                    unset($data[\'product_id\']);\n                } elseif ($this->config->get(\'module_marketplace_status\') && $this->config->get(\'marketplace_useseo\') AND is_array($this->config->get(\'marketplace_SefUrlspath\')) AND in_array($data[\'route\'],$this->config->get(\'marketplace_SefUrlspath\'))) {\n                    $sefKey = array_search($data[\'route\'],$this->config->get(\'marketplace_SefUrlspath\'));\n\n                    $wkSefUrlsvalue = $this->config->get(\'marketplace_SefUrlsvalue\');\n                    if(isset($wkSefUrlsvalue[$sefKey])){\n                        if($data[\'route\']==\'customerpartner/profile\'){\n                            if($key == \'id\'){\n                                $url .=  \'/\'.$wkSefUrlsvalue[$sefKey];\n\n                                $query = $this->db->query(\"SELECT screenname FROM \" . DB_PREFIX . \"customerpartner_to_customer WHERE `customer_id` = \'\" . (int)$data[$key] . \"\'\");\n                                if ($query->num_rows) {\n\n                                   if(trim($query->row[\'screenname\'])){\n                                      $url .= \'/\' . $query->row[\'screenname\'];\n                                    }else{\n                                      $url .= \'\';\n                                    }\n                                    unset($data[$key]);\n                                }\n                            }\n                        }elseif(($data[\'route\'] != \'product/product\') && ($data[\'route\'] != \'customerpartner/profile\')){\n                            $url .=  \'/\'.$wkSefUrlsvalue[$sefKey];\n                            unset($data[$key]);\n                        }\n                    }\n\n            ]]></add>\n        </operation>\n    </file>\n\n    <file path=\"catalog/controller/checkout/confirm.php\">\n        <operation>\n            <search><![CDATA[\n                \'price\'      => $this->currency->format($this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\')), $this->session->data[\'currency\']),\n            ]]></search>\n            <add position=\"replace\"><![CDATA[\n                \'price\'      => $this->currency->format($this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\'))+$product[\'commission_amount\'], $this->session->data[\'currency\']),\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[\n                \'total\'      => $this->currency->format($this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\')) * $product[\'quantity\'], $this->session->data[\'currency\']),\n            ]]></search>\n            <add position=\"replace\"><![CDATA[\n                \'total\'      => $this->currency->format(($this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\'))+$product[\'commission_amount\']) * $product[\'quantity\'], $this->session->data[\'currency\']),\n            ]]></add>\n        </operation>\n    </file>\n\n    <file path=\"system/library/cart/cart.php\">\n\n      <operation>\n          <search><![CDATA[\n            public function getProducts() {\n          ]]></search>\n          <add position=\"before\"><![CDATA[\n            public function calculateCommission($product,$customer_id) {\n\n              if($product) {\n                $categories_array = $this->db->query(\"SELECT p2c.category_id,c.parent_id FROM \".DB_PREFIX.\"product_to_category p2c LEFT JOIN \".DB_PREFIX.\"category c ON (p2c.category_id = c.category_id) WHERE p2c.product_id = \'\".(int)$product[\'product_id\'].\"\' ORDER BY p2c.product_id \");\n\n                if($this->config->get(\'marketplace_commissionworkedon\'))\n                  $categories = $categories_array->rows;\n                else\n                  $categories = array($categories_array->row);\n\n                //get commission array for priority\n                $commission = $this->config->get(\'marketplace_boxcommission\');\n                $commission_amount = 0;\n                $commission_type = \'\';\n\n                if($commission)\n                  foreach($commission as $various) {\n                    switch ($various) {\n                      case \'category\': //get all parent category according to product and process\n                        if(isset($categories[0]) && $categories[0]){\n\n                          foreach($categories as $category) {\n                            if($category[\'parent_id\']==0){\n                              $category_commission = $query = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"customerpartner_commission_category WHERE category_id = \'\" . (int)$category[\'category_id\'] . \"\'\")->row;\n                              if($category_commission){\n                                $commission_amount += ( $category_commission[\'percentage\'] ? ($category_commission[\'percentage\']*$product[\'product_total\']/100) : 0 ) + $category_commission[\'fixed\'];\n                              }\n                            }\n                          }\n                          $commission_type = \'Category Based\';\n                          if($commission_amount)\n                            break;\n                        }\n\n                      case \'category_child\': //get all child category according to product and process\n                        if(isset($categories[0]) && $categories[0]){\n\n                          foreach($categories as $category){\n                            if($category[\'parent_id\'] > 0){\n                              $category_commission = $query = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"customerpartner_commission_category WHERE category_id = \'\" . (int)$category[\'category_id\'] . \"\'\")->row;\n                              if($category_commission){\n                                $commission_amount += ( $category_commission[\'percentage\'] ? ($category_commission[\'percentage\']*$product[\'product_total\']/100) : 0 ) + $category_commission[\'fixed\'];\n                              }\n                            }\n                          }\n\n                          $commission_type = \'Category Child Based\';\n                          if($commission_amount)\n                            break;\n                        }\n\n                      default: //just get all amount and process on that (precentage based)\n                        $customer_commission = $query = $this->db->query(\"SELECT commission FROM \".DB_PREFIX.\"customerpartner_to_customer WHERE customer_id = \'\" . (int)$customer_id . \"\'\")->row;\n                        if($customer_commission) {\n                          $commission_amount += $customer_commission[\'commission\'] ? ($customer_commission[\'commission\']*$product[\'product_total\']/100) : 0;\n                        }\n\n                        $commission_type = \'Partner Fixed Based\';\n                        break;\n                    }\n                    if($commission_amount)\n                      break;\n                  }\n\n                  if($this->config->get(\'module_wk_seller_group_status\')) {\n					\n                    $result = end($this->db->query(\"SELECT * FROM \".DB_PREFIX.\"seller_group_customer WHERE customer_id = \'\" . $customer_id.\"\'\")->rows);\n                    if($result && !$result[\'suspended\']) {\n\n                      $categories = $this->db->query(\"SELECT category_id FROM \".DB_PREFIX.\"product_to_category WHERE product_id = \'\" . (int)$product[\'product_id\'].\"\' \")->rows;\n                      \n                      foreach ($categories as $category) {\n                        if ($category && isset($category[\'category_id\']) && $category[\'category_id\']) {\n                          $groupCommission = $this->db->query(\"SELECT percentage,fixed FROM \".DB_PREFIX.\"seller_group_commission_categorywise WHERE category_id = \'\" . $category[\'category_id\'] . \"\' AND seller_id = \'\" . $customer_id . \"\' AND group_id = \'\" . $result[\'gid\'].\"\' \")->row;\n                          if (empty($groupCommission)) {\n                            $groupCommission = $this->db->query(\"SELECT customerDefaultGroupCommissionPercentage as percentage,customerDefaultGroupCommissionFixed as fixed FROM \".DB_PREFIX.\"seller_group_customer WHERE customer_id = \'\" . $customer_id.\"\' AND gid = \'\" . $result[\'gid\'] . \"\' \")->row;\n                          }\n                        } else {\n                          $groupCommission = $this->db->query(\"SELECT customerDefaultGroupCommissionPercentage as percentage,customerDefaultGroupCommissionFixed as fixed FROM \".DB_PREFIX.\"seller_group_customer WHERE customer_id = \'\" . $customer_id.\"\' AND gid = \'\" .  $result[\'gid\'] .\"\' \")->row;\n                        }\n                      }\n                     	if(isset($groupCommission) && $groupCommission) {\n                        $commission_amount += ( $groupCommission[\'percentage\'] ? ($groupCommission[\'percentage\']*$product[\'product_total\']/100) : 0 ) + $groupCommission[\'fixed\'];\n                      }\n                      $commission_type = \'Membership Based\';\n                    }\n                  }\n                $return_array = array(\n                  \'commission\' => $commission_amount,\n                  \'customer\' => $product[\'product_total\']- $commission_amount,\n                  \'type\' => $commission_type,\n                );\n                return($return_array);\n              }\n            }\n          ]]></add>\n      </operation>\n\n      <operation>\n          <search><![CDATA[\n            \'price\'           => ($price + $option_price),\n          ]]></search>\n          <add position=\"after\"><![CDATA[\n            \'commission_amount\'  => $commission_amount,\n          ]]></add>\n      </operation>\n\n      <operation>\n          <search><![CDATA[\n            \'total\'           => ($price + $option_price) * $cart[\'quantity\'],\n          ]]></search>\n          <add position=\"replace\"><![CDATA[\n            \'total\'           => ($price + $option_price + $commission_amount) * $cart[\'quantity\'],\n          ]]></add>\n      </operation>\n\n        <operation>\n            <search><![CDATA[\n                $total += $this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\')) * $product[\'quantity\'];\n            ]]></search>\n            <add position=\"replace\"><![CDATA[\n                $total += ($this->tax->calculate($product[\'price\'], $product[\'tax_class_id\'], $this->config->get(\'config_tax\'))+$product[\'commission_amount\']) * $product[\'quantity\'];\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[\n              $tax_rates = $this->tax->getRates($product[\'price\'], $product[\'tax_class_id\']);\n            ]]></search>\n            <add position=\"replace\"><![CDATA[\n              $tax_rates = $this->tax->getRates($product[\'total\'], $product[\'tax_class_id\']);\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[\n              $product_data[] = array(\n            ]]></search>\n            <add position=\"before\"><![CDATA[\n              $commission_amount = 0;\n              if ($this->config->get(\'module_marketplace_status\')) {\n                 $check_seller_product = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"customerpartner_to_product WHERE product_id = \'\".$product_query->row[\'product_id\'].\"\'\")->row;\n                 if ($check_seller_product) {\n                  if ($this->config->get(\'marketplace_commission_tax\')) {\n                    $commission_array = $this->calculateCommission(array(\'product_id\'=> $product_query->row[\'product_id\'], \'product_total\'=> $this->tax->calculate(($price + $option_price), $product_query->row[\'tax_class_id\'], $this->config->get(\'config_tax\'))),$check_seller_product[\'customer_id\']);\n                  }else{\n                    $commission_array = $this->calculateCommission(array(\'product_id\'=>$product_query->row[\'product_id\'], \'product_total\'=>($price + $option_price)),$check_seller_product[\'customer_id\']);\n                  }\n\n                  if($commission_array && isset($commission_array[\'commission\']) && $this->config->get(\'marketplace_commission_unit_price\')){\n                        $commission_amount = $commission_array[\'commission\'];\n                  }\n                }\n              }\n            ]]></add>\n        </operation>\n\n    </file>\n\n    <file path=\"system/library/cart/cart.php\">\n      <operation>\n          <search><![CDATA[\n            $this->data[] = array(\n          ]]></search>\n          <add position=\"before\"><![CDATA[\n            $commission_amount = 0;\n            if ($this->config->get(\'module_marketplace_status\')) {\n               $check_seller_product = $this->db->query(\"SELECT * FROM \".DB_PREFIX.\"customerpartner_to_product WHERE product_id = \'\".$product_query->row[\'product_id\'].\"\'\")->row;\n               if ($check_seller_product) {\n                if ($this->config->get(\'marketplace_commission_tax\')) {\n                  $commission_array = $this->calculateCommission(array(\'product_id\'=> $product_query->row[\'product_id\'], \'product_total\'=> $this->tax->calculate(($price + $option_price), $product_query->row[\'tax_class_id\'], $this->config->get(\'config_tax\'))),$check_seller_product[\'customer_id\']);\n                }else{\n                  $commission_array = $this->calculateCommission(array(\'product_id\'=>$product_query->row[\'product_id\'], \'product_total\'=>($price + $option_price)),$check_seller_product[\'customer_id\']);\n                }\n\n                if($commission_array && isset($commission_array[\'commission\']) && $this->config->get(\'marketplace_commission_unit_price\')){\n                      $commission_amount = $commission_array[\'commission\'];\n                }\n              }\n            }\n          ]]></add>\n      </operation>\n    </file>\n\n    <file path=\"admin/view/template/catalog/product_form.twig\">\n        <operation>\n            <search><![CDATA[\n              $(\'input[name=\\\'category\\\']\').val(\'\');\n            ]]></search>\n            <add position=\"before\"><![CDATA[\n              addCategoryAttribute(item);\n              addCategoryOption(item);\n            ]]></add>\n        </operation>\n        <operation>\n            <search><![CDATA[\n                var option_row = {{ option_row }};\n            ]]></search>\n            <add position=\"after\"><![CDATA[\n            function addCategoryOption(item)  {\n              if (item.value) {\n                $.ajax({\n                  url: \'index.php?route=customerpartner/optionmapping/categoryOption&user_token={{user_token}}&category_id=\' + item.value,\n                  dataType: \'json\',\n                  success: function(json) {\n                    $.each(json, function(key,val){\n                        addOption(val);\n                        var category_option_row = option_row -1;\n                        $(\'input[name=\\\'product_option[\' + category_option_row + \'][name]\\\']\').val(val.name);\n                        $(\'input[name=\\\'product_option[\' + category_option_row + \'][option_id]\\\']\').val(val.option_id);\n                    });\n                  }\n                });\n              }\n            }\n            function addOption(item) {\n              html  = \'<div class=\"tab-pane\" id=\"tab-option\' + option_row + \'\">\';\n              html += \'	<input type=\"hidden\" name=\"product_option[\' + option_row + \'][product_option_id]\" value=\"\" />\';\n              html += \'	<input type=\"hidden\" name=\"product_option[\' + option_row + \'][name]\" value=\"\' + item[\'label\'] + \'\" />\';\n              html += \'	<input type=\"hidden\" name=\"product_option[\' + option_row + \'][option_id]\" value=\"\' + item[\'option_id\'] + \'\" />\';\n              html += \'	<input type=\"hidden\" name=\"product_option[\' + option_row + \'][type]\" value=\"\' + item[\'type\'] + \'\" />\';\n\n              html += \'	<div class=\"form-group\">\';\n              html += \'	  <label class=\"col-sm-2 control-label\" for=\"input-required\' + option_row + \'\">{{ entry_required }}</label>\';\n              html += \'	  <div class=\"col-sm-10\"><select name=\"product_option[\' + option_row + \'][required]\" id=\"input-required\' + option_row + \'\" class=\"form-control\">\';\n              html += \'	      <option value=\"1\">{{ text_yes }}</option>\';\n              html += \'	      <option value=\"0\">{{ text_no }}</option>\';\n              html += \'	  </select></div>\';\n              html += \'	</div>\';\n\n              if (item[\'type\'] == \'text\') {\n                html += \'	<div class=\"form-group\">\';\n                html += \'	  <label class=\"col-sm-2 control-label\" for=\"input-value\' + option_row + \'\">{{ entry_option_value }}</label>\';\n                html += \'	  <div class=\"col-sm-10\"><input type=\"text\" name=\"product_option[\' + option_row + \'][value]\" value=\"\" placeholder=\"{{ entry_option_value }}\" id=\"input-value\' + option_row + \'\" class=\"form-control\" /></div>\';\n                html += \'	</div>\';\n              }\n\n              if (item[\'type\'] == \'textarea\') {\n                html += \'	<div class=\"form-group\">\';\n                html += \'	  <label class=\"col-sm-2 control-label\" for=\"input-value\' + option_row + \'\">{{ entry_option_value }}</label>\';\n                html += \'	  <div class=\"col-sm-10\"><textarea name=\"product_option[\' + option_row + \'][value]\" rows=\"5\" placeholder=\"{{ entry_option_value }}\" id=\"input-value\' + option_row + \'\" class=\"form-control\"></textarea></div>\';\n                html += \'	</div>\';\n              }\n\n              if (item[\'type\'] == \'file\') {\n                html += \'	<div class=\"form-group\" style=\"display: none;\">\';\n                html += \'	  <label class=\"col-sm-2 control-label\" for=\"input-value\' + option_row + \'\">{{ entry_option_value }}</label>\';\n                html += \'	  <div class=\"col-sm-10\"><input type=\"text\" name=\"product_option[\' + option_row + \'][value]\" value=\"\" placeholder=\"{{ entry_option_value }}\" id=\"input-value\' + option_row + \'\" class=\"form-control\" /></div>\';\n                html += \'	</div>\';\n              }\n\n              if (item[\'type\'] == \'date\') {\n                html += \'	<div class=\"form-group\">\';\n                html += \'	  <label class=\"col-sm-2 control-label\" for=\"input-value\' + option_row + \'\">{{ entry_option_value }}</label>\';\n                html += \'	  <div class=\"col-sm-3\"><div class=\"input-group date\"><input type=\"text\" name=\"product_option[\' + option_row + \'][value]\" value=\"\" placeholder=\"{{ entry_option_value }}\" data-date-format=\"YYYY-MM-DD\" id=\"input-value\' + option_row + \'\" class=\"form-control\" /><span class=\"input-group-btn\"><button type=\"button\" class=\"btn btn-default\"><i class=\"fa fa-calendar\"></i></button></span></div></div>\';\n                html += \'	</div>\';\n              }\n\n              if (item[\'type\'] == \'time\') {\n                html += \'	<div class=\"form-group\">\';\n                html += \'	  <label class=\"col-sm-2 control-label\" for=\"input-value\' + option_row + \'\">{{ entry_option_value }}</label>\';\n                html += \'	  <div class=\"col-sm-10\"><div class=\"input-group time\"><input type=\"text\" name=\"product_option[\' + option_row + \'][value]\" value=\"\" placeholder=\"{{ entry_option_value }}\" data-date-format=\"HH:mm\" id=\"input-value\' + option_row + \'\" class=\"form-control\" /><span class=\"input-group-btn\"><button type=\"button\" class=\"btn btn-default\"><i class=\"fa fa-calendar\"></i></button></span></div></div>\';\n                html += \'	</div>\';\n              }\n\n              if (item[\'type\'] == \'datetime\') {\n                html += \'	<div class=\"form-group\">\';\n                html += \'	  <label class=\"col-sm-2 control-label\" for=\"input-value\' + option_row + \'\">{{ entry_option_value }}</label>\';\n                html += \'	  <div class=\"col-sm-10\"><div class=\"input-group datetime\"><input type=\"text\" name=\"product_option[\' + option_row + \'][value]\" value=\"\" placeholder=\"{{ entry_option_value }}\" data-date-format=\"YYYY-MM-DD HH:mm\" id=\"input-value\' + option_row + \'\" class=\"form-control\" /><span class=\"input-group-btn\"><button type=\"button\" class=\"btn btn-default\"><i class=\"fa fa-calendar\"></i></button></span></div></div>\';\n                html += \'	</div>\';\n              }\n\n              if (item[\'type\'] == \'select\' || item[\'type\'] == \'radio\' || item[\'type\'] == \'checkbox\' || item[\'type\'] == \'image\') {\n                html += \'<div class=\"table-responsive\">\';\n                html += \'  <table id=\"option-value\' + option_row + \'\" class=\"table table-striped table-bordered table-hover\">\';\n                html += \'  	 <thead>\';\n                html += \'      <tr>\';\n                html += \'        <td class=\"text-left\">{{ entry_option_value }}</td>\';\n                html += \'        <td class=\"text-right\">{{ entry_quantity }}</td>\';\n                html += \'        <td class=\"text-left\">{{ entry_subtract }}</td>\';\n                html += \'        <td class=\"text-right\">{{ entry_price }}</td>\';\n                html += \'        <td class=\"text-right\">{{ entry_option_points }}</td>\';\n                html += \'        <td class=\"text-right\">{{ entry_weight }}</td>\';\n                html += \'        <td></td>\';\n                html += \'      </tr>\';\n                html += \'  	 </thead>\';\n                html += \'  	 <tbody>\';\n                html += \'    </tbody>\';\n                html += \'    <tfoot>\';\n                html += \'      <tr>\';\n                html += \'        <td colspan=\"6\"></td>\';\n                html += \'        <td class=\"text-left\"><button type=\"button\" onclick=\"addOptionValue(\' + option_row + \');\" data-toggle=\"tooltip\" title=\"{{ button_option_value_add }}\" class=\"btn btn-primary\"><i class=\"fa fa-plus-circle\"></i></button></td>\';\n                html += \'      </tr>\';\n                html += \'    </tfoot>\';\n                html += \'  </table>\';\n                html += \'</div>\';\n\n                      html += \'  <select id=\"option-values\' + option_row + \'\" style=\"display: none;\">\';\n\n                      for (i = 0; i < item[\'option_value\'].length; i++) {\n                  html += \'  <option value=\"\' + item[\'option_value\'][i][\'option_value_id\'] + \'\">\' + item[\'option_value\'][i][\'name\'] + \'</option>\';\n                      }\n\n                      html += \'  </select>\';\n                html += \'</div>\';\n              }\n\n              $(\'#tab-option .tab-content\').append(html);\n\n              $(\'#option > li:last-child\').before(\'<li><a href=\"#tab-option\' + option_row + \'\" data-toggle=\"tab\"><i class=\"fa fa-minus-circle\" onclick=\" $(\\\'#option a:first\\\').tab(\\\'show\\\');$(\\\'a[href=\\\\\\\'#tab-option\' + option_row + \'\\\\\\\']\\\').parent().remove(); $(\\\'#tab-option\' + option_row + \'\\\').remove();\"></i>\' + item[\'name\'] + \'</li>\');\n\n              $(\'#option a[href=\\\'#tab-option\' + option_row + \'\\\']\').tab(\'show\');\n\n              $(\'[data-toggle=\\\'tooltip\\\']\').tooltip({\n                container: \'body\',\n                html: true\n              });\n\n              $(\'.date\').datetimepicker({\n                pickTime: false\n              });\n\n              $(\'.time\').datetimepicker({\n                pickDate: false\n              });\n\n              $(\'.datetime\').datetimepicker({\n                pickDate: true,\n                pickTime: true\n              });\n\n              option_row++;\n            }\n            ]]></add>\n        </operation>\n        <operation>\n            <search><![CDATA[\n                function addAttribute() {\n            ]]></search>\n            <add position=\"before\"><![CDATA[\n              function addCategoryAttribute(item)  {\n\n                if (item.value) {\n                  $.ajax({\n                    url: \'index.php?route=customerpartner/categorymapping/categoryAttribute&user_token={{ user_token }}&category_id=\' + item.value,\n                    dataType: \'json\',\n                    success: function(json) {\n                      $.each(json, function() {\n                          addAttribute();\n                          var category_attribute_row = attribute_row -1;\n                          $(\'input[name=\\\'product_attribute[\' + category_attribute_row + \'][name]\\\']\').val(this.name);\n                          $(\'input[name=\\\'product_attribute[\' + category_attribute_row + \'][attribute_id]\\\']\').val(this.attribute_id);\n                      });\n                    }\n                  });\n                }\n              }\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/checkout/shipping_method.php\">\n\n    <operation>\n        <search><![CDATA[\n          $this->response->setOutput($this->load->view(\'checkout/shipping_method\', $data));\n        ]]></search>\n        <add position=\"before\"><![CDATA[\n          if (isset($data[\'shipping_methods\']) && isset($data[\'shipping_methods\'][\'wk_custom_shipping\']) && isset($this->session->data[\'seller_custom_shipping\']) && $this->session->data[\'seller_custom_shipping\'] && $this->config->get(\'shipping_wk_custom_shipping_seller_status\')) {\n          $data[\'seller_custom_shipping\'] = $this->session->data[\'seller_custom_shipping\'];\n          $data[\'text_seller_name\'] = $this->language->get(\'text_seller_name\');\n					$data[\'text_seller_shipping\'] = $this->language->get(\'text_seller_shipping\');\n          $data[\'text_event_amount\'] = $this->language->get(\'text_event_amount\');\n          $data[\'event_shipping_amount\'] = isset($this->session->data[\'event_shipping_amount\']) ? $this->session->data[\'event_shipping_amount\'] : 0;\n        }\n        ]]></add>\n        </operation>\n\n        <operation>\n          <search><![CDATA[\n          $this->load->model(\'setting/extension\');\n          ]]></search>\n          <add position=\"after\"><![CDATA[\n           if ($this->config->get(\'shipping_wk_custom_shipping_status\')) {\n			$this->load->language(\'extension/shipping/wk_custom_shipping\');\n			if ($this->config->get(\'shipping_wk_custom_shipping_priority_status\')) {\n				$this->load->model(\'account/customerpartnerorder\');\n					\n				$this->load->model(\'account/add_shipping_mod\');\n				$shipping = array();\n				$this->load->model(\'account/customer\');\n					\n					  \n				$seller = $this->model_account_customerpartnerorder->sellerAdminData($this->cart->getProducts());\n  \n				  foreach ($seller as $key => $value) {\n						if ($this->config->get(\'shipping_wk_custom_shipping_seller_details\') && $value[\'seller\'] != \'Admin\') {	\n						\n					  $sellername = $this->model_account_customer->getCustomer($value[\'seller\']);\n						  $shipping = $this->model_account_add_shipping_mod->getPriorityShipping($value[\'seller\']);\n  \n						  if (!empty($shipping) && $shipping[\'status\']) {\n							foreach ($shipping as $keys => $values) {\n							  if ($keys == \'high\') {\n								$shipping[$keys] = (array)json_decode($shipping[$keys]);\n								$shipping[$keys][\'text\'] = $this->currency->format($shipping[$keys][\'amount\'],$this->session->data[\'currency\']);\n							  } else if ($keys == \'low\') {\n								$shipping[$keys] = (array)json_decode($shipping[$keys]);\n  \n								$shipping[$keys][\'text\'] = $this->currency->format($shipping[$keys][\'amount\'],$this->session->data[\'currency\']);\n							  } else if ($keys == \'medium\') {\n								$shipping[$keys] = (array)json_decode($shipping[$keys]);\n								$shipping[$keys][\'text\'] = $this->currency->format($shipping[$keys][\'amount\'],$this->session->data[\'currency\']);\n							  } else {\n								$shipping[$keys] = $shipping[$keys];\n							  }\n							}\n							$priority_shipping[$value[\'seller\']] = $shipping;\n							$priority_shipping[$value[\'seller\']][\'name\'] = ucfirst($sellername[\'firstname\']) . \' \' . ucfirst($sellername[\'lastname\']);\n						  } else {\n							$priority_shipping[$value[\'seller\']] = array();\n						  }\n					  } else if($value[\'seller\'] == \'Admin\' || !$this->config->get(\'shipping_wk_custom_shipping_seller_details\') && $value[\'seller\'] != \'Admin\') {\n						$priority_shipping[0][\'high\'] = array(\n						  \'day\'    => $this->config->get(\'shipping_wk_custom_shipping_high_priority_day\'),\n						  \'amount\' => $this->config->get(\'shipping_wk_custom_shipping_high_priority_amount\'),\n						  \'text\'	 => $this->currency->format($this->config->get(\'shipping_wk_custom_shipping_high_priority_amount\'),$this->session->data[\'currency\'])\n						);\n						$priority_shipping[0][\'medium\'] = array(\n						  \'day\'    => $this->config->get(\'shipping_wk_custom_shipping_mid_priority_day\'),\n						  \'amount\' => $this->config->get(\'shipping_wk_custom_shipping_mid_priority_amount\'),\n						  \'text\'	 => $this->currency->format($this->config->get(\'shipping_wk_custom_shipping_mid_priority_amount\'),$this->session->data[\'currency\'])\n						);\n            $priority_shipping[0][\'low\'] = array(\n						  \'day\'    => $this->config->get(\'shipping_wk_custom_shipping_low_priority_day\'),\n						  \'amount\' => $this->config->get(\'shipping_wk_custom_shipping_low_priority_amount\'),\n						  \'text\'	 => $this->currency->format($this->config->get(\'shipping_wk_custom_shipping_low_priority_amount\'),$this->session->data[\'currency\'])\n						);\n						$priority_shipping[0][\'name\'] = \'Admin\';\n					}\n				  }\n					  $data[\'text_priority\']        = $this->language->get(\'text_priority\');\n					  $data[\'entry_high\']           = $this->language->get(\'entry_high\');\n					  $data[\'entry_medium\']         = $this->language->get(\'entry_medium\');\n					  $data[\'entry_low\']            = $this->language->get(\'entry_low\');\n					  $data[\'text_seller_name\']     = $this->language->get(\'text_seller_name\');\n					  $data[\'text_seller_shipping\'] = $this->language->get(\'text_seller_shipping\');\n					  $data[\'text_day\']             = $this->language->get(\'text_day\');\n					  $data[\'text_duration\']        = $this->language->get(\'text_duration\');\n					  $data[\'text_charges\']         = $this->language->get(\'text_charges\');\n					  $data[\'text_event_amount\']    = $this->language->get(\'text_event_amount\');\n					  $data[\'priority_shipping\']    = isset($priority_shipping) ? $priority_shipping : array();\n					  \n					}\n		   } \n\n            ]]></add>\n      </operation>\n\n      <operation>\n          <search><![CDATA[\n           $this->session->data[\'shipping_method\'] = $this->session->data[\'shipping_methods\'][$shipping[0]][\'quote\'][$shipping[1]];\n          ]]></search>\n          <add position=\"after\"><![CDATA[\n          if ($this->session->data[\'shipping_method\'][\'code\'] == \'wk_custom_shipping.wk_custom_shipping\') {\n            if (isset($this->request->post[\'shipping_priority\']) && is_array($this->request->post[\'shipping_priority\']) && !empty($this->request->post[\'shipping_priority\'])) {\n                  $priority_sum = 0;\n                  foreach ($this->request->post[\'shipping_priority\'] as $key => $value) {\n                    $this->session->data[\'seller_priority_shipping\'][$key]	= $value;\n                    $priority_sum += $value;\n                  }\n                  unset($this->request->post[\'shipping_priority\']);\n                  $this->request->post[\'shipping_priority\'] = $priority_sum;\n                } else {\n                  unset($this->request->post[\'shipping_priority\']);\n                  $this->request->post[\'shipping_priority\'] = 0;\n                }\n            $this->session->data[\'shipping_method\'][\'cost\'] += $this->request->post[\'shipping_priority\'];\n            $this->session->data[\'shipping_method\'][\'text\'] = $this->currency->format($this->session->data[\'shipping_method\'][\'cost\'], $this->session->data[\'currency\']);\n          } else {\n              unset($this->session->data[\'seller_priority_shipping\']);\n          }\n            ]]></add>\n      </operation>\n      \n    </file>\n\n\n    <file path=\"catalog/view/theme/*/template/checkout/shipping_method.twig\">\n      <operation>\n        <search><![CDATA[\n          {{ quote.title }} - {{ quote.text }}</label>\n        ]]></search>\n        <add position=\"after\" offset=\"1\"><![CDATA[\n          {% if quote[\'code\'] == \'wk_custom_shipping.wk_custom_shipping\' %}\n           {% if (priority_shipping is defined and priority_shipping and priority_shipping is not empty) %} \n            <p><strong>{{ text_priority }}</strong></p>\n            {% for key,shipping in priority_shipping %} \n                {% if (shipping is iterable) %} \n                    <strong>{% if (shipping[\'name\'] is defined) %} {{ shipping[\'name\'] }} {% endif %}</strong>\n                  {% for keys,priority in shipping %} \n                      {% if (keys == \'high\') %} \n                        <div class =\"radio\">\n                          <label><input type=\"radio\" class = \"priority\" name=\"shipping_priority[{{ key }}]\" value=\"{{ priority[\'amount\'] }}\" />{{ entry_high }} : {{ text_duration }} - {% if (priority[\'day\'] is defined and priority[\'day\']) %} {{ priority[\'day\'] }} {% else %} {{ \'0\' }} {% endif %} {{ text_day }} : {{ text_charges }} - {% if (priority[\'text\'] is defined and priority[\'text\']) %} {{ priority[\'text\'] }} {% endif %} \n                            </label>\n                        </div>\n                      {% endif %} \n                      {% if (keys == \'medium\') %} \n                        <div class =\"radio\">\n                          <label><input type=\"radio\" class = \"priority\" name=\"shipping_priority[{{ key }}]\" value=\"{{ priority[\'amount\'] }}\" />{{ entry_medium }} : {{ text_duration }} -{% if (priority[\'day\'] is defined and priority[\'day\']) %} {{ priority[\'day\'] }} {% else %} {{ \'0\' }} {% endif %} {{ text_day }} : {{ text_charges }} - {% if (priority[\'text\'] is defined and priority[\'text\']) %} {{ priority[\'text\'] }} {% endif %} \n                            </label>\n                        </div>\n                      {% endif %} \n                      {% if (keys == \'low\') %} \n                        <div class =\"radio\">\n                          <label><input type=\"radio\" class = \"priority\" name=\"shipping_priority[{{ key }}]\" value=\"{{ priority[\'amount\'] }}\" />{{ entry_low }}: {{ text_duration }} - {% if (priority[\'day\'] is defined and priority[\'day\']) %} {{ priority[\'day\'] }} {% else %} {{ \'0\' }} {% endif %} {{ text_day }} :  {{ text_charges }} - {% if (priority[\'text\'] is defined and priority[\'text\']) %} {{ priority[\'text\'] }} {% endif %} \n                            </label>\n                        </div>\n                      {% endif %} \n                {% endfor %}\n                {% endif %}\n                {% endfor %}\n                {% endif %}\n            {% if seller_custom_shipping is defined and seller_custom_shipping %}\n              <div class=\"table-responsive\" style=\"width:50%;\">\n               <table class=\"table table-stripped table-bordered table-hover\">\n                  <thead>\n                    <tr>\n                      <th class=\"text-left\">{{ text_seller_name }}</th>\n                      <th class=\"text-right\">{{ text_seller_shipping }}</th>\n                      {% if event_shipping_amount is defined and event_shipping_amount %}\n                        <th class=\"text-right\">{{ text_event_amount }}</th>\n                      {% endif %}\n                    </tr>\n                  </thead>\n                  <tbody>\n                  {% for key,value in seller_custom_shipping %}\n                    <tr>\n                        <td class=\"text-left\">{{ key }}</td>\n                        <td class=\"text-right\">{{ value.shipping_price }}</td>\n                        {% if event_shipping_amount is defined and event_shipping_amount %}\n                        <td class=\"text-right\">{{ value.prefix }} {{ value.event_shipping_amount }}</td>\n                        {% endif %}\n                    </tr>\n                  {% endfor %}\n            \n                  </tbody>\n                </table>\n              </div>\n            {% endif %}\n          {% endif %}\n        ]]></add>\n      </operation>\n      <operation>\n    <search><![CDATA[\n    <div class=\"buttons\">\n    ]]></search>\n    <add position=\"after\" offset = \"5\"><![CDATA[\n    <script type=\"text/javascript\">\n      $(\'#collapse-shipping-method input[name=\\\'shipping_method\\\']\').on(\'change\', function() {\n      if ($(this).val() != \'wk_custom_shipping.wk_custom_shipping\') {\n        $(\'.priority\').prop(\'checked\',false);\n      }\n      });\n      $(\'#collapse-shipping-method input[type=\\\'radio\\\']\').on(\'change\', function() {\n      if ($(\'#collapse-shipping-method input[name=\\\'shipping_method\\\']:checked\').val() != \'wk_custom_shipping.wk_custom_shipping\') {\n          $(\'.priority\').prop(\'checked\',false);\n      }\n      });\n\n    </script>\n    ]]></add>\n    </operation>\n    </file>\n\n    <file path=\"admin/controller/catalog/information.php\">\n      <operation>\n        <search><![CDATA[\n          $this->response->redirect($this->url->link(\'catalog/information\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\n        ]]></search>\n        <add position=\"replace\"><![CDATA[\n          if ($this->config->get(\'module_marketplace_status\') && isset($this->request->get[\'mpcheck\'])) {\n              $this->response->redirect($this->url->link(\'customerpartner/information\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\n          } else {\n              $this->response->redirect($this->url->link(\'catalog/information\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\n          }\n        ]]></add>\n      </operation>\n\n      <operation>\n        <search><![CDATA[\n          $data[\'action\'] = $this->url->link(\'catalog/information/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&information_id=\' . $this->request->get[\'information_id\'] . $url, true);\n        ]]></search>\n        <add position=\"replace\"><![CDATA[\n          if (isset($this->request->get[\'mpcheck\']) && $this->request->get[\'mpcheck\']) {\n            $data[\'action\'] = $this->url->link(\'catalog/information/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&mpcheck=1&information_id=\' . $this->request->get[\'information_id\'] . $url, true);\n          } else {\n            $data[\'action\'] = $this->url->link(\'catalog/information/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&information_id=\' . $this->request->get[\'information_id\'] . $url, true);\n          }\n        ]]></add>\n      </operation>\n    </file>\n</modification>\n', 0, '2021-07-11 15:42:03');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(6, 11, 'Admin Product Status Quick Change', '40835', 'opencarttools@gmail.com', '2.X - 3.X', 'http://www.opencarttools.net', '<modification>\r\n	<name>Admin Product Status Quick Change</name>\r\n    <version>2.X - 3.X</version>\r\n    <link>http://www.opencarttools.net</link>\r\n    <author>opencarttools@gmail.com</author>\r\n    <code>40835</code>\r\n	<file path=\"admin/controller/catalog/product.php\">\r\n        <operation error=\"skip\">\r\n            <search position=\"before\"><![CDATA[function getList]]></search>\r\n			<add position=\"before\"><![CDATA[public function prodstchngsave() {\r\n				if(isset($this->request->post[\'id\']) && $this->request->post[\'id\']) { \r\n					$status = (isset($this->request->post[\'status\']) && $this->request->post[\'status\']) ? 1 : 0;\r\n					$this->db->query(\"UPDATE \" . DB_PREFIX . \"product SET status = \'\" . $this->db->escape($status) . \"\' WHERE product_id = \'\" . (int)$this->request->post[\'id\'] . \"\'\");\r\n				}\r\n			}]]></add> \r\n        </operation>\r\n		<operation error=\"skip\">\r\n            <search position=\"after\"><![CDATA[function getList]]></search>\r\n			<add position=\"after\"><![CDATA[if(file_exists(\'model/extension/prodstchng.php\')) {\r\n				$this->load->model(\'extension/prodstchng\');\r\n				$this->model_extension_prodstchng->checkdb();\r\n				$this->document->addScript(\'view/javascript/prodstchng.js\');\r\n				$this->document->addStyle(\'view/javascript/prodstchng.css\');\r\n			}]]></add> \r\n        </operation>\r\n		<operation error=\"skip\">\r\n            <search position=\"after\"><![CDATA[=> $result[\'status\']]]></search>\r\n			<add position=\"after\"><![CDATA[\'status\' => $result[\'status\'] ? \'<label class=\"oct_switch\"> <input type=\"checkbox\" checked class=\"chkstatus\" data-str=\"\'.$result[\'product_id\'].\'\"/><span class=\"oct_slider oct_round\"></span></label>\' : \'<label class=\"oct_switch\"> <input type=\"checkbox\" class=\"chkstatus\" data-str=\"\'.$result[\'product_id\'].\'\"/><span class=\"oct_slider oct_round\"></span></label>\',]]></add> \r\n        </operation> 			\r\n 	</file>\r\n</modification>', 1, '2021-07-25 17:13:06'),
(7, 12, 'TMD SMS OTP Verification Module', '#TOM-2.3.0.2', 'TMD(opencartextensions.in)', '1.0', 'http://opencartextensions.in/', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification>\r\n	<name>TMD SMS OTP Verification Module</name>\r\n	<version>1.0</version>\r\n	<code>#TOM-2.3.0.2</code>\r\n	<author>TMD(opencartextensions.in)</author>\r\n	<link>http://opencartextensions.in/</link>\r\n\r\n	<file path=\"admin/language/*/common/column_left.php\">\r\n		<operation error=\"skip\">\r\n			<search ><![CDATA[// Text]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$_[\'text_smssetting\']                = \'Tmd Sms Setting\';\r\n			$_[\'text_tmdsms\']                    = \'Tmd Sms OTP\';\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"admin/controller/common/column_left.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[// Users]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			\r\n		$tmdsms = array();\r\n\r\n			if ($this->user->hasPermission(\'access\', \'extension/setting\')) {\r\n				$tmdsms[] = array(\r\n					\'name\'	   => $this->language->get(\'text_smssetting\'),\r\n					\'href\'     => $this->url->link(\'extension/setting\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()\r\n				);\r\n			}\r\n\r\n			if ($tmdsms) {\r\n				$data[\'menus\'][] = array(\r\n					\'id\'       => \'menu-design\',\r\n					\'icon\'	   => \'fa fa-comments\',\r\n					\'name\'	   => $this->language->get(\'text_tmdsms\'),\r\n					\'href\'     => \'\',\r\n					\'children\' => $tmdsms\r\n				);\r\n			}\r\n			/// xml]]></add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/controller/mail/order.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$order_products = $this->model_checkout_order->getOrderProducts($order_info[\'order_id\']);]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			/// xml\r\n		    	$tmdstatus = $this->config->get(\'tmdsms_status\');\r\n		    	if($tmdstatus == 1){\r\n				if(isset($order_info[\'telephone\'])){\r\n\r\n				$orderstatusmessgae = array();\r\n\r\n				$tmdorderstatuss = $this->config->get(\'tmdsms_orderstatus\');\r\n\r\n				foreach ($tmdorderstatuss as $key => $value) {\r\n					if(!empty($order_status_id == $key)){\r\n						$orderstatusmessgae = $value[\'name\'];\r\n						$orderstatusmessgaedltid = $value[\'dltid\'];\r\n					}\r\n				}\r\n\r\n				if(!empty($orderstatusmessgae)) {\r\n					$smsproduct=\'\';\r\n					foreach ($order_products as $order_product) {\r\n						$smsproduct .=$order_product[\'name\'];\r\n\r\n						$order_options = $this->model_checkout_order->getOrderOptions($order_info[\'order_id\'], $order_product[\'order_product_id\']);\r\n\r\n						foreach ($order_options as $order_option) {\r\n							if ($order_option[\'type\'] != \'file\') {\r\n								$value = $order_option[\'value\'];\r\n							} else {\r\n								$upload_info = $this->model_tool_upload->getUploadByCode($order_option[\'value\']);\r\n\r\n								if ($upload_info) {\r\n									$value = $upload_info[\'name\'];\r\n								} else {\r\n									$value = \'\';\r\n								}\r\n							}\r\n							$smsproduct .= \' ( \' .$order_option[\'name\'].\':\'.(utf8_strlen($value) > 20 ? utf8_substr($value, 0, 20) . \'..\' : $value).\' )\';\r\n\r\n						}\r\n\r\n							$smsproduct .= \' * \'.$order_product[\'quantity\'].\' , \';\r\n						}\r\n\r\n\r\n					$find = array(\r\n						\'{customername}\',\r\n						\'{order_id}\',\r\n						\'{order_status}\',\r\n						\'{order_amount}\',\r\n						\'{products}\'\r\n					);\r\n\r\n				$replace = array(\r\n					\'customername\' =>$order_info[\'firstname\'].\' \'.$order_info[\'lastname\'],\r\n					\'order_id\' =>$order_info[\'order_id\'],\r\n					\'order_status\' =>$order_info[\'order_status\'],\r\n					\'order_amount\' =>html_entity_decode($this->currency->format($order_info[\'total\'], $order_info[\'currency_code\'], $order_info[\'currency_value\']), ENT_NOQUOTES, \'UTF-8\'),\r\n					\'products\' =>$smsproduct\r\n				);\r\n\r\n				$tmdadminorder = $this->config->get(\'tmdsms_admin_order\');\r\n\r\n				$mobilemessage = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace, $orderstatusmessgae))));\r\n				$mobilemessageadmin = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace, $tmdadminorder))));\r\n				\r\n				if(!empty($mobilemessage)){\r\n					$sms_data = array(\r\n						\'telephone\' 	=> $order_info[\'telephone\'],\r\n						\'message\' 		=> $mobilemessage,\r\n						\'dltid\' 		=> $orderstatusmessgaedltid,\r\n					);\r\n\r\n					$this->load->model(\'extension/tmdsms/tmdsms\');\r\n					$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n				}}\r\n				}\r\n				///// Customer order sms\r\n\r\n				///// Admin  order sms\r\n\r\n\r\n				if(!empty($mobilemessageadmin))\r\n				{\r\n					$sms_data = array(\r\n						\'telephone\' 	=> $this->config->get(\'tmdsms_telephone\'),\r\n						\'message\' 		=> $mobilemessageadmin,\r\n						\'dltid\' 		=> $this->config->get(\'tmdsms_admin_order_dltid\'),\r\n					);\r\n\r\n					$this->load->model(\'extension/tmdsms/tmdsms\');\r\n					$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n				}\r\n\r\n			}\r\n\r\n			/// xml\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$language->load(\'mail/order_edit\');]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			/// xml\r\n			$tmdsmsstatus = $tmdstatus = $this->config->get(\'tmdsms_status\');\r\n			if($tmdsmsstatus == 1){\r\n				if(isset($order_info[\'telephone\'])){\r\n\r\n				$order_status_query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"order_status WHERE order_status_id = \'\" . (int)$order_status_id . \"\' AND language_id = \'\" . (int)$order_info[\'language_id\'] . \"\'\");\r\n\r\n				if ($order_status_query->num_rows) {\r\n					$order_status = $order_status_query->row[\'name\'];\r\n				} else {\r\n					$order_status = \'\';\r\n				}\r\n				$orderstatusmessgae = array();\r\n\r\n				$tmdorderstatuss = $this->config->get(\'tmdsms_orderstatus\');\r\n\r\n				foreach ($tmdorderstatuss as $key => $value) {\r\n					if(!empty($order_status_id == $key)){\r\n						$orderstatusmessgae = $value[\'name\'];\r\n						$orderstatusmessgaedltid = $value[\'dltid\'];\r\n					}\r\n\r\n				}\r\n\r\n				if(!empty($orderstatusmessgae))\r\n				{\r\n				$smsproduct=\'\';\r\n					$order_products = $this->model_checkout_order->getOrderProducts($order_info[\'order_id\']);\r\n					foreach ($order_products as $order_product) {\r\n								$smsproduct .=$order_product[\'name\'];\r\n\r\n								$order_options = $this->model_checkout_order->getOrderOptions($order_info[\'order_id\'], $order_product[\'order_product_id\']);\r\n\r\n								foreach ($order_options as $order_option) {\r\n									if ($order_option[\'type\'] != \'file\') {\r\n										$value = $order_option[\'value\'];\r\n									} else {\r\n										$upload_info = $this->model_tool_upload->getUploadByCode($order_option[\'value\']);\r\n\r\n										if ($upload_info) {\r\n											$value = $upload_info[\'name\'];\r\n										} else {\r\n											$value = \'\';\r\n										}\r\n									}\r\n									$smsproduct .= \' ( \' .$order_option[\'name\'].\':\'.(utf8_strlen($value) > 20 ? utf8_substr($value, 0, 20) . \'..\' : $value).\' )\';\r\n\r\n								}\r\n\r\n								$smsproduct .= \' * \'.$order_product[\'quantity\'].\' , \';\r\n								}\r\n				$find = array(\r\n					\'{customername}\',\r\n					\'{order_id}\',\r\n					\'{order_status}\',\r\n					\'{order_amount}\',\r\n					\'{products}\'\r\n				);\r\n\r\n				$replace = array(\r\n					\'customername\' =>$order_info[\'firstname\'].\' \'.$order_info[\'lastname\'],\r\n					\'order_id\' =>$order_info[\'order_id\'],\r\n					\'order_status\' =>$order_status,\r\n					\'order_amount\' =>html_entity_decode($this->currency->format($order_info[\'total\'], $order_info[\'currency_code\'], $order_info[\'currency_value\']), ENT_NOQUOTES, \'UTF-8\'),\r\n					\'products\' =>$smsproduct\r\n				);\r\n\r\n				$mobilemessage = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace, $orderstatusmessgae))));\r\n\r\n				if(!empty($mobilemessage)){\r\n					$sms_data = array(\r\n						\'telephone\' 	=> $order_info[\'telephone\'],\r\n						\'message\' 		=> $mobilemessage,\r\n						\'dltid\' 		=> $orderstatusmessgaedltid,\r\n					);\r\n\r\n					$this->load->model(\'extension/tmdsms/tmdsms\');\r\n					$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n				}\r\n\r\n				///// Customer order sms\r\n				}\r\n\r\n\r\n				}\r\n			}\r\n			/// xml\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/controller/mail/affiliate.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[if (in_array(\'affiliate\', (array)$this->config->get(\'config_mail_alert\'))) {]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n\r\n\r\n				$tmdsmsstatus = $tmdstatus = $this->config->get(\'tmdsms_status\');\r\n				if($tmdsmsstatus == 1){\r\n				if(isset($args[1][\'telephone\']))\r\n				{\r\n\r\n					if (!$this->config->get(\'config_affiliate_approval\')) {\r\n						$approved = $this->config->get(\'tmdsms_affiliate_approval\');\r\n						$approveddlt = $this->config->get(\'tmdsms_affiliate_approval_dltid\');\r\n					}\r\n					else\r\n					{\r\n						$approved = $this->config->get(\'tmdsms_affiliate_disapproval\');\r\n						$approveddlt = $this->config->get(\'tmdsms_affiliate_disapproval_dltid\');\r\n					}\r\n					if(!empty($approved)){\r\n					$find = array(\r\n						\'{customername}\',\r\n						\'{email}\',\r\n					);\r\n\r\n					$replace = array(\r\n						\'customername\'	=> $args[1][\'firstname\'] . \' \' . $args[1][\'lastname\'],\r\n						\'email\' 		=> $args[1][\'email\'],\r\n					);\r\n\r\n					$adminaffilifate = $this->config->get(\'tmdsms_admin_affiliate\');\r\n					$adminaffilifatedltid = $this->config->get(\'tmdsms_admin_affiliate_dltid\');\r\n\r\n					$mobilemessage = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace, $approved))));\r\n\r\n					$mobilemessageadmin= str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace, $adminaffilifate))));\r\n\r\n					if(!empty($mobilemessage)){\r\n							$sms_data = array(\r\n								\'telephone\' 	=> $data[\'telephone\'],\r\n								\'message\' 		=> $mobilemessage,\r\n								\'dltid\' 		=> $approveddlt,\r\n							);\r\n\r\n							$this->load->model(\'extension/tmdsms/tmdsms\');\r\n							$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n					}\r\n					}}\r\n\r\n					if(!empty($mobilemessageadmin)){\r\n							$sms_data = array(\r\n								\'telephone\' 	=> $this->config->get(\'tmdsms_telephone\'),\r\n								\'message\' 		=> $mobilemessageadmin,\r\n								\'dltid\' 		=> $adminaffilifatedltid,\r\n							);\r\n\r\n							$this->load->model(\'extension/tmdsms/tmdsms\');\r\n							$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n					}\r\n\r\n				}\r\n\r\n\r\n\r\n			/// xml\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/account/customer.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$customer_id = $this->db->getLastId();]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n\r\n\r\n				$tmdsmsstatus = $tmdstatus = $this->config->get(\'tmdsms_status\');\r\n				if($tmdsmsstatus == 1){\r\n				if(isset($data[\'telephone\']))\r\n				{\r\n\r\n					if (!$customer_group_info[\'approval\']) {\r\n						$approved = $this->config->get(\'tmdsms_registrtion_approval\');\r\n						$dltapprovedid = $this->config->get(\'tmdsms_registrtion_approval_dltid\');\r\n					}\r\n					else {\r\n						$approved = $this->config->get(\'tmdsms_registrtion_disapproval\');\r\n						$dltapprovedid = $this->config->get(\'tmdsms_registrtion_disapproval_dltid\');\r\n					}\r\n					if(!empty($approved)){\r\n					$find = array(\r\n						\'{customername}\',\r\n						\'{email}\',\r\n					);\r\n\r\n					$replace = array(\r\n						\'customername\'	=> $data[\'firstname\'] . \' \' . $data[\'lastname\'],\r\n						\'email\' 		=> $data[\'email\'],\r\n					);\r\n\r\n					$admincustomer = $this->config->get(\'tmdsms_admin_customer\');\r\n					$admincustomerdltid = $this->config->get(\'tmdsms_admin_customer_dltid\');\r\n\r\n					$mobilemessage = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace, $approved))));\r\n\r\n					$mobilemessageadmin= str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace, $admincustomer))));\r\n\r\n					if(!empty($mobilemessage)){\r\n							$sms_data = array(\r\n								\'telephone\' 	=> $data[\'telephone\'],\r\n								\'message\' 		=> $mobilemessage,\r\n								\'dltid\' 		=> $dltapprovedid,\r\n							);\r\n\r\n							$this->load->model(\'extension/tmdsms/tmdsms\');\r\n							$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n					}}\r\n					}\r\n					\r\n					if(!empty($mobilemessageadmin)){\r\n						$sms_data = array(\r\n								\'telephone\' 	=> $this->config->get(\'tmdsms_telephone\'),\r\n								\'message\' 		=> $mobilemessageadmin,\r\n								\'dltid\' 		=> $admincustomerdltid,\r\n							);\r\n\r\n							$this->load->model(\'extension/tmdsms/tmdsms\');\r\n							$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n					}\r\n\r\n					$tmdsmsotp = $this->config->get(\'tmdsms_otpverifystatus\');\r\n\r\n					if($tmdsmsotp == 1) {\r\n\r\n						$code=token(9);\r\n\r\n						$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"tmdsmsverify SET\r\n						customer_id = \'\" . (int)$customer_id . \"\',\r\n						otp = \'\" .$code.\"\',\r\n						verify_status = \'0\'\");\r\n\r\n						if(isset($tmdsmsotp)){\r\n							$find = array(\r\n								\'{customername}\',\r\n								\'{telephone}\',\r\n								\'{code}\',\r\n							);\r\n\r\n							$replace = array(\r\n								\'customername\'	=> $data[\'firstname\'] . \' \' . $data[\'lastname\'],\r\n								\'telephone\' 	=> $data[\'telephone\'],\r\n								\'otp\' 			=> $code,\r\n							);\r\n\r\n							$tmdsmsotpmsg=$this->config->get(\'tmdsms_otpmsg\');\r\n							$tmdsmsotpmsgdltid=$this->config->get(\'tmdsms_otpmsg_dltid\');\r\n\r\n							$otpmessage = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_replace(array(\"/\\s\\s+/\", \"/\\r\\r+/\", \"/\\n\\n+/\"), \'\', trim(str_replace($find, $replace,html_entity_decode($tmdsmsotpmsg)))));\r\n\r\n\r\n							if(!empty($otpmessage)){\r\n								$sms_data = array(\r\n									\'telephone\' 	=> $data[\'telephone\'],\r\n									\'message\' 		=> $otpmessage,\r\n									\'dltid\' 		=> $tmdsmsotpmsgdltid,\r\n								);\r\n\r\n								$this->load->model(\'extension/tmdsms/tmdsms\');\r\n								$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n							}\r\n\r\n						}\r\n					}\r\n\r\n				}\r\n\r\n\r\n\r\n			/// xml\r\n			]]></add>\r\n		</operation>\r\n\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[public function getAffiliateByTracking($tracking) {]]></search>\r\n			<add position=\"after\" offset=\"4\"><![CDATA[\r\n\r\n			/* new code */\r\n\r\n			public function getTotalCustomersByPhone($telephone) {\r\n				$query = $this->db->query(\"SELECT COUNT(*) AS total FROM \" . DB_PREFIX . \"customer WHERE telephone = \'\" . $this->db->escape($telephone) . \"\'\");\r\n\r\n				return $query->row[\'total\'];\r\n			}\r\n\r\n			public function getCustomerByPhone($telephone) {\r\n				$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"customer WHERE telephone = \'\" . $this->db->escape($telephone) . \"\'\");\r\n				return $query->row;\r\n			}\r\n\r\n			public function addnewphone($data) {\r\n				$this->db->query(\"UPDATE \" . DB_PREFIX . \"customer SET telephone = \'\".$this->db->escape($data[\'telephone\']).\"\' WHERE customer_id = \'\" . $this->customer->getId() . \"\'\");\r\n			}\r\n			/* new code */\r\n\r\n			/// xml\r\n			]]></add>\r\n		</operation>\r\n\r\n	</file>\r\n\r\n	<file path=\"catalog/controller/account/forgotten.php\">\r\n			<operation error=\"skip\">\r\n			<search><![CDATA[$this->model_account_customer->editCode($this->request->post[\'email\'], token(40));]]></search>\r\n			<add position=\"replace\"><![CDATA[$this->model_account_customer->editCode($this->request->post[\'email\'],$code);]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[if (($this->request->server[\'REQUEST_METHOD\'] == \'POST\') && $this->validate()) {]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$code=token(40);\r\n			$this->load->model(\'account/customer\');\r\n			$customer_info = $this->model_account_customer->getCustomerByEmail($this->request->post[\'email\']);\r\n\r\n			$tmdsmsstatus = $this->config->get(\'tmdsms_status\');\r\n			if($tmdsmsstatus == 1){\r\n			if($customer_info[\'telephone\']){\r\n				$forgetpasswordz = $this->config->get(\'tmdsms_forgotpassword_sms\');\r\n				$forgetpassworddltid = $this->config->get(\'tmdsms_forgotpassword_dltid\');\r\n				if(!empty($forgetpasswordz)){\r\n				$find = array(\r\n					\'{customername}\',\r\n					\'{link}\',\r\n					\'{email}\',\r\n				);\r\n\r\n				$replace = array(\r\n					\'customername\'	=> $customer_info[\'firstname\'] . \' \' . $customer_info[\'lastname\'],\r\n					\'link\' 		=>	$this->url->link(\'account/reset\', \'code=\' . $code, true),\r\n					\'email\' 		=> $customer_info[\'email\'],\r\n				);\r\n\r\n				$mobilemessage = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\"), \'\', preg_repl