;]]></add>\r\n		</operation>\r\n	</file>\r\n\r\n  <file path=\"catalog/view/theme/*/template/checkout/checkout.twig\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[{{ footer }}]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			{% if mainstatus == 1 %}\r\n			{% if loginotpstatus == 1 %}\r\n			<!--otp code start here-->\r\n			<div class=\"membershipModal modal fade\" role=\"dialog\">\r\n			<div class=\"modal-dialog modal-sm\">\r\n\r\n					{{ tmd_otplogin}}\r\n\r\n			</div>\r\n			</div>\r\n			{% endif %}\r\n			{% endif %}\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/login.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$this->response->setOutput($this->load->view(\'checkout/login\', $data));]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			$data[\'mainstatus\'] = $this->config->get(\'tmdsms_status\');\r\n		$data[\'loginotpstatus\'] = $this->config->get(\'tmdsms_loginbtnstatus\');\r\n\r\n		$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n\r\n		if($tmdsmsotplogin){\r\n			$data[\'entry_loginotp\'] = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'loginbtntext\'];\r\n		} else {\r\n			$data[\'entry_loginotp\'] = $this->language->get(\'entry_loginotp\');\r\n		}\r\n\r\n			$data[\'tmd_otplogin\'] = $this->load->controller(\'extension/tmdsms/tmd_otplogin\');]]></add>\r\n		</operation>\r\n	</file>\r\n  <file path=\"catalog/controller/checkout/checkout.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$this->response->setOutput($this->load->view(\'checkout/checkout\', $data));]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			$data[\'mainstatus\'] = $this->config->get(\'tmdsms_status\');\r\n		$data[\'loginotpstatus\'] = $this->config->get(\'tmdsms_loginbtnstatus\');\r\n\r\n		$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n\r\n		if($tmdsmsotplogin){\r\n			$data[\'entry_loginotp\'] = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'loginbtntext\'];\r\n		} else {\r\n			$data[\'entry_loginotp\'] = $this->language->get(\'entry_loginotp\');\r\n		}\r\n\r\n			$data[\'tmd_otplogin\'] = $this->load->controller(\'extension/tmdsms/tmd_otplogin\');]]></add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/controller/account/register.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$this->error[\'telephone\'] = $this->language->get(\'error_telephone\');]]></search>\r\n			<add position=\"after\" offset=\"1\">\r\n				<![CDATA[\r\n				if ($this->model_account_customer->getTotalCustomersByPhone($this->request->post[\'telephone\'])) {\r\n					$this->error[\'warning\'] = $this->language->get(\'error_telephoneexists\');\r\n				}\r\n				]]>\r\n			</add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/controller/account/edit.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$this->document->setTitle($this->language->get(\'heading_title\'));]]></search>\r\n			<add position=\"before\">\r\n				<![CDATA[\r\n				$data[\'mainstatus\'] = $this->config->get(\'tmdsms_status\');\r\n				$data[\'otpverifystatus\'] = $this->config->get(\'tmdsms_otpverifystatus\');\r\n				$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n\r\n				if($tmdsmsotplogin){\r\n					$data[\'entry_label\'] = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'label2\'];\r\n				} else {\r\n					$data[\'entry_label\'] = $this->language->get(\'entry_label\');\r\n				}\r\n				]]>\r\n			</add>\r\n		</operation>\r\n\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[protected function validate() {]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n				public function chkphonenumber() {\r\n				$json=array();\r\n					$this->load->model(\'account/customer\');\r\n\r\n					$this->load->language(\'account/edit\');\r\n\r\n					$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n					if($tmdsmsotplogin){\r\n						$successmsg = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'successmsg\'];\r\n					} else {\r\n						$successmsg = $this->language->get(\'text_success\');\r\n					}\r\n\r\n\r\n					$customer_info = $this->model_account_customer->getCustomerByPhone($this->request->post[\'telephone\']);\r\n					if(empty($this->request->post[\'telephone\'])){\r\n						$json[\'error\'] = $this->language->get(\'error_telephone\');\r\n					} elseif(!empty($customer_info[\'telephone\']) == $this->request->post[\'telephone\']) {\r\n						$json[\'error\']= $this->language->get(\'error_existstelephone\');\r\n					} else {\r\n\r\n						$otpcode = rand(100000,999999);\r\n						$this->session->data[\'otpcode\']=$otpcode;\r\n						$find = array(\r\n							\'{code}\'\r\n						);\r\n\r\n						$this->load->model(\'tool/image\');\r\n						$replace = array(\r\n							\'code\' => $otpcode\r\n						);\r\n\r\n						$mobilemessage=str_replace(\'+\',\' \',urlencode(trim(str_replace($find, $replace, $this->config->get(\'tmdsms_otpmsg\')))));\r\n						$mobilemessage=str_replace(\' \',\' \',$mobilemessage);\r\n\r\n						if(!empty($mobilemessage)){\r\n							$sms_data = array(\r\n								\'telephone\' 	=> $this->request->post[\'telephone\'],\r\n								\'message\' 		=> $mobilemessage,\r\n								\'dltid\'			=> $this->config->get(\'tmdsms_otpmsg_dltid\')\r\n							);\r\n\r\n							$this->load->model(\'extension/tmdsms/tmdsms\');\r\n							$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n						}\r\n\r\n						$json[\'success\']= $successmsg;\r\n					}\r\n\r\n				$this->response->setOutput(json_encode($json));\r\n			}\r\n\r\n			public function addotp() {\r\n				$json=array();\r\n\r\n				$this->load->model(\'account/customer\');\r\n\r\n				$this->load->language(\'account/edit\');\r\n\r\n				$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n				if($tmdsmsotplogin){\r\n					$errormsg = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'errornotmatch\'];\r\n				} else {\r\n					$errormsg = $this->language->get(\'entry_errormsg\');\r\n				}\r\n\r\n				if($tmdsmsotplogin){\r\n					$invalidmsg = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'invalidotperrormsg\'];\r\n				} else {\r\n					$invalidmsg = $this->language->get(\'entry_invaliderrormsg\');\r\n				}\r\n\r\n\r\n				if($tmdsmsotplogin){\r\n					$successmsg = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'successmsg\'];\r\n				} else {\r\n					$successmsg = $this->language->get(\'text_success\');\r\n				}\r\n\r\n				$otpcode = $this->session->data[\'otpcode\'];\r\n				if(empty($this->request->post[\'otp\'])){\r\n					$json[\'error\'] = $errormsg;\r\n				} elseif($otpcode != $this->request->post[\'otp\']){\r\n					$json[\'error\'] = $invalidmsg;\r\n				} else {\r\n					$this->model_account_customer->addnewphone($this->request->post);\r\n					$json[\'success\'] = $successmsg;\r\n				}\r\n\r\n				$this->response->setOutput(json_encode($json));\r\n			}\r\n\r\n			public function resendotp(){\r\n				$this->load->language(\'extension/tmdsms/tmd_otplogin\');\r\n				$json=array();\r\n\r\n				$otpcode = rand(100000,999999);\r\n				$this->session->data[\'otpcode\']=$otpcode;\r\n				$find = array(\r\n					\'{code}\'\r\n				);\r\n\r\n				$this->load->model(\'tool/image\');\r\n				$replace = array(\r\n					\'code\' => $otpcode\r\n				);\r\n\r\n				$mobilemessage=str_replace(\'+\',\' \',urlencode(trim(str_replace($find, $replace, $this->config->get(\'tmdsms_otpmsg\')))));\r\n				$mobilemessage=str_replace(\' \',\' \',$mobilemessage);\r\n\r\n				if(!empty($mobilemessage)){\r\n					$sms_data = array(\r\n						\'telephone\' 	=> $this->customer->getTelephone(),\r\n						\'message\' 		=> $mobilemessage,\r\n						\'dltid\' 		=> $this->config->get(\'tmdsms_otpmsg_dltid\'),\r\n					);\r\n\r\n					$this->load->model(\'extension/tmdsms/tmdsms\');\r\n					$this->model_extension_tmdsms_tmdsms->sendSms($sms_data);\r\n				}\r\n\r\n				$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n				if($tmdsmsotplogin){\r\n					$successmsg = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'successmsg\'];\r\n				} else {\r\n					$successmsg = $this->language->get(\'entry_otpresendmsg\');\r\n				}\r\n				$json[\'success\']= $successmsg;\r\n\r\n				$this->response->setOutput(json_encode($json));\r\n			}\r\n				]]>\r\n			</add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/language/*/account/register.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[// Error]]></search>\r\n			<add position=\"before\">\r\n				<![CDATA[ $_[\'error_telephoneexists\']                  = \'Warning: Phone Number is already registered!\';\r\n				]]>\r\n			</add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/language/*/account/edit.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[// Error]]></search>\r\n			<add position=\"before\">\r\n				<![CDATA[$_[\'error_existstelephone\']       = \'Warning: Telephone Number is already registered!\';\r\n				$_[\'entry_label\'] = \'Enter OTP\';\r\n				]]>\r\n			</add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/view/theme/*/template/account/edit.twig\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[<label class=\"col-sm-2 control-label\" for=\"input-telephone\">{{ entry_telephone }}</label>]]></search>\r\n			<add position=\"before\" offset=\"1\">\r\n				<![CDATA[{% if mainstatus is not empty or otpverifystatus is not empty %}\r\n\r\n				  <div class=\"form-group required telehide\" id=\"tmdotpbox\">\r\n						<label class=\"col-sm-2 control-label\" for=\"input-telephone\">{{ entry_telephone }}</label>\r\n						<div class=\"col-sm-10\">\r\n							<div class=\"input-group telephoneerror\" >\r\n								<input type=\"tel\" maxlength=\"10\"  name=\"telephone\" disabled value=\"{{ telephone }}\" placeholder=\"{{ entry_telephone }}\" id=\"input-telephonenew\" class=\"form-control \" />\r\n								<span class=\"input-group-btn\">\r\n								<input type=\"button\" id=\"addnew\" class=\"btn btn-success\" value=\"Add new Number\">\r\n								<input type=\"button\" id=\"veify\" class=\"btn btn-success hide\" value=\"Submit\">\r\n								<input type=\"button\" id=\"cancel\" class=\"btn btn-danger hide\" value=\"Cancel\">\r\n								</span>\r\n							</div>\r\n						</div>\r\n					</div>\r\n\r\n					<div class=\"form-group required showotpinput\" id=\"otpverify\" style=\"display:none\">\r\n						<label class=\"col-sm-2 control-label\" for=\"input-telephone\">{{ entry_label }}</label>\r\n						<div class=\"col-sm-10\">\r\n							<div class=\"input-group otperror\">\r\n							<input type=\"number\" name=\"otp\" placeholder=\"{{ entry_label }}\" id=\"\" class=\"form-control\" />\r\n								<span class=\"input-group-btn\">\r\n								<input type=\"button\" id=\"verifyotp\" class=\"btn btn-success\" value=\"Verify\">\r\n								<input type=\"button\" id=\"resend-otp\" class=\"btn btn-primary\" value=\"Resend\">\r\n								</span>\r\n							</div>\r\n						</div>\r\n					</div>\r\n				  {% else %}\r\n				]]>\r\n			</add>\r\n		</operation>\r\n\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[{% for custom_field in custom_fields %}]]></search>\r\n			<add position=\"before\" offset=\"1\">\r\n				<![CDATA[{% endif %}\r\n				]]>\r\n			</add>\r\n		</operation>\r\n\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[{{ footer }}]]></search>\r\n			<add position=\"before\">\r\n				<![CDATA[\r\n					<script>\r\n					$(document).ready(function() {\r\n						$(\"#addnew\").click(function() {\r\n							$( \"#input-telephonenew\" ).prop( \"disabled\", false );\r\n							$(\"#veify\").removeClass(\"hide\");\r\n							$(\"#cancel\").removeClass(\"hide\");\r\n							$(\"#addnew\").addClass(\"hide\");\r\n						});\r\n\r\n						$(\"#cancel\").click(function() {\r\n							$(\"#input-telephonenew\" ).prop( \"disabled\", true );\r\n							$(\"#cancel\").addClass(\"hide\");\r\n							$(\"#veify\").addClass(\"hide\");\r\n							$(\"#addnew\").removeClass(\"hide\");\r\n						});\r\n					});\r\n\r\n					$(\'#veify\').bind(\'click\', function() {\r\n						$.ajax({\r\n							url: \'index.php?route=account/edit/chkphonenumber\',\r\n							type: \'post\',\r\n							data: $(\'#tmdotpbox input[type=\\\'tel\\\']\'),\r\n							dataType: \'json\',\r\n							beforeSend: function() {\r\n								$(\'#veify\').button(\'loading\');\r\n							},\r\n							complete: function() {\r\n								$(\'#veify\').button(\'reset\');\r\n							},\r\n\r\n							success: function(json) {\r\n								$(\'.alert, .alert-success, .text-danger\').remove();\r\n\r\n								if (json[\'error\']) {\r\n									$(\'.telephoneerror\').after(\'<div class=\"text-danger\">\'+ json[\'error\'] + \'</div>\');\r\n								}\r\n\r\n								if (json[\'success\']) {\r\n									$(\'#successmsg\').before(\'<div class=\"success-box\"><div class=\"alert alert-success\" style=\"padding:10px;\">\'+ json[\'success\'] +\'</div> </div>\');\r\n									$(\'.telehide\').hide();\r\n									$(\'#otpverify\').hide().fadeIn(800).delay(3000);\r\n									setTimeout(function(){ $(\'.success-box\').hide(); $(\'.showotpinput\').show(); }, 1000);\r\n								}\r\n							}\r\n						});\r\n					});\r\n\r\n					$(\'#verifyotp\').bind(\'click\', function() {\r\n					$.ajax({\r\n						url: \'index.php?route=account/edit/addotp\',\r\n						type: \'post\',\r\n						data: $(\'#otpverify input[type=\\\'number\\\']\'),\r\n						dataType: \'json\',\r\n						beforeSend: function() {\r\n							$(\'#verifyotp\').button(\'loading\');\r\n						},\r\n						complete: function() {\r\n							$(\'#verifyotp\').button(\'reset\');\r\n						},\r\n\r\n						success: function(json) {\r\n							$(\'.alert, .alert-success, .text-danger\').remove();\r\n\r\n							if (json[\'error\']) {\r\n								$(\'.otperror\').after(\'<div class=\"text-danger\">\'+ json[\'error\'] + \'</div>\');\r\n							}\r\n\r\n							if (json[\'success\']) {\r\n							$(\'#successmsg\').before(\'<div class=\"alert alert-success\">\'+ json[\'success\'] +\'<button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button></div>\');\r\n							$(\'input[name=otp]\').val(\'\');\r\n\r\n							$(\"#input-telephonenew\").prop( \"disabled\", true );\r\n							$(\'.telehide\').show();\r\n							$(\'.showotpinput\').hide();\r\n							$(\"#addnew\").removeClass(\"hide\");\r\n							$(\"#cancel\").addClass(\"hide\");\r\n							$(\"#veify\").addClass(\"hide\");\r\n\r\n							}\r\n						}\r\n						});\r\n					});\r\n\r\n					$(\'#resend-otp\').bind(\'click\', function() {\r\n					$.ajax({\r\n						url: \'index.php?route=account/edit/resendotp\',\r\n						type: \'post\',\r\n						dataType: \'json\',\r\n						beforeSend: function() {\r\n							$(\'#resend-otp\').button(\'loading\');\r\n						},\r\n						complete: function() {\r\n							$(\'#resend-otp\').button(\'reset\');\r\n						},\r\n						success: function(json) {\r\n						$(\'.alert, .alert-success, .text-danger\').remove();\r\n							$(\'#successmsg\').before(\'<div class=\"alert alert-success\" style=\"padding:10px;\">\'+ json[\'success\'] +\'</div>\');\r\n\r\n						}\r\n					});\r\n				});\r\n					</script>\r\n				]]>\r\n			</add>\r\n		</operation>\r\n	</file>\r\n		<file path=\"catalog/controller/checkout/login.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$this->response->setOutput($this->load->view(\'checkout/login\', $data));]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			$data[\'mainstatus\'] = $this->config->get(\'tmdsms_status\');\r\n		$data[\'loginotpstatus\'] = $this->config->get(\'tmdsms_loginbtnstatus\');\r\n\r\n		$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n\r\n		if($tmdsmsotplogin){\r\n			$data[\'entry_loginotp\'] = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'loginbtntext\'];\r\n		} else {\r\n			$data[\'entry_loginotp\'] = $this->language->get(\'entry_loginotp\');\r\n		}\r\n\r\n			$data[\'tmd_otplogin\'] = $this->load->controller(\'extension/tmdsms/tmd_otplogin\');]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/journal3/checkout.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$data[\'login_block\'] = $this->renderView(\'journal3/checkout/login\', array(]]></search>\r\n			<add position=\"before\">\r\n				<![CDATA[$data[\'mainstatus\'] = $this->config->get(\'tmdsms_status\');\r\n		$data[\'loginotpstatus\'] = $this->config->get(\'tmdsms_loginbtnstatus\');\r\n\r\n		$tmdsmsotplogin = $this->config->get(\'tmdsms_loginotp\');\r\n\r\n		if($tmdsmsotplogin){\r\n			$entry_loginotp = $tmdsmsotplogin[$this->config->get(\'config_language_id\')][\'loginbtntext\'];\r\n		} else {\r\n			$entry_loginotp = $this->language->get(\'entry_loginotp\');\r\n		}\r\n\r\n			$data[\'tmd_otplogin\'] = $this->load->controller(\'extension/tmdsms/tmd_otplogin\');\r\n				]]>\r\n			</add>\r\n		</operation>\r\n\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\'button_login\'   => $this->language->get(\'button_login\'),]]></search>\r\n			<add position=\"after\">\r\n				<![CDATA[\r\n				\'entry_loginotp\' 	=>$entry_loginotp,\r\n				\'loginotpstatus\' 	=>$data[\'loginotpstatus\'],\r\n				\'mainstatus\'=>$data[\'mainstatus\'],\r\n				]]>\r\n			</add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"catalog/view/theme/journal3/template/journal3/checkout/checkout.twig\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[<script>window[\'_QuickCheckoutData\'] = {{ checkout_data|json_encode }};</script>]]></search>\r\n			<add position=\"before\">\r\n				<![CDATA[{% if mainstatus == 1 %}\r\n			{% if loginotpstatus == 1 %}\r\n			<!--otp code start here-->\r\n			<div class=\"modal fade membershipModal\" role=\"dialog\">\r\n			<div class=\"modal-dialog modal-sm\">\r\n\r\n					{{ tmd_otplogin}}\r\n\r\n			</div>\r\n			</div>\r\n			{% endif %}\r\n			{% endif %}\r\n				]]>\r\n			</add>\r\n		</operation>\r\n\r\n	</file>\r\n\r\n	<file path=\"catalog/view/theme/journal3/template/journal3/checkout/login.twig\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[<button type=\"button\" id=\"button-login\" v-on:click=\"login()\" data-loading-text=\"<span>{{ button_login }}</span>\" class=\"btn btn-primary\"><span>{{ button_login }}</span></button>]]></search>\r\n			<add position=\"after\">\r\n				<![CDATA[{% if mainstatus == 1 %}\r\n              {% if loginotpstatus == 1 %}\r\n                <button style=\"margin-left:5px;\" type=\"button\" id=\"\" class=\"btn btn-primary membership\" data-toggle=\"modal\" data-target=\".membershipModal\">{{ entry_loginotp }}</button>\r\n              {% endif %}\r\n              {% endif %}\r\n				]]>\r\n			</add>\r\n		</operation>\r\n\r\n	</file>\r\n\r\n</modification>\r\n', 0, '2021-07-25 17:14:17');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(8, 14, 'Purpletree Custom Product Designer for OpenCart 3.x', 'Purpletree Custom Product Designer for OpenCart 3.x', 'Purpletree', '3.x', '', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification> \r\n  <name>Purpletree Custom Product Designer for OpenCart 3.x</name> \r\n  <code>Purpletree Custom Product Designer for OpenCart 3.x</code>  \r\n  <version>3.x</version>\r\n  <author>Purpletree</author> \r\n    <file path=\"admin/controller/startup/permission.php\"> \r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$extension = array(]]></search>\r\n			<add position=\"after\"><![CDATA[\'extension/purpletree_product_designer\',]]></add>\r\n		</operation>\r\n	</file>  \r\n    <file path=\"admin/controller/common/column_left.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$report = array();]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			if ($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				$this->load->language(\'purpletree_product_designer/admintemplate\');\r\n			$purpletree_product_designer = array();\r\n			\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/purpletree_product_designer\')) {\r\n			\r\n				$purpletree_product_designer[] = array(\r\n					\'name\'	   => $this->language->get(\'text_pd_setting\'),\r\n					\'href\'     => $this->url->link(\'extension/module/purpletree_product_designer\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n			if ($this->user->hasPermission(\'access\', \'extension/purpletree_product_designer/clipart\')) {			\r\n				$purpletree_product_designer[] = array(\r\n					\'name\'	   => $this->language->get(\'text_pd_clipart\'),\r\n					\'href\'     => $this->url->link(\'extension/purpletree_product_designer/clipart\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n				if ($this->user->hasPermission(\'access\', \'extension/purpletree_product_designer/product_designer_fonts\')) {			\r\n				$purpletree_product_designer[] = array(\r\n					\'name\'	   => $this->language->get(\'manage_fonts\'),\r\n					\'href\'     => $this->url->link(\'extension/purpletree_product_designer/product_designer_fonts\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n			if ($this->user->hasPermission(\'access\', \'extension/purpletree_product_designer/product_designer_products\')) {			\r\n				$purpletree_product_designer[] = array(\r\n					\'name\'	   => $this->language->get(\'manage_products\'),\r\n					\'href\'     => $this->url->link(\'extension/purpletree_product_designer/product_designer_products\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n		\r\n			if ($this->config->get(\'module_purpletree_product_designer_template\')) {\r\n			if ($this->user->hasPermission(\'access\', \'extension/purpletree_product_designer/producttemplate\')) {			\r\n				$purpletree_product_designer[] = array(\r\n					\'name\'	   => $this->language->get(\'manage_templates\'),\r\n					\'href\'     => $this->url->link(\'extension/purpletree_product_designer/producttemplate\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n			}\r\n			\r\n			if ($purpletree_product_designer) {\r\n				$data[\'menus\'][] = array(\r\n					\'id\'       => \'menu-custom-product-designer\',\r\n					\'icon\'	   => \'fa fa-paint-brush\', \r\n					\'name\'	   => $this->language->get(\'text_purpletree_online_product_designer\'),\r\n					\'href\'     => \'\',\r\n					\'children\' => $purpletree_product_designer\r\n				);	\r\n			}\r\n			}\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n	<file path=\"admin/controller/extension/extension/module.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$this->model_setting_extension->install(\'module\', $this->request->get[\'extension\']);]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			if($this->request->get[\'extension\']==\"purpletree_product_designer\"){\r\n				$this->load->model(\'extension/purpletree_product_designer/install\');\r\n						 $this->model_extension_purpletree_product_designer_install->CreateTables();\r\n						 $this->model_extension_purpletree_product_designer_install->addFontAwsomeicons();\r\n\r\n				$all_images= array();		\r\n				$all_images=glob(DIR_IMAGE.\"catalog/pts_clipart/*.*\");				\r\n				if(!empty($all_images)){			\r\n					foreach($all_images as $clipart_image ){\r\n						$pts_clipart=explode(\'image/\',$clipart_image);\r\n						$this->db->query(\"INSERT INTO `\" . DB_PREFIX . \"purpletree_clipart_image` SET clipart_image=\'\".$pts_clipart[1].\"\'\");\r\n					}\r\n				}\r\n								$fonts = array(\r\n					\'Arial\'=>\'\',\r\n					\'Arial Narrow\'=>\'\',\r\n					\'Calibri\'=>\'\',\r\n					\'Cairo\'=>\'sans-serif\',\r\n					\'Amiri\'=>\'serif\',\r\n					\'Lalezar\'=>\'cursive\',\r\n					\'El Messiri\'=>\'sans-serif\',\r\n					\'Changa\'=>\'sans-serif\',\r\n					\'Tajawal\'=>\'sans-serif\',\r\n					\'Scheherazade\'=>\'serif\',\r\n					\'Lateef\'=>\'cursive\',\r\n					\'Markazi Text\'=>\'serif\',\r\n					\'Mada\'=>\'sans-serif\',\r\n					\'Noto Sans\'=>\'sans-serif\',\r\n					\'Hind\'=>\'sans-serif\',\r\n					\'Rajdhani\'=>\'sans-serif\',\r\n					\'Mukta\'=>\'sans-serif\',\r\n					\'Teko\'=>\'sans-serif\',\r\n					\'Kalam\'=>\'cursive\',\r\n					\'Martel\'=>\'serif\',\r\n					\'Khand\'=>\'sans-serif\',\r\n					\'Pragati Narrow\'=>\'sans-serif\',\r\n					\'Glegoo\'=>\'serif\',\r\n					\'Amita\'=>\'cursive\',\r\n					\'Roboto\'=>\'sans-serif\',\r\n					\'Noto Sans HK\'=>\'sans-serif\',\r\n					\'Open Sans\'=>\'sans-serif\',\r\n					\'Lato\'=>\'sans-serif\',\r\n					\'Aguafina Script\'=>\'cursive\',\r\n					\'Montserrat\'=>\'sans-serif\',\r\n					\'Mali\'=>\'cursive\',\r\n					\'Source Sans Pro\'=>\'sans-serif\',\r\n					\'Roboto Condensed\'=>\'sans-serif\',\r\n					\'Roboto Mono\'=>\'monospace\',\r\n					\'Roboto Slab\'=>\'serif\',\r\n					\'Merriweather\'=>\'serif\',\r\n					\'Slabo 27px\'=>\'serif\',\r\n					\'Saira Semi Condensed\'=>\'sans-serif\',\r\n					\'PT Sans\'=>\'sans-serif\',\r\n					\'Ubuntu\'=>\'sans-serif\',\r\n					\'Open Sans Condensed\'=>\'sans-serif\',\r\n					\'Muli\'=>\'sans-serif\',\r\n					\'Dosis\'=>\'sans-serif\',\r\n					\'Crimson Text\'=>\'serif\',\r\n					\'Indie Flower\'=>\'cursive\',\r\n					\'Abel\'=>\'sans-serif\',\r\n					\'Pacifico\'=>\'cursive\',\r\n					\'Dancing Script\'=>\'cursive\',\r\n					\'Merriweather Sans\'=>\'sans-serif\',\r\n					\'Swanky and Moo Moo\'=>\'cursive\',\r\n					\'Shadows Into Light\'=>\'cursive\',\r\n					\'Barlow\'=>\'sans-serif\',\r\n					\'Oswald\'=>\'sans-serif\',\r\n				);\r\n				if(!empty($fonts)){\r\n					foreach ($fonts as $key => $value) {\r\n						$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"purpletree_google_font SET font_name=\'\".$key.\"\'\");\r\n					}\r\n				}\r\n			$help_image=array(\'module_purpletree_product_designer_help_img\'=>\'catalog/help_image.png\');\r\n			$this->load->model(\'setting/setting\');			\r\n			$this->model_setting_setting->editSetting(\'module_purpletree_product_designer\', $help_image);\r\n		}\r\n		\r\n		\r\n		\r\n		\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$this->model_setting_extension->uninstall(\'module\', $this->request->get[\'extension\']);]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			if($this->request->get[\'extension\']==\"purpletree_product_designer\"){\r\n				$query = $this->db->query(\"SHOW TABLES LIKE \'\" . DB_PREFIX . \"purpletree_product_design\'\");	\r\n				if($query->num_rows==1) \r\n				{\r\n					$this->db->query(\"DROP TABLE \". DB_PREFIX .\"purpletree_product_design\");					\r\n					$this->db->query(\"DROP TABLE \". DB_PREFIX .\"purpletree_clipart_image\");					\r\n					$this->db->query(\"DROP TABLE \". DB_PREFIX .\"purpletree_product_design_image\");					\r\n					$this->db->query(\"DROP TABLE \". DB_PREFIX .\"purpletree_canvas_order_image\");					\r\n					$this->db->query(\"DROP TABLE \". DB_PREFIX .\"purpletree_google_font\");					\r\n					$this->db->query(\"DROP TABLE \". DB_PREFIX .\"purpletree_templates_product\");					\r\n					$this->db->query(\"DROP TABLE \". DB_PREFIX .\"purpletree_design_templates\");					\r\n				}\r\n			}\r\n			]]></add>\r\n		</operation>         \r\n	</file>			\r\n	<file path=\"admin/controller/common/filemanager.php\"> \r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\'image/gif\']]></search>\r\n			<add position=\"after\"><![CDATA[,\'image/svg+xml\']]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\'png\']]></search>\r\n			<add position=\"after\"><![CDATA[,\'svg\']]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$files = glob($directory . \'/\' . $filter_name . \'*.{jpg,jpeg,png,gif,JPG,JPEG,PNG,GIF}\', GLOB_BRACE);]]></search>\r\n			<add position=\"replace\"><![CDATA[$files = glob($directory . \'/\' . $filter_name . \'*.{jpg,jpeg,png,gif,svg,JPG,JPEG,PNG,GIF,SVG}\', GLOB_BRACE);]]></add>\r\n		</operation>	\r\n\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[} elseif (is_file($image)) {]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n					$ext    = substr(basename($image), strrpos(basename($image), \'.\')+1);\r\n					$svgimg = explode(\'image/\',$image);\r\n					$thumb  = $this->model_tool_image->resize(utf8_substr($image, utf8_strlen(DIR_IMAGE)), 100, 100);\r\n					if($ext == \'svg\') {\r\n						$thumb = $server . \'image/\' .$svgimg[1];\r\n					}\r\n					]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\'thumb\' => $this->model_tool_image->resize(utf8_substr($image, utf8_strlen(DIR_IMAGE)), 100, 100),]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					\'thumb\' => $thumb,\r\n					]]></add>\r\n		</operation>\r\n	</file>  	\r\n	<file path=\"admin/view/template/common/filemanager.twig\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[<a href=\"{{ image.href }}\" class=\"thumbnail\"><img src=\"{{ image.thumb }}\" alt=\"{{ image.name }}\" title=\"{{ image.name }}\" /></a>]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n			<a href=\"{{ image.href }}\" class=\"thumbnail\"><img height=\"100\" width=\"100\" src=\"{{ image.thumb }}\" alt=\"{{ image.name }}\" title=\"{{ image.name }}\" /></a>\r\n					 \r\n					]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/common/header.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[public function index() {]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				if (isset($this->request->get[\'route\'])) {\r\n					if (isset($this->request->get[\'route\']) && ($this->request->get[\'route\'] == \'catalog/product/edit\' || $this->request->get[\'route\'] == \'catalog/product/add\' || $this->request->get[\'route\'] == \'extension/purpletree_product_designer/producttemplate/editTemplate\')) {\r\n						$data[\'module_purpletree_product_designer_status\'] = $this->config->get(\'module_purpletree_product_designer_status\');\r\n					}\r\n				}  \r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/view/template/common/header.twig\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[jquery-2.1.1.min.js]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				{% if module_purpletree_product_designer_status %}\r\n				<script src=\"../catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/jquery-ui.js\" type=\"text/javascript\"></script>\r\n				{% endif %}\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/common/header.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[public function index(]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n		if(isset($this->request->get[\'route\']) && $this->request->get[\'route\'] == \'extension/purpletree_product_designer/product_template_designer\' && $this->config->get(\'module_purpletree_product_designer_status\')) {\r\n		$data[\'module_purpletree_product_designer_status\'] = $this->config->get(\'module_purpletree_product_designer_status\');\r\n		if($this->config->get(\'module_purpletree_product_designer_jquery\')) {\r\n			$data[\'module_purpletree_product_designer_jquery\'] = $this->config->get(\'module_purpletree_product_designer_jquery\');\r\n		}\r\n		if($this->config->get(\'module_purpletree_product_designer_jquery_ui\')) {\r\n			$data[\'module_purpletree_product_designer_jquery_ui\'] = $this->config->get(\'module_purpletree_product_designer_jquery_ui\');\r\n		}\r\n		if($this->config->get(\'module_purpletree_product_designer_bootstrapjs\')) {\r\n			$data[\'module_purpletree_product_designer_bootstrapjs\'] = $this->config->get(\'module_purpletree_product_designer_bootstrapjs\');\r\n		}\r\n		}\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/view/theme/*/template/common/header.twig\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[jquery-2.1.1.min.js]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				{% if module_purpletree_product_designer_jquery_ui %}\r\n<script src=\"catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/jquery-ui.js\" type=\"text/javascript\"></script>\r\n{% endif %}\r\n				]]></add>\r\n		</operation>\r\n				<operation error=\"skip\">\r\n				<search><![CDATA[</head>]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				{% if module_purpletree_product_designer_status %}\r\n				{% if module_purpletree_product_designer_jquery %}\r\n				<script src=\"catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/jquery-2.1.1.min.js\" type=\"text/javascript\"></script>\r\n				\r\n				{% if module_purpletree_product_designer_jquery_ui %}\r\n				<script src=\"catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/jquery-ui.js\" type=\"text/javascript\"></script>\r\n				{% endif %}\r\n				{% endif %}\r\n				{% if module_purpletree_product_designer_bootstrapjs %}\r\n				<script src=\"catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/bootstrap.min.js\" type=\"text/javascript\"></script>\r\n				{% endif %}\r\n				<script src=\"catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/cmykcolorpicker/jquery.colorpicker.js\"></script>\r\n				<link href=\"catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/cmykcolorpicker/jquery.colorpicker.css\" rel=\"stylesheet\" type=\"text/css\"/>\r\n				{% endif %}\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/journal2/settings.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[bootstrap.min.js]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				if($this->config->get(\'module_purpletree_product_designer_jquery_ui\')) {	$this->journal2->minifier->addScript(\'catalog/view/theme/default/stylesheet/ptsproductdesign/jquery/jquery-ui.js\', \'header\');\r\n			}\r\n			}\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[jquery-ui-slider.min.js]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				if (isset($this->request->get[\'route\']) && $this->request->get[\'route\'] == \'extension/purpletree_product_designer/product_template_designer\') {\r\n				} else {\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[jquery-ui-slider.min.js]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				}\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/view/template/sale/order_info.twig\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[{% endfor %}</td>]]></search>\r\n				<add position=\"replace\"><![CDATA[\r\n				{% endfor %}\r\n				{% if product.canvas_images %}\r\n			<div><small> - Preview Image &nbsp &nbsp  </small>\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.image_full }}\"><img src=\"{{ canvas_image.product_image }}\" alt=\"{{ canvas_image.image_label }}\" title=\"{{ canvas_image.image_label }}\" class=\"img-thumbnail\" /></a>\r\n				{% endfor %}\r\n				</div>\r\n					<div style=\"margin-top: 6px;\"><small> - Download Image</small>\r\n					{% set i=1 %}\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.canvas_image_full }}\" download=\"{{ canvas_image.canvas_image_full }}\"><span style=\" padding: 4px 10.5px; line-height: 1.42857; background-color: #fff; border: 1px solid #ddd; border-radius: 3px; display: inline-block; max-width: 100%; height: auto;\">{{ i }}</span></a>\r\n						 {% set i=i+1 %}\r\n				{% endfor %}\r\n				</div>\r\n				<div style=\"margin-top: 6px;\"><small> - Download JPG Image</small>\r\n					{% set i=1 %}\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.canvas_jpg_image_wtwm_full }}\" ><span style=\" padding: 4px 10.5px; line-height: 1.42857; background-color: #fff; border: 1px solid #ddd; border-radius: 3px; display: inline-block; max-width: 100%; height: auto;\">{{ i }}</span></a>\r\n						 {% set i=i+1 %}\r\n				{% endfor %}\r\n				</div>\r\n\r\n				<div style=\"margin-top: 6px;\"><small> - Download pdf </small>\r\n					<a href=\"{{ product.img_download }}\"><i class=\"fa fa-file-pdf-o\" style=\"font-size:25px;color:red;margin-left: 18px;\"></i></a>	\r\n				</div>\r\n				<div style=\"margin-top: 6px;\"><small> - Download without watermark pdf </small>\r\n					<a href=\"{{ product.img_wm_download }}\"><i class=\"fa fa-file-pdf-o\" style=\"font-size:25px;color:red;margin-left: 18px;\"></i></a>	\r\n				</div>\r\n				{% endif %}\r\n			  </td>\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/model/sale/order.php\"> \r\n		<operation error=\"skip\">\r\n				<search><![CDATA[class ModelSaleOrder extends Model ]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n				public function getCanvasFromOrder($order_id,$product_id){\r\n					$sql   = \"SELECT * FROM \" . DB_PREFIX . \"purpletree_canvas_order_image pcoi WHERE order_id = \'\" . $order_id . \"\' AND product_id = \'\" . $product_id . \"\' ORDER BY `id` ASC\";\r\n					$query = $this->db->query($sql);\r\n					$data  = array();\r\n						if($query->num_rows>0){	\r\n							$data = $query->rows;\r\n						} \r\n					return $data;\r\n					}\r\n					\r\n						public function getProductDesignStatus($product_id){\r\n					$sql   = \"SELECT status FROM \" . DB_PREFIX . \"purpletree_product_design  WHERE product_id = \'\" . $product_id . \"\'\";\r\n					$query = $this->db->query($sql);\r\n					$data  = array();\r\n						if($query->num_rows>0){	\r\n							return $query->row[\'status\'];\r\n							\r\n						} else {\r\n							return NULL;\r\n						}\r\n					\r\n					}\r\n				//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/sale/order.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$data[\'products\'][] = array(]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				\r\n				//purpletree_product_designer_status\r\n				$product[\'canvas_image_c\'] = array();\r\n				$pdfUrl=\'\';\r\n				$canvas_images = $this->model_sale_order->getCanvasFromOrder($this->request->get[\'order_id\'],$product[\'product_id\']);\r\n				$productDesignStatus = $this->model_sale_order->getProductDesignStatus($product[\'product_id\']);\r\n				//if($productDesignStatus) {\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				if(!empty($canvas_images)) {\r\n				if ($this->request->server[\'HTTPS\']) {\r\n					$image_full = HTTPS_CATALOG . \'image/\';\r\n				} else {\r\n					$image_full = HTTP_CATALOG . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					foreach($canvas_images as $key => $orderitems) {\r\n						$product[\'canvas_image_c\'][$key] = array(\r\n						\'id\' => $orderitems[\'id\'],\r\n						\'image_label\' => $orderitems[\'image_label\'],\r\n						\'product_image\'=> $this->model_tool_image->resize($orderitems[\'product_image\'],20,20),\r\n						\'canvas_image\'=> $this->model_tool_image->resize($orderitems[\'canvas_image\'],20,20),\r\n						\'image_full\'=> $image_full.$orderitems[\'product_image\'],\r\n						\'canvas_image_full\'=> $image_full.$orderitems[\'canvas_image\'],\r\n						\'canvas_jpg_image_wtwm_full\' => $this->url->link(\'sale/order/downloadjpeg\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&product_id=\' . $product[\'product_id\']. \'&key=\' . $key. \'&order_id=\' . $this->request->get[\'order_id\'], true)\r\n						);\r\n					}\r\n				}\r\n					$pdfUrl=$this->url->link(\'sale/order/download_pdi\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&product_id=\' . $product[\'product_id\']. \'&order_id=\' . $this->request->get[\'order_id\'], true);\r\n					$pdfWithoutWMUrl=$this->url->link(\'sale/order/download_without_wm_pdf\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&product_id=\' . $product[\'product_id\']. \'&order_id=\' . $this->request->get[\'order_id\'], true);\r\n			}\r\n			//purpletree_product_designer_status\r\n			\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$data[\'products\'][] = array(]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				\'canvas_images\'  => $product[\'canvas_image_c\'],\r\n				]]></add>\r\n		</operation>	\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[\'href\'     		   => $this->url->link(\'catalog/product/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&product_id=\' . $product[\'product_id\'], true)]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				,\'img_download\'     	 => $pdfUrl\r\n				,\'img_wm_download\'     	 => $pdfWithoutWMUrl\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[public function info() {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n					public function download_pdi() {\r\n				$this->load->model(\'sale/order\');\r\n				$product_designer = array();\r\n				$canvas_images_d = $this->model_sale_order->getCanvasFromOrder($this->request->get[\'order_id\'],$this->request->get[\'product_id\']);\r\n				require_once( DIR_SYSTEM.\'library/purpletree_product_designer/fpdf.php\' );\r\n\r\n				if(!empty($canvas_images_d)) {\r\n						if ($this->request->server[\'HTTPS\']) {\r\n					$image_full_d = HTTPS_CATALOG . \'image/\';\r\n				} else {\r\n					$image_full_d = HTTP_CATALOG . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					$size_unit=0;\r\n					foreach($canvas_images_d as $orderitems_d) {\r\n						$labelll = explode(\'_\', $orderitems_d[\'image_label\']);\r\n						$resolution = \'\';\r\n						if(isset($labelll[2]) && isset($labelll[1]) && is_numeric($labelll[2])) {\r\n							$resolution = $labelll[1];\r\n						}\r\n						$onepixel = 1;\r\n						if($resolution != \'\' and $resolution > 0) {\r\n							 $onepixel = 25.4/$resolution;\r\n						}\r\n						list($width, $height, $type, $attr) = getimagesize($image_full_d.$orderitems_d[\'canvas_image\']);\r\n						$img_width[]=$width*$onepixel;\r\n						$img_height[]=$height*$onepixel;\r\n						$size_unit = $orderitems_d[\'size_unit\'];\r\n					}\r\n					if($size_unit==1){\r\n						$size_unit=\'mm\';		\r\n					} else if($size_unit==2){\r\n						$size_unit=\'cm\';\r\n					} else if($size_unit==3){\r\n						$size_unit=\'foot\';\r\n					} else if($size_unit==4){\r\n						$size_unit=\'in\';\r\n					} else {\r\n						$size_unit=\'mm\';	\r\n					}\r\n					\r\n					$max_width=max($img_width)*(0.464583);\r\n					$max_height=max($img_height)*(0.464583);\r\n				$pdf = new FPDF(\'L\',$size_unit,array($max_width,$max_height));\r\n				\r\n					foreach($canvas_images_d as $keyyy => $orderitems_d) {\r\n						$sizee = array($img_height[$keyyy],$img_width[$keyyy]);\r\n							$orentation = \"L\";\r\n						if($img_height[$keyyy] > $img_width[$keyyy]) {\r\n							$orentation = \"P\";\r\n						}\r\n						$pdf->AddPage($orentation,$sizee);\r\n						$pdf->Image($image_full_d.$orderitems_d[\'canvas_image\'],0,0,$img_width[$keyyy],$img_height[$keyyy]);\r\n					}\r\n					$pdf->Output(\"D\",\"purpletree_product_designer.pdf\");\r\n				}\r\n		\r\n	}\r\n	\r\n		public function download_without_wm_pdf() {\r\n				$this->load->model(\'sale/order\');\r\n				$product_designer = array();\r\n				$canvas_images_d = $this->model_sale_order->getCanvasFromOrder($this->request->get[\'order_id\'],$this->request->get[\'product_id\']);\r\n				require_once( DIR_SYSTEM.\'library/purpletree_product_designer/fpdf.php\' );\r\n\r\n				if(!empty($canvas_images_d)) {\r\n						if ($this->request->server[\'HTTPS\']) {\r\n					$image_full_d = HTTPS_CATALOG . \'image/\';\r\n				} else {\r\n					$image_full_d = HTTP_CATALOG . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					$size_unit =0;\r\n					foreach($canvas_images_d as $orderitems_d) {\r\n						$labelll = explode(\'_\', $orderitems_d[\'image_label\']);\r\n						$resolution = \'\';\r\n						if(isset($labelll[2]) && isset($labelll[1]) && is_numeric($labelll[2])) {\r\n							$resolution = $labelll[1];\r\n						}\r\n						$onepixel = 1;\r\n						if($resolution != \'\' and $resolution > 0) {\r\n							 $onepixel = 25.4/$resolution;\r\n						}\r\n						list($width, $height, $type, $attr) = getimagesize($image_full_d.$orderitems_d[\'image_without_wm\']);\r\n						$img_width[]=$width*$onepixel;\r\n						$img_height[]=$height*$onepixel;\r\n						$size_unit = $orderitems_d[\'size_unit\'];\r\n					}\r\n					\r\n					if($size_unit==1){\r\n						$size_unit=\'mm\';		\r\n					} else if($size_unit==2){\r\n						$size_unit=\'cm\';\r\n					} else if($size_unit==3){\r\n						$size_unit=\'foot\';\r\n					} else if($size_unit==4){\r\n						$size_unit=\'in\';\r\n					} else {\r\n						$size_unit=\'mm\';	\r\n					}\r\n					$max_width=max($img_width)*(0.464583);\r\n					$max_height=max($img_height)*(0.464583);\r\n				$pdf = new FPDF(\'L\',$size_unit,array($max_width,$max_height));\r\n				\r\n					foreach($canvas_images_d as $keyyy => $orderitems_d) {\r\n						$sizee = array($img_height[$keyyy],$img_width[$keyyy]);\r\n							$orentation = \"L\";\r\n						if($img_height[$keyyy] > $img_width[$keyyy]) {\r\n							$orentation = \"P\";\r\n						}\r\n						$pdf->AddPage($orentation,$sizee);\r\n						$pdf->Image($image_full_d.$orderitems_d[\'image_without_wm\'],0,0,$img_width[$keyyy],$img_height[$keyyy]);\r\n					}\r\n					$pdf->Output(\"D\",\"purpletree_product_designer.pdf\");\r\n				}\r\n		\r\n	}\r\n	\r\n		public function downloadjpeg() {\r\n		\r\n//purpletree_product_designer_status\r\n				//$product[\'canvas_image_c\'] = array();\r\n				$image_url=\'\';\r\n				$pdfUrl=\'\';\r\n				$this->load->model(\'sale/order\');\r\n				$canvas_images = $this->model_sale_order->getCanvasFromOrder($this->request->get[\'order_id\'],$this->request->get[\'product_id\']);\r\n				$productDesignStatus = $this->model_sale_order->getProductDesignStatus($this->request->get[\'product_id\']);\r\n				//if($productDesignStatus) {\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				if(!empty($canvas_images)) {\r\n				if ($this->request->server[\'HTTPS\']) {\r\n					$image_full = HTTPS_CATALOG . \'image/\';\r\n				} else {\r\n					$image_full = HTTP_CATALOG . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					\r\n					foreach($canvas_images as $key => $orderitems) {\r\n						if($key == $this->request->get[\'key\']) {\r\n						$img=$image_full.$orderitems[\'image_without_wm\'];	\r\n					if(is_file(DIR_IMAGE.$orderitems[\'image_without_wm\'])){						\r\n						$createImg = imagecreatefrompng(DIR_IMAGE.$orderitems[\'image_without_wm\']);\r\n						$imgSize = GetImageSize($img);\r\n						$newJpgFileName=pathinfo($orderitems[\'image_without_wm\'], PATHINFO_FILENAME);\r\n						$marge_right = 0;\r\n						$marge_bottom = 0;\r\n						if($imgSize[2] == 1){ \r\n							$img = imagecreatefromgif($img);\r\n							$sx = imagesx($createImg);\r\n							$sy = imagesy($createImg);\r\n							$white = imagecolorallocate($img,  255, 255, 255);\r\n							imagefilledrectangle($img, 0, 0, imagesx($createImg), imagesy($createImg), $white);\r\n							imagecopy($img, $createImg, imagesx($img) - $sx - $marge_right, imagesy($img) - $sy - $marge_bottom, 0, 0, imagesx($createImg), imagesy($createImg));\r\n							imagegif($img,DIR_IMAGE.\"catalog/ptsdesigner/\".$newJpgFileName.\'.jpg\');\r\n							$image_root=\"catalog/ptsdesigner/\".$newJpgFileName.\".jpg\";\r\n						}elseif($imgSize[2] == 2){\r\n							$img = imagecreatefromjpeg($img);\r\n							$sx = imagesx($createImg);\r\n							$sy = imagesy($createImg);\r\n							$white = imagecolorallocate($img,  255, 255, 255);\r\n							imagefilledrectangle($img, 0, 0, imagesx($createImg), imagesy($createImg), $white);\r\n							imagecopy($img, $createImg, imagesx($img) - $sx - $marge_right, imagesy($img) - $sy - $marge_bottom, 0, 0, imagesx($createImg), imagesy($createImg));\r\n							imagejpeg($img,DIR_IMAGE.\"catalog/ptsdesigner/\".$newJpgFileName.\'.jpg\');\r\n							$image_root=\"catalog/ptsdesigner/\".$newJpgFileName.\".jpg\";\r\n						}elseif($imgSize[2] == 3){\r\n							$img = imagecreatefrompng($img);\r\n							$sx = imagesx($createImg);\r\n							$sy = imagesy($createImg);\r\n							$white = imagecolorallocate($img,  255, 255, 255);\r\n							imagefilledrectangle($img, 0, 0, imagesx($createImg), imagesy($createImg), $white);\r\n							imagecopy($img, $createImg, imagesx($img) - $sx - $marge_right, imagesy($img) - $sy - $marge_bottom, 0, 0, imagesx($createImg), imagesy($createImg));\r\n							imagepng($img,DIR_IMAGE.\"catalog/ptsdesigner/\".$newJpgFileName.\'.jpg\');\r\n							$image_root=\"catalog/ptsdesigner/\".$newJpgFileName.\".jpg\";\r\n						}\r\n						$image_url = $image_full.$image_root;\r\n						}\r\n						}\r\n					}\r\n				}\r\n				\r\n			}\r\nheader(\'Content-Type: application/octet-stream\');\r\nheader(\"Content-Transfer-Encoding: Binary\"); \r\nheader(\"Content-disposition: attachment; filename=\\\"\" . basename($image_url) . \"\\\"\"); \r\nreadfile($image_url); \r\n			//purpletree_product_designer_status\r\n	}\r\n	\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/account.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$this->load->view]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n		if ($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n			$data[\'module_purpletree_product_designer_status\'] = $this->config->get(\'module_purpletree_product_designer_status\');\r\n			$data[\'save_later\'] = $this->url->link(\'extension/purpletree_product_designer/product_designer_saved\', \'\', true);\r\n		}\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/view/theme/*/template/extension/module/account.twig\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[text_logout]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				{% if module_purpletree_product_designer_status %}\r\n				<li style=\"list-style: none;\"><a href=\"{{ save_later }}\" class=\"list-group-item\">Saved Designs</a></li>\r\n				{% endif %}\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/account/order.php\">\r\n	<operation error=\"skip\">\r\n				<search><![CDATA[public function getOrder($order_id) {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n								//module_purpletree_product_designer_status\r\n				public function getCanvasFromOrder($order_id,$product_id){\r\n					$sql   = \"SELECT * FROM \" . DB_PREFIX . \"purpletree_canvas_order_image pcoi WHERE order_id = \'\" . $order_id . \"\' AND product_id = \'\" . $product_id . \"\' ORDER BY `id` ASC\";\r\n					$query = $this->db->query($sql);\r\n					$data  = array();\r\n						if($query->num_rows>0){	\r\n							$data = $query->rows;\r\n						} \r\n					return $data;\r\n					}\r\n					\r\n						public function getProductDesignStatus($product_id){\r\n					$sql   = \"SELECT status FROM \" . DB_PREFIX . \"purpletree_product_design  WHERE product_id = \'\" . $product_id . \"\'\";\r\n					$query = $this->db->query($sql);\r\n					$data  = array();\r\n						if($query->num_rows>0){	\r\n							return $query->row[\'status\'];\r\n							\r\n						} else {\r\n							return NULL;\r\n						}\r\n					\r\n					}\r\n				//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	\r\n	<file path=\"catalog/controller/account/order.php\">\r\n	<operation error=\"skip\">\r\n				<search><![CDATA[if ($upload_info) {]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				$mask = basename($upload_info[\'name\']);\r\n						if ($this->request->server[\'HTTPS\']) {\r\n							$designurl = $this->config->get(\'config_ssl\') . \'image/catalog/ptsdesigner/\' . $mask;\r\n						} else {\r\n							$designurl = $this->config->get(\'config_url\') . \'image/catalog/ptsdesigner/\' . $mask;\r\n						}\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$option_data[] = array(]]></search>\r\n				<add position=\"after\"><![CDATA[\'designurl\'  => $designurl,]]></add>\r\n		</operation>\r\n		\r\n	<operation error=\"skip\">\r\n		<search><![CDATA[foreach ($products as $product) {]]></search>\r\n			<add position=\"before\"><![CDATA[				\r\n			$this->load->model(\'extension/purpletree_product_designer/product_designer\');\r\n			$buy_design_sts= $this->model_extension_purpletree_product_designer_product_designer->getBuyDesignStatus($order_id);\r\n				]]></add>\r\n	</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$option_data = array();]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				$designurl = \'\';\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$data[\'products\'][] = array(]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				//purpletree_product_designer_status\r\n				$product[\'canvas_image_c\'] = array();\r\n				$pdfUrl=\'\';\r\n				$this->load->model(\'account/order\');\r\n				$canvas_images = $this->model_account_order->getCanvasFromOrder($order_id,$product[\'product_id\']);\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				if(!empty($canvas_images)) {\r\n				if ($this->request->server[\'HTTPS\']) {\r\n					$image_full = $this->config->get(\'config_ssl\') . \'image/\';\r\n				} else {\r\n					$image_full = $this->config->get(\'config_url\') . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					$image_url=\'\';\r\n\r\n					foreach($canvas_images as $key => $orderitems) {\r\n						$product[\'canvas_image_c\'][$key] = array(\r\n						\'id\' => $orderitems[\'id\'],\r\n						\'image_label\' => $orderitems[\'image_label\'],\r\n						\'product_image\'=> $this->model_tool_image->resize($orderitems[\'product_image\'],20,20),\r\n						\'canvas_image\'=> $this->model_tool_image->resize($orderitems[\'canvas_image\'],20,20),\r\n						\'image_full\'=> $image_full.$orderitems[\'product_image\'],\r\n						\'canvas_image_full\'=> $image_full.$orderitems[\'canvas_image\'],\r\n						\'canvas_jpg_image_wtwm_full\' => $this->url->link(\'account/order/downloadjpeg\', \'&product_id=\' . $product[\'product_id\']. \'&key=\' . $key. \'&order_id=\' . $this->request->get[\'order_id\'], true)\r\n						);\r\n					}\r\n				}\r\n				$pdfUrl=$this->url->link(\'account/order/download_pdi\', \'&product_id=\' . $product[\'product_id\']. \'&order_id=\' . $this->request->get[\'order_id\'], true);\r\n				\r\n				$pdfWithoutWMUrl=$this->url->link(\'account/order/download_without_wm_pdf\', \'&product_id=\' . $product[\'product_id\']. \'&order_id=\' . $this->request->get[\'order_id\'], true);\r\n				}\r\n				\r\n				$data[\'module_purpletree_product_designer_status\'] = $this->config->get(\'module_purpletree_product_designer_status\');\r\n				\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$data[\'products\'][] = array(]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n					\'canvas_images\'  => $product[\'canvas_image_c\'],\r\n					\'img_download\'     	 => $pdfUrl,\r\n					\'img_wm_download\'     	 => $pdfWithoutWMUrl,\r\n					\'buy_design_sts\'     	 => $buy_design_sts,\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[public function info() {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				\r\n						public function downloadjpeg() {\r\n		\r\n//purpletree_product_designer_status\r\n				//$product[\'canvas_image_c\'] = array();\r\n				$image_url=\'\';\r\n				$pdfUrl=\'\';\r\n				$this->load->model(\'account/order\');\r\n				$canvas_images = $this->model_account_order->getCanvasFromOrder($this->request->get[\'order_id\'],$this->request->get[\'product_id\']);\r\n				$productDesignStatus = $this->model_account_order->getProductDesignStatus($this->request->get[\'product_id\']);\r\n				//if($productDesignStatus) {\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				if(!empty($canvas_images)) {\r\n				if ($this->request->server[\'HTTPS\']) {\r\n					$image_full = $this->config->get(\'config_ssl\') . \'image/\';\r\n				} else {\r\n					$image_full = $this->config->get(\'config_url\') . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					\r\n					foreach($canvas_images as $key => $orderitems) {\r\n						if($key == $this->request->get[\'key\']) {\r\n						$img=$image_full.$orderitems[\'image_without_wm\'];	\r\n					if(is_file(DIR_IMAGE.$orderitems[\'image_without_wm\'])){						\r\n						$createImg = imagecreatefrompng(DIR_IMAGE.$orderitems[\'image_without_wm\']);\r\n						$imgSize = GetImageSize($img);\r\n						$newJpgFileName=pathinfo($orderitems[\'image_without_wm\'], PATHINFO_FILENAME);\r\n						$marge_right = 0;\r\n						$marge_bottom = 0;\r\n						if($imgSize[2] == 1){ \r\n							$img = imagecreatefromgif($img);\r\n							$sx = imagesx($createImg);\r\n							$sy = imagesy($createImg);\r\n							$white = imagecolorallocate($img,  255, 255, 255);\r\n							imagefilledrectangle($img, 0, 0, imagesx($createImg), imagesy($createImg), $white);\r\n							imagecopy($img, $createImg, imagesx($img) - $sx - $marge_right, imagesy($img) - $sy - $marge_bottom, 0, 0, imagesx($createImg), imagesy($createImg));\r\n							imagegif($img,DIR_IMAGE.\"catalog/ptsdesigner/\".$newJpgFileName.\'.jpg\');\r\n							$image_root=\"catalog/ptsdesigner/\".$newJpgFileName.\".jpg\";\r\n						}elseif($imgSize[2] == 2){\r\n							$img = imagecreatefromjpeg($img);\r\n							$sx = imagesx($createImg);\r\n							$sy = imagesy($createImg);\r\n							$white = imagecolorallocate($img,  255, 255, 255);\r\n							imagefilledrectangle($img, 0, 0, imagesx($createImg), imagesy($createImg), $white);\r\n							imagecopy($img, $createImg, imagesx($img) - $sx - $marge_right, imagesy($img) - $sy - $marge_bottom, 0, 0, imagesx($createImg), imagesy($createImg));\r\n							imagejpeg($img,DIR_IMAGE.\"catalog/ptsdesigner/\".$newJpgFileName.\'.jpg\');\r\n							$image_root=\"catalog/ptsdesigner/\".$newJpgFileName.\".jpg\";\r\n						}elseif($imgSize[2] == 3){\r\n							$img = imagecreatefrompng($img);\r\n							$sx = imagesx($createImg);\r\n							$sy = imagesy($createImg);\r\n							$white = imagecolorallocate($img,  255, 255, 255);\r\n							imagefilledrectangle($img, 0, 0, imagesx($createImg), imagesy($createImg), $white);\r\n							imagecopy($img, $createImg, imagesx($img) - $sx - $marge_right, imagesy($img) - $sy - $marge_bottom, 0, 0, imagesx($createImg), imagesy($createImg));\r\n							imagepng($img,DIR_IMAGE.\"catalog/ptsdesigner/\".$newJpgFileName.\'.jpg\');\r\n							$image_root=\"catalog/ptsdesigner/\".$newJpgFileName.\".jpg\";\r\n						}\r\n						$image_url = $image_full.$image_root;\r\n						}\r\n						}\r\n					}\r\n				}\r\n				\r\n			}\r\nheader(\'Content-Type: application/octet-stream\');\r\nheader(\"Content-Transfer-Encoding: Binary\"); \r\nheader(\"Content-disposition: attachment; filename=\\\"\" . basename($image_url) . \"\\\"\"); \r\nreadfile($image_url); \r\n			//purpletree_product_designer_status\r\n	}\r\n	\r\n						public function download_pdi() {\r\n				$this->load->model(\'account/order\');\r\n				$product_designer = array();\r\n				$canvas_images_d = $this->model_account_order->getCanvasFromOrder($this->request->get[\'order_id\'],$this->request->get[\'product_id\']);\r\n				require_once( DIR_SYSTEM.\'library/purpletree_product_designer/fpdf.php\' );\r\n\r\n				if(!empty($canvas_images_d)) {\r\n							if ($this->request->server[\'HTTPS\']) {\r\n					$image_full_d = $this->config->get(\'config_ssl\') . \'image/\';\r\n				} else {\r\n					$image_full_d = $this->config->get(\'config_url\') . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					$size_unit =0;\r\n					foreach($canvas_images_d as $orderitems_d) {\r\n						$labelll = explode(\'_\', $orderitems_d[\'image_label\']);\r\n						$resolution = \'\';\r\n						if(isset($labelll[2]) && isset($labelll[1]) && is_numeric($labelll[2])) {\r\n							$resolution = $labelll[1];\r\n						}\r\n						$onepixel = 1;\r\n						if($resolution != \'\' and $resolution > 0) {\r\n							 $onepixel = 25.4/$resolution;\r\n						}\r\n						list($width, $height, $type, $attr) = getimagesize($image_full_d.$orderitems_d[\'canvas_image\']);\r\n						$img_width[]=$width*$onepixel;\r\n						$img_height[]=$height*$onepixel;\r\n						$size_unit = $orderitems_d[\'size_unit\'];\r\n					}\r\n					$max_width=max($img_width)*(0.464583);\r\n					$max_height=max($img_height)*(0.464583);\r\n					\r\n					if($size_unit==1){\r\n						$size_unit=\'mm\';		\r\n					} else if($size_unit==2){\r\n						$size_unit=\'cm\';\r\n					} else if($size_unit==3){\r\n						$size_unit=\'foot\';\r\n					} else if($size_unit==4){\r\n						$size_unit=\'in\';\r\n					} else {\r\n						$size_unit=\'mm\';	\r\n					}\r\n					\r\n				$pdf = new FPDF(\'L\',$size_unit,array($max_width,$max_height));\r\n				\r\n					foreach($canvas_images_d as $keyyy => $orderitems_d) {\r\n						$sizee = array($img_height[$keyyy],$img_width[$keyyy]);\r\n							$orentation = \"L\";\r\n						if($img_height[$keyyy] > $img_width[$keyyy]) {\r\n							$orentation = \"P\";\r\n						}\r\n						$pdf->AddPage($orentation,$sizee);\r\n						$pdf->Image($image_full_d.$orderitems_d[\'canvas_image\'],0,0,$img_width[$keyyy],$img_height[$keyyy]);\r\n					}\r\n					$pdf->Output(\"D\",\"purpletree_product_designer.pdf\");\r\n				}\r\n		\r\n	}\r\n	\r\n		public function download_without_wm_pdf() {\r\n				$this->load->model(\'account/order\');\r\n				$product_designer = array();\r\n				$canvas_images_d = $this->model_account_order->getCanvasFromOrder($this->request->get[\'order_id\'],$this->request->get[\'product_id\']);\r\n				require_once( DIR_SYSTEM.\'library/purpletree_product_designer/fpdf.php\' );\r\n\r\n				if(!empty($canvas_images_d)) {\r\n					if ($this->request->server[\'HTTPS\']) {\r\n					$image_full_d = $this->config->get(\'config_ssl\') . \'image/\';\r\n				} else {\r\n					$image_full_d = $this->config->get(\'config_url\') . \'image/\';\r\n				}\r\n					$this->load->model(\'tool/image\');\r\n					$size_unit = 0;\r\n					foreach($canvas_images_d as $orderitems_d) {\r\n						$labelll = explode(\'_\', $orderitems_d[\'image_label\']);\r\n						$resolution = \'\';\r\n						if(isset($labelll[2]) && isset($labelll[1]) && is_numeric($labelll[2])) {\r\n							$resolution = $labelll[1];\r\n						}\r\n						$onepixel = 1;\r\n						if($resolution != \'\' and $resolution > 0) {\r\n							 $onepixel = 25.4/$resolution;\r\n						}\r\n						list($width, $height, $type, $attr) = getimagesize($image_full_d.$orderitems_d[\'image_without_wm\']);\r\n						$img_width[]=$width*$onepixel;\r\n						$img_height[]=$height*$onepixel;\r\n						$size_unit = $orderitems_d[\'size_unit\'];\r\n					}\r\n					$max_width=max($img_width)*(0.464583);\r\n					$max_height=max($img_height)*(0.464583);\r\n					\r\n					if($size_unit==1){\r\n						$size_unit=\'mm\';		\r\n					} else if($size_unit==2){\r\n						$size_unit=\'cm\';\r\n					} else if($size_unit==3){\r\n						$size_unit=\'foot\';\r\n					} else if($size_unit==4){\r\n						$size_unit=\'in\';\r\n					} else {\r\n						$size_unit=\'mm\';	\r\n					}\r\n					\r\n				$pdf = new FPDF(\'L\',$size_unit,array($max_width,$max_height));\r\n				\r\n					foreach($canvas_images_d as $keyyy => $orderitems_d) {\r\n						$sizee = array($img_height[$keyyy],$img_width[$keyyy]);\r\n							$orentation = \"L\";\r\n						if($img_height[$keyyy] > $img_width[$keyyy]) {\r\n							$orentation = \"P\";\r\n						}\r\n						$pdf->AddPage($orentation,$sizee);\r\n						$pdf->Image($image_full_d.$orderitems_d[\'image_without_wm\'],0,0,$img_width[$keyyy],$img_height[$keyyy]);\r\n					}\r\n					$pdf->Output(\"D\",\"purpletree_product_designer.pdf\");\r\n				}\r\n		\r\n	}\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/view/theme/*/template/account/order_info.twig\">\r\n	<operation error=\"skip\">\r\n				<search><![CDATA[{{ option.value }}]]></search>\r\n				<add position=\"replace\"><![CDATA[\r\n				{% if module_purpletree_product_designer_status and option.name == \'Upload Your Design\' %}</br>\r\n					 <a title=\"{{ option.value }}\" target=\"_blank\" href=\"{{ option.designurl }}\"><img height=\"30\" width=\"30\" src=\"{{ option.designurl }}\" alt=\"{{ option.value }}\" title=\"{{ option.value }}\" class=\"img-thumbnail\" /></a>\r\n					 	{% else %} {{ option.value }} {% endif %}\r\n				]]></add>\r\n						</operation>\r\n<operation error=\"skip\">\r\n	<search><![CDATA[</small> {% endfor %}</td>]]></search>\r\n		<add position=\"replace\"><![CDATA[\r\n		</small> {% endfor %}\r\n	{% if module_purpletree_product_designer_status %}\r\n		{% if product.buy_design_sts %}\r\n		{% if product.canvas_images %}\r\n			<div><small> - Preview Image &nbsp &nbsp  </small>\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.image_full }}\"><img src=\"{{ canvas_image.product_image }}\" alt=\"{{ canvas_image.image_label }}\" title=\"{{ canvas_image.image_label }}\" class=\"img-thumbnail\" /></a>\r\n				{% endfor %}\r\n				</div>\r\n					<div style=\"margin-top: 6px;\"><small> - Download Image</small>\r\n					{% set i=1 %}\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.canvas_image_full }}\" download=\"{{ canvas_image.canvas_image_full }}\"><span style=\" padding: 4px 10.5px; line-height: 1.42857; background-color: #fff; border: 1px solid #ddd; border-radius: 3px; display: inline-block; max-width: 100%; height: auto;\">{{ i }}</span></a>\r\n						 {% set i=i+1 %}\r\n				{% endfor %}\r\n				</div>\r\n				<div style=\"margin-top: 6px;\"><small> - Download JPG Image</small>\r\n					{% set i=1 %}\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.canvas_jpg_image_wtwm_full }}\" ><span style=\" padding: 4px 10.5px; line-height: 1.42857; background-color: #fff; border: 1px solid #ddd; border-radius: 3px; display: inline-block; max-width: 100%; height: auto;\">{{ i }}</span></a>\r\n						 {% set i=i+1 %}\r\n				{% endfor %}\r\n				</div>\r\n\r\n				<div style=\"margin-top: 6px;\"><small> - Download pdf </small>\r\n					<a href=\"{{ product.img_download }}\"><i class=\"fa fa-file-pdf-o\" style=\"font-size:25px;color:red;margin-left: 18px;\"></i></a>	\r\n				</div>\r\n				<div style=\"margin-top: 6px;\"><small> - Download without watermark pdf </small>\r\n					<a href=\"{{ product.img_wm_download }}\"><i class=\"fa fa-file-pdf-o\" style=\"font-size:25px;color:red;margin-left: 18px;\"></i></a>	\r\n				</div>\r\n				{% endif %}\r\n				</td>\r\n				{% endif %}\r\n			{% endif %} </td> \r\n				]]></add>\r\n	</operation>					\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[<small> - {{ option.name }}: {{ option.value }}</small> {% endfor %}</td>]]></search>\r\n				<add position=\"replace\"><![CDATA[\r\n				<small> - {{ option.name }}: {{ option.value }}</small> {% endfor %}\r\n				 {% if product.canvas_images %}\r\n			<div>\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.image_full }}\"><img src=\"{{ canvas_image.product_image }}\" alt=\"{{ canvas_image.image_label }}\" title=\"{{ canvas_image.image_label }}\" class=\"img-thumbnail\" /></a>\r\n				{% endfor %}\r\n				</div>\r\n				{% endif %}\r\n			  </td>\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/checkout/order.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$order_id = $this->db->getLastId();]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n							//module_purpletree_product_designer_status\r\n		if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n		foreach ($this->cart->getProducts() as $productcart) {\r\n		\r\n			if(isset($productcart[\'canvas_images\']) && !empty($productcart[\'canvas_images\'])) {\r\n\r\n					foreach($productcart[\'canvas_images\'] as $canvas_image) {\r\n						$this->db->query(\"UPDATE `\" . DB_PREFIX . \"purpletree_canvas_order_image` SET order_id = \'\" . (int)$order_id . \"\' WHERE session_id = \'\" . $this->db->escape($this->session->getId()) . \"\' AND (order_id IS NULL OR order_id=\'0\')\");\r\n					}\r\n				} else {\r\n					$ptsquery =$this->db->query(\"SELECT order_id FROM `\" . DB_PREFIX . \"purpletree_canvas_order_image` WHERE session_id = \'\" . $this->db->escape($this->session->getId()) . \"\' ORDER BY id DESC LIMIT 1 \");\r\n						if(isset($ptsquery->row[\'order_id\'])) {\r\n					$last_order_id=$ptsquery->row[\'order_id\'];\r\n\r\n					if($last_order_id){\r\n						$this->db->query(\"UPDATE `\" . DB_PREFIX . \"purpletree_canvas_order_image` SET order_id = \'\" . (int)$order_id . \"\' WHERE session_id = \'\" . $this->db->escape($this->session->getId()) . \"\' AND order_id=\'\".$last_order_id.\"\'\");\r\n					}\r\n					}\r\n					\r\n				}\r\n		}\r\n		}\r\n		//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[foreach ($product[\'option\'] as $option) {]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n					//module_purpletree_product_designer_status\r\n					if($option[\'product_option_id\']==\'\'){\r\n						$option[\'value\'] = $this->currency->format($option[\'value\'], $this->session->data[\'currency\']);	\r\n						}\r\n				//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/journal3/checkout.php\">\r\n		<operation error=\"skip\">\r\n		<search><![CDATA[$products[] = array(]]></search>\r\n		<add position=\"before\" ><![CDATA[\r\n		//module_purpletree_product_designer_status\r\n		$product[\'canvas_image\'] = array();\r\n		if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n			$sql  