		if($last_order_id){\r\n						$this->db->query(\"UPDATE `\" . DB_PREFIX . \"purpletree_canvas_order_image` SET order_id = \'\" . (int)$order_id . \"\' WHERE session_id = \'\" . $this->db->escape($this->session->getId()) . \"\' AND order_id=\'\".$last_order_id.\"\'\");\r\n					}\r\n					}\r\n					\r\n				}\r\n		}\r\n		}\r\n		//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		</file>\r\n	<file path=\"system/library/cart/cart.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[foreach (json_decode($cart[\'option\']) as $product_option_id => $value) {]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n							if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				if($product_option_id == \'optionalpdffiles\' && !empty($value)) {\r\n					foreach($value as $keyname => $ddd) {\r\n						if($ddd != \'\') {\r\n						$option_data[] = array(\r\n									\'product_option_id\'       => \'file\',\r\n									\'product_option_value_id\' => \'\',\r\n									\'option_id\'               => \'\',\r\n									\'option_value_id\'         => \'\',\r\n									\'name\'                    => $keyname,\r\n									\'value\'                   => $ddd,\r\n									\'type\'                    => \'file\',\r\n									\'quantity\'                => 1,\r\n									\'subtract\'                => \'\',\r\n									\'price\'                   => \'\',\r\n									\'price_prefix\'            => \'\',\r\n									\'points\'                  => \'\',\r\n									\'points_prefix\'           => \'\',\r\n									\'weight\'                  => \'\',\r\n									\'weight_prefix\'           => \'\'\r\n								);\r\n						}\r\n					}\r\n				}\r\n					if($product_option_id == \'price_per_page\') {\r\n						$option_data[] = array(\r\n									\'product_option_id\'       => \'\',\r\n									\'product_option_value_id\' => \'\',\r\n									\'option_id\'               => \'\',\r\n									\'option_value_id\'         => \'\',\r\n									\'