ach($product[\'canvas_images\'] as $orderitems) {\r\n						$product[\'canvas_image_c\'][] = array(\'id\' => $orderitems[\'id\'],\'image_label\' => $orderitems[\'image_label\'], \'product_image\'=> $this->model_tool_image->resize($orderitems[\'product_image\'],20,20),\'image_full\'=> $image_full.$orderitems[\'product_image\']);\r\n					}\r\n				}\r\n				}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[\'cart_id\'   => $product[\'cart_id\'],]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n			 \'canvas_images\'  => $product[\'canvas_image_c\'],\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$value = $option[\'value\'];]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n					if($option[\'product_option_id\']==\'\'){\r\n						$value = $this->currency->format($option[\'value\'], $this->session->data[\'currency\']);	\r\n						}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/confirm.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$value = $option[\'value\'];]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n					if($option[\'product_option_id\']==\'\'){\r\n						$value = $this->currency->format($option[\'value\'], $this->session->data[\'currency\']);	\r\n						}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/cart.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[if ($upload_info) {]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				$mask = basename($upload_info[\'name\']);\r\n						if ($this->request->server[\'HTTPS\']) {\r\n							$designurl = $this->config->get(\'config_ssl\') . \'image/catalog/ptsdesigner/\' . $mask;\r\n						} else {\r\n							$designurl = $this->config->get(\'config_url\') . \'image/catalog/ptsdesigner/\' . $mask;\r\n						}\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$option_data[] = array(]]></search>\r\n				<add position=\"after\"><![CDATA[\'designurl\'  => $designurl,]]></add>\r\n		</operation>\r\n		\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[public function edit() {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n		protected function filteredImages($images=array()) {\r\n			if(!empty($images)){\r\n				foreach($images as $pts_key=> $pts_val){\r\n					$pts_no=explode(\"_\",$pts_key);\r\n					$pts_count=count($pts_no)-1;\r\n					$filter_array[$pts_no[$pts_count]]=$pts_val;\r\n				 }\r\n				 ksort($filter_array);\r\n				 if(!empty($filter_array)){\r\n					foreach($filter_array as $ffkey=>$ffval){\r\n						foreach($this->request->post[\'canvaslabel\'] as $fkey=>$fval){\r\n							$pts_last_val=explode(\"_\",$fkey);\r\n							$cnt=count($pts_last_val)-1;\r\n							$pts_last_value = $pts_last_val[$cnt];\r\n							if($pts_last_value==$ffkey){\r\n							$filtered_images[$fkey]=$ffval;\r\n							}\r\n									\r\n						}\r\n					}\r\n				}\r\n				return $filtered_images;\r\n			}\r\n			return array();\r\n	} \r\n	]]></add>\r\n		</operation>\r\n		\r\n		\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$option_data = array();]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				$designurl = \'\';\r\n				]]></add>\r\n		</operation>\r\n				<operation error=\"skip\">\r\n				<search><![CDATA[if (isset($this->request->post[\'option\'])) {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n					\r\n					$this->load->model(\'extension/purpletree_product_designer/product_template_designer\');\r\n					if (isset($this->request->post[\'template_id\'])) {\r\n					$template_id = $this->request->post[\'template_id\'];\r\n						$designnn = 1;\r\n					if($template_id == 0) {\r\n						$designnn = 3;\r\n					}\r\n				$getcartdata = $this->model_extension_purpletree_product_designer_product_template_designer->getDatafromTemplateCart($product_id,$designnn);\r\n				if(!empty($getcartdata)) {\r\n				if(isset($getcartdata[\'qtyprice\']) && $getcartdata[\'qtyprice\'] != 0) {\r\n					$getcustomqtyPrice = $this->model_extension_purpletree_product_designer_product_template_designer->getcustomqtyPrice($getcartdata[\'qtyprice\'],$product_id);\r\n						if(!empty($getcustomqtyPrice)) {\r\n							$quantity = $getcustomqtyPrice[\'quantity\'];\r\n						}\r\n				} \r\n					if(isset($getcartdata[\'option\']) && $getcartdata[\'option\'] != \'\') {\r\n					$this->request->post[\'option\'] = json_decode($getcartdata[\'option\'],true);\r\n					}\r\n				}\r\n				}\r\n		\r\n				if (isset($this->request->post[\'qtyprice\'])) {\r\n						$getcustomqtyPrice = $this->model_extension_purpletree_product_designer_product_template_designer->getcustomqtyPrice($this->request->post[\'qtyprice\'],$product_id);\r\n						if(!empty($getcustomqtyPrice)) {\r\n							$quantity = $getcustomqtyPrice[\'quantity\'];\r\n							$this->request->post[\'option\'][\'customprice\'] = $getcustomqtyPrice[\'price\'];\r\n						}\r\n					}\r\n		} \r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$json[\'redirect\']]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n					if(isset($json[\'insertid\']) && !isset($json[\'error\'])) {\r\n						$json[\'redirecturl\'] = \'1\';\r\n						if(isset($this->request->get[\'designvar\']) && $this->request->get[\'designvar\'] == 3) {\r\n					$json[\'redirect\'] = str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/purpletree_product_designer/product_template_designer\', \'product_id=\' . $this->request->post[\'product_id\']));\r\n						} else {\r\n					$json[\'redirect\'] = str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/purpletree_product_designer/product_designer_startdesign\', \'product_id=\' . $this->request->post[\'product_id\']));\r\n					}\r\n				}\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[if (!$json) {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n					//if($istemplateprodutc) {\r\n								$template = 1;		\r\n						$this->load->model(\'extension/purpletree_product_designer/product_designer\');\r\n						if($this->config->get(\'module_purpletree_product_designer_template\')) {\r\n					\r\n							$hasqtyprice = $this->model_extension_purpletree_product_designer_product_designer->getdiscount($product_info[\'product_id\']);\r\n							if($hasqtyprice) {\r\n									$template = 0;	\r\n						if (isset($this->request->post[\'qtyprice\'])) {\r\n									$template = 1;	\r\n						} else {\r\n							if(!isset($option[\'customprice\'])) {\r\n							$json[\'error\'][\'option\'][\'qtyprice\'] = sprintf($this->language->get(\'error_required\'), \'Quantity\');\r\n							}\r\n						}\r\n							}\r\n					} \r\n					//}\r\n				\r\n			if($template == 1 && !isset($json[\'error\'])) {\r\n			$this->load->model(\'extension/purpletree_product_designer/product_designer\');\r\n			$this->load->model(\'extension/purpletree_product_designer/product_templete_start\');\r\n			$istemplateprodutc = $this->model_extension_purpletree_product_designer_product_designer->istemplateproduct($product_id);\r\n			if($istemplateprodutc) {\r\n			if(isset($this->request->get[\'designvar\']) && $this->request->get[\'designvar\'] == 2){\r\n				\r\n\r\n			\r\n			} else {\r\n					\r\n				if(isset($this->request->get[\'designvar\'])) {\r\n					$this->request->post[\'design\'] = $this->request->get[\'designvar\'];\r\n				\r\n				$this->request->post[\'option\'] = $option;\r\n				$json[\'insertid\'] = $this->model_extension_purpletree_product_designer_product_templete_start->insertincart($this->request->post);\r\n				}\r\n				}\r\n			}\r\n			}\r\n		}\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$this->cart->add($this->request->post[\'product_id\'], $quantity, $option, $recurring_id);]]></search>\r\n				<add position=\"replace\"><![CDATA[\r\n						//module_purpletree_product_designer_status\r\n							if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n						$pdfprice = array();\r\n		if (isset($this->request->post[\'pdfprice\']) && isset($this->request->post[\'pdfprice\'][\'total\']) && $this->request->post[\'pdfprice\'][\'total\'] != \'\' && isset($this->request->post[\'pdfprice\'][\'price_per_page\']) && $this->request->post[\'pdfprice\'][\'price_per_page\'] != \'\' && isset($this->request->post[\'pdfprice\'][\'no_of_pages\']) && $this->request->post[\'pdfprice\'][\'no_of_pages\'] != \'\') {\r\n			$pdfprice = $this->request->post[\'pdfprice\'];\r\n		}\r\n		$option = $pdfprice + $option;\r\n		if (isset($this->request->post[\'optionalpdffiles\']) && isset($this->request->post[\'optionalpdffiles\'][\'optionalpdffiles\'])){\r\n			$optionalpdffiles = $this->request->post[\'optionalpdffiles\'];\r\n			$option = $optionalpdffiles + $option;\r\n		}\r\n		}\r\n		$this->cart->add($this->request->post[\'product_id\'], $quantity, $option, $recurring_id,$canvas_label,$product_design_opt,$buy_design_status);\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[if ($product_info) {]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n		//module_purpletree_product_designer_status\r\n		$canvas_label = array();\r\n			if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				$this->load->model(\'extension/purpletree_product_designer/product_template_designer\');\r\n				$sizeUnit = $this->model_extension_purpletree_product_designer_product_template_designer->getCanvasSizeUnit($product_id);\r\n				\r\n				if(isset($this->request->post[\'template_id\'])){\r\n					$temp_id=$this->request->post[\'template_id\'];\r\n					if($temp_id){\r\n					$sizeUnit = $this->model_extension_purpletree_product_designer_product_template_designer->getCanvasTemplateSizeUnit($product_id,$temp_id);\r\n					}\r\n				}\r\n\r\n				$online_product_design_status = $this->model_catalog_product->getProductDesignStatus($this->request->post[\'product_id\']);\r\n				if (isset($this->request->post[\'canvaslabel\']) && !empty($this->request->post[\'canvaslabel\'])) {\r\n					if($this->cart->hasProducts() && $this->cart->hasDesignerProduct($this->request->post[\'product_id\'])) {\r\n						$errormsg = \"Please Remove \'\" .$product_info[\'name\']. \"\' from cart to add it again with new design.\";\r\n						$json[\'error\'][\'product_designer\'] = $errormsg;\r\n						$this->session->data[\'warning\'] = $errormsg;\r\n						$this->response->addHeader(\'Content-Type: application/json\');\r\n						$this->response->setOutput(json_encode($json));\r\n					} else {\r\n						if(!empty($this->request->post[\'canvaslabel\'])){\r\n						$images= $this->filteredImages($this->request->post[\'canvaslabel\']);\r\n						foreach($images as $keyy => $canvvv) {\r\n							$canvas_without_bg_img=\'\';\r\n							$canvas_without_WM_img=\'\';\r\n							if(isset($this->request->post[\'canvas_without_bg_img\'][$keyy])){\r\n							$canvas_without_bg_img=	$this->request->post[\'canvas_without_bg_img\'][$keyy];\r\n							}\r\n							if(isset($this->request->post[\'canvas_without_WM_img\'][$keyy])){\r\n							$canvas_without_WM_img=	$this->request->post[\'canvas_without_WM_img\'][$keyy];\r\n							}\r\n							$canvas_label[] = array(\r\n							\'product_image\' =>$canvvv,\r\n							\'product_without_bg_image\' =>$canvas_without_bg_img,\r\n							\'product_without_wm_image\' =>$canvas_without_WM_img,\r\n							\'image_label\'=>$keyy,\r\n							\'size_unit\'=>$sizeUnit,\r\n							); \r\n						}\r\n						}\r\n					}\r\n				} elseif($online_product_design_status) {\r\n				if(!isset($this->request->get[\'designvar\'])) { \r\n					$json[\'error\'][\'option\'][\'product_designer\'] = sprintf($this->language->get(\'error_required\'), \"Product Design\");\r\n					$json[\'redirect\'] = str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/purpletree_product_designer/product_designer\', \'product_id=\' . $this->request->post[\'product_id\']));\r\n					$this->response->addHeader(\'Content-Type: application/json\');\r\n					$this->response->setOutput(json_encode($json));\r\n					}\r\n				}\r\n			}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		\r\n				<operation error=\"skip\">\r\n				<search><![CDATA[$this->load->model(\'catalog/product\');]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				if (isset($this->request->post[\'istemplateprodutc\'])) {\r\n			$istemplateprodutc = (int)$this->request->post[\'istemplateprodutc\'];\r\n		} else {\r\n			$istemplateprodutc = 0;\r\n		}\r\n		$template = 0;	\r\n				//module_purpletree_product_designer_status\r\n				if (isset($this->request->post[\'pts_option_label\'])) {\r\n					$pts_option_label = $this->request->post[\'pts_option_label\'];\r\n				} else {\r\n					$pts_option_label = \'0\';\r\n				}\r\n				\r\n				if (isset($this->request->post[\'buy_design_status\'])) {\r\n					$buy_design_status = $this->request->post[\'buy_design_status\'];\r\n				} else {\r\n					$buy_design_status = \'\';\r\n				}\r\n				\r\n				if (isset($this->request->post[\'pts_layer_price\'])) {\r\n					 $pts_layer_price =$this->request->post[\'pts_layer_price\'];\r\n				} else {\r\n					 $pts_layer_price = \'\';\r\n				}\r\n				\r\n				$product_design_option=array();\r\n				if($pts_option_label!=\'\' && $pts_layer_price!=\'\'){\r\n				$product_design_option=array(\r\n				\'pts_opt_label\'=>$pts_option_label,\r\n				\'pts_opt_price\'=>(float)$pts_layer_price\r\n				);\r\n				}\r\n				$product_design_opt = json_encode($product_design_option);\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[foreach ($products as $product) {]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n			//module_purpletree_product_designer_status\r\n			$product[\'canvas_image_c\'] = array();\r\n			$data[\'module_purpletree_product_designer_status\'] = $this->config->get(\'module_purpletree_product_designer_status\');\r\n				if($this->config->get(\'module_purpletree_product_designer_status\')) {\r\n				if(isset($product[\'canvas_images\']) && !empty($product[\'canvas_images\'])) {\r\n				if ($this->request->server[\'HTTPS\']) {\r\n					$image_full = $this->config->get(\'config_ssl\') . \'image/\';\r\n				} else {\r\n					$image_full = $this->config->get(\'config_url\') . \'image/\';\r\n				}\r\n					foreach($product[\'canvas_images\'] as $orderitems) {\r\n						$product[\'canvas_image_c\'][] = array(\'id\' => $orderitems[\'id\'],\'image_label\' => $orderitems[\'image_label\'], \'product_image\'=> $this->model_tool_image->resize($orderitems[\'product_image\'],20,20),\'image_full\'=> $image_full.$orderitems[\'product_image\']);\r\n					}\r\n				}\r\n				}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[\'cart_id\'   => $product[\'cart_id\'],]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n			 \'canvas_images\'  => $product[\'canvas_image_c\'],\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n		<search><![CDATA[$value = $option[\'value\'];]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n					if($option[\'product_option_id\']==\'\'){\r\n						$value = $this->currency->format($option[\'value\'], $this->session->data[\'currency\']);	\r\n						}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/view/theme/*/template/common/cart.twig\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[{{ option.value }}]]></search>\r\n				<add position=\"replace\"><![CDATA[\r\n				{% if module_purpletree_product_designer_status and option.name == \'Upload Your Design\' %}</br>\r\n					 <a title=\"{{ option.value }}\" target=\"_blank\" href=\"{{ option.designurl }}\"><img height=\"30\" width=\"30\" src=\"{{ option.designurl }}\" alt=\"{{ option.value }}\" title=\"{{ option.value }}\" class=\"img-thumbnail\" /></a>\r\n					 	{% else %} {{ option.value }} {% endif %}\r\n				]]></add>\r\n						</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[{% if product.recurring %}]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				<!--module_purpletree_product_designer_status-->\r\n					{% if module_purpletree_product_designer_status %}\r\n					{% if product.canvas_images %}\r\n			<div>\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.image_full }}\"><img src=\"{{ canvas_image.product_image }}\" alt=\"{{ canvas_image.image_label }}\" title=\"{{ canvas_image.image_label }}\" class=\"img-thumbnail\" /></a>\r\n				{% endfor %}\r\n				</div>\r\n			{% endif %}\r\n			{% endif %}\r\n			\r\n				<!--module_purpletree_product_designer_status-->\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/view/theme/*/template/checkout/cart.twig\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[{{ option.value }}]]></search>\r\n				<add position=\"replace\"><![CDATA[\r\n				{% if module_purpletree_product_designer_status and option.name == \'Upload Your Design\' %}</br>\r\n					 <a title=\"{{ option.value }}\" target=\"_blank\" href=\"{{ option.designurl }}\"><img height=\"30\" width=\"30\" src=\"{{ option.designurl }}\" alt=\"{{ option.value }}\" title=\"{{ option.value }}\" class=\"img-thumbnail\" /></a>\r\n					 	{% else %} {{ option.value }} {% endif %}\r\n				]]></add>\r\n						</operation>\r\n				<operation error=\"skip\">\r\n				<search><![CDATA[{% if product.recurring %}]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				<!--module_purpletree_product_designer_status-->\r\n					{% if module_purpletree_product_designer_status %}\r\n					{% if product.canvas_images %}\r\n			<div>\r\n				{% for key,canvas_image in product.canvas_images %}\r\n					 <a style=\"display: inline-block;margin-left: 2px;\" id=\"canvas_cart_{{ canvas_image.id }}\" target=\"_blank\" href=\"{{ canvas_image.image_full }}\"><img src=\"{{ canvas_image.product_image }}\" alt=\"{{ canvas_image.image_label }}\" title=\"{{ canvas_image.image_label }}\" class=\"img-thumbnail\" /></a>\r\n				{% endfor %}\r\n				</div>\r\n			{% endif %}\r\n			{% endif %}\r\n					<!--module_purpletree_product_designer_status-->\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/catalog/product.php\">\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$this->response->redirect(]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n				if ((isset($this->request->post[\'product_designer_status\']) AND $this->request->post[\'product_designer_status\'] == 1) OR (isset($this->request->post[\'product_designer_book_printing\']) AND $this->request->post[\'product_designer_book_printing\'] == 1)) {\r\n				$this->response->redirect($this->url->link(\'extension/purpletree_product_designer/product_designer_products\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true));\r\n			}\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[protected function getForm() {]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n$this->load->language(\'purpletree_product_designer/admintemplate\');\r\n			$data[\'module_purpletree_product_designer_template\'] = $this->config->get(\'module_purpletree_product_designer_template\');\r\n			]]></add>\r\n		</operation>\r\n				<operation error=\"skip\">\r\n				<search><![CDATA[if (isset($this->request->post[\'product_special\'])) {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n//\r\n		if($this->config->get(\'module_purpletree_product_designer_status\') && $this->config->get(\'module_purpletree_product_designer_template\')) {\r\n		$this->load->model(\'extension/purpletree_product_designer/pts_product_template\');\r\n				if (isset($this->request->post[\'product_price_quantity\'])) {\r\n			$product_price_quantitys = $this->request->post[\'product_price_quantity\'];\r\n		} elseif (isset($this->request->get[\'product_id\'])) {\r\n			$product_price_quantitys = $this->model_extension_purpletree_product_designer_pts_product_template->getProductprice_quantitys($this->request->get[\'product_id\']);\r\n		} else {\r\n			$product_price_quantitys = array();\r\n		}\r\n\r\n		$data[\'product_price_quantitys\'] = array();\r\n\r\n		foreach ($product_price_quantitys as $product_price_quantity) {\r\n			$data[\'product_price_quantitys\'][] = array(\r\n				\'quantity\'          => $product_price_quantity[\'quantity\'],\r\n				\'price\'             => $product_price_quantity[\'price\']\r\n			);\r\n		}\r\n		}\r\n		//\r\n				]]></add>\r\n		</operation>\r\n				<operation error=\"skip\">\r\n				<search><![CDATA[if (isset($this->request->post[\'model\'])) {]]></search>\r\n				<add position=\"before\"><![CDATA[\r\n										///   online purpletree prouct design \\\\\\\\ \r\n					 $data[\'module_purpletree_product_designer_status\'] = $this->config->get(\'module_purpletree_product_designer_status\');\r\n					   if(isset($data[\'module_purpletree_product_designer_status\'])){\r\n					   \r\n						if (isset($this->request->post[\'product_designer_status\'])) {\r\n							$data[\'product_designer_status\'] = $this->request->post[\'product_designer_status\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$data[\'product_designer_status\'] = $this->model_catalog_product->getProductDesignStatus($this->request->get[\'product_id\']);\r\n						} else {\r\n							$data[\'product_designer_status\'] = \'\';\r\n						}\r\n						if (isset($this->request->post[\'product_designer_book_printing\'])) {\r\n							$data[\'product_designer_book_printing\'] = $this->request->post[\'product_designer_book_printing\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$data[\'product_designer_book_printing\'] = $this->model_catalog_product->getProductbookStatus($this->request->get[\'product_id\']);\r\n						} else {\r\n							$data[\'product_designer_book_printing\'] = \'\';\r\n						}\r\n						$this->load->model(\'extension/purpletree_product_designer/pts_product_template\');\r\n				if (isset($this->request->post[\'short_description\'])) {\r\n			$data[\'short_description\'] = $this->request->post[\'short_description\'];\r\n		} elseif (isset($this->request->get[\'product_id\'])) {\r\n			$data[\'short_description\'] = $this->model_extension_purpletree_product_designer_pts_product_template->getshortdesc($this->request->get[\'product_id\']);\r\n		} else {\r\n			$data[\'short_description\'] = array();\r\n		}	\r\n						\r\n						if (isset($this->request->post[\'product_designer_total_layers\'])) {\r\n							$data[\'product_designer_total_layers\'] = $this->request->post[\'product_designer_total_layers\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_layers[\'total_layers\'])) {\r\n								$data[\'product_designer_total_layers\'] = $t_layers[\'total_layers\'];\r\n							} else {\r\n								$data[\'product_designer_total_layers\'] = \'999\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_total_layers\'] = \'999\';\r\n						}\r\n						if (isset($this->request->post[\'product_designer_price_binding\'])) {\r\n							$data[\'product_designer_price_binding\'] = $this->request->post[\'product_designer_price_binding\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_layers[\'price_binding\'])) {\r\n							$data[\'product_designer_price_binding\'] = $t_layers[\'price_binding\'];\r\n							} else {\r\n							$data[\'product_designer_price_binding\'] = \'\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_price_binding\'] = \'\';\r\n						}\r\n						if (isset($this->request->post[\'product_designer_price_per_page\'])) {\r\n							$data[\'product_designer_price_per_page\'] = $this->request->post[\'product_designer_price_per_page\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_layers[\'price_per_page\'])) {\r\n							$data[\'product_designer_price_per_page\'] = $t_layers[\'price_per_page\'];\r\n							} else {\r\n							$data[\'product_designer_price_per_page\'] = \'\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_price_per_page\'] = \'\';\r\n						}\r\n						if (isset($this->request->post[\'is_price_binding\'])) {\r\n							$data[\'is_price_binding\'] = $this->request->post[\'is_price_binding\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_layers[\'is_price_binding\'])) {\r\n							$data[\'is_price_binding\'] = $t_layers[\'is_price_binding\'];\r\n							} else {\r\n							$data[\'is_price_binding\'] = \'\';\r\n							}\r\n						} else {\r\n							$data[\'is_price_binding\'] = \'\';\r\n						}\r\n						\r\n						if (isset($this->request->post[\'product_designer_total_text_layers\'])) {\r\n							$data[\'product_designer_total_text_layers\'] = $this->request->post[\'product_designer_total_text_layers\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_text_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_text_layers[\'total_text_layers\'])) {\r\n							$data[\'product_designer_total_text_layers\'] = $t_text_layers[\'total_text_layers\'];\r\n							} else {\r\n							$data[\'product_designer_total_text_layers\'] = \'99\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_total_text_layers\'] = \'99\';\r\n						}\r\n						\r\n						if (isset($this->request->post[\'product_designer_total_clipart_layers\'])) {\r\n							$data[\'product_designer_total_clipart_layers\'] = $this->request->post[\'product_designer_total_clipart_layers\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_clipart_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_clipart_layers[\'total_clipart_layers\'])) {\r\n							$data[\'product_designer_total_clipart_layers\'] = $t_clipart_layers[\'total_clipart_layers\'];\r\n							} else {\r\n							$data[\'product_designer_total_clipart_layers\'] = \'99\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_total_clipart_layers\'] = \'99\';\r\n						}\r\n						\r\n						if (isset($this->request->post[\'product_designer_total_image_layers\'])) {\r\n							$data[\'product_designer_total_image_layers\'] = $this->request->post[\'product_designer_total_image_layers\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_image_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_image_layers[\'total_image_layers\'])) {\r\n							$data[\'product_designer_total_image_layers\'] = $t_image_layers[\'total_image_layers\'];\r\n							} else {\r\n							$data[\'product_designer_total_image_layers\'] = \'99\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_total_image_layers\'] = \'99\';\r\n						}\r\n						if (isset($this->request->post[\'product_designer_total_shapes_layers\'])) {\r\n							$data[\'product_designer_total_shapes_layers\'] = $this->request->post[\'product_designer_total_shapes_layers\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_shapes_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_shapes_layers[\'total_shapes_layers\'])) {\r\n							$data[\'product_designer_total_shapes_layers\'] = $t_shapes_layers[\'total_shapes_layers\'];\r\n							} else {\r\n							$data[\'product_designer_total_shapes_layers\'] = \'99\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_total_shapes_layers\'] = \'99\';\r\n						}\r\n						\r\n						if (isset($this->request->post[\'product_designer_canvas_size\'])) {\r\n							$data[\'product_designer_canvas_size\'] = $this->request->post[\'product_designer_canvas_size\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_shapes_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_shapes_layers[\'size_unit\'])) {\r\n							$data[\'product_designer_canvas_size\'] = $t_shapes_layers[\'size_unit\'];\r\n							} else {\r\n							$data[\'product_designer_canvas_size\'] = \'\';\r\n							}\r\n						} else {\r\n							$data[\'product_designer_canvas_size\'] = \'\';\r\n						}\r\n						\r\n						\r\n						if (isset($this->request->post[\'product_designer_total_icons_layers\'])) {\r\n							$data[\'product_designer_total_icons_layers\'] = $this->request->post[\'product_designer_total_icons_layers\'];\r\n						} elseif (isset($this->request->get[\'product_id\'])) {\r\n							$t_icons_layers=$this->model_catalog_product->getProductDesignSetting($this->request->get[\'product_id\']);\r\n							if(isset($t_icons_layers[\'total_icons_layers\'])) {\r\n							$data[\'product_designer_total_icons_layers\'] = $t_icons_layers[\'total_icons_layers\'];\r\n							} else {\r\n							$data[\'product_designer_total_icons_layers\'] = \'99\';							\r\n							}\r\n						} else {\r\n							$data[\'product_designer_total_icons_layers\'] = \'99\';\r\n						}\r\n						\r\n						\r\n					if (isset($this->request->post[\'product_design_image\'])) {\r\n						$product_design_images = $this->request->post[\'product_design_image\'];\r\n					} elseif (isset($this->request->get[\'product_id\'])) {\r\n						$product_design_images = $this->model_catalog_product->getProductDesignImages($this->request->get[\'product_id\']);\r\n					} else {\r\n						$product_design_images = array();\r\n					}\r\n\r\n					$data[\'product_design_images\'] = array();\r\n				$http_server=explode(\'/\',HTTPS_SERVER);\r\n				array_pop($http_server);\r\n				array_pop($http_server);\r\n				$image_root=implode(\'/\',$http_server);\r\n				$data[\'DESIGN_IMAGE_ROOT\']=$image_root.\"/image/\";\r\n				\r\n					$this->load->model(\'tool/image\');\r\n					if(!empty($product_design_images)){\r\n					foreach ($product_design_images as $product_design_image) {\r\n						$design_image=\'\';\r\n						if(isset($product_design_image[\'design_image\'])){\r\n						$design_image=$product_design_image[\'design_image\'];	\r\n						}\r\n						if (is_file(DIR_IMAGE . $design_image)) {\r\n							$image = $product_design_image[\'design_image\'];\r\n							$thumb = $product_design_image[\'design_image\'];\r\n						} else {\r\n							$image = \'\';\r\n							$thumb = \'no_image.png\';\r\n						}\r\n						\r\n			$can_left=50;\r\n			if(!empty($product_design_image[\'can_left\'])){\r\n				$can_left=$product_d