){\r\n					$sqlmod.=\",total_image_layers = \'\" . (int)$data[\'product_designer_total_image_layers\'] . \"\'\";\r\n				}\r\n					if($data[\'product_designer_total_shapes_layers\']!=\'\'){\r\n					$sqlmod.=\",total_shapes_layers = \'\" . (int)$data[\'product_designer_total_shapes_layers\'] . \"\'\";\r\n				}\r\n				if($data[\'product_designer_total_icons_layers\']!=\'\'){\r\n					$sqlmod.=\",total_icons_layers = \'\" . (int)$data[\'product_designer_total_icons_layers\'] . \"\'\";\r\n				}\r\n				if($data[\'product_designer_canvas_size\']!=\'\'){\r\n					$sqlmod.=\",size_unit = \'\" . (int)$data[\'product_designer_canvas_size\'] . \"\'\";\r\n				}\r\n\r\n					$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"purpletree_product_design SET product_id = \'\" . (int)$product_id . \"\', status = \'\" . (int)$data[\'product_designer_status\'] . \"\'\".$sqlmod);	\r\n		}\r\n		}\r\n	if(isset($data[\'short_description\'])) {\r\n				$product_designer_status_tempa = 0;\r\n			if(isset($data[\'product_designer_status_tempa\'])) {\r\n				$product_designer_status_tempa = $data[\'product_designer_status_tempa\'];\r\n			}\r\n						$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"purpletree_templates_product SET status = \'\".$product_designer_status_tempa.\"\', short_description=\'\". $this->db->escape($data[\'short_description\']).\"\', product_id = \'\" . (int)$product_id . \"\'\");\r\n					}\r\n				\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[public function getProducts($data = array()) {]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			public function getProductDesignStatus($product_id) {\r\n				$query = $this->db->query(\"SELECT DISTINCT status FROM \" . DB_PREFIX . \"purpletree_product_design  WHERE product_id = \'\" . (int)$product_id . \"\'\");\r\n				if($query->num_rows>0){\r\n                 return $query->row[\'status\'];\r\n		         }else{\r\n			       return null;\r\n		         }\r\n			}\r\n			public function getProductDesignSetting($product_id) {\r\n				$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"purpletree_product_design  WHERE product_id = \'\" . (int)$product_id . \"\'\");\r\n				if($query->num_rows>0){\r\n                 return $query->row;\r\n		         }else{\r\n			       return null;\r\n		         }\r\n			}\r\n			public function getProductDesignImages($product_id) {\r\n				$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"purpletree_product_design_image  WHERE product_id = \'\" . (int)$product_id . \"\' ORDER BY design_image_id ASC\");\r\n				if($query->num_rows>0){\r\n                 return $query->rows;\r\n		         }else{\r\n			       return null;\r\n		         }\r\n			}\r\n			public function getProductbookStatus($product_id){\r\n					$sql   = \"SELECT `book_printing` FROM \" . DB_PREFIX . \"purpletree_product_design  WHERE product_id = \'\" . $product_id . \"\'\";\r\n					$query = $this->db->query($sql);\r\n					$data  = array();\r\n						if($query->num_rows>0){	\r\n							return $query->row[\'book_printing\'];\r\n							\r\n						} else {\r\n							return NULL;\r\n						}\r\n					\r\n					}\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/view/template/catalog/product_form.twig\">\r\n	<operation error=\"skip\">\r\n			<search><![CDATA[var discount_row = {{ discount_row }};]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n	  var price_quantity_row = \'{{ price_quantity_row }}\';\r\n\r\n  function addprice_quantity() {\r\n	  html = \'<tr id=\"price_quantity-row\' + price_quantity_row + \'\">\';\r\n	  html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_price_quantity[\' + price_quantity_row + \'][quantity]\" value=\"\" placeholder=\"{{ entry_quantity }}\" class=\"form-control\" /></td>\';\r\n	  html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_price_quantity[\' + price_quantity_row + \'][price]\" value=\"\" placeholder=\"{{ entry_price }}\" class=\"form-control\" /></td>\';\r\n	  html += \'  <td class=\"text-left\"><button type=\"button\" onclick=\"$(\\\'#price_quantity-row\' + price_quantity_row + \'\\\').remove();\" data-toggle=\"tooltip\" title=\"{{ button_remove }}\" class=\"btn btn-danger\"><i class=\"fa fa-minus-circle\"></i></button></td>\';\r\n	  html += \'</tr>\';\r\n\r\n	  $(\'#price_quantity tbody\').append(html);\r\n\r\n	  $(\'.date\').datetimepicker({\r\n		  pickTime: false\r\n	  });\r\n\r\n	  price_quantity_row++;\r\n  }\r\n  $(document).on(\'change\',\'.use-img\',function(e){\r\n	var use_img_id=e.target.id;\r\n	var use_img_row=use_img_id.split(\'-\');\r\n	var use_img_row_id=use_img_row[2];\r\n	var use_img_val=$(\'#\'+use_img_id).val();\r\nif(use_img_val==\'1\'){\r\n		$(\'#without-img-td-\'+use_img_row_id).css(\'display\',\'none\');\r\n		$(\'#thumb-design-image\'+use_img_row_id).css(\'display\',\'block\');\r\n		$(\'#alwaysontop\'+use_img_row_id).css(\'display\',\'block\');\r\n		\r\n			$(\'input[name=\"product_design_image[\'+use_img_row_id+\'][safe_lines]\"]\').attr(\'disabled\',\'disabled\');\r\n		$(\'input[name=\"product_design_image[\'+use_img_row_id+\'][bleed_size]\"]\').attr(\'disabled\',\'disabled\');\r\n		$(\'input[name=\"product_design_image[\'+use_img_row_id+\'][fold_line]\"]\').attr(\'disabled\',\'disabled\');\r\n		$(\'#create-canvas_\'+use_img_row_id).removeAttr(\'disabled\');\r\n			$(\'#create-canvas_\'+use_img_row_id).attr(\'onclick\',\'vewProductImage(this)\');\r\n	} else if (use_img_val==\'0\'){\r\n		$(\'#thumb-design-image\'+use_img_row_id).css(\'display\',\'none\');\r\n		$(\'#alwaysontop\'+use_img_row_id).css(\'display\',\'none\');\r\n		$(\'#without-img-td-\'+use_img_row_id).css(\'display\',\'block\');\r\n	$(\'input[name=\"product_design_image[\'+use_img_row_id+\'][safe_lines]\"]\').removeAttr(\'disabled\');\r\n		$(\'input[name=\"product_design_image[\'+use_img_row_id+\'][bleed_size]\"]\').removeAttr(\'disabled\');\r\n		$(\'input[name=\"product_design_image[\'+use_img_row_id+\'][fold_line]\"]\').removeAttr(\'disabled\');\r\n		$(\'#create-canvas_\'+use_img_row_id).attr(\'disabled\',\'disabled\');\r\n	\r\n		$(\'#create-canvas_\'+use_img_row_id).removeAttr(\'onclick\');\r\n	}\r\n	});\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[<li><a href=\"#tab-design\" data-toggle=\"tab\">{{ tab_design }}</a></li>]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			<!--  online product design Tab-->\r\n						{% if module_purpletree_product_designer_status %}\r\n				<li><a href=\"#tab-online_produc_desing\" data-toggle=\"tab\">Custom Product Designer </a></li>\r\n					{% if module_purpletree_product_designer_template %}\r\n					<li><a href=\"#tab-price\" data-toggle=\"tab\">{{ price_quantity }}</a></li>\r\n				 {% endif %}\r\n				 {% endif %}\r\n			]]></add>\r\n		</operation>\r\n		\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[<link href=\"view/javascript/codemirror/lib/codemirror.css\" rel=\"stylesheet\"/>]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			<!--  online product design Tab-->\r\n			{% if module_purpletree_product_designer_status %}\r\n				<!-- <script src=\"view/javascript/jquery/jquery-ui/jquery-ui.min.js\" type=\"text/javascript\"></script> -->\r\n				{% endif %}\r\n			]]></add>\r\n		</operation>\r\n	<operation error=\"skip\">\r\n			<search><![CDATA[</form>]]></search>\r\n			<add position=\"before\" offset=\"1\"><![CDATA[	\r\n      <!-- online product design Tab-->\r\n	  {% if module_purpletree_product_designer_status %}\r\n				<div class=\"tab-pane\" id=\"tab-online_produc_desing\">\r\n				<div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-status\">{{ text_enable }}</label>\r\n				<div class=\"col-sm-10\">			\r\n				<select name=\"product_designer_status\" id=\"input-product-design-status\" class=\"form-control\">\r\n			  {% if product_designer_status %}\r\n                <option value=\"1\" selected=\"selected\">{{ text_yes }}</option>\r\n                <option value=\"0\">{{ text_no }}</option>\r\n					{% else %}\r\n                <option value=\"1\">{{ text_yes }}</option>\r\n                <option value=\"0\" selected=\"selected\">{{ text_no }}</option>\r\n                {% endif %}\r\n              </select>\r\n				</div>\r\n              </div>\r\n			   <div class=\"bookprintingdiv\">\r\n			   <div class=\"form-group bookprintingdiv\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-book-printing\">{{ book_printing }}</label>\r\n				<div class=\"col-sm-10\">			\r\n				<select name=\"product_designer_book_printing\" id=\"input-product-book-printing\" class=\"form-control\">\r\n			  {% if product_designer_book_printing %}\r\n                <option value=\"1\" selected=\"selected\">{{ text_yes }}</option>\r\n                <option value=\"0\">{{ text_no }}</option>\r\n					{% else %}\r\n                <option value=\"0\" selected=\"selected\">{{ text_no }}</option>\r\n                <option value=\"1\">{{ text_yes }}</option>\r\n                {% endif %}\r\n              </select>\r\n				</div>\r\n              </div>\r\n			 <div class=\"bookprnitnginput\">\r\n			 <div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-price_per_page\">{{ entry_price_per_page }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_price_per_page\" value=\"{{ product_designer_price_per_page }}\" id=\"input-product-design-price_per_page\" placeholder=\"{{ entry_price_per_page }}\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			  <div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-book-is_price_binding\">{{ is_price_bindingbook_printing }}</label>\r\n				<div class=\"col-sm-10\">			\r\n				<select name=\"is_price_binding\" id=\"input-product-book-is_price_binding\" class=\"form-control\">\r\n			  {% if is_price_binding %}\r\n                <option value=\"1\" selected=\"selected\">{{ text_yes }}</option>\r\n                <option value=\"0\">{{ text_no }}</option>\r\n					{% else %}\r\n                <option value=\"0\" selected=\"selected\">{{ text_no }}</option>\r\n                <option value=\"1\">{{ text_yes }}</option>\r\n                {% endif %}\r\n              </select>\r\n				</div>\r\n				</div>\r\n			  <div class=\"form-group is_price_bindingdiv\" {% if is_price_binding %} {% else %} style=\"display:none\" {% endif %}>\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-price-binding\">{{ entry_price_binding }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_price_binding\" value=\"{{ product_designer_price_binding }}\" id=\"input-product-design-price-binding\" placeholder=\"{{ entry_price_binding }}\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			   </div>\r\n              </div>\r\n			    <div class=\"form-group\">\r\n										<label class=\"col-sm-2 control-label\" for=\"input-short_description{{ language.language_id }}\">{{ entry_short_description }}</label>\r\n										<div class=\"col-sm-10\">\r\n											<textarea name=\"short_description\" placeholder=\"{{ entry_short_description }}\" id=\"input-short-description\" data-toggle=\"summernote\" data-lang=\"{{ summernote }}\" class=\"form-control\">{{ short_description ? short_description }}</textarea>\r\n										</div>\r\n									</div>\r\n             \r\n			  <div class=\"table-responsive\" id=\"pts-pro-design\">\r\n			   <div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-total-layers\">{{ total_layers }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_total_layers\" value=\"{{ product_designer_total_layers }}\" id=\"input-product-design-total-layers\" placeholder=\"{{ total_layers }}\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			  <div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-total-text-layers\">{{ total_text_layers }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_total_text_layers\" value=\"{{ product_designer_total_text_layers }}\" id=\"input-product-design-total-text-layers\" placeholder=\"{{ total_text_layers }}\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			  	<div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-total-clipart-layers\">{{ total_clipart_layers }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_total_clipart_layers\" value=\"{{ product_designer_total_clipart_layers }}\" placeholder=\"{{ total_layers }}\" id=\"input-product-design-total-clipart-layers\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			  <div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-total-image-layers\">{{ total_image_layers }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_total_image_layers\" value=\"{{ product_designer_total_image_layers }}\" id=\"input-product-design-total-image-layers\" placeholder=\"{{ total_image_layers }}\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			   <div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-total-icon-layers\">{{ total_icon_layers }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_total_icons_layers\" value=\"{{ product_designer_total_icons_layers }}\" id=\"input-product-design-total-icon-layers\" placeholder=\"{{ total_icon_layers }}\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			  <div class=\"form-group\">\r\n				<label class=\"col-sm-2 control-label\" for=\"input-product-design-total-shape-layers\">{{ total_shape_layers }}</label>\r\n				<div class=\"col-sm-10\">		\r\n				<input type=\"text\" name=\"product_designer_total_shapes_layers\" value=\"{{ product_designer_total_shapes_layers }}\" id=\"input-product-design-total-shape-layers\" placeholder=\"{{ total_shape_layers }}\" class=\"form-control\" />				\r\n				</div>\r\n              </div>\r\n			   <div class=\"form-group\">	\r\n							<label class=\"col-sm-2 control-label\" for=\"input-product-design-total-shape-layers\">{{ text_size }}</label>\r\n							<div class=\"col-sm-10\">\r\n						<select name=\"product_designer_canvas_size\" id=\"input-product-design-canvas-size\" class=\"form-control\">\r\n						<option value=\"1\" {% if product_designer_canvas_size==1 %}selected=\"selected\"{% endif %}> {{ text_mm }} </option>\r\n						<option value=\"2\" {% if product_designer_canvas_size==2 %}selected=\"selected\"{% endif %}> {{ text_cm }} </option>\r\n						<option value=\"3\" {% if product_designer_canvas_size==3 %}selected=\"selected\"{% endif %}> {{ text_foot }} </option>\r\n						<option value=\"4\" {% if product_designer_canvas_size==4 %}selected=\"selected\"{% endif %}> {{ text_inches }} </option>\r\n						</select>\r\n					</div>\r\n				</div>\r\n             <table id=\"design-images\" class=\"table table-striped table-bordered table-hover\">\r\n                  <thead>\r\n                    <tr>\r\n                     <td class=\"text-right\">{{ text_use_image }}</td>\r\n                      <td class=\"text-left\">{{ entry_pts_p_design_image }}</td>\r\n                      <td class=\"text-right\">{{ text_always_top }}</td>\r\n                      <td class=\"text-right\"></td>\r\n                     \r\n                      <td class=\"text-right\">{{ entry_pts_lable }}</td>\r\n					    <td class=\"text-right\">{{ entry_dpi }}</td>\r\n						<td class=\"text-right\">{{ entry_safe_line }}</td>\r\n						<td class=\"text-right\">{{ entry_bleed_size }}</td>\r\n						<td class=\"text-right\">{{ entry_fold_line }}</td>\r\n                      <td class=\"text-right\">{{ entry_pts_sort_order }}</td>\r\n                      <td></td>\r\n                    </tr>\r\n                  </thead>\r\n                  <tbody>\r\n				{% set image_design_row = 0 %}\r\n                  {% for product_design_image in product_design_images %}\r\n                  <tr id=\"image-design-row{{ image_design_row }}\">\r\n					<td class=\"text-left use-img\">\r\n					<select id=\"use-img-{{ image_design_row }}\" name=\"product_design_image[{{ image_design_row }}][use_img]\" class=\"form-control\"  style=\"width:70px\" >\r\n						{% if product_design_image.use_img ==1 or product_design_image.use_img == 2 %}\r\n						<option value=\"1\" selected=\"selected\">{{ text_yes }} </option>\r\n						<option value=\"0\">{{ text_no }} </option>\r\n							{% else %}\r\n						<option value=\"1\" >{{ text_yes }} </option>\r\n						<option value=\"0\"  selected=\"selected\">{{ text_no }} </option>\r\n							{% endif %}\r\n						</select>\r\n					</td>\r\n                    <td class=\"text-left use-img\">					\r\n					<a href=\"\" id=\"thumb-design-image{{ image_design_row }}\" data-toggle=\"image\" class=\"img-thumbnail\" {% if product_design_image.use_img ==0 %} style=\"display:none\" {% endif %}><img src=\"{{ product_design_image.thumb }}\" alt=\"\" title=\"\" data-placeholder=\"{{ placeholder }}\" /></a>\r\n					<img style=\"display:none\" id=\"thumb-design-thumb{{ image_design_row }}\" src=\"{{ product_design_image.design_thumb }}\" />\r\n                      <input type=\"hidden\" name=\"product_design_image[{{ image_design_row }}][image]\" value=\"{{ product_design_image.image }}\" id=\"input-design-image{{ image_design_row }}\" />\r\n					 <div class=\"text-left divheightwidth \" id=\"without-img-td-{{ image_design_row }}\" {% if product_design_image.use_img ==1 or product_design_image.use_img ==2 %} style=\"display:none\" {% endif %}> \r\n					  <div class=\"col-sm-9 \">\r\n					  <div class=\"col-sm-5 \">{{ text_width }}</div>\r\n					  <div class=\"col-sm-7 \"><input type=\"text\" name=\"product_design_image[{{ image_design_row }}][width]\" value=\"{{ product_design_image.width }}\" placeholder=\"width\" class=\"form-control\" style=\"width: 70px;\" /></div>\r\n					  </div>\r\n					  <div class=\"col-sm-9 \">\r\n					  <div class=\"col-sm-5 \">{{ text_height }}</div>\r\n					  <div class=\"col-sm-7 \"><input type=\"text\" name=\"product_design_image[{{ image_design_row }}][height]\" value=\"{{ product_design_image.height }}\" placeholder=\"{{ text_height }}\" class=\"form-control\" style=\"width: 70px;\" /></div>\r\n					  </div>					  \r\n					  </div></td>\r\n					  \r\n					  <td class=\"text-center\"><div id=\"alwaysontop{{ image_design_row }}\" {% if product_design_image.use_img ==0 %} style=\"display:none\" {% endif %} class=\"ptsalwaysontop\"><input style=\"margin-right: 4px;\" id=\"alwaysontopcheckbox{{ image_design_row }}\" type=\"checkbox\" name=\"product_design_image[{{ image_design_row }}][alwaysontop]\" {% if product_design_image.alwaysontop == 1 %} checked=\"checked\" {% endif %}value=\"1\" /></div>\r\n					  </td> \r\n					  \r\n					  <td class=\"text-right\"><span class=\"btn btn-primary\" id=\"create-canvas_{{ image_design_row }}\"  {% if product_design_image.use_img == 1 or product_design_image.use_img == 2 %} onclick=\"vewProductImage(this);\" {% else %} disabled=\"disabled\"  {% endif %}>{{ entry_create_canvas }}</span>\r\n					  <input type=\"hidden\" name=\"product_design_image[{{ image_design_row }}][canvas_area]\" id=\"create-canvas-area_{{ image_design_row }}\" value=\"{{ product_design_image.canvas_area }}\">\r\n					  </td>\r\n					  <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[{{ image_design_row }}][lable]\" value=\"{{ product_design_image.lable }}\" placeholder=\"{{ entry_pts_lable }}\" class=\"form-control\" /></td>\r\n					   <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[{{ image_design_row }}][dpi]\" value=\"{{ product_design_image.dpi }}\" placeholder=\"{{ entry_dpi }}\" class=\"form-control\" /></td>\r\n					   \r\n					    <td class=\"text-right {{ product_design_image.use_img }}\"><input {% if product_design_image.use_img == 1 or product_design_image.use_img == 2 %}  disabled=\"disabled\" {% endif %} type=\"text\" name=\"product_design_image[{{ image_design_row }}][safe_lines]\" value=\"{{ product_design_image.safe_lines }}\" placeholder=\"{{ entry_safe_line }}\" class=\"form-control\" /></td>\r\n					 \r\n						<td class=\"text-right\"><input {% if product_design_image.use_img == 1 or product_design_image.use_img == 2 %}   disabled=\"disabled\" {% endif %} type=\"text\" name=\"product_design_image[{{ image_design_row }}][bleed_size]\" value=\"{{ product_design_image.bleed_size }}\" placeholder=\"{{ entry_bleed_size }}\" class=\"form-control\" /></td>\r\n						\r\n						<td class=\"text-right\"><input {% if product_design_image.use_img == 1 or product_design_image.use_img == 2 %}   disabled=\"disabled\" {% endif %} type=\"text\" name=\"product_design_image[{{ image_design_row }}][fold_line]\" value=\"{{ product_design_image.fold_line }}\" placeholder=\"{{ entry_fold_line }}\" class=\"form-control\" /></td>\r\n					   \r\n                    <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[{{ image_design_row }}][sort_order]\" value=\"{{ product_design_image.sort_order }}\" placeholder=\"{{ entry_sort_order }}\" class=\"form-control\" /></td>\r\n                    <td class=\"text-left\"><button type=\"button\" onclick=\"$(\'#image-design-row{{ image_design_row }}\').remove();\" data-toggle=\"tooltip\" title=\"{{ button_remove }}\" class=\"btn btn-danger\"><i class=\"fa fa-minus-circle\"></i></button></td>\r\n                  </tr>\r\n                  {% set image_design_row = image_design_row + 1 %}\r\n                  {% endfor %}\r\n				  </tbody>\r\n                  \r\n                  <tfoot>\r\n                    <tr>\r\n                       <td colspan=\"10\"><strong>{{ text_note }}</strong>{{ text_for }}<strong>Always on Top</strong> {{ text_msg_text }} <strong>{{ text_product_design_img }}</strong>. </td>\r\n                      <td class=\"text-left\"><button type=\"button\" onclick=\"addDesignImage()\" data-toggle=\"tooltip\" title=\"{{ button_image_add }}\" class=\"btn btn-primary\"><i class=\"fa fa-plus-circle\"></i></button></td>\r\n                    </tr>\r\n                  </tfoot>\r\n                </table>\r\n              </div> \r\n              </div>\r\n			    <link href=\"../catalog/view/theme/default/stylesheet/ptsproductdesign/css/jquery-ui-n.css\" rel=\"stylesheet\" />\r\n				{% if module_purpletree_product_designer_template %}\r\n				<div class=\"tab-pane\" id=\"tab-price\">\r\n				 <div class=\"table-responsive\">\r\n					 <table id=\"price_quantity\" class=\"table table-striped table-bordered table-hover\">\r\n                  <thead>\r\n                    <tr>\r\n                      <td class=\"text-right\">{{ entry_quantity }}</td>\r\n                      <td class=\"text-right\">{{ entry_price }}</td>\r\n                      <td></td>\r\n                    </tr>\r\n                  </thead>\r\n                  <tbody>\r\n                  {% set price_quantity_row = 0 %}\r\n                  {% for product_price_quantity in product_price_quantitys %}\r\n                  <tr id=\"price_quantity-row{{ price_quantity_row }}\">\r\n                    \r\n                    <td class=\"text-right\"><input type=\"text\" name=\"product_price_quantity[{{ price_quantity_row }}][quantity]\" value=\"{{ product_price_quantity.quantity }}\" placeholder=\"{{ entry_quantity }}\" class=\"form-control\" /></td>\r\n                  \r\n                    <td class=\"text-right\"><input type=\"text\" name=\"product_price_quantity[{{ price_quantity_row }}][price]\" value=\"{{ product_price_quantity.price }}\" placeholder=\"{{ entry_price }}\" class=\"form-control\" /></td>\r\n                   \r\n                    <td class=\"text-left\"><button type=\"button\" onclick=\"$(\'#price_quantity-row{{ price_quantity_row }}\').remove();\" data-toggle=\"tooltip\" title=\"{{ button_remove }}\" class=\"btn btn-danger\"><i class=\"fa fa-minus-circle\"></i></button></td>\r\n                  </tr>\r\n                  {% set price_quantity_row = price_quantity_row + 1 %}\r\n                  {% endfor %}\r\n                    </tbody>\r\n                  \r\n                  <tfoot>\r\n                    <tr>\r\n                      <td colspan=\"2\"></td>\r\n                      <td class=\"text-left\"><button type=\"button\" onclick=\"addprice_quantity();\" data-toggle=\"tooltip\" title=\"{{ button_price_quantity_add }}\" class=\"btn btn-primary\"><i class=\"fa fa-plus-circle\"></i></button></td>\r\n                    </tr>\r\n                  </tfoot>\r\n                </table>\r\n				</div>\r\n				</div>\r\n		{% endif %}		\r\n		{% endif %}		\r\n       <!-- online product design Tab-->\r\n				\r\n			]]></add>\r\n	</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[var image_row = {{ image_row }};]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			\r\n	{% if module_purpletree_product_designer_status %}\r\n			   $(document).on(\'click\', function(e) {\r\n			 var checkedValue=e.target.checked;\r\n			var parentNode1=e.target.parentNode.id;\r\n			var ptsVar= $(\'#\'+parentNode1).hasClass(\'ptsalwaysontop\');\r\n			if(ptsVar){\r\n					$(\'#\'+e.target.id).val(0);\r\n					 if(checkedValue==true){\r\n						$(\'#\'+e.target.id).val(1);\r\n					 }\r\n			}\r\n		  });\r\n	var image_design_row = {{ image_design_row }};\r\n	 function addDesignImage() {\r\n		html  = \'<tr id=\"image-design-row\' + image_design_row + \'\">\';\r\n		\r\n		html += \' <td class=\"text-left use-img\"><select id=\"use-img-\'+ image_design_row +\'\" name=\"product_design_image[\'+ image_design_row +\'][use_img]\" class=\"form-control\" style=\"width:70px\"><option value=\"1\" selected=\"selected\">{{ text_yes }} </option><option value=\"0\">{{ text_no }} </option></select></td>\';\r\n		\r\n		html += \'<td class=\"text-left\" id=\"thumb-img-td-\'+image_design_row+\'\"><a href=\"\" id=\"thumb-design-image\' + image_design_row + \'\"data-toggle=\"image\" class=\"img-thumbnail\"><img src=\"{{ placeholder }}\" alt=\"\" title=\"\" data-placeholder=\"{{ placeholder }}\" /></a><img style=\"display:none\" id=\"thumb-design-thumb{{ image_design_row }}\" src=\"{{ product_design_image.design_thumb }}\" /><input type=\"hidden\" name=\"product_design_image[\' + image_design_row + \'][image]\" value=\"\" id=\"input-design-image\' + image_design_row + \'\" /><div class=\"text-left divheightwidth \" id=\"without-img-td-\'+image_design_row +\'\" style=\"display:none\"><div class=\"col-sm-9 \"> <div class=\"col-sm-5 \">Width</div><div class=\"col-sm-7 \"><input type=\"text\" name=\"product_design_image[\'+ image_design_row +\'][width]\" value=\"550\" placeholder=\"width\" class=\"form-control\" style=\"width: 70px;\" /></div></div><div class=\"col-sm-9 \"><div class=\"col-sm-5 \">Height</div> <div class=\"col-sm-7 \"><input type=\"text\" name=\"product_design_image[\'+image_design_row +\'][height]\" value=\"550\" placeholder=\"{{ text_height }}\" class=\"form-control\"  style=\"width: 70px;\"/></div></div></div></td>\';\r\n		\r\n		html += \'<td class=\"text-center\"><div id=\"alwaysontop\'+ image_design_row +\'\"  class=\"ptsalwaysontop\"><input style=\"margin-right: 4px;\" id=\"alwaysontopcheckbox\'+ image_design_row +\'\" type=\"checkbox\" name=\"product_design_image[\'+ image_design_row +\'][alwaysontop]\" value=\"\" /></div></td>\';\r\n		html += \'<td class=\"text-right\"><span class=\"btn btn-primary\" id=\"create-canvas_\'+ image_design_row +\'\" onclick=\"vewProductImage(this);\">{{ entry_create_canvas }}</span><input type=\"hidden\" name=\"product_design_image[\'+image_design_row +\'][canvas_area]\" id=\"create-canvas-area_\'+image_design_row+\'\" value=\"50,50,50,50\"></td>\';\r\n		html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[\' + image_design_row + \'][lable]\" value=\"\" placeholder=\"{{ entry_pts_lable }}\" class=\"form-control\" /></td>\';\r\n		html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[\' + image_design_row + \'][dpi]\" value=\"400\" placeholder=\"{{ entry_dpi }}\" class=\"form-control\" /></td>\';\r\n		\r\n		html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[\' + image_design_row + \'][safe_lines]\" disabled=\"disabled\" value=\"0\" placeholder=\"{{ entry_safe_line }}\" class=\"form-control\" /></td>\';		\r\n		html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[\' + image_design_row + \'][bleed_size]\" disabled=\"disabled\" value=\"0\" placeholder=\"{{ entry_bleed_size }}\" class=\"form-control\" /></td>\';\r\n		\r\n		html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[\' + image_design_row + \'][fold_line]\" disabled=\"disabled\" value=\"0\" placeholder=\"{{ entry_fold_line }}\" class=\"form-control\" /></td>\';\r\n		\r\n		html += \'  <td class=\"text-right\"><input type=\"text\" name=\"product_design_image[\' + image_design_row + \'][sort_order]\" value=\"0\" placeholder=\"{{ entry_sort_order }}\" class=\"form-control\" /></td>\';\r\n		html += \'  <td class=\"text-left\"><button type=\"button\" onclick=\"$(\\\'#image-design-row\' + image_design_row  + \'\\\').remove();\" data-toggle=\"tooltip\" title=\"{{ button_remove }}\" class=\"btn btn-danger\"><i class=\"fa fa-minus-circle\"></i></button></td>\';\r\n		html += \'</tr>\';\r\n		$(\'#design-images tbody\').append(html);\r\n		image_design_row++;\r\n	}\r\n		{% endif %}	\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$(\'input[name=\\\'manufacturer\\\']\').autocomplete({]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n					{% if module_purpletree_product_designer_status %}\r\n			var productDesignStatus=$(\'#input-product-design-status\').val();\r\n			if(productDesignStatus==\'1\'){\r\n			$(\'#pts-pro-design\').css(\'display\',\'block\');\r\n			$(\'.bookprnitnginput\').css(\'display\',\'none\');\r\n			}else {\r\n			$(\'#pts-pro-design\').css(\'display\',\'none\');\r\n			var bookprintingdiv=$(\'#input-product-book-printing\').val();\r\n			if(bookprintingdiv==\'1\'){\r\n			$(\'.bookprnitnginput\').css(\'display\',\'block\');\r\n			}else {\r\n			$(\'.bookprnitnginput\').css(\'display\',\'none\');\r\n			}\r\n			}\r\n\r\n			$(\'#input-product-book-printing\').on(\'change\',function(){\r\n			var bookprintingdiv=$(\'#input-product-book-printing\').val();\r\n			if(bookprintingdiv==\'1\'){\r\n			$(\'.bookprnitnginput\').css(\'display\',\'block\');\r\n			}else {\r\n			$(\'.bookprnitnginput\').css(\'display\',\'none\');\r\n			}	\r\n			});\r\n			$(\'#input-product-book-is_price_binding\').on(\'change\',function(){\r\n			var bookprintingdiv=$(\'#input-product-book-is_price_binding\').val();\r\n			if(bookprintingdiv==\'1\'){\r\n			$(\'.is_price_bindingdiv\').css(\'display\',\'block\');\r\n			}else {\r\n			$(\'.is_price_bindingdiv\').css(\'display\',\'none\');\r\n			}	\r\n			});\r\n			$(\'#input-product-design-status\').on(\'change\',function(){\r\n			var productDesignStatus=$(\'#input-product-design-status\').val();\r\n			if(productDesignStatus==\'1\'){\r\n			$(\'#pts-pro-design\').css(\'display\',\'block\');\r\n			$(\'.bookprintingdiv\').css(\'display\',\'none\');\r\n			}else {\r\n			$(\'.bookprintingdiv\').css(\'display\',\'block\');\r\n			$(\'#pts-pro-design\').css(\'display\',\'none\');\r\n			}	\r\n			});\r\n			\r\n				function vewProductImage(e){\r\n				var row_id = e.parentNode.parentNode.id;\r\n				var base_path=\'\';\r\n				if($(\'#\'+row_id+\' td input[id^=input-design-image]\').val()){\r\n				$(\"#view_design_image\").modal(\"show\");\r\n				base_path=\"{{ DESIGN_IMAGE_ROOT }}\"+$(\'#\'+row_id+\' td input[id^=input-design-image]\').val();\r\n				$(\'#\'+row_id+\' td img[id^=thumb-design-thumb]\').attr(\'src\',base_path);\r\n				$(\'#view_img\').attr(\'src\',base_path);\r\n				\r\n			 var div_width=\'\';\r\n			 var div_height=\'\'; \r\n			 var img_width=\'\';\r\n			 var img_height=\'\';\r\n			 \r\n		setTimeout(function(){\r\n			 img_width=$(\'#\'+row_id+\' td img[id^=thumb-design-thumb]\').width();\r\n			 img_height=$(\'#\'+row_id+\' td img[id^=thumb-design-thumb]\').height();\r\n			 \r\n			var div_width=$(\'#view_design_image .modal-dialog .modal-content .modal-body\').width();\r\n			\r\n			var div_height=(div_width*img_height)/img_width;\r\n\r\n			var can_input= e.id.split(\"_\");\r\n			var canva_area=$(\'#create-canvas-area_\'+can_input[1]).val().split(\",\");\r\n			var mar_left=(550-($(\"#view_img\").width()))/2;\r\n		//	alert(mar_left);\r\n			\r\n			var image_src=$(\'#\'+row_id+\' td img[id^=thumb-design-thumb]\').attr(\'src\');\r\n			//if(image_src){\r\n			var x_left=(50)+mar_left;\r\n			if(canva_area[0]){	\r\n			x_left=parseFloat(canva_area[0])+(mar_left);\r\n			}\r\n			\r\n			var x_top=50;\r\n			if(canva_area[1]){	\r\n			x_top=parseFloat(canva_area[1]);\r\n			}\r\n			\r\n			var x_width=50;\r\n			if(canva_area[2]){	\r\n			x_width=parseFloat(canva_area[2]);\r\n			}\r\n			\r\n			var x_height=50;\r\n			if(canva_area[2]){	\r\n			x_height=parseFloat(canva_area[3]);\r\n			}\r\n\r\n			 if(canva_area){\r\n			$( \"#canvas_draggable\" ).css(\'left\',x_left+\'px\');	\r\n			$( \"#canvas_draggable\" ).css(\'top\',x_top+\'px\');	\r\n			$( \"#canvas_draggable\" ).css(\'width\',x_width+\'px\');	\r\n			$( \"#canvas_draggable\" ).css(\'height\',x_height+\'px\');	\r\n			} \r\n			\r\n				 $(function() {\r\n					$( \"#canvas_draggable\" ).draggable({\r\n								containment: \'#view_img\', \r\n							   drag: function (event, ui) {\r\n								   \r\n								  var mar_left=(550-($(\"#view_img\").width()))/2; \r\n								 var posi_left=((ui.position.left)-mar_left);\r\n								  \r\n								  var posi_top=ui.position.top;\r\n								  var posi_width=($(\'#canvas_draggable\').css(\'width\')).replace(\'px\',\'\');\r\n								  \r\n								  var posi_height=($(\'#canvas_draggable\').css(\'height\')).replace(\'px\',\'\');\r\n								  \r\n								$(\'#create-canvas-area_\'+can_input[1]).val(posi_left+\',\'+posi_top+\',\'+posi_width+\',\'+posi_height);\r\n		   \r\n							   }\r\n							}).resizable({\r\n									  containment: \'#view_img\', \r\n								  resize: function (event, ui) {\r\n									  \r\n								 var mar_left=(550-($(\"#view_img\").width()))/2;\r\n\r\n								  var posi_left=((ui.position.left)-mar_left).toFixed(4);\r\n								  var posi_top=(ui.position.top).toFixed(4);\r\n								  \r\n								  var posi_width=(ui.size.width).toFixed(4);\r\n								  var posi_height=(ui.size.height).toFixed(4);\r\n								 \r\n									$(\'#create-canvas-area_\'+can_input[1]).val(posi_left+\',\'+posi_top+\',\'+posi_width+\',\'+posi_height);\r\n							   }\r\n								\r\n							});\r\n				  } );\r\n				}, 500);\r\n				} else {\r\n					$(\"#view_design_image\").modal(\"hide\");\r\n					alert(\'Please image upload\');\r\n				}\r\n			  }\r\n			  {% endif %}	\r\n			]]></add>\r\n	</operation>\r\n		<operation error=\"skip\">\r\n			<search ><![CDATA[{{ footer }}]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				{% if module_purpletree_product_designer_status %}\r\n		<!-- view Model -->\r\n   		  <div class=\"modal fade\" id=\"view_design_image\" role=\"dialog\">\r\n			<div class=\"modal-dialog\">\r\n			\r\n			  <!-- Modal content-->\r\n			  <div class=\"modal-content\">\r\n				<div class=\"modal-header\">\r\n				  <button type=\"button\" class=\"close\" data-dismiss=\"modal\">&times;</button>\r\n				  <h4 class=\"modal-title\">Create Design</h4>\r\n				</div>\r\n				<div class=\"modal-body\">\r\n				  <div class=\"canvas_draggable_div\">\r\n				 <img id=\"view_img\" src=\"\"> \r\n				<div id=\"canvas_draggable\" >\r\n				</div>\r\n				</div>\r\n				</div>\r\n				<div class=\"modal-footer\">\r\n				  <button type=\"button\" class=\"btn btn-default btn-primary\" data-dismiss=\"modal\">Save</button>\r\n				</div>\r\n			  </div>\r\n			  \r\n			</div>\r\n		  </div>\r\n   <!-- view Model -->\r\n  <link rel=\"stylesheet\" href=\"/resources/demos/style.css\">\r\n  <style>\r\n.canvas_draggable_div {\r\n	margin: 0 auto;\r\n	text-align: center;\r\n	width:550px;\r\n}\r\n#view_design_image .modal-dialog {\r\n	width:553px;\r\n}\r\n#view_design_image .modal-body {\r\n    width: 550px;\r\n}\r\n  #canvas_draggable { left:100px; top:100px; width: 150px; height: 150px; position:absolute; border: 2px dotted green; }\r\n  #view_design_image .modal-body {\r\n    position: relative;\r\n    padding: 0px;\r\n}\r\n#view_img{ max-width:100%;}\r\n.divheightwidth input{\r\n	width: 62px;\r\n    margin-left: 12px;\r\n    margin-bottom: 19px;\r\n}\r\n.divheightwidth div{\r\n	padding:0;\r\n	line-height: 35px;\r\n}\r\n.divheightwidth {\r\n	width:108px;\r\n}\r\n  </style>\r\n  {% endif %}]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/product/product.php\">\r\n	  <operation error=\"skip\">\r\n			<search index=\"0\"><![CDATA[$this->document->addStyle]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$this->document->addStyle(\'catalog/view/theme/default/stylesheet/ptsproductdesign/css/bookprinting.css\'); \r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[if ($product_info) {]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		if($this->config->get(\'module_purpletree_product_designer_status\')){\r\n			$this->load->model(\'extension/purpletree_product_designer/product_designer\');\r\n			$getProductDesignee = $this->model_extension_purpletree_product_designer_product_designer->getProductDesignLimit($product_id);\r\n			if($getProductDesignee) {\r\n				$data[\'customdesign\'] = $getProductDesignee[\'status\'];\r\n			}\r\n				}\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$data[\'recurrings\']]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n						if($this->config->get(\'module_purpletree_product_designer_status\')){\r\n						$this->load->model(\'extension/purpletree_product_designer/product_designer_book\');\r\n			$bookprinting = $this->model_extension_purpletree_product_designer_product_designer_book->getifbookprintingProduct($product_id); \r\n			$data[\'module_purpletree_product_designer_status\'] = $this->config->get(\'module_purpletree_product_designer_status\');\r\n				$data[\'module_purpletree_product_designer_template\'] = $this->config->get(\'module_purpletree_product_designer_template\');\r\n			if($bookprinting) {\r\n					$this->load->language(\'purpletree_product_designer/book_printing\');\r\n				$data[\'bookprinting\'] = 1;\r\n				\r\n				$data[\'price\'] = \'\';\r\n				$bookprinting = $this->model_extension_purpletree_product_designer_product_designer_book->getbookprintingProduct($product_id);\r\n				$data[\'price_per_page\'] = isset($bookprinting[\'price_per_page\'])?$this->currency->format($bookprinting[\'price_per_page\'], $this->session->data[\'currency\']):\'\';\r\n				$data[\'price_per_page_no_currency\'] = isset($bookprinting[\'price_per_page\'])?$bookprinting[\'price_per_page\']:\'\';\r\n				$data[\'price_binding\'] = isset($bookprinting[\'price_binding\'])?$this->currency->format($bookprinting[\'price_binding\'], $this->session->data[\'currency\']):\'\';			\r\n				$data[\'price_binding_no_currency\'] = isset($bookprinting[\'price_binding\'])?$bookprinting[\'price_binding\']:\'\';\r\n				$data[\'is_price_binding\'] = isset($bookprinting[\'is_price_binding\'])?$bookprinting[\'is_price_binding\']:0;	\r\n				$data[\'entry_qty\'] = \'No Of Copies.\';\r\n			} else {\r\n				if($this->config->get(\'module_purpletree_product_designer_template\')){\r\n						$this->load->model(\'extension/purpletree_product_designer/product_designer\');\r\n					$istemplateprodutc = $this->model_extension_purpletree_product_designer_product_designer->istemplateproduct($this->request->get[\'product_id\']);\r\n					if($istemplateprodutc) {\r\n					$getpriceqty = $this->model_extension_purpletree_product_designer_product_designer->getdiscount($product_id);\r\n						$data[\'price\'] = \'\';\r\n						$data[\'qtyprice\'] = $getpriceqty;\r\n						$data[\'istemplateprodutc\'] = 1;\r\n						if(!empty($getpriceqty)) {\r\n						foreach($getpriceqty as $keyyy => $priccccc) {\r\n						$data[\'qtyprice\'][$keyyy][\'price\'] =  $this->currency->format($priccccc[\'price\'], $this->session->data[\'currency\']);\r\n						}		\r\n						}						\r\n						\r\n						}\r\n				}\r\n				}\r\n					$getshortdesc = $this->model_extension_purpletree_product_designer_product_designer->getshortdescription($product_id);\r\n				if($getshortdesc) {\r\n				$data[\'short_description\'] = html_entity_decode($getshortdesc, ENT_QUOTES, \'UTF-8\');\r\n				if($data[\'short_description\'] == \'<br>\') {\r\n					$data[\'short_description\'] = \'\';\r\n				}\r\n				}\r\n			}\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	 <file path=\"catalog/controller/tool/upload.php\">\r\n	 <operation error=\"skip\">\r\n			<search><![CDATA[index()]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$uploadyourdesign = (isset($this->request->get[\'uploadyourdesign\']))?$this->request->get[\'uploadyourdesign\']:\'\';\r\n			$productpage = (isset($this->request->get[\'productpage\']))?$this->request->get[\'productpage\']:\'\';\r\n			$perpage = (isset($this->request->get[\'perpage\']))?$this->request->get[\'perpage\']:\'\';\r\n			$pagebinding = (isset($this->request->get[\'pagebinding\']))?$this->request->get[\'pagebinding\']:\'\';\r\n			$nextid = (isset($this->request->get[\'nextid\']))?$this->request->get[\'nextid\']:\'\';\r\n			$noofpages = (isset($this->request->get[\'noofpages\']))?$this->request->get[\'noofpages\']:\'\';\r\n			$selectedoption = (isset($this->request->get[\'selectedoption\']))?$this->request->get[\'selectedoption\']:array();\r\n			if($productpage != \'\'){\r\n				$priceaddoption = array();\r\n			$selectedoption = explode(\',\',$selectedoption);\r\n				if(!empty($selectedoption)) {\r\n				$this->load->model(\'catalog/product\');\r\n				$this->load->model(\'extension/purpletree_product_designer/product_designer_book\');\r\n					$product_info = $this->model_catalog_product->getProduct($productpage);\r\n					if ($product_info) {\r\n							foreach($selectedoption as $mmm) {\r\n								$vall = explode(\'_\',$mmm);\r\n								if(isset($vall[1])) {\r\n									$priceaddoption[] = $this->model_extension_purpletree_product_designer_product_designer_book->getoptionprice($vall,$productpage,$product_info[\'tax_class_id\']);\r\n								}\r\n							}\r\n					}\r\n				}\r\n			}\r\n			\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[if (!in_array(strtolower(substr(strrchr($filename, \'.\'), 1)), $allowed)) {]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			if($this->config->get(\'module_purpletree_product_designer_status\') AND $this->config->get(\'module_purpletree_product_designer_pdfproduct\')) {\r\n				if(isset($productpage) && $productpage != \'\'){\r\n					$allowed = array(\'pdf\');\r\n				}\r\n			}\r\n			if($this->config->get(\'module_purpletree_product_designer_status\') && $uploadyourdesign == 1) {\r\n				$allowed = array(\'JPG\',\'JPEG\',\'PNG\',\'jpg\',\'jpeg\',\'png\');\r\n			}\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[if (!$json) {]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n	$json[\'filename\'] = $filename;\r\n			if(isset($pages)) {\r\n				$json[\'pagesuniq\']= $pages;\r\n			}\r\n			if(isset($nextid1)) {\r\n				$json[\'nextid\']= $nextid1;\r\n			}\r\n			if(isset($optionalpdffilesname)) {\r\n				$json[\'optionalpdffilesname\']= $optionalpdffilesname;\r\n			}\r\n			if(isset($optionalpdffiles)) {\r\n				$json[\'optionalpdffiles\']= $optionalpdffiles;\r\n			}\r\n			if(isset($caluclateprice_no)) {\r\n				$json[\'caluclateprice_no\'] = $caluclateprice_no;\r\n			}\r\n			if(isset($caluclateprice)) {\r\n				$json[\'caluclateprice\'] = $caluclateprice;\r\n			}\r\n			if(isset($noofpages)) {\r\n			$json[\'pages\'] = $noofpages;\r\n			}\r\n			if($this->config->get(\'module_purpletree_product_designer_status\') && $uploadyourdesign == 1) {\r\n				copy($this->request->files[\'file\'][\'tmp_name\'], DIR_IMAGE .\'catalog/ptsdesigner/\'. $filename);\r\n			}\r\n			]]></add>\r\n		</operation>\r\n			<operation error=\"skip\">\r\n			<search><![CDATA[if (!$json) {]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			if (!$json) {\r\nif($this->config->get(\'module_purpletree_product_designer_status\') AND $this->config->get(\'module_purpletree_product_designer_pdfproduct\')) {\r\n				$this->load->model(\'extension/purpletree_product_designer/product_designer_book\');\r\n				if($productpage != \'\'){\r\n					copy($this->request->files[\'file\'][\'tmp_name\'], DIR_UPLOAD . $filename);\r\n					//$pdftext = file_get_contents(DIR_UPLOAD . $filename);\r\n					//$pages = preg_match_all(\"/\\/Page\\W/\", $pdftext, $dummy);\r\n					$pages = $this->getNumPagesInPDF(DIR_UPLOAD . $filename);\r\n					unlink(DIR_UPLOAD . $filename);\r\n					if($pagebinding != \'\' && $perpage != \'\') {\r\n						if($pages > 0) {\r\n							if($noofpages != \'\') {\r\n							$noofpages = $pages+$noofpages;	\r\n							} else {\r\n							$noofpages = $pages;	\r\n							}\r\n							$optionval = 0;\r\n							if(!empty($priceaddoption)) {\r\n								foreach($priceaddoption as $ppp) {\r\n									$optionval += ($ppp*$noofpages);\r\n								}\r\n							}\r\n							$caluclateprice = $this->currency->format((($noofpages*$perpage)+$pagebinding+$optionval), $this->session->data[\'currency\']);\r\n							$caluclateprice_no = (($noofpages*$perpage)+$pagebinding+$optionval);\r\n							\r\n							$nextid1 = 1;\r\n							if($nextid != \'\') {\r\n								$nextid1 = (int)$nextid+1;\r\n							}\r\n								$optionalpdffiles = $this->model_extension_purpletree_product_designer_product_designer_book->getnextupload($nextid1);\r\n								if($optionalpdffiles) {\r\n									$optionalpdffilesname = \"PDF Upload \".$nextid1;\r\n								}\r\n						} else {\r\n							$json[\'error\'] = \'PDF is corrupted or Encrypted\';\r\n						}\r\n					} else {\r\n						$json[\'error\'] = \'Something Went wrong, please try again.\';\r\n					}\r\n				} \r\n			}\r\n			}\r\n			]]></add>\r\n		</operation>\r\n	<operation error=\"skip\">\r\n			<search><![CDATA[index()]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n	public function getNumPagesInPDF($file) {\r\n        if(!file_exists($file))return null;\r\n        if (!$fp = @fopen($file,\"r\"))return null;\r\n        $max=0;\r\n        while(!feof($fp)) {\r\n                $line = fgets($fp,255);\r\n                if (preg_match(\'/\\/Count [0-9]+/\', $line, $matches)){\r\n                        preg_match(\'/[0-9]+/\',$matches[0], $matches2);\r\n                        if ($max<$matches2[0]) $max=$matches2[0];\r\n                }\r\n        }\r\n        fclose($fp);\r\n        return (int)$max;\r\n    }\r\n	public function removepages() {\r\n			$productpage = (isset($this->request->get[\'productpage\']))?$this->request->get[\'productpage\']:\'\';\r\n			$perpage = (isset($this->request->get[\'perpage\']))?$this->request->get[\'perpage\']:\'\';\r\n			$pagebinding = (isset($this->request->get[\'pagebinding\']))?$this->request->get[\'pagebinding\']:\'\';\r\n			$noofpages = (isset($this->request->get[\'noofpages\']))?$this->request->get[\'noofpages\']:\'\';\r\n				$selectedoption = (isset($this->request->get[\'selectedoption\']))?$this->request->get[\'selectedoption\']:array();\r\n			if($productpage != \'\'){\r\n				$priceaddoption = array();\r\n			$selectedoption = explode(\',\',$selectedoption);\r\n				if(!empty($selectedoption)) {\r\n				$this->load->model(\'catalog/product\');\r\n				$this->load->model(\'extension/purpletree_product_designer/product_designer_book\');\r\n					$product_info = $this->model_catalog_product->getProduct($productpage);\r\n					if ($product_info) {\r\n							foreach($selectedoption as $mmm) {\r\n								$vall = explode(\'_\',$mmm);\r\n								if(isset($vall[1])) {\r\n									$priceaddoption[] = $this->model_extension_purpletree_product_designer_product_designer_book->getoptionprice($vall,$productpage,$product_info[\'tax_class_id\']);\r\n								}\r\n							}\r\n					}\r\n				}\r\n			}\r\n			if($perpage != \'\' && $pagebinding != \'\' && $noofpages !=\'\') {\r\n				if($noofpages == 0) {\r\n					$caluclateprice_no = \'\';\r\n					$caluclateprice    = \'\';\r\n					$noofpages 		   = \'\';\r\n				} else {\r\n					$optionval = 0;\r\n							if(!empty($priceaddoption)) {\r\n								foreach($priceaddoption as $ppp) {\r\n									$optionval += ($ppp*$noofpages);\r\n								}\r\n							}\r\n					$caluclateprice 			= $this->currency->format((($noofpages*$perpage)+$pagebinding+$optionval), $this->session->data[\'currency\']);\r\n					$caluclateprice_no  		= (($noofpages*$perpage)+$pagebinding+$optionval);\r\n				}\r\n				$json[\'caluclateprice_no\'] 	= $caluclateprice_no;\r\n				$json[\'caluclateprice\'] 	= $caluclateprice;\r\n				$json[\'pages\'] 				= $noofpages;\r\n				$this->response->addHeader(\'Content-Type: application/json\');\r\n				$this->response->setOutput(json_encode($json));\r\n			}\r\n	}\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	 <file path=\"catalog/view/theme/*/template/product/product.twig\">\r\n	<operation error=\"skip\">\r\n			<search><![CDATA[id=\"button-cart\"]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			 {% if module_purpletree_product_designer_status and customdesign == 1 and not singlecartbutton %}\r\