 = 0;\r\n				if(is_price_binding == 1) {\r\n					pagebinding = {{ price_binding_no_currency }};\r\n				}\r\n			} \r\n			if($(this).parent().hasClass(\'required\')) {\r\n				 var thisitem = 0;\r\n				if($(this).parent().children().hasClass(\'text-fulename\')) {\r\n				 var thisitem = $(this).parent().children(\'small.text-fulename\').attr(\'pagesuniq\');\r\n				 }\r\n				 noofpages = 0;\r\n				$(\".pagesuniq\").each(function() {\r\n						noofpages = parseFloat($(this).attr(\'pagesuniq\'))+parseFloat(noofpages);\r\n				});\r\n				noofpages = parseFloat(noofpages)-parseFloat(thisitem);\r\n				 productpage = {{ product_id }};\r\n				var perpage = {{ price_per_page_no_currency }};\r\n				var is_price_binding = {{ is_price_binding }};\r\n				var pagebinding = 0;\r\n				if(is_price_binding == 1) {\r\n					pagebinding = {{ price_binding_no_currency }};\r\n				}\r\n			}\r\n			{% endif %}\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[$(\'button[id^=\\\'button-upload\\\']\').on(\'click\', function () {]]></search>\r\n			<add position=\"replace\"><![CDATA[$(document).on(\'click\', \'button[id^=\\\'button-upload\\\']\', function () {]]></add>\r\n		</operation>\r\n			<operation error=\"skip\">\r\n			<search><![CDATA[$(\'.text-danger\').remove();]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$(node).parent().find(\'.text-fulename\').remove();\r\n				 {% if bookprinting %}\r\n			if(productpage != \'\') {\r\n				 //$(\'.text-fulename\').remove();\r\n				 $(\'.product-price-afterpdf\').text(\'\');\r\n				 $(\'.product-price-pages\').text(\'\');\r\n				 $(\'.product-price-afterpdf\').attr(\'price\',\'\');\r\n				  $(\'#pdftotal\').val(\'\');\r\n				  $(\'#no_of_pagesid\').val(\'\');\r\n			 }\r\n			{% endif %}\r\n				if(uploadyourdesign == 1) {\r\n				$(\'#bbttnid2\').css(\'display\',\'none\');\r\n				$(\'.uploadbttnn\').css(\'display\',\'block\');\r\n				$(\'#bbttnid3\').removeAttr(\'disabled\');\r\n				$(\'#bbttnid3\').removeClas