ile option-file-pdfoptional\"><label class=\"control-label\">\'+optionalpdffilesname+\'</label><button type=\"button\" id=\"button-upload\'+optionalpdffiles+\'\" data-loading-text=\"Loading...\" class=\"btn btn-default btn-block\"><i class=\"fa fa-upload\"></i> Upload File</button><input type=\"hidden\" name=\"optionalpdffiles[optionalpdffiles][\'+optionalpdffilesname+\']\" value=\"\" id=\"input-option\'+optionalpdffiles+\'\"></div>\');\r\n			 }\r\n			 }\r\n			 if (json[\'pages\']) {\r\n				  $(\'.product-price-pages\').text(\'No of Pages: \'+json[\'pages\']);\r\n				  $(\'#no_of_pagesid\').val(json[\'pages\']);\r\n				  if(json[\'caluclateprice\'] && json[\'caluclateprice_no\']) {\r\n				  $(\'.product-price-afterpdf\').text(json[\'caluclateprice\']);\r\n				  $(\'.product-price-afterpdf\').attr(\'price\',json[\'caluclateprice_no\']);\r\n				  $(\'#pdftotal\').val(json[\'caluclateprice_no\']);\r\n				  }\r\n			  }\r\n			{% endif %}\r\n			]]></add>\r\n		</operation>\r\n	\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[{% if recurrings %}]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		 {% if bookprinting %}\r\n			<ul class=\"list-unstyled price\">\r\n			    <li price=\"{{ price_per_page_no_currency }}\" class=\"price_per_page\">{{ entry_price_per_page }} {{ price_per_page }}</li>\r\n				 {% if is_price_binding %}\r\n			    <li price=\"{{ price_binding_no_currency }}\" class=\"price_binding\">{{ entry_price_binding }} {{ price_binding }}</li>\r\n					 <input type=\"hidden\" name=\"pdfprice[binding_price]\" id=\"binding_priceid\" value=\"{{ price_binding_no_currency }}\" />\r\n				{% endif %}\r\n				     <li class=\"product-price-pages\"></li>\r\n				      <li class=\"product-price-afterpdf product-price\"></li>\r\n					 <input type=\"hidden\" name=\"pdfprice[total]\" id=\"pdftotal\" value=\"\" />\r\n					 <input type=\"hidden\" name=\"pdfprice[price_per_page]\" id=\"price_per_pageid\" value=\"{{ price_per_page_no_currency }}\" />\r\n					 <input type