;\r\n				} else {\r\n					$image_full = $this->config->get(\'config_url\') . \'image/\';\r\n				}\r\n					foreach($product[\'canvas_images\'] as $orderitems) {\r\n						$product[\'canvas_image_c\'][] = array(\'id\' => $orderitems[\'id\'],\'image_label\' => $orderitems[\'image_label\'], \'product_image\'=> $this->model_tool_image->resize($orderitems[\'product_image\'],20,20),\'image_full\'=> $image_full.$orderitems[\'product_image\']);\r\n					}\r\n				}\r\n				}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n				<search><![CDATA[$data[\'product\']= array(]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n			 \'canvas_images\'  => $product[\'canvas_image_c\'],\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n		<search><![CDATA[$value = $option[\'value\'];]]></search>\r\n				<add position=\"after\"><![CDATA[\r\n				//module_purpletree_product_designer_status\r\n					if($option[\'product_option_id\']==\'\'){\r\n						$value = $this->currency->format($option[\'value\'], $this->session->data[\'currency\']);	\r\n						}\r\n			//module_purpletree_product_designer_status\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n		<file path=\"catalog/view/theme/so-emarket/template/product/product.twig\">\r\n	<operation error=\"skip\">\r\n		<search><![CDATA[{% if istemplateprodutc and qtyprice %} 	{% else %} <!--ptsqtyprice1-->]]></search>\r\n		<add position=\"replace\"><![CDATA[ ]]></add>\r\n	</operation>\r\n	<operation error=\"skip\">\r\n		<search><![CDATA[<div class=\"option quantity\">]]></search>\r\n		<add position=\"after\"><![CDATA[\r\n			{% if istemplateprodutc and qtyprice %} 	{% else %}\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[<span class=\"input-group-addon product_quantity_up fa fa-plus\"></span>]]></search>\r\n			<add positio