ion>', 0, '2021-07-27 07:10:19');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(9, 15, 'Xtensions-Best Checkout and Customer FrameWork', 'xtensions_best_checkout', 'Xtensions', 'Module_Version_5.0.3.4_OC_V_3.x.', 'https://www.opencart.com/index.php?route=marketplace/extension/info&extension_id=20736', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <name>Xtensions-Best Checkout and Customer FrameWork</name>\n    <version>Module_Version_5.0.3.4_OC_V_3.x.x.x</version>\n    <author>Xtensions</author>\n    <link>https://www.opencart.com/index.php?route=marketplace/extension/info&amp;extension_id=20736</link>\n    <code>xtensions_best_checkout</code>	\n	<file path=\"admin/controller/customer/custom_field.php\">\n		<operation>\n			<search><![CDATA[\'sort_order\'      => $result[\'sort_order\'],]]></search>\n			<add position=\"after\"><![CDATA[\n				\'edit_custom\'     => $this->url->link($this->config->get(\'xtensions_custom_fields_path\').\'/edit\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&custom_field_id=\' . $result[\'custom_field_id\'] . $url, true),\n			]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[if (isset($this->request->post[\'selected\'])) {]]></search>\n			<add position=\"before\"><![CDATA[\n        		$data[\'button_edit_custom\'] = $this->language->get(\'button_edit_custom\');\n        		$data[\'button_add_custom\'] = $this->language->get(\'button_add_custom\');\n        		$data[\'add_custom\'] = $this->url->link($this->config->get(\'xtensions_custom_fields_path\').\'/add\', \'user_token=\' . $this->session->data[\'user_token\'] . $url, true);\n        ]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/language/*/customer/custom_field.php\">\n		<operation>\n			<search><![CDATA[<?php]]></search>\n			<add position=\"after\"><![CDATA[\n				$_[\'button_edit_custom\']                = \'Edit using Xtensions Custom Fields\';\n				$_[\'button_add_custom\']                 = \'Add New using Xtensions Custom Fields\';\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/view/template/customer/custom_field_list.twig\">\n		<operation>\n			<search><![CDATA[<td class=\"text-right\"><a href=\"{{ custom_field.edit }}\" data-toggle=\"tooltip\" title=\"{{ button_edit }}\" class=\"btn btn-primary\"><i class=\"fa fa-pencil\"></i></a></td>]]></search>\n			<add position=\"replace\"><![CDATA[\n				<td class=\"text-right\"><a href=\"{{ custom_field.edit_custom }}\" data-toggle=\"tooltip\" title=\"{{ button_edit_custom }}\" class=\"btn btn-primary\"><i class=\"fa fa-pencil\"></i> {{ button_edit_custom }}</a><a href=\"{{ custom_field.edit }}\" data-toggle=\"tooltip\" title=\"{{ button_edit }}\" class=\"btn btn-primary\"><i class=\"fa fa-pencil\"></i></a></td>\n			]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[<div class=\"pull-right\"><a href=\"{{ add }}\" data-toggle=\"tooltip\" title=\"{{ button_add }}\" class=\"btn btn-primary\"><i class=\"fa fa-plus\"></i></a>]]></search>\n			<add position=\"replace\"><![CDATA[\n				<div class=\"pull-right\"><a href=\"{{ add_custom }}\" data-toggle=\"tooltip\" title=\"{{ button_add_custom }}\" class=\"btn btn-primary\"><i class=\"fa fa-plus\"></i> {{ button_add_custom }}</a><a href=\"{{ add }}\" data-toggle=\"tooltip\" title=\"{{ button_add }}\" class=\"btn btn-primary\"><i class=\"fa fa-plus\"></i></a>\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/view/template/sale/order_invoice.twig\">\n		<operation error=\"skip\">\n			<search><![CDATA[{{ order.payment_address }}]]></search>\n			<add position=\"after\"><![CDATA[\n			{% if order[\'customer_fields\'] %} {{ \'<br/>\' }} {% endif %}\n			{% for field in order[\'customer_fields\'] %}\n			{{ field?\'<br/>\'~field:\'\' }}\n			{% endfor %}			\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/view/template/sale/order_shipping.twig\">\n		<operation error=\"skip\">\n			<search><![CDATA[{{ order.telephone }}</td>]]></search>\n			<add position=\"replace\"><![CDATA[\n			{{ order.telephone }}	\n			{% if order[\'customer_fields\'] %} {{ \'<br/>\' }} {% endif %}\n			{% for field in order[\'customer_fields\'] %}\n			{{ field?\'<br/>\'~field:\'\' }}\n			{% endfor %}\n			</td>\n       		]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/controller/sale/order.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[$data[\'products\'] = array();]]></search>\n			<add position=\"before\"><![CDATA[\n        //xtensions- Custom Fields\n  			if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$order_info[\'store_id\'])){\n  				$formatted_address = $this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_path\'))->getFormattedAddressForOrder($order_info);\n  				$data[\'payment_address\'] = $formatted_address[\'payment_address_formatted\'];\n  				$data[\'shipping_address\'] = $formatted_address[\'shipping_address_formatted\'];\n  			}\n  			//xtensions- Custom Fields\n			]]></add>\n		</operation>\n		<operation error=\"skip\">\n			<search><![CDATA[$product_data = array();]]></search>\n			<add position=\"before\"><![CDATA[\n        //xtensions- Custom Fields\n				$customer_fields =array();\n				if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$order_info[\'store_id\'])){\n					$customer_fields =array();\n					$fieldData = $this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_path\'))->getCustomFieldByIdentifier($order_info[\'custom_field\'],\'account\');\n					foreach($this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_path\'))->getCustomFieldsAll($order_info[\'customer_group_id\']) as $field){\n						if($field[\'location\']==\'account\' && $field[\'invoice\']){\n							if(isset($fieldData[$field[\'identifier\']])){\n								$customer_fields[] = $fieldData[$field[\'identifier\']];\n							}\n						}\n					}\n					$formatted_address = $this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_path\'))->getFormattedAddressForOrder($order_info);\n					$payment_address = $formatted_address[\'payment_address_formatted\'];\n					$shipping_address = $formatted_address[\'shipping_address_formatted\'];\n				}\n				//xtensions- Custom Fields\n			]]></add>\n		</operation>\n		<operation error=\"skip\">\n			<search><![CDATA[\'order_id\'	       => $order_id,]]></search>\n			<add position=\"before\"><![CDATA[\n        //xtensions- Custom Fields\n        \'customer_fields\'	 => $customer_fields,\n        //xtensions- Custom Fields\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/controller/startup/startup.php\">\n		<operation>\n			<search><![CDATA[$this->registry->set(\'cart\', new Cart\\Cart($this->registry));]]></search>\n			<add position=\"after\"><![CDATA[\n        $xtensions_checkout = new XtensionsCheckout($this->registry);\n  			$this->registry->set(\'xtensions_checkout\', $xtensions_checkout);\n                ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/startup/startup.php\">\n		<operation>\n			<search><![CDATA[$this->registry->set(\'cart\', new Cart\\Cart($this->registry));]]></search>\n			<add position=\"after\"><![CDATA[\n        	$xtensions_checkout = new XtensionsCheckout($this->registry);\n  			$this->registry->set(\'xtensions_checkout\', $xtensions_checkout);\n                ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/checkout/success.php\">\n	    <operation>\n			<search><![CDATA[unset($this->session->data[\'shipping_method\']);]]></search>\n			<add position=\"before\"><![CDATA[\n            if($this->registry->has(\'xtensions_checkout\') && $this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n				$this->xtensions_checkout->unsetters($this);\n			}\n            ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/checkout/checkout.php\">\n		<operation>\n			<search><![CDATA[$this->response->setOutput($this->load->view(\'checkout/checkout\', $data));]]></search>\n			<add position=\"replace\"><![CDATA[\n        // Xtensions Best Checkout\n    		if ($this->xtensions_checkout->isActive(\'xtensions_best_checkout\', $this->config->get(\'config_store_id\'))) {\n    			$data += $this->load->language($this->config->get(\'xtensions_language_path\'));\n    			$data[\'xtensions_controller_path\'] = $this->config->get(\'xtensions_controller_path\');\n    			$data[\'xheader\'] = $this->load->controller($data[\'xtensions_controller_path\'].\'xheader\');\n    			$data[\'xfooter\'] = $this->load->controller($data[\'xtensions_controller_path\'].\'xfooter\');\n    			$data[\'xcvc\'] = $this->load->controller($data[\'xtensions_controller_path\'].\'xcvc\');\n\n    			$modData = $this->xtensions_checkout->getXtensionsData($this->config->get(\'config_store_id\'), \'xtensions_best_checkout\');\n    			$data[\'custom_js\'] = isset($modData[\'xconfig\'][\'design\'][\'js\']) ? html_entity_decode($modData[\'xconfig\'][\'design\'][\'js\'], ENT_QUOTES, \'UTF-8\') : \'\';\n    			if(isset($modData[\'xconfig\'][\'options\'][\'show_country_code\']) && $modData[\'xconfig\'][\'options\'][\'show_country_code\']){\n    				$data[\'has_country_code\'] = $this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_model_path\'))->getCountryCode($this->customer->getId());	\n    			}else{\n    				$data[\'has_country_code\'] = true;\n    			}\n    			    			\n    			$this->response->setOutput($this->load->view($this->config->get(\'xtensions_view_path\').\'xcheckout\', $data));\n    			// Xtensions Best Checkout\n    		} else {\n    			$this->response->setOutput($this->load->view(\'checkout/checkout\', $data));\n    		}\n			]]></add>\n		</operation>\n		<operation error=\"skip\">\n			<search><![CDATA[$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/moment.js\');]]></search>\n			<add position=\"replace\"><![CDATA[\n        if ($this->xtensions_checkout->isActive(\'xtensions_best_checkout\', $this->config->get(\'config_store_id\'))) {\n        	// $this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/moment.js\'); - Included by Xtensions\n        } else {\n        	 $this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/moment.js\');\n        }\n        ]]></add>\n		</operation>\n    <operation error=\"skip\">\n			<search><![CDATA[$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.js\');]]></search>\n			<add position=\"replace\"><![CDATA[\n        if ($this->xtensions_checkout->isActive(\'xtensions_best_checkout\', $this->config->get(\'config_store_id\'))) {\n    			// $this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.js\'); - Included by Xtensions\n    		} else {\n    			$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.js\');\n    		}\n        ]]></add>\n		</operation>\n    <operation error=\"skip\">\n			<search><![CDATA[$this->document->addStyle(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.css\');]]></search>\n			<add position=\"replace\"><![CDATA[\n        if ($this->xtensions_checkout->isActive(\'xtensions_best_checkout\', $this->config->get(\'config_store_id\'))) {\n    			// $this->document->addStyle(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.css\'); - Included by Xtensions\n    		} else {\n    			$this->document->addStyle(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.css\');\n    		}\n        ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/checkout/confirm.php\">\n		<operation>\n			<search><![CDATA[$this->response->setOutput($this->load->view(\'checkout/confirm\', $data));]]></search>\n			<add position=\"replace\"><![CDATA[\n        // Xtensions Best Checkout\n        if ($this->xtensions_checkout->isActive(\'xtensions_best_checkout\', $this->config->get(\'config_store_id\'))) {\n    			$this->response->setOutput($this->load->view($this->config->get(\'xtensions_view_path\').\'xconfirm\', $data));\n    		} else {\n    			$this->response->setOutput($this->load->view(\'checkout/confirm\', $data));\n    		}\n        // Xtensions Best Checkout\n        ]]></add>\n		</operation>\n    <operation>\n			<search><![CDATA[$this->session->data[\'order_id\'] = $this->model_checkout_order->addOrder($order_data);]]></search>\n			<add position=\"replace\"><![CDATA[\n        // Xtensions Best Checkout\n            $xconfig = $this->xtensions_checkout->getXtensionsData($this->config->get(\'config_store_id\'), \'xtensions_best_checkout\');\n            $misc_options = $xconfig[\'xconfig\'][\'options\'];\n            if(isset($misc_options[\'payment\'][\'content\'][$this->session->data[\'payment_method\'][\'code\']][$this->config->get(\'config_language_id\')])){\n            	$data[\'before_content\'] = html_entity_decode($misc_options[\'payment\'][\'content\'][$this->session->data[\'payment_method\'][\'code\']][$this->config->get(\'config_language_id\')], ENT_QUOTES, \'UTF-8\');\n            }else{\n            	$data[\'before_content\'] = \'\';\n            }\n  			$data[\'isBestActive\'] = $this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'));\n  			if(!isset($this->session->data[\'order_id\']) || !$this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n  				$this->session->data[\'order_id\'] = $this->model_checkout_order->addOrder($order_data);\n  			}else if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\')) && isset($misc_options[\'order_id_criteria\']) && $misc_options[\'order_id_criteria\'] == \'new\'){\n  				$this->session->data[\'order_id\']   =   $this->model_checkout_order->addOrder( $order_data ) ;\n  			}else{\n  			    $this->request->get[\'xtensions_edit_donotaddhistory\'] = true;\n  				$this->model_checkout_order->editOrder($this->session->data[\'order_id\'],$order_data);\n  				$this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_model_path\'))->editOrderXtensions($this->session->data[\'order_id\'],$order_data);\n  			}\n  			$this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_model_path\'))->setOrderCountryCode($this->session->data[\'order_id\']);\n  			// Xtensions Best Checkout\n        ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/mail/order.php\">\n		<operation error=\"skip\">\n			<search index=\"0\"><![CDATA[$data[\'ip\'] = $order_info[\'ip\'];]]></search>\n			<add position=\"after\"><![CDATA[\n        // Xtensions Best Checkout\n				$data[\'customer_fields\'] = array();\n				if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n\n					$fieldData = $this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_model_path\'))->getCustomFieldByIdentifier($order_info[\'custom_field\'],\'account\');\n					foreach($this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_model_path\'))->getCustomFields($order_info[\'customer_group_id\']) as $field){\n						if($field[\'location\']==\'account\' && $field[\'email_display\']){\n							if(isset($fieldData[$field[\'identifier\']])){\n								$data[\'customer_fields\'][] = array(\'name\'=>$field[\'name\'],\'value\'=>$fieldData[$field[\'identifier\']]);\n							}\n						}\n					}\n				}\n				// Xtensions Best Checkout\n      ]]></add>\n		</operation>\n		<operation error=\"skip\">\n			<search index=\"0\"><![CDATA[$data[\'products\'] = array();]]></search>\n			<add position=\"before\"><![CDATA[\n        // Xtensions Best Checkout\n				if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n					$formatted_address = $this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_model_path\'))->getFormattedAddressForOrder($order_info);\n					$data[\'payment_address\'] = $formatted_address[\'payment_address_formatted\'];\n					$data[\'shipping_address\'] = $formatted_address[\'shipping_address_formatted\'];\n				}\n				// Xtensions Best Checkout\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/model/checkout/order.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[\'order_id\'                => $order_query->row[\'order_id\'],]]></search>\n			<add position=\"after\"><![CDATA[\n        // Xtensions Best Checkout\n        			\'customer_group_id\'       => $order_query->row[\'customer_group_id\'],\n        // Xtensions Best Checkout\n        ]]></add>\n		</operation>\n		<operation error=\"skip\">\n			<search><![CDATA[public function addOrderHistory(]]></search>\n			<add position=\"after\"><![CDATA[        // Xtensions Best Checkout\n		if(isset($this->request->get[\'xtensions_edit_donotaddhistory\'])){\n			unset($this->request->get[\'xtensions_edit_donotaddhistory\']);\n			return ;\n		}\n		// Xtensions Best Checkout]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/view/theme/*/template/mail/order_add.twig\">\n		<operation>\n			<search><![CDATA[<b>{{ text_ip }}</b> {{ ip }}<br />]]></search>\n			<add position=\"before\"><![CDATA[\n			{% for field in customer_fields %}\n  			{% if field[\'value\'] %}\n            	<b>{{ field[\'name\'] }}</b> {{ field[\'value\'] }}<br />\n            {% endif %}\n            {% endfor %}\n      ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/account/order.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[$data[\'shipping_method\'] = $order_info[\'shipping_method\'];]]></search>\n			<add position=\"before\"><![CDATA[\n        //xtensions- Custom Fields\n  			if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n  				$formatted_address = $this->xtensions_checkout->getXtensionsModel($this->config->get(\'xtensions_custom_fields_model_path\'))->getFormattedAddressForOrder($order_info);\n  				$data[\'payment_address\'] = $formatted_address[\'payment_address_formatted\'];\n  				$data[\'shipping_address\'] = $formatted_address[\'shipping_address_formatted\'];\n  			}\n  			//xtensions- Custom Fields\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/controller/account/address.php\">\n		<operation>\n			<search><![CDATA[public function add() {]]></search>\n			<add position=\"after\"><![CDATA[\n        if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n    			$this->response->setOutput($this->load->controller($this->config->get(\'xtensions_account_controller_path\').\'address/add\', \'\', \'SSL\'));\n    			return \'\';\n    		}\n      ]]></add>\n		</operation>\n    <operation>\n			<search><![CDATA[public function edit() {]]></search>\n			<add position=\"after\"><![CDATA[\n        if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n    			$this->response->setOutput($this->load->controller($this->config->get(\'xtensions_account_controller_path\').\'address/edit\', \'\', \'SSL\'));\n    			return \'\';\n    		}\n      ]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[$data[\'add\'] = $this->url->link(\'account/address/add\', \'\', true);]]></search>\n			<add position=\"before\"><![CDATA[\n        if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n			$data[\'addresses\'] = $this->load->controller($this->config->get(\'xtensions_account_controller_path\').\'address/addresses\');\n		}\n      ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/account/edit.php\">\n		<operation>\n			<search><![CDATA[public function index() {]]></search>\n			<add position=\"after\"><![CDATA[\n        if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n    			$this->response->setOutput($this->load->controller($this->config->get(\'xtensions_account_controller_path\').\'edit\', \'\', \'SSL\'));\n    			return \'\';\n    		}\n        ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/account/register.php\">\n		<operation>\n			<search><![CDATA[public function index() {]]></search>\n			<add position=\"after\"><![CDATA[\n        if($this->xtensions_checkout->isActive(\'xtensions_best_checkout\',$this->config->get(\'config_store_id\'))){\n    			$this->response->setOutput($this->load->controller($this->config->get(\'xtensions_account_controller_path\').\'register\', \'\', \'SSL\'));\n    			return;\n    		}\n        ]]></add>\n		</operation>\n	</file>\n</modification>\n', 1, '2021-08-09 14:20:46'),
(10, 16, 'Additional pages (Bestseller, Latest, Mostviewed, All products)', 'Additional pages (Bestseller, Latest, Mostviewed, All products)', 'Dashko L. (kagan). Email: dev.dashko@gmail.com', '1.3.1', 'http://opencart-modules.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification>\r\n  <name>Additional pages (Bestseller, Latest, Mostviewed, All products)</name>\r\n  <code>Additional pages (Bestseller, Latest, Mostviewed, All products)</code>\r\n  <version>1.3.1</version>\r\n  <author>Dashko L. (kagan). Email: dev.dashko@gmail.com</author>\r\n  <link>http://opencart-modules.com</link>\r\n\r\n<!-- Adding links to additional pages in the footer -->\r\n  <file path=\"catalog/controller/common/footer.php\">\r\n    <operation>\r\n      <search><![CDATA[$data[\'text_special\'] = $this->language->get(\'text_special\');]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      $data[\'text_bestseller\'] = $this->language->get(\'text_bestseller\');\r\n      $data[\'text_latest\'] = $this->language->get(\'text_latest\');\r\n      $data[\'text_mostviewed\'] = $this->language->get(\'text_mostviewed\');\r\n      $data[\'text_all_products\'] = $this->language->get(\'text_all_products\');\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      ]]></add>\r\n    </operation>\r\n    <operation>\r\n      <search><![CDATA[$data[\'special\'] = $this->url->link(\'product/special\');]]></search>\r\n      <add position=\"after\"><![CDATA[\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      $data[\'bestseller\'] = $this->url->link(\'product/bestseller\');\r\n      $data[\'latest\'] = $this->url->link(\'product/latest\');\r\n      $data[\'mostviewed\'] = $this->url->link(\'product/mostviewed\');\r\n      $data[\'all_products\'] = $this->url->link(\'product/all-products\');\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n<!-- Adding links to additional pages in the footer -->\r\n  <file path=\"catalog/view/theme/*/template/common/footer.twig\">\r\n    <operation>\r\n      <search><![CDATA[<li><a href=\"<?php echo $special; ?>\">]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n      {# Additional pages (bestseller, latest, mostviewed) #}\r\n      <li><a href=\"{{ bestseller }}\">{{ text_bestseller }}</a></li>\r\n      <li><a href=\"{{ latest }}\">{{ text_latest }}</a></li>\r\n      <li><a href=\"{{ mostviewed }}\">{{ text_mostviewed }}</a></li>\r\n      <li><a href=\"{{ all_products }}\">{{ text_all_products }}</a></li>\r\n      {# Additional pages (bestseller, latest, mostviewed) #}\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n<!-- Replacement in languages files -->\r\n  <file path=\"catalog/language/en-gb/common/footer.php\">\r\n    <operation>\r\n      <search><![CDATA[$_[\'text_account\']]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      $_[\'text_bestseller\']   = \'Bestsellers\';\r\n      $_[\'text_latest\']       = \'Latest products\';\r\n      $_[\'text_mostviewed\']   = \'Most viewed products\';\r\n      $_[\'text_all_products\'] = \'All products\';\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n\r\n  <file path=\"catalog/language/ru-ru/common/footer.php\">\r\n    <operation>\r\n      <search><![CDATA[$_[\'text_account\']]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      $_[\'text_bestseller\']   = \'Хиты Продаж\';\r\n      $_[\'text_latest\']       = \'Новинки\';\r\n      $_[\'text_mostviewed\']   = \'Популярные товары\';\r\n      $_[\'text_all_products\'] = \'Все товары\';\r\n      /* Additional pages (bestseller, latest, mostviewed) */\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n</modification>\r\n', 1, '2021-08-30 14:16:21'),
(11, 17, 'E-Piksel Improved Image Resize', 'E-Piksel Improved Image Resize EPMOD3', 'Mahmoud Hamdy', '1.0.1.0', 'http://e-piksel.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification>\r\n\r\n	<name>E-Piksel Improved Image Resize</name>\r\n	<version>1.0.1.0</version>\r\n	<code>E-Piksel Improved Image Resize EPMOD3</code>\r\n	<author>Mahmoud Hamdy</author>\r\n	<link>http://e-piksel.com</link>\r\n\r\n	<file path=\"catalog/model/tool/image.php\">\r\n		<operation>\r\n			<search><![CDATA[public function resize($filename, $width, $height) {]]></search>\r\n			<add position=\"replace\"><![CDATA[public function resize($filename, $width, $height, $type = \'\') {]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[$image_new = \'cache/\' . utf8_substr($filename, 0, utf8_strrpos($filename, \'.\')) . \'-\' . (int)$width . \'x\' . (int)$height . \'.\' . $extension;]]></search>\r\n			<add position=\"replace\"><![CDATA[$image_new = \'cache/\' . utf8_substr($filename, 0, utf8_strrpos($filename, \'.\')) . \'-\' . (int)$width . \'x\' . (int)$height . \'.\' . $type . \'.\' . $extension;]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[$image->resize($width, $height);]]></search>\r\n			<add position=\"replace\"><![CDATA[$image->resize($width, $height, $type);]]></add>\r\n		</operation>\r\n	</file>\r\n\r\n	<file path=\"system/library/image.php\">\r\n		\r\n\r\n		<operation>\r\n			<search><![CDATA[} elseif ($default == \'h\') {]]></search>\r\n			<add position=\"after\" offset=\"1\"><![CDATA[		} elseif ($default == \'a\') {\r\n			if ($width/$height > $this->width/$this->height) {\r\n				$scale = $scale_w;\r\n			} elseif ($width/$height < $this->width/$this->height) {\r\n				$scale = $scale_h;\r\n			}]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[public function watermark($watermark, $position = \'bottomright\') {]]></search>\r\n			<add position=\"replace\"><![CDATA[public function watermark($watermark, $position = \'bottomright\', $offset = 5) {]]></add>\r\n		</operation>\r\n\r\n		\r\n\r\n		<operation>\r\n			<search><![CDATA[$watermark_pos_x = 0;]]></search>\r\n			<add position=\"replace\"><![CDATA[$watermark_pos_x = 0 + $offset;]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[$watermark_pos_y = 0;]]></search>\r\n			<add position=\"replace\"><![CDATA[$watermark_pos_y = 0 + $offset;]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[$watermark_pos_x = $this->width - $watermark->getWidth();]]></search>\r\n			<add position=\"replace\"><![CDATA[$watermark_pos_x = ($this->width - $watermark->getWidth()) - $offset;]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[$watermark_pos_y = $this->height - $watermark->getHeight();]]></search>\r\n			<add position=\"replace\"><![CDATA[$watermark_pos_y = ($this->height - $watermark->getHeight()) - $offset;]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[imagealphablending( $this->image, true );]]></search>\r\n			<add position=\"before\" offset=\"2\"><![CDATA[\r\n				default: // center\r\n				$watermark_pos_x = ($this->width / 2) - ($watermark->getWidth() / 2);\r\n				$watermark_pos_y = ($this->height / 2) - ($watermark->getHeight() / 2);\r\n				break;\r\n			]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[imagecopy($this->image, $watermark->getImage(), $watermark_pos_x, $watermark_pos_y, 0, 0, $watermark->getWidth(), $watermark->getHeight());]]></search>\r\n			<add position=\"replace\"><![CDATA[$this->imagecopymerge_alpha($this->image, $watermark->getImage(), $watermark_pos_x, $watermark_pos_y, 0, 0, $watermark->getWidth(), $watermark->getHeight(), 75);]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[private function html2rgb($color) {]]></search>\r\n			<add position=\"before\"><![CDATA[private function imagecopymerge_alpha($dst_im, $src_im, $dst_x, $dst_y, $src_x, $src_y, $src_w, $src_h, $pct) {\r\n		$w = imagesx($src_im);\r\n		$h = imagesy($src_im);\r\n\r\n		// creating a cut resource\r\n		$cut = imagecreatetruecolor($src_w, $src_h);\r\n\r\n		// copying that section of the background to the cut\r\n		imagecopy($cut, $dst_im, 0, 0, $dst_x, $dst_y, $src_w, $src_h);\r\n\r\n		// placing the watermark now\r\n		imagecopy($cut, $src_im, 0, 0, $src_x, $src_y, $src_w, $src_h);\r\n		imagecopymerge($dst_im, $cut, $dst_x, $dst_y, $src_x, $src_y, $src_w, $src_h, $pct);\r\n	}\r\n\r\n	]]>\r\n		\r\n	</add>\r\n		</operation>\r\n	</file>\r\n</modification>', 1, '2021-09-27 11:56:57');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(12, 18, 'Opencart SHOPPING CART REST API', '00001', 'Opencart-api.com', '1.0', 'http://opencart-api.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <name>Opencart SHOPPING CART REST API</name>\n    <code>00001</code>\n    <version>1.0</version>\n    <author>Opencart-api.com</author>\n    <link>http://opencart-api.com</link>\n    <file path=\"catalog/model/account/customer.php\">\n        <operation>\n            <search><![CDATA[\n			class ModelAccountCustomer extends Model {\n			 ]]></search>\n            <add position=\"after\"><![CDATA[\n				public function editPasswordById($customer_id, $password) {\n					$this->db->query(\"UPDATE \" . DB_PREFIX . \"customer SET password = \'\" . $this->db->escape(md5($password)) . \"\' WHERE customer_id = \'\" . (int)$customer_id . \"\'\");\n				}\n\n				public function editCustomerById($customer_id, $data) {\n\n					$this->db->query(\"UPDATE \" . DB_PREFIX . \"customer SET firstname = \'\" . $this->db->escape($data[\'firstname\']) . \"\', lastname = \'\" . $this->db->escape($data[\'lastname\']) . \"\', email = \'\" . $this->db->escape($data[\'email\']) . \"\', telephone = \'\" . $this->db->escape($data[\'telephone\']) . \"\', fax = \'\" . $this->db->escape($data[\'fax\']) . \"\' WHERE customer_id = \'\" . (int)$customer_id . \"\'\");\n				}\n\n				public function getCustomersMod($data = array()) {\n					$sql = \"SELECT *, CONCAT(c.firstname, \' \', c.lastname) AS name, cgd.name AS customer_group FROM \" . DB_PREFIX . \"customer c LEFT JOIN \" . DB_PREFIX . \"customer_group_description cgd ON (c.customer_group_id = cgd.customer_group_id) WHERE cgd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\n\n					$implode = array();\n\n					if (!empty($data[\'filter_name\'])) {\n						$implode[] = \"CONCAT(c.firstname, \' \', c.lastname) LIKE \'%\" . $this->db->escape($data[\'filter_name\']) . \"%\'\";\n					}\n\n					if (!empty($data[\'filter_email\'])) {\n						$implode[] = \"c.email LIKE \'\" . $this->db->escape($data[\'filter_email\']) . \"%\'\";\n					}\n\n					if (isset($data[\'filter_newsletter\']) && !is_null($data[\'filter_newsletter\'])) {\n						$implode[] = \"c.newsletter = \'\" . (int)$data[\'filter_newsletter\'] . \"\'\";\n					}\n\n					if (!empty($data[\'filter_customer_group_id\'])) {\n						$implode[] = \"c.customer_group_id = \'\" . (int)$data[\'filter_customer_group_id\'] . \"\'\";\n					}\n\n					if (!empty($data[\'filter_ip\'])) {\n						$implode[] = \"c.customer_id IN (SELECT customer_id FROM \" . DB_PREFIX . \"customer_ip WHERE ip = \'\" . $this->db->escape($data[\'filter_ip\']) . \"\')\";\n					}\n\n					if (isset($data[\'filter_status\']) && !is_null($data[\'filter_status\'])) {\n						$implode[] = \"c.status = \'\" . (int)$data[\'filter_status\'] . \"\'\";\n					}\n\n					if (isset($data[\'filter_approved\']) && !is_null($data[\'filter_approved\'])) {\n						$implode[] = \"c.approved = \'\" . (int)$data[\'filter_approved\'] . \"\'\";\n					}\n\n					if (!empty($data[\'filter_date_added\'])) {\n						$implode[] = \"DATE(c.date_added) = DATE(\'\" . $this->db->escape($data[\'filter_date_added\']) . \"\')\";\n					}\n\n					if ($implode) {\n						$sql .= \" AND \" . implode(\" AND \", $implode);\n					}\n\n					$sort_data = array(\n						\'name\',\n						\'c.email\',\n						\'customer_group\',\n						\'c.status\',\n						\'c.approved\',\n						\'c.ip\',\n						\'c.date_added\'\n					);\n\n					if (isset($data[\'sort\']) && in_array($data[\'sort\'], $sort_data)) {\n						$sql .= \" ORDER BY \" . $data[\'sort\'];\n					} else {\n						$sql .= \" ORDER BY name\";\n					}\n\n					if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n						$sql .= \" DESC\";\n					} else {\n						$sql .= \" ASC\";\n					}\n\n					if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n						if ($data[\'start\'] < 0) {\n							$data[\'start\'] = 0;\n						}\n\n						if ($data[\'limit\'] < 1) {\n							$data[\'limit\'] = 20;\n						}\n\n						$sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n					}\n\n					$query = $this->db->query($sql);\n\n					return $query->rows;\n				}\n\n			]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/model/account/order.php\">\n        <operation>\n            <search><![CDATA[\n           class ModelAccountOrder extends Model {\n    		 ]]></search>\n            <add position=\"after\"><![CDATA[\n			public function getAllOrders($start = 0, $limit = 20) {\n				if ($start < 0) {\n					$start = 0;\n				}\n\n				if ($limit < 1) {\n					$limit = 1;\n				}\n\n				$query = $this->db->query(\"SELECT o.order_id, o.firstname, o.lastname, os.name as status, o.date_added, o.total, o.currency_code, o.currency_value FROM `\" . DB_PREFIX . \"order` o LEFT JOIN \" . DB_PREFIX . \"order_status os ON (o.order_status_id = os.order_status_id) WHERE o.order_status_id > \'0\' AND os.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' ORDER BY o.order_id DESC LIMIT \" . (int)$start . \",\" . (int)$limit);\n\n				return $query->rows;\n			}\n\n			public function getOrdersByUser($customer_id) {\n\n				$query = $this->db->query(\"SELECT o.order_id, o.firstname, o.lastname, os.name as status, o.date_added, o.total, o.currency_code, o.currency_value FROM `\" . DB_PREFIX . \"order` o LEFT JOIN \" . DB_PREFIX . \"order_status os ON (o.order_status_id = os.order_status_id) WHERE o.customer_id = \'\" . (int)$customer_id . \"\' AND o.order_status_id > \'0\' AND os.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' ORDER BY o.order_id DESC\");\n\n				return $query->rows;\n			}\n\n			public function getOrdersByFilter($data = array()) {\n				$sql = \"SELECT o.*, CONCAT(o.firstname, \' \', o.lastname) AS customer,\n				            payment_country.iso_code_2 as pc_iso_code_2,\n				            payment_country.iso_code_3 as pc_iso_code_3,\n                            shipping_country.iso_code_2 as sc_iso_code_2,\n				            shipping_country.iso_code_3 as sc_iso_code_3,\n				            payment_zone.code as payment_zone_code,\n				            shipping_zone.code as shipping_zone_code\n\n				        FROM `\" . DB_PREFIX . \"order` o\n				        LEFT JOIN `\" . DB_PREFIX . \"country` payment_country ON ( payment_country.country_id = o.payment_country_id)\n				        LEFT JOIN `\" . DB_PREFIX . \"country` shipping_country ON ( shipping_country.country_id = o.shipping_country_id)\n				        LEFT JOIN `\" . DB_PREFIX . \"zone` payment_zone ON ( payment_zone.zone_id = o.payment_zone_id)\n				        LEFT JOIN `\" . DB_PREFIX . \"zone` shipping_zone ON ( shipping_zone.zone_id = o.shipping_zone_id)\n				                    \";\n\n				if (isset($data[\'filter_order_status\']) && !empty($data[\'filter_order_status\'])) {\n					$implode = array();\n\n					$order_statuses = explode(\',\', $data[\'filter_order_status\']);\n\n					foreach ($order_statuses as $order_status_id) {\n						$implode[] = \"order_status_id = \'\" . (int)$order_status_id . \"\'\";\n					}\n\n					if ($implode) {\n						$sql .= \" WHERE (\" . implode(\" OR \", $implode) . \")\";\n					}\n				} elseif (isset($data[\'filter_order_status_id\']) && $data[\'filter_order_status_id\'] !== \'\') {\n					$sql .= \" WHERE order_status_id = \'\" . (int)$data[\'filter_order_status_id\'] . \"\'\";\n				} else {\n					$sql .= \" WHERE order_status_id > \'0\'\";\n				}\n\n				if (!empty($data[\'filter_order_id\'])) {\n					$sql .= \" AND o.order_id = \'\" . (int)$data[\'filter_order_id\'] . \"\'\";\n				}\n\n				if (!empty($data[\'filter_customer\'])) {\n					$sql .= \" AND CONCAT(o.firstname, \' \', o.lastname) LIKE \'%\" . $this->db->escape($data[\'filter_customer\']) . \"%\'\";\n				}\n\n\n				if (!empty($data[\'filter_date_added_to\']) && !empty($data[\'filter_date_added_from\'])) {\n\n					$sql .= \" AND o.date_added BETWEEN STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_added_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\') AND STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_added_to\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n				} elseif (!empty($data[\'filter_date_added_from\'])) {\n\n					$sql .= \" AND o.date_added >= STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_added_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n				} elseif (!empty($data[\'filter_date_added_on\'])) {\n\n					$sql .= \" AND DATE(o.date_added) = DATE(\'\" . $this->db->escape($data[\'filter_date_added_on\']) . \"\')\";\n				}\n\n				if (!empty($data[\'filter_date_modified_to\']) && !empty($data[\'filter_date_modified_from\'])) {\n\n					$sql .= \" AND o.date_modified BETWEEN STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_modified_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\') AND STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_modified_to\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n				} elseif (!empty($data[\'filter_date_modified_from\'])) {\n\n					$sql .= \" AND o.date_modified >= STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_modified_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n				} elseif (!empty($data[\'filter_date_modified_on\'])) {\n\n					$sql .= \" AND DATE(o.date_modified) = DATE(\'\" . $this->db->escape($data[\'filter_date_modified_on\']) . \"\')\";\n				}\n\n\n				if (!empty($data[\'filter_total\'])) {\n					$sql .= \" AND o.total = \'\" . (float)$data[\'filter_total\'] . \"\'\";\n				}\n\n				$sort_data = array(\n					\'o.order_id\',\n					\'customer\',\n					\'o.date_added\',\n					\'o.date_modified\',\n					\'o.total\'\n				);\n\n				if (isset($data[\'sort\']) && in_array($data[\'sort\'], $sort_data)) {\n					$sql .= \" ORDER BY \" . $data[\'sort\'];\n				} else {\n					$sql .= \" ORDER BY o.order_id\";\n				}\n\n				if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n					$sql .= \" DESC\";\n				} else {\n					$sql .= \" ASC\";\n				}\n\n				if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n					if ($data[\'start\'] < 0) {\n						$data[\'start\'] = 0;\n					}\n\n					if ($data[\'limit\'] < 1) {\n						$data[\'limit\'] = 20;\n					}\n\n					$sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n				}\n\n                $orders_query = $this->db->query($sql);\n                $orders = array();\n                $index = 0;\n\n                $this->load->model(\'localisation/language\');\n\n                foreach ($orders_query->rows as $order) {\n\n                    $payment_iso_code_2 = \'\';\n                    $payment_iso_code_3 = \'\';\n\n                    if (isset($order[\"pc_iso_code_2\"])) {\n                        $payment_iso_code_2 = $order[\"pc_iso_code_2\"];\n                    }\n\n                    if (isset($order[\"pc_iso_code_3\"])) {\n                        $payment_iso_code_3 = $order[\"pc_iso_code_3\"];\n                    }\n\n                    $shipping_iso_code_2 = \'\';\n                    $shipping_iso_code_3 = \'\';\n\n                    if (isset($order[\"sc_iso_code_2\"])) {\n                        $shipping_iso_code_2 = $order[\"sc_iso_code_2\"];\n                    }\n\n                    if (isset($order[\"sc_iso_code_3\"])) {\n                        $shipping_iso_code_3 = $order[\"sc_iso_code_3\"];\n                    }\n\n                    if (isset($order[\"payment_zone_code\"])) {\n                        $payment_zone_code = $order[\"payment_zone_code\"];\n                    } else {\n                        $payment_zone_code = \'\';\n                    }\n\n                    if (isset($order[\"shipping_zone_code\"])) {\n                        $shipping_zone_code = $order[\"shipping_zone_code\"];\n                    } else {\n                        $shipping_zone_code = \'\';\n                    }\n\n\n                    $language_info = $this->model_localisation_language->getLanguage($order[\'language_id\']);\n\n                    if ($language_info) {\n                        $language_code = $language_info[\'code\'];\n                        $language_filename = $language_info[\'filename\'];\n                        $language_directory = $language_info[\'directory\'];\n                    } else {\n                        $language_code = \'\';\n                        $language_filename = \'\';\n                        $language_directory = \'\';\n                    }\n\n                    $orders[$index] =  array(\n                    \'order_id\'                => $order[\'order_id\'],\n                    \'invoice_no\'              => $order[\'invoice_no\'],\n                    \'invoice_prefix\'          => $order[\'invoice_prefix\'],\n                    \'store_id\'                => $order[\'store_id\'],\n                    \'store_name\'              => $order[\'store_name\'],\n                    \'store_url\'               => $order[\'store_url\'],\n                    \'customer_id\'             => $order[\'customer_id\'],\n                    \'firstname\'               => $order[\'firstname\'],\n                    \'lastname\'                => $order[\'lastname\'],\n                    \'telephone\'               => $order[\'telephone\'],\n                    \'fax\'                     => $order[\'fax\'],\n                    \'email\'                   => $order[\'email\'],\n                    \'payment_firstname\'       => $order[\'payment_firstname\'],\n                    \'payment_lastname\'        => $order[\'payment_lastname\'],\n                    \'payment_company\'         => $order[\'payment_company\'],\n                    //\'payment_company_id\'      => $order[\'payment_company_id\'],\n                    //\'payment_tax_id\'          => $order[\'payment_tax_id\'],\n                    \'payment_address_1\'       => $order[\'payment_address_1\'],\n                    \'payment_address_2\'       => $order[\'payment_address_2\'],\n                    \'payment_postcode\'        => $order[\'payment_postcode\'],\n                    \'payment_city\'            => $order[\'payment_city\'],\n                    \'payment_zone_id\'         => $order[\'payment_zone_id\'],\n                    \'payment_zone\'            => $order[\'payment_zone\'],\n                    \'payment_zone_code\'       => $payment_zone_code,\n                    \'payment_country_id\'      => $order[\'payment_country_id\'],\n                    \'payment_country\'         => $order[\'payment_country\'],\n                    \'payment_iso_code_2\'      => $payment_iso_code_2,\n                    \'payment_iso_code_3\'      => $payment_iso_code_3,\n                    \'payment_address_format\'  => $order[\'payment_address_format\'],\n                    \'payment_method\'          => $order[\'payment_method\'],\n                    \'payment_code\'            => $order[\'payment_code\'],\n                    \'shipping_firstname\'      => $order[\'shipping_firstname\'],\n                    \'shipping_lastname\'       => $order[\'shipping_lastname\'],\n                    \'shipping_company\'        => $order[\'shipping_company\'],\n                    \'shipping_address_1\'      => $order[\'shipping_address_1\'],\n                    \'shipping_address_2\'      => $order[\'shipping_address_2\'],\n                    \'shipping_postcode\'       => $order[\'shipping_postcode\'],\n                    \'shipping_city\'           => $order[\'shipping_city\'],\n                    \'shipping_zone_id\'        => $order[\'shipping_zone_id\'],\n                    \'shipping_zone\'           => $order[\'shipping_zone\'],\n                    \'shipping_zone_code\'      => $shipping_zone_code,\n                    \'shipping_country_id\'     => $order[\'shipping_country_id\'],\n                    \'shipping_country\'        => $order[\'shipping_country\'],\n                    \'shipping_iso_code_2\'     => $shipping_iso_code_2,\n                    \'shipping_iso_code_3\'     => $shipping_iso_code_3,\n                    \'shipping_address_format\' => $order[\'shipping_address_format\'],\n                    \'shipping_method\'         => $order[\'shipping_method\'],\n                    \'shipping_code\'           => $order[\'shipping_code\'],\n                    \'comment\'                 => $order[\'comment\'],\n                    \'total\'                   => $order[\'total\'],\n                    \'order_status_id\'         => $order[\'order_status_id\'],\n                    \'language_id\'             => $order[\'language_id\'],\n                    \'language_code\'           => $language_code,\n                    \'language_filename\'       => $language_filename,\n                    \'language_directory\'      => $language_directory,\n                    \'currency_id\'             => $order[\'currency_id\'],\n                    \'currency_code\'           => $order[\'currency_code\'],\n                    \'currency_value\'          => $order[\'currency_value\'],\n                    \'ip\'                      => $order[\'ip\'],\n                    \'forwarded_ip\'            => $order[\'forwarded_ip\'],\n                    \'user_agent\'              => $order[\'user_agent\'],\n                    \'accept_language\'         => $order[\'accept_language\'],\n                    \'date_modified\'           => $order[\'date_modified\'],\n                    \'date_added\'              => $order[\'date_added\']\n                    );\n                    $index++;\n                }\n\n                return $orders;\n            }\n\n            public function getOrderStatuses() {\n\n                $query = $this->db->query(\"SELECT order_status_id, name FROM \" . DB_PREFIX . \"order_status WHERE language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' ORDER BY name\");\n\n                return $query->rows;\n            }\n\n        public function getOrderOptionsMod($order_id, $order_product_id) {\n            $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"order_option\n             LEFT JOIN \" . DB_PREFIX . \"product_option_value pov ON (\" . DB_PREFIX . \"order_option.product_option_value_id = pov.product_option_value_id)\n            WHERE order_id = \'\" . (int)$order_id . \"\' AND order_product_id = \'\" . (int)$order_product_id . \"\'\");\n\n            return $query->rows;\n        }\n\n        public function getOrderHistoriesRest($order_id) {\n            $query = $this->db->query(\"SELECT oh.date_added, os.name AS status, oh.comment, oh.notify FROM \" . DB_PREFIX . \"order_history oh LEFT JOIN \" . DB_PREFIX . \"order_status os ON oh.order_status_id = os.order_status_id WHERE oh.order_id = \'\" . (int)$order_id . \"\' AND os.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' ORDER BY oh.date_added ASC\");\n\n            return $query->rows;\n        }\n\n        public function getOrderStatusById($order_id) {\n            $query = $this->db->query(\"SELECT order_status_id AS status FROM `\" . DB_PREFIX . \"order` WHERE order_id = \'\" . (int)$order_id . \"\'\");\n\n            return $query->row[\'status\'];\n        }\n\n			]]></add>\n        </operation>\n        <operation>\n            <search><![CDATA[\n           return array(\n    		 ]]></search>\n            <add position=\"after\"><![CDATA[\n				\'payment_custom_field\'    => json_decode($order_query->row[\'payment_custom_field\'], true),\n				\'shipping_custom_field\'   => json_decode($order_query->row[\'shipping_custom_field\'], true),\n				\'custom_field\'            => json_decode($order_query->row[\'custom_field\'], true),\n			]]></add>\n\n        </operation>\n    </file>\n    <file path=\"catalog/model/catalog/product.php\">\n        <operation>\n            <search><![CDATA[\n           class ModelCatalogProduct extends Model {\n			 ]]></search>\n            <add position=\"after\"><![CDATA[\n				public function getChecksum() {\n					$query = $this->db->query(\"CHECKSUM TABLE \" . DB_PREFIX . \"product, \"\n						. DB_PREFIX . \"category,\"\n						. DB_PREFIX . \"product_to_category,\"\n						. DB_PREFIX . \"product_description\"\n\n					);\n					return $query->rows;\n				}\n\n				public function getTotalProductsByManufacturerId($manufacturer_id) {\n					$query = $this->db->query(\"SELECT COUNT(*) AS total FROM \" . DB_PREFIX . \"product WHERE manufacturer_id = \'\" . (int)$manufacturer_id . \"\'\");\n					return $query->row[\'total\'];\n				}\n\n				public function getProductsAllData($data = array(), $customer) {\n					if ($customer->isLogged()) {\n						$customer_group_id = $customer->getGroupId();\n					} else {\n						$customer_group_id = $this->config->get(\'config_customer_group_id\');\n					}\n\n					$sql = \"\n							  SELECT DISTINCT *,\n								 pd.name AS name, p.image, m.name AS manufacturer,\n								(SELECT price FROM \" . DB_PREFIX . \"product_discount pd2 WHERE pd2.product_id = p.product_id AND pd2.customer_group_id = \'\" . (int)$customer_group_id . \"\' AND pd2.quantity = \'1\' AND ((pd2.date_start = \'0000-00-00\' OR pd2.date_start < NOW()) AND (pd2.date_end = \'0000-00-00\' OR pd2.date_end > NOW())) ORDER BY pd2.priority ASC, pd2.price ASC LIMIT 1)\n								 AS discount,\n								(SELECT price FROM \" . DB_PREFIX . \"product_special ps WHERE ps.product_id = p.product_id AND ps.customer_group_id = \'\" . (int)$this->config->get(\'config_customer_group_id\') . \"\' AND ((ps.date_start = \'0000-00-00\' OR ps.date_start < NOW()) AND (ps.date_end = \'0000-00-00\' OR ps.date_end > NOW())) ORDER BY ps.priority ASC, ps.price ASC LIMIT 1)\n								 AS special,\n								(SELECT product_special_id FROM \" . DB_PREFIX . \"product_special ps\n									WHERE ps.product_id = p.product_id AND ps.customer_group_id = \'\" . (int)$customer_group_id . \"\'\n									AND ((ps.date_start = \'0000-00-00\' OR ps.date_start < NOW())\n									AND (ps.date_end = \'0000-00-00\' OR ps.date_end > NOW())) ORDER BY ps.priority ASC, ps.price ASC LIMIT 1)\n								 AS special_id,\n								 (SELECT points FROM \" . DB_PREFIX . \"product_reward pr\n									WHERE pr.product_id = p.product_id AND customer_group_id = \'\" . (int)$customer_group_id . \"\')\n								 AS reward,\n									(SELECT ss.name FROM \" . DB_PREFIX . \"stock_status ss WHERE ss.stock_status_id = p.stock_status_id\n									 AND ss.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\')\n								 AS stock_status,\n									(SELECT wcd.unit FROM \" . DB_PREFIX . \"weight_class_description wcd\n										WHERE p.weight_class_id = wcd.weight_class_id AND wcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\')\n								AS weight_class,\n									(SELECT lcd.unit FROM \" . DB_PREFIX . \"length_class_description lcd\n										WHERE p.length_class_id = lcd.length_class_id AND lcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\')\n								AS length_class,\n									(SELECT AVG(rating) AS total FROM \" . DB_PREFIX . \"review r1\n										WHERE r1.product_id = p.product_id AND r1.status = \'1\' GROUP BY r1.product_id)\n								AS rating,\n									(SELECT COUNT(*) AS total FROM \" . DB_PREFIX . \"review r2 WHERE r2.product_id = p.product_id\n										AND r2.status = \'1\' GROUP BY r2.product_id)\n								AS reviews,\n								p.sort_order \";\n\n							if (!empty($data[\'filter_category_id\'])) {\n								if (!empty($data[\'filter_sub_category\'])) {\n									$sql .= \" FROM \" . DB_PREFIX . \"category_path cp LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c ON (cp.category_id = p2c.category_id)\";\n								} else {\n									$sql .= \" FROM \" . DB_PREFIX . \"product_to_category p2c\";\n								}\n								if (!empty($data[\'filter_filter\'])) {\n									$sql .= \" LEFT JOIN \" . DB_PREFIX . \"product_filter pf ON (p2c.product_id = pf.product_id) LEFT JOIN \" . DB_PREFIX . \"product p ON (pf.product_id = p.product_id)\";\n								} else {\n									$sql .= \" LEFT JOIN \" . DB_PREFIX . \"product p ON (p2c.product_id = p.product_id)\";\n								}\n							} else {\n								$sql .= \" FROM \" . DB_PREFIX . \"product p\";\n							}\n\n						  $sql.= \"\n						  LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id)\n						  LEFT JOIN \" . DB_PREFIX . \"product_to_store p2s ON (p.product_id = p2s.product_id)\n						  LEFT JOIN \" . DB_PREFIX . \"manufacturer m ON (p.manufacturer_id = m.manufacturer_id)\n						  WHERE pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\n						  AND p.status = \'1\' AND p.date_available <= NOW()\n						  AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\').\"\'\";\n\n					$sql.= $this->filterSql($data);\n\n					$query = $this->db->query($sql);\n\n					if ($query->num_rows) {\n                        $ret = $this->productData($query->rows);\n                        $specialIds = $ret[\'specialIds\'];\n                        $product_data = $ret[\'product_data\'];\n\n						if(count($specialIds) > 0){\n							$specialsQuery = $this->db->query(\"SELECT date_start, date_end, price, product_id FROM \" . DB_PREFIX . \"product_special ps WHERE ps.product_special_id IN (\" . implode(\',\', $specialIds) . \")\");\n\n							foreach ($specialsQuery->rows as $special) {\n\n								if(isset($product_data[$special[\'product_id\']])){\n									$product_data[$special[\'product_id\']][\'special\'] = $special[\'price\'];\n									$product_data[$special[\'product_id\']][\'special_start_date\'] = $special[\'date_start\'];\n									$product_data[$special[\'product_id\']][\'special_end_date\'] = $special[\'date_end\'];\n								}\n							}\n						}\n						return $product_data;\n					} else {\n						return false;\n					}\n				}\n                public function getProductSeoUrls($product_id) {\n\n                    $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url\n                    WHERE query = \'product_id=\" . (int)$product_id . \"\'\n                    AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\n                    AND store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\n                    \");\n\n                    if ($query->num_rows) {\n                        return $query->row[\'keyword\'];\n                    }\n                    return \"\";\n                }\n\n                public function getCategorySeoUrls($category_id) {\n\n                    $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url\n                    WHERE query = \'category_id=\" . (int)$category_id . \"\'\n                    AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\n                    AND store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\n                    \");\n\n                    if ($query->num_rows) {\n                        return $query->row[\'keyword\'];\n                    }\n\n                    return \"\";\n                }\n                public function getProductBySeoUrl($seoUrl) {\n                    $product = array();\n\n                    $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url WHERE query\n                    LIKE \'%product_id=%\' AND keyword = \'\" . $this->db->escape($seoUrl) . \"\'\n                    AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\n                    AND store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\n                    \");\n\n                    if ($query->num_rows) {\n\n                        $url = explode(\'=\', $query->row[\'query\']);\n\n                        if ($url[0] == \'product_id\') {\n                            return $url[1];\n                        }\n					}\n\n					return null;\n                }\n                public function getCategoryBySeoUrl($seoUrl) {\n                    $product = array();\n\n                    $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url WHERE query\n                    LIKE \'%category_id=%\' AND keyword = \'\" . $this->db->escape($seoUrl) . \"\'\n                    AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\n                    AND store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\n                    \");\n\n                    if ($query->num_rows) {\n\n                        $url = explode(\'=\', $query->row[\'query\']);\n\n                        if ($url[0] == \'category_id\') {\n                            return $url[1];\n                        }\n					}\n					return null;\n                }\n\n                public function getProductsTotal($data = array(), $customer, $onlycount=true) {\n\n					if ($customer->isLogged()) {\n						$customer_group_id = $customer->getGroupId();\n					} else {\n						$customer_group_id = $this->config->get(\'config_customer_group_id\');\n					}\n\n                    $sql = \"SELECT COUNT(DISTINCT p.product_id) AS total\";\n\n\n                    if (!empty($data[\'filter_category_id\'])) {\n                        if (!empty($data[\'filter_sub_category\'])) {\n                            $sql .= \" FROM \" . DB_PREFIX . \"category_path cp LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c ON (cp.category_id = p2c.category_id)\";\n                        } else {\n                            $sql .= \" FROM \" . DB_PREFIX . \"product_to_category p2c\";\n                        }\n                        if (!empty($data[\'filter_filter\'])) {\n                            $sql .= \" LEFT JOIN \" . DB_PREFIX . \"product_filter pf ON (p2c.product_id = pf.product_id) LEFT JOIN \" . DB_PREFIX . \"product p ON (pf.product_id = p.product_id)\";\n                        } else {\n                            $sql .= \" LEFT JOIN \" . DB_PREFIX . \"product p ON (p2c.product_id = p.product_id)\";\n                        }\n                    } else {\n                        $sql .= \" FROM \" . DB_PREFIX . \"product p\";\n                    }\n\n                      $sql.= \"\n                      LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id)\n                      LEFT JOIN \" . DB_PREFIX . \"product_to_store p2s ON (p.product_id = p2s.product_id)\n                      LEFT JOIN \" . DB_PREFIX . \"manufacturer m ON (p.manufacturer_id = m.manufacturer_id)\n                      WHERE pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\n                      AND p.status = \'1\' AND p.date_available <= NOW()\n                      AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\').\"\'\";\n\n					$sql.= $this->filterSql($data, $onlycount);\n\n                    $query = $this->db->query($sql);\n                    return $query->row[\'total\'];\n\n				}\n\n				private function filterSql($data, $onlycount = false){\n			        $sql = \"\";\n					if (!empty($data[\'filter_category_id\'])) {\n						if (!empty($data[\'filter_sub_category\'])) {\n							$sql .= \" AND cp.path_id = \'\" . (int)$data[\'filter_category_id\'] . \"\'\";\n						} else {\n							$categoryImplode = array();\n\n							$categoryFilters = explode(\',\', $data[\'filter_category_id\']);\n\n							foreach ($categoryFilters as $categoryFilterId) {\n								$categoryImplode[] = (int)$categoryFilterId;\n							}\n\n                            if(count($categoryImplode) > 1) {\n							    $sql .= \" AND p2c.category_id IN (\" . implode(\',\', $categoryImplode) . \")\";\n							} else {\n							    $sql .= \" AND p2c.category_id = \'\" . (int)$data[\'filter_category_id\'] . \"\'\";\n							}\n						}\n\n						if (!empty($data[\'filter_filter\'])) {\n							$implode = array();\n\n							$filters = explode(\',\', $data[\'filter_filter\']);\n\n							foreach ($filters as $filter_id) {\n								$implode[] = (int)$filter_id;\n							}\n\n							$sql .= \" AND pf.filter_id IN (\" . implode(\',\', $implode) . \")\";\n						}\n					}\n\n                    if (!empty($data[\'filter_sku\'])) {\n                        $sql .= \" OR LCASE(p.sku) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_sku\'])) . \"\'\";\n                    }\n\n                    if (!empty($data[\'filter_model\'])) {\n                        $sql .= \" OR LCASE(p.model) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_model\'])) . \"\'\";\n                    }\n\n					if (!empty($data[\'filter_name\']) ) {\n						$sql .= \" AND (\";\n\n						if (!empty($data[\'filter_name\'])) {\n							$implode = array();\n\n							$words = explode(\' \', trim(preg_replace(\'/\\s\\s+/\', \' \', $data[\'filter_name\'])));\n\n							foreach ($words as $word) {\n								$implode[] = \"pd.name LIKE \'%\" . $this->db->escape($word) . \"%\'\";\n							}\n\n							if ($implode) {\n								$sql .= \" \" . implode(\" AND \", $implode) . \"\";\n							}\n\n							if (!empty($data[\'filter_description\'])) {\n								$sql .= \" OR pd.description LIKE \'%\" . $this->db->escape($data[\'filter_name\']) . \"%\'\";\n							}\n						}\n\n						if (!empty($data[\'filter_name\']) && !empty($data[\'filter_tag\'])) {\n							$sql .= \" OR \";\n						}\n\n						if (!empty($data[\'filter_tag\'])) {\n							$sql .= \"pd.tag LIKE \'%\" . $this->db->escape($data[\'filter_tag\']) . \"%\'\";\n						}\n\n						if (!empty($data[\'filter_name\'])) {\n							$sql .= \" OR LCASE(p.model) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_name\'])) . \"\'\";\n							$sql .= \" OR LCASE(p.sku) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_name\'])) . \"\'\";\n							$sql .= \" OR LCASE(p.upc) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_name\'])) . \"\'\";\n							$sql .= \" OR LCASE(p.ean) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_name\'])) . \"\'\";\n							$sql .= \" OR LCASE(p.jan) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_name\'])) . \"\'\";\n							$sql .= \" OR LCASE(p.isbn) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_name\'])) . \"\'\";\n							$sql .= \" OR LCASE(p.mpn) = \'\" . $this->db->escape(utf8_strtolower($data[\'filter_name\'])) . \"\'\";\n						}\n\n						$sql .= \")\";\n					}\n\n					if (!empty($data[\'filter_manufacturer_id\'])) {\n						$sql .= \" AND p.manufacturer_id = \'\" . (int)$data[\'filter_manufacturer_id\'] . \"\'\";\n					}\n\n\n					if (!empty($data[\'filter_date_added_to\']) && !empty($data[\'filter_date_added_from\'])) {\n\n						$sql .= \" AND p.date_added BETWEEN STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_added_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\') AND STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_added_to\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n					} elseif (!empty($data[\'filter_date_added_from\'])) {\n\n						$sql .= \" AND p.date_added >= STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_added_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n					} elseif (!empty($data[\'filter_date_added_on\'])) {\n\n						$sql .= \" AND DATE(p.date_added) = DATE(\'\" . $this->db->escape($data[\'filter_date_added_on\']) . \"\')\";\n					}\n\n					if (!empty($data[\'filter_date_modified_to\']) && !empty($data[\'filter_date_modified_from\'])) {\n\n						$sql .= \" AND p.date_modified BETWEEN STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_modified_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\') AND STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_modified_to\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n					} elseif (!empty($data[\'filter_date_modified_from\'])) {\n\n						$sql .= \" AND p.date_modified >= STR_TO_DATE(\'\" . $this->db->escape($data[\'filter_date_modified_from\']) . \"\',\'%Y-%m-%d %H:%i:%s\')\";\n\n					} elseif (!empty($data[\'filter_date_modified_on\'])) {\n\n						$sql .= \" AND DATE(p.date_modified) = DATE(\'\" . $this->db->escape($data[\'filter_date_modified_on\']) . \"\')\";\n					}\n\n\n                    if(empty($onlycount)) {\n\n                        $sql .= \" GROUP BY p.product_id\";\n\n                        $sort_data = array(\n                            \'name\'=>\'pd.name\',\n                            \'model\'=>\'p.model\',\n                            \'quantity\'=>\'p.quantity\',\n                            \'price\'=>\'p.price\',\n                            \'id\'=>\'p.product_id\',\n                            \'rating\'=>\'rating\',\n                            \'sort_order\'=>\'p.sort_order\',\n                            \'date_added\'=>\'p.date_added\',\n                            \'date_modified\'=>\'p.date_modified\'\n                        );\n\n                        if (isset($data[\'sort\']) && in_array($data[\'sort\'], array_keys($sort_data))) {\n                            if ($data[\'sort\'] == \'name\' || $data[\'sort\'] == \'model\') {\n                                $sql .= \" ORDER BY LCASE(\" . $sort_data[$data[\'sort\']] . \")\";\n                            } elseif ($data[\'sort\'] == \'price\') {\n                                $sql .= \" ORDER BY (CASE WHEN special IS NOT NULL THEN special WHEN discount IS NOT NULL THEN discount ELSE p.price END)\";\n                            } else {\n                                $sql .= \" ORDER BY \" . $sort_data[$data[\'sort\']];\n                            }\n                        } else {\n                            $sql .= \" ORDER BY p.sort_order\";\n                        }\n\n                        if (isset($data[\'order\']) && (strtolower($data[\'order\']) == strtolower(\'DESC\'))) {\n                            $sql .= \" DESC, LCASE(pd.name) DESC\";\n                        } else {\n                            $sql .= \" ASC, LCASE(pd.name) ASC\";\n                        }\n\n\n                        if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n                            if ($data[\'limit\'] < 1) {\n                                $limit = 20;\n                            }else {\n                                $limit = (int)$data[\'limit\'];\n                            }\n\n\n                            if ($data[\'start\'] < 0) {\n                                $offset = 0;\n                            }else{\n                                $offset = (int)$data[\'start\'];\n                            }\n\n                            $sql .= \" LIMIT \" . $offset . \",\" . $limit;\n                        }\n                    }\n\n                return $sql;\n            }\n\n            private function productData($results){\n            $specialIds = array();\n            $product_data = array();\n            foreach ($results as $result) {\n						$specialIds[$result[\'product_id\']] = $result[\'special_id\'];\n                        $product_data[$result[\'product_id\']] = array(\n                                        \'product_id\'       => $result[\'product_id\'],\n                                        \'name\'             => $result[\'name\'],\n                                        \'description\'      => $result[\'description\'],\n                                        \'meta_description\' => $result[\'meta_description\'],\n                                        \'meta_keyword\'     => $result[\'meta_keyword\'],\n                                        \'meta_title\'     => $result[\'meta_title\'],\n                                        \'tag\'              => $result[\'tag\'],\n                                        \'model\'            => $result[\'model\'],\n                                        \'sku\'              => $result[\'sku\'],\n                                        \'upc\'              => $result[\'upc\'],\n                                        \'ean\'              => $result[\'ean\'],\n                                        \'jan\'              => $result[\'jan\'],\n                                        \'isbn\'             => $result[\'isbn\'],\n                                        \'mpn\'              => $result[\'mpn\'],\n                                        \'location\'         => $result[\'location\'],\n                                        \'quantity\'         => $result[\'quantity\'],\n                                        \'stock_status\'     => $result[\'stock_status\'],\n                                        \'image\'            => $result[\'image\'],\n                                        \'manufacturer_id\'  => $result[\'manufacturer_id\'],\n                                        \'manufacturer\'     => $result[\'manufacturer\'],\n                                        \'price\'            => ($result[\'discount\'] ? $result[\'discount\'] : $result[\'price\']),\n                                        \'special\'          => isset($result[\'special\']) ? $result[\'special\'] : \'\',\n                                        \'reward\'           => $result[\'reward\'],\n                                        \'points\'           => $result[\'points\'],\n                                        \'tax_class_id\'     => $result[\'tax_class_id\'],\n                                        \'date_available\'   => $result[\'date_available\'],\n                                        \'weight\'           => $result[\'weight\'],\n                                        \'weight_class_id\'  => $result[\'weight_class_id\'],\n                                        \'length\'           => $result[\'length\'],\n                                        \'width\'            => $result[\'width\'],\n                                        \'height\'           => $result[\'height\'],\n                                        \'length_class_id\'  => $result[\'length_class_id\'],\n                                        \'subtract\'         => $result[\'subtract\'],\n                                        \'rating\'           => round($result[\'rating\']),\n                                        \'reviews\'          => $result[\'reviews\'] ? $result[\'reviews\'] : 0,\n                                        \'minimum\'          => $result[\'minimum\'],\n                                        \'sort_order\'       => $result[\'sort_order\'],\n                                        \'status\'           => $result[\'status\'],\n                                        \'date_added\'       => $result[\'date_added\'],\n                                        \'date_modified\'    => $result[\'date_modified\'],\n                                        \'viewed\'           => $result[\'viewed\'],\n										\'weight_class\'     => $result[\'weight_class\'],\n										\'stock_status_id\'  => $result[\'stock_status_id\'],\n										\'length_class\'     => $result[\'length_class\']\n                                    );\n                    }\n\n					$specialIds = array_filter($specialIds, function($item){\n						return !empty($item);\n					});\n\n                    return array(\n                                \'specialIds\' => $specialIds,\n                                \'product_data\' => $product_data\n                    );\n            }\n\n           public function getProductsData($data = array(), $customer) {\n                if ($customer->isLogged()) {\n                    $customer_group_id = $customer->getGroupId();\n                } else {\n                    $customer_group_id = $this->config->get(\'config_customer_group_id\');\n                }\n\n                $sql = \"SELECT p.product_id\";\n\n\n                if (!empty($data[\'filter_category_id\'])) {\n                    if (!empty($data[\'filter_sub_category\'])) {\n                        $sql .= \" FROM \" . DB_PREFIX . \"category_path cp LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c ON (cp.category_id = p2c.category_id)\";\n                    } else {\n                        $sql .= \" FROM \" . DB_PREFIX . \"product_to_category p2c\";\n                    }\n                    if (!empty($data[\'filter_filter\'])) {\n                        $sql .= \" LEFT JOIN \" . DB_PREFIX . \"product_filter pf ON (p2c.product_id = pf.product_id) LEFT JOIN \" . DB_PREFIX . \"product p ON (pf.product_id = p.product_id)\";\n                    } else {\n                        $sql .= \" LEFT JOIN \" . DB_PREFIX . \"product p ON (p2c.product_id = p.product_id)\";\n                    }\n                } else {\n                    $sql .= \" FROM \" . DB_PREFIX . \"product p\";\n                }\n\n                $sql .= \" LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id) LEFT JOIN \" . DB_PREFIX . \"product_to_store p2s ON (p.product_id = p2s.product_id) WHERE pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' AND p.status = \'1\' AND p.date_available <= NOW() AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\";\n\n                $product_data = array();\n\n				$sql.= $this->filterSql($data);\n\n                $query = $this->db->query($sql);\n\n                foreach ($query->rows as $result) {\n                    $product_data[$result[\'product_id\']] = $result[\'product_id\'];\n                }\n\n                return $this->getProductsByIds(array_keys($product_data), $customer, $sortSql);\n            }\n\n            public function getProductsByIds($product_ids, $customer, $sortSql = \"ORDER BY p.product_id ASC\") {\n\n                if(count($product_ids) == 0){\n                    return false;\n                }\n\n                if ($customer->isLogged()) {\n                    $customer_group_id = $customer->getGroupId();\n                } else {\n                    $customer_group_id = $this->config->get(\'config_customer_group_id\');\n                }\n\n                $query = $this->db->query(\"SELECT DISTINCT *, pd.name AS name, p.image, m.name AS manufacturer, (SELECT price FROM \" . DB_PREFIX . \"product_discount pd2 WHERE pd2.product_id = p.product_id AND pd2.customer_group_id = \'\" . (int)$customer_group_id . \"\' AND pd2.quantity = \'1\' AND ((pd2.date_start = \'0000-00-00\' OR pd2.date_start < NOW()) AND (pd2.date_end = \'0000-00-00\' OR pd2.date_end > NOW())) ORDER BY pd2.priority ASC, pd2.price ASC LIMIT 1) AS discount,\n				(SELECT price FROM \" . DB_PREFIX . \"product_special ps WHERE ps.product_id = p.product_id AND ps.customer_group_id = \'\" . (int)$this->config->get(\'config_customer_group_id\') . \"\' AND ((ps.date_start = \'0000-00-00\' OR ps.date_start < NOW()) AND (ps.date_end = \'0000-00-00\' OR ps.date_end > NOW())) ORDER BY ps.priority ASC, ps.price ASC LIMIT 1) AS special,\n				(SELECT product_special_id FROM \" . DB_PREFIX . \"product_special ps\n				WHERE ps.product_id = p.product_id AND ps.customer_group_id = \'\" . (int)$customer_group_id . \"\'\n				AND ((ps.date_start = \'0000-00-00\' OR ps.date_start < NOW()) AND (ps.date_end = \'0000-00-00\' OR ps.date_end > NOW())) ORDER BY ps.priority ASC, ps.price ASC LIMIT 1) AS special_id, (SELECT points FROM \" . DB_PREFIX . \"product_reward pr WHERE pr.product_id = p.product_id AND customer_group_id = \'\" . (int)$customer_group_id . \"\') AS reward, (SELECT ss.name FROM \" . DB_PREFIX . \"stock_status ss WHERE ss.stock_status_id = p.stock_status_id AND ss.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\') AS stock_status, (SELECT wcd.unit FROM \" . DB_PREFIX . \"weight_class_description wcd WHERE p.weight_class_id = wcd.weight_class_id AND wcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\') AS weight_class, (SELECT lcd.unit FROM \" . DB_PREFIX . \"length_class_description lcd WHERE p.length_class_id = lcd.length_class_id AND lcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\') AS length_class, (SELECT AVG(rating) AS total FROM \" . DB_PREFIX . \"review r1 WHERE r1.product_id = p.product_id AND r1.status = \'1\' GROUP BY r1.product_id) AS rating, (SELECT COUNT(*) AS total FROM \" . DB_PREFIX . \"review r2 WHERE r2.product_id = p.product_id AND r2.status = \'1\' GROUP BY r2.product_id) AS reviews, p.sort_order FROM \" . DB_PREFIX . \"product p LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id) LEFT JOIN \" . DB_PREFIX . \"product_to_store p2s ON (p.product_id = p2s.product_id) LEFT JOIN \" . DB_PREFIX . \"manufacturer m ON (p.manufacturer_id = m.manufacturer_id) WHERE p.product_id IN (\" . implode(\',\', $product_ids) . \") AND pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' AND p.status = \'1\' AND p.date_available <= NOW() AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\".$sortSql);\n\n				if ($query->num_rows) {\n					$ret = $this->productData($query->rows);\n					$specialIds = $ret[\'specialIds\'];\n					$product_data = $ret[\'product_data\'];\n\n					if(count($specialIds) > 0){\n						$specialsQuery = $this->db->query(\"SELECT date_start, date_end, price, product_id FROM \" . DB_PREFIX . \"product_special ps WHERE ps.product_special_id IN (\" . implode(\',\', $specialIds) . \")\");\n\n						foreach ($specialsQuery->rows as $special) {\n\n							if(isset($product_data[$special[\'product_id\']])){\n								$product_data[$special[\'product_id\']][\'special\'] = $special[\'price\'];\n								$product_data[$special[\'product_id\']][\'special_start_date\'] = $special[\'date_start\'];\n								$product_data[$special[\'product_id\']][\'special_end_date\'] = $special[\'date_end\'];\n							}\n						}\n					}\n					return $product_data;\n				} else {\n					return false;\n				}\n            }\n\n            public function getOrderStatusByName($status) {\n                $query = $this->db->query(\"SELECT order_status_id FROM \" . DB_PREFIX . \"order_status WHERE LCASE(name) = \'\" . $this->db->escape(utf8_strtolower($status)) . \"\' AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\");\n                return $query->rows;\n            }\n\n        public function getWeightClasses($data = array()) {\n            if ($data) {\n                $sql = \"SELECT * FROM \" . DB_PREFIX . \"weight_class wc LEFT JOIN \" . DB_PREFIX . \"weight_class_description wcd ON (wc.weight_class_id = wcd.weight_class_id) WHERE wcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\n\n                $sort_data = array(\n                    \'title\',\n                    \'unit\',\n                    \'value\'\n                );\n\n                if (isset($data[\'sort\']) && in_array($data[\'sort\'], $sort_data)) {\n                    $sql .= \" ORDER BY \" . $data[\'sort\'];\n                } else {\n                    $sql .= \" ORDER BY title\";\n                }\n\n                if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n                    $sql .= \" DESC\";\n                } else {\n                    $sql .= \" ASC\";\n                }\n\n                if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n                    if ($data[\'start\'] < 0) {\n                        $data[\'start\'] = 0;\n                    }\n\n                    if ($data[\'limit\'] < 1) {\n                        $data[\'limit\'] = 20;\n                    }\n\n                    $sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n                }\n\n                $query = $this->db->query($sql);\n\n                return $query->rows;\n            } else {\n                $weight_class_data = $this->cache->get(\'weight_class.\' . (int)$this->config->get(\'config_language_id\'));\n\n                if (!$weight_class_data) {\n                    $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"weight_class wc LEFT JOIN \" . DB_PREFIX . \"weight_class_description wcd ON (wc.weight_class_id = wcd.weight_class_id) WHERE wcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\");\n\n                    $weight_class_data = $query->rows;\n\n                    $this->cache->set(\'weight_class.\' . (int)$this->config->get(\'config_language_id\'), $weight_class_data);\n                }\n\n                return $weight_class_data;\n            }\n        }\n\n        public function getStockStatuses($data = array()) {\n            if ($data) {\n                $sql = \"SELECT * FROM \" . DB_PREFIX . \"stock_status WHERE language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\n\n                $sql .= \" ORDER BY name\";\n\n                if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n                    $sql .= \" DESC\";\n                } else {\n                    $sql .= \" ASC\";\n                }\n\n                if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n                    if ($data[\'start\'] < 0) {\n                        $data[\'start\'] = 0;\n                    }\n                    if ($data[\'limit\'] < 1) {\n                        $data[\'limit\'] = 20;\n                    }\n                    $sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n                }\n\n                $query = $this->db->query($sql);\n\n                return $query->rows;\n            } else {\n                $stock_status_data = $this->cache->get(\'stock_status.\' . (int)$this->config->get(\'config_language_id\'));\n\n                if (!$stock_status_data) {\n                    $query = $this->db->query(\"SELECT stock_status_id, name FROM \" . DB_PREFIX . \"stock_status WHERE language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' ORDER BY name\");\n\n                    $stock_status_data = $query->rows;\n\n                    $this->cache->set(\'stock_status.\' . (int)$this->config->get(\'config_language_id\'), $stock_status_data);\n                }\n\n                return $stock_status_data;\n            }\n        }\n\n        public function getLengthClasses($data = array()) {\n            if ($data) {\n                $sql = \"SELECT * FROM \" . DB_PREFIX . \"length_class lc LEFT JOIN \" . DB_PREFIX . \"length_class_description lcd ON (lc.length_class_id = lcd.length_class_id) WHERE lcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\n\n                $sort_data = array(\n                    \'title\',\n                    \'unit\',\n                    \'value\'\n                );\n\n                if (isset($data[\'sort\']) && in_array($data[\'sort\'], $sort_data)) {\n                    $sql .= \" ORDER BY \" . $data[\'sort\'];\n                } else {\n                    $sql .= \" ORDER BY title\";\n                }\n\n                if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n                    $sql .= \" DESC\";\n                } else {\n                    $sql .= \" ASC\";\n                }\n\n                if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n                    if ($data[\'start\'] < 0) {\n                        $data[\'start\'] = 0;\n                    }\n\n                    if ($data[\'limit\'] < 1) {\n                        $data[\'limit\'] = 20;\n                    }\n\n                    $sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n                }\n\n                $query = $this->db->query($sql);\n\n                return $query->rows;\n            } else {\n                $length_class_data = $this->cache->get(\'length_class.\' . (int)$this->config->get(\'config_language_id\'));\n\n                if (!$length_class_data) {\n                    $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"length_class lc LEFT JOIN \" . DB_PREFIX . \"length_class_description lcd ON (lc.length_class_id = lcd.length_class_id) WHERE lcd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\");\n\n                    $length_class_data = $query->rows;\n\n                    $this->cache->set(\'length_class.\' . (int)$this->config->get(\'config_language_id\'), $length_class_data);\n                }\n\n                return $length_class_data;\n            }\n        }\n\n        public function getStores($data = array()) {\n            $store_data = $this->cache->get(\'store\');\n\n            if (!$store_data) {\n                $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"store ORDER BY url\");\n\n                $store_data = $query->rows;\n\n                $this->cache->set(\'store\', $store_data);\n            }\n\n            return $store_data;\n        }\n\n            public function getRecurrings($data = array()) {\n                $sql = \"SELECT * FROM `\" . DB_PREFIX . \"recurring` r LEFT JOIN \" . DB_PREFIX . \"recurring_description rd ON (r.recurring_id = rd.recurring_id) WHERE rd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\n\n                if (!empty($data[\'filter_name\'])) {\n                    $sql .= \" AND rd.name LIKE \'\" . $this->db->escape($data[\'filter_name\']) . \"%\'\";\n                }\n\n                $sort_data = array(\n                    \'rd.name\',\n                    \'r.sort_order\'\n                );\n\n                if (isset($data[\'sort\']) && in_array($data[\'sort\'], $sort_data)) {\n                    $sql .= \" ORDER BY \" . $data[\'sort\'];\n                } else {\n                    $sql .= \" ORDER BY rd.name\";\n                }\n\n                if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n                    $sql .= \" DESC\";\n                } else {\n                    $sql .= \" ASC\";\n                }\n\n                if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n                    if ($data[\'start\'] < 0) {\n                        $data[\'start\'] = 0;\n                    }\n\n                    if ($data[\'limit\'] < 1) {\n                        $data[\'limit\'] = 20;\n                    }\n\n                    $sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n                }\n\n                $query = $this->db->query($sql);\n\n                return $query->rows;\n            }\n\n\n            public function checkProductExists($product_id) {\n                $query = $this->db->query(\"SELECT COUNT(DISTINCT product_id) AS total FROM \" . DB_PREFIX . \"product WHERE product_id = \'\" . (int)$product_id . \"\'\");\n\n                if (isset($query->row[\'total\'])) {\n                    return $query->row[\'total\'];\n                } else {\n                    return 0;\n                }\n            }\n\n            public static $fields = array(\n                \"category\" => \"p2c.category_id\",\n                \"quantity\" => \"p.quantity\",\n                \"stock_status\" => \"p.stock_status_id\",\n                \"manufacturer\" => \"p.manufacturer_id\",\n                \"model\" => \"p.model\",\n                \"upc\" => \"p.upc\",\n                \"name\" => \"pd.name\",\n                \"date_start\" => \"ps.date_start\",\n                \"date_end\" => \"ps.date_end\",\n                \"product_id\" => \"p.product_id\",\n                \"price\" => \"p.price\",\n                \"status\" => \"p.status\",\n                \"date_available\" => \"p.date_available\",\n                \"store_id\" => \"p2s.store_id\",\n                \"filter_text\" => \"filter_text\",\n            );\n\n\n            public static $operands = array(\n                \"=\" => \"=\",\n                \"!=\" => \"!=\",\n                \">\" => \">\",\n                \">=\" => \">=\",\n                \"<\" => \"<\",\n                \"<=\" => \"<=\",\n                \"!<\" => \"!<\",\n                \"!>\" => \"!>\",\n                \"<>\" => \"<>\",\n                \"in\" => \"in\",\n                \"not_in\" => \"not in\",\n                \"like\" => \"like\",\n            );\n\n            public static $logicalOperands = array(\n                \"and\"=>\"AND\",\n                \"or\"=>\"OR\"\n            );\n\n            public static $sort_data = array(\n                            \'name\'=>\'pd.name\',\n                            \'model\'=>\'p.model\',\n                            \'quantity\'=>\'p.quantity\',\n                            \'price\'=>\'p.price\',\n                            \'rating\'=>\'rating\',\n                            \'sort_order\'=>\'p.sort_order\',\n                            \'date_added\'=>\'p.date_added\'\n                        );\n\n\n            private function searchHelper($request){\n                $sql = \"\";\n\n                foreach($request[\'filters\'] as $filter){\n                    if(array_key_exists($filter[\'field\'], static::$fields)) {\n                        $filter[\'operand\'] = html_entity_decode($filter[\'operand\']);\n                        $operand = array_key_exists($filter[\'operand\'], static::$operands) ? strtolower(static::$operands[$filter[\'operand\']]) : \"=\";\n                        $logicalOperand = isset($filter[\'logical_operand\']) && array_key_exists(strtolower($filter[\'logical_operand\']), static::$logicalOperands) ? $filter[\'logical_operand\'] : \"AND\";\n\n                        if (static::$fields[$filter[\'field\']] == \'filter_text\' ) {\n                            $sql .= $logicalOperand.\"  (\";\n\n                            if (!empty( $filter[\'value\'])) {\n                                $implode = array();\n\n                                $words = explode(\' \', trim(preg_replace(\'/\\s\\s+/\', \' \',  $filter[\'value\'])));\n\n                                foreach ($words as $word) {\n                                    $implode[] = \"pd.name LIKE \'%\" . $this->db->escape($word) . \"%\'\";\n                                }\n\n                                if ($implode) {\n                                    $sql .= \" \" . implode(\" AND \", $implode) . \"\";\n                                }\n\n                                $sql .= \" OR pd.description LIKE \'%\" . $this->db->escape( $filter[\'value\']) . \"%\'\";\n                            }\n\n                            if (!empty( $filter[\'value\'])) {\n                                $sql .= \" OR LCASE(p.model) = \'\" . $this->db->escape(utf8_strtolower( $filter[\'value\'])) . \"\'\";\n                            }\n\n                            if (!empty( $filter[\'value\'])) {\n                                $sql .= \" OR LCASE(p.sku) = \'\" . $this->db->escape(utf8_strtolower( $filter[\'value\'])) . \"\'\";\n                            }\n\n                            if (!empty( $filter[\'value\'])) {\n                                $sql .= \" OR LCASE(p.upc) = \'\" . $this->db->escape(utf8_strtolower( $filter[\'value\'])) . \"\'\";\n                            }\n\n                            if (!empty( $filter[\'value\'])) {\n                                $sql .= \" OR LCASE(p.ean) = \'\" . $this->db->escape(utf8_strtolower( $filter[\'value\'])) . \"\'\";\n                            }\n\n                            if (!empty( $filter[\'value\'])) {\n                                $sql .= \" OR LCASE(p.jan) = \'\" . $this->db->escape(utf8_strtolower( $filter[\'value\'])) . \"\'\";\n                            }\n\n                            if (!empty( $filter[\'value\'])) {\n                                $sql .= \" OR LCASE(p.isbn) = \'\" . $this->db->escape(utf8_strtolower( $filter[\'value\'])) . \"\'\";\n                            }\n\n                            if (!empty( $filter[\'value\'])) {\n                                $sql .= \" OR LCASE(p.mpn) = \'\" . $this->db->escape(utf8_strtolower( $filter[\'value\'])) . \"\'\";\n                            }\n\n                            $sql .= \")\";\n                        } else {\n                            if($operand == \"in\" || $operand == \"not in\"){\n                                $sql.=\" \".$logicalOperand.\" \".static::$fields[$filter[\'field\']]\n                                    .\" \".$operand.\" (\".$this->db->escape(implode(\",\",$filter[\'value\'])).\")\";\n                            } elseif($operand == \"like\" ){\n                                $sql.=\" \".$logicalOperand.\" \".static::$fields[$filter[\'field\']];\n                                $sql .= \" LIKE \'%\" . $this->db->escape( strtolower($filter[\'value\'])) . \"%\'\";\n                            } else{\n                                $sql.=\" \".$logicalOperand.\" \".static::$fields[$filter[\'field\']]\n                                    .\" \".$operand.\" \".$this->db->escape($filter[\'value\']);\n                            }\n                        }\n                    }\n                }\n                return $sql;\n            }\n            public function search($data = array(), $request, $customer) {\n                if ($customer->isLogged()) {\n                    $customer_group_id = $customer->getGroupId();\n                } else {\n                    $customer_group_id = $this->config->get(\'config_customer_group_id\');\n                }\n\n                $sql = \"SELECT p.product_id,\n                              (SELECT price FROM \" . DB_PREFIX . \"product_discount pd2 WHERE pd2.product_id = p.product_id AND pd2.customer_group_id = \'\" . (int)$customer_group_id . \"\' AND pd2.quantity = \'1\' AND ((pd2.date_start = \'0000-00-00\' OR pd2.date_start < NOW()) AND (pd2.date_end = \'0000-00-00\' OR pd2.date_end > NOW())) ORDER BY pd2.priority ASC, pd2.price ASC LIMIT 1)\n								 AS discount,\n							    (SELECT price FROM \" . DB_PREFIX . \"product_special ps WHERE ps.product_id = p.product_id AND ps.customer_group_id = \'\" . (int)$this->config->get(\'config_customer_group_id\') . \"\' AND ((ps.date_start = \'0000-00-00\' OR ps.date_start < NOW()) AND (ps.date_end = \'0000-00-00\' OR ps.date_end > NOW())) ORDER BY ps.priority ASC, ps.price ASC LIMIT 1)\n								 AS special,\n								 (SELECT AVG(rating) AS total FROM \" . DB_PREFIX . \"review r1\n										WHERE r1.product_id = p.product_id AND r1.status = \'1\' GROUP BY r1.product_id)\n								AS rating\n                                FROM \" . DB_PREFIX . \"product p\n                              LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c\n                                        ON (p.product_id = p2c.product_id)\n                              LEFT JOIN \" . DB_PREFIX . \"product_description pd\n                                        ON (p.product_id = pd.product_id)\n                              LEFT JOIN \" . DB_PREFIX . \"product_to_store p2s\n                                        ON (p.product_id = p2s.product_id)\n                              WHERE pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\n                              AND p.status = \'1\' AND p.date_available <= NOW() AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'\n                              \";\n\n                        if(isset($request[\'filters\'])){\n                        	$sql.= $this->searchHelper($request);\n                        }\n\n                        $sql .= \" GROUP BY p.product_id\";\n\n                $sortSql = \"\";\n\n                if (isset($request[\'sort\']) && in_array($request[\'sort\'], array_keys(static::$sort_data))) {\n                    if ($request[\'sort\'] == \'name\' || $request[\'sort\'] == \'model\') {\n                        $sortSql .= \" ORDER BY LCASE(\" . static::$sort_data[$request[\'sort\']] . \")\";\n                    } elseif ($request[\'sort\'] == \'price\') {\n                        $sortSql .= \" ORDER BY (CASE WHEN special IS NOT NULL THEN special WHEN discount IS NOT NULL THEN discount ELSE p.price END)\";\n                    } else {\n                        $sortSql .= \" ORDER BY \" . static::$sort_data[$request[\'sort\']];\n                    }\n                } else {\n                    $sortSql .= \" ORDER BY p.sort_order\";\n                }\n\n                if (isset($request[\'order\']) && (strtolower($request[\'order\']) == strtolower(\'DESC\'))) {\n                    $sortSql .= \" DESC, LCASE(pd.name) DESC\";\n                } else {\n                    $sortSql .= \" ASC, LCASE(pd.name) ASC\";\n                }\n\n                $sql.= $sortSql;\n\n                if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n                    if ($data[\'limit\'] < 1) {\n                        $limit = 20;\n                    }else {\n                        $limit = (int)$data[\'limit\'];\n                    }\n\n                    if ($data[\'start\'] < 0) {\n                        $offset = 0;\n                    }else{\n                        $offset = (int)$data[\'start\'];\n                    }\n\n                    $sql .= \" LIMIT \" . $offset . \",\" . $limit;\n                }\n\n                if(isset($request[\'debug\']) && isset($request[\'debug\']) == true){\n                    var_dump($sql);\n                }\n\n                $product_data = array();\n\n                $query = $this->db->query($sql);\n                foreach ($query->rows as $result) {\n                    $product_data[$result[\'product_id\']] = $result[\'product_id\'];\n                }\n\n                return $this->getProductsByIds(array_keys($product_data), $customer, $sortSql);\n            }\n\n            public function getStore($store_id) {\n                $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"setting WHERE store_id = \'\" . (int)$store_id . \"\'\");\n                return $query->rows;\n            }\n\n	public function getModulesByCode($code) {\n		$query = $this->db->query(\"SELECT * FROM `\" . DB_PREFIX . \"module` WHERE `code` = \'\" . $this->db->escape($code) . \"\' ORDER BY `name`\");\n\n		return $query->rows;\n	}\n\n	public function getBanners($data = array()) {\n		$sql = \"SELECT * FROM \" . DB_PREFIX . \"banner\";\n\n		$sort_data = array(\n			\'name\',\n			\'status\'\n		);\n\n		if (isset($data[\'sort\']) && in_array($data[\'sort\'], $sort_data)) {\n			$sql .= \" ORDER BY \" . $data[\'sort\'];\n		} else {\n			$sql .= \" ORDER BY name\";\n		}\n\n		if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n			$sql .= \" DESC\";\n		} else {\n			$sql .= \" ASC\";\n		}\n\n		if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n			if ($data[\'start\'] < 0) {\n				$data[\'start\'] = 0;\n			}\n\n			if ($data[\'limit\'] < 1) {\n				$data[\'limit\'] = 20;\n			}\n\n			$sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n		}\n\n		$query = $this->db->query($sql);\n\n		return $query->rows;\n	}\n\n			]]></add>\n\n        </operation>\n    </file>\n\n    <file path=\"system/library/cart/currency.php\">\n        <operation>\n            <search><![CDATA[\n				public function has($currency) {\n			 ]]></search>\n            <add position=\"before\"><![CDATA[\n\n\n			public $restCurrencyCode;\n\n			public function setRestCurrencyCode($code){\n				$this->restCurrencyCode = $code;\n			}\n\n			public function getRestCurrencyCode(){\n				return $this->restCurrencyCode;\n			}\n\n			]]></add>\n        </operation>\n    </file>\n    <file path=\"system/library/session.php\">\n        <operation>\n\n            <search><![CDATA[\n				if (!$session_id) {\n			 ]]></search>\n            <add position=\"replace\"><![CDATA[\n\n			$headers = apache_request_headers();\n\n			if(isset($headers[\'X-Oc-Session\'])){\n				$session_id = $headers[\'X-Oc-Session\'];\n			}else if(isset($headers[\'X-OC-SESSION\'])){\n				$session_id = $headers[\'X-OC-SESSION\'];\n			}else if(isset($headers[\'x-oc-session\'])){\n			    $rest_session_id = $headers[\'x-oc-session\'];\n			}\n\n            if (!$session_id) {\n\n			]]></add>\n\n        </operation>\n\n        <operation>\n\n            <search><![CDATA[\n				class Session {\n			 ]]></search>\n            <add position=\"replace\"><![CDATA[\n            //if your php doesn\'t support apache_request_headers\n            if( !function_exists(\'apache_request_headers\') ) {\n                function apache_request_headers() {\n                    $arh = array();\n                    $rx_http = \'/\\AHTTP_/\';\n\n                    foreach($_SERVER as $key => $val) {\n                        if( preg_match($rx_http, $key) ) {\n                            $arh_key = preg_replace($rx_http, \'\', $key);\n                            $rx_matches = array();\n                       // do some nasty string manipulations to restore the original letter case\n                       // this should work in most cases\n                            $rx_matches = explode(\'_\', $arh_key);\n\n                            if( count($rx_matches) > 0 and strlen($arh_key) > 2 ) {\n                                foreach($rx_matches as $ak_key => $ak_val) {\n                                    $rx_matches[$ak_key] = ucfirst($ak_val);\n                                }\n\n                                $arh_key = implode(\'-\', $rx_matches);\n                            }\n\n                            $arh[$arh_key] = $val;\n                        }\n                    }\n\n                    return( $arh );\n                }\n            }\n\n			    class Session {\n\n			]]></add>\n\n        </operation>\n    </file>\n\n    <file path=\"catalog/model/catalog/category.php\">\n        <operation>\n            <search><![CDATA[\n           public function getCategory($category_id) {\n			 ]]></search>\n            <add position=\"before\"><![CDATA[\n            		    public function getAllCategories($data = array(), $onlyCount = false) {\n\n        if($onlyCount){\n            $sql = \"SELECT count(*) as total FROM \";\n        } else {\n            $sql = \"SELECT * FROM \";\n        }\n\n        $sql.= \" \" . DB_PREFIX . \"category c\n                LEFT JOIN \" . DB_PREFIX . \"category_description cd ON (c.category_id = cd.category_id)\";\n\n        $sql.= \" LEFT JOIN \" . DB_PREFIX . \"category_to_store c2s ON (c.category_id = c2s.category_id) \";\n        $sql.= \" WHERE  c2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\' \";\n        $sql.= \" AND cd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\n\n\n        if($onlyCount) {\n            $query = $this->db->query($sql);\n            return $query->row[\'total\'];\n        } else {\n            $sort_data = array(\n                \'c.category_id\',\n                \'c.sort_order\',\n                \'cd.name\'\n            );\n\n            if (isset($data[\'sort\']) && in_array($data[\'sort\'], $sort_data)) {\n                $sql .= \" ORDER BY \" . $data[\'sort\'];\n            } else {\n                $sql .= \" ORDER BY c.sort_order, LCASE(cd.name)\";\n            }\n\n            if (isset($data[\'order\']) && ($data[\'order\'] == \'DESC\')) {\n                $sql .= \" DESC\";\n            } else {\n                $sql .= \" ASC\";\n            }\n\n            if (isset($data[\'start\']) || isset($data[\'limit\'])) {\n                if ($data[\'start\'] < 0) {\n                    $data[\'start\'] = 0;\n                }\n\n                if ($data[\'limit\'] < 1) {\n                    $data[\'limit\'] = 20;\n                }\n\n                $sql .= \" LIMIT \" . (int)$data[\'start\'] . \",\" . (int)$data[\'limit\'];\n            }\n\n            $query = $this->db->query($sql);\n\n            return $query->rows;\n        }\n    }\n            ]]>\n            </add>\n        </operation>\n    </file>\n</modification>', 0, '2021-11-13 00:57:15');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(13, 19, 'Tabby payment', 'Tabby payment', 'https://tabby.ai/', '1.3.0', '', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<modification>\n    <name>Tabby payment</name>\n    <code>Tabby payment</code>\n    <version>1.3.0</version>\n    <author>https://tabby.ai/</author>\n    <file path=\"admin/view/template/sale/order_info.twig\">\n        <operation>\n            <search><![CDATA[$(document).delegate(\'#button-invoice\', \'click\', function() {]]></search>\n            <add position=\"after\"><![CDATA[\n    var button_capure = $(\'a.capture\'),\n        config_tabby_capture = \'{{ config_tabby_capture }}\';\n    if (button_capure.length > 0 && config_tabby_capture === \'invoice\') {\n      capturePayment(button_capure);\n    }\n            ]]></add>\n        </operation>\n        <operation>\n            <search><![CDATA[//--></script>]]></search>\n            <add position=\"before\"><![CDATA[\nfunction capturePayment(a) {\n  var data = $(a).data(),\n      amount = $(a).closest(\'.amount_capture\').find(\'input[name=\"amount\"]\').val(),\n      url = \'{{ catalog }}index.php?route=api/order/tabby_capture&api_token={{ api_token }}&transaction_id=\' + data.transactionId;\n  $.ajax({\n    url: url,\n    type: \'post\',\n    dataType: \'json\',\n    data: \'amount=\' + data.amount,\n    beforeSend: function() {\n      $(\'.capture\').button(\'loading\');\n    },\n    complete: function() {\n      $(\'.capture\').button(\'reset\');\n    },\n    success: function(json) {\n      $(\'.alert-dismissible\').remove();\n\n      if (json[\'error\']) {\n        $(\'#tabbyPayment\').parent().before(\'<div class=\"alert alert-danger alert-dismissible\"><i class=\"fa fa-exclamation-circle\"></i> \' + json[\'error\'] + \' <button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button></div>\');\n      }\n\n      if (json[\'success\']) {\n        $(\'#history\').load(\'index.php?route=sale/order/history&user_token={{ user_token }}&order_id={{ order_id }}\');\n        $(\'#tabbyPayment\').parent().load(\'index.php?route=extension/payment/tabby_paylater/order&user_token={{ user_token }}&order_id={{ order_id }}\');\n\n        $(\'#tabbyPayment\').parent().before(\'<div class=\"alert alert-success alert-dismissible\"><i class=\"fa fa-check-circle\"></i> \' + json[\'success\'] + \' <button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button></div>\');\n\n      }\n    },\n    error: function(xhr, ajaxOptions, thrownError) {\n      alert(thrownError + \"\\r\\n\" + xhr.statusText + \"\\r\\n\" + xhr.responseText);\n    }\n  });\n}\n\nfunction refundPayment(a) {\n  var data = $(a).data(),\n      amount = $(a).closest(\'.amount_refund\').find(\'input[name=\"amount_refund\"]\').val(),\n      amount_danger = $(\'.amount-danger\'),\n      url = \'{{ catalog }}index.php?route=api/order/tabby_refund&api_token={{ api_token }}&transaction_id=\' + data.transactionId;\n  amount_danger.hide();\n  if(amount === 0 || amount === \'\' || amount === undefined) {\n    amount_danger.show();\n    return;\n  }\n  $.ajax({\n    url: url,\n    type: \'post\',\n    dataType: \'json\',\n    data: \'amount=\' + amount,\n    beforeSend: function() {\n      $(\'.refund\').button(\'loading\');\n    },\n    complete: function() {\n      $(\'.refund\').button(\'reset\');\n    },\n    success: function(json) {\n      $(\'.alert-dismissible\').remove();\n\n      if (json[\'error\']) {\n        $(\'#tabbyPayment\').parent().before(\'<div class=\"alert alert-danger alert-dismissible\"><i class=\"fa fa-exclamation-circle\"></i> \' + json[\'error\'] + \' <button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button></div>\');\n      }\n\n      if (json[\'success\']) {\n        $(\'#history\').load(\'index.php?route=sale/order/history&user_token={{ user_token }}&order_id={{ order_id }}\');\n        $(\'#tabbyPayment\').parent().load(\'index.php?route=extension/payment/tabby_paylater/order&user_token={{ user_token }}&order_id={{ order_id }}\');\n\n        $(\'#tabbyPayment\').parent().before(\'<div class=\"alert alert-success alert-dismissible\"><i class=\"fa fa-check-circle\"></i> \' + json[\'success\'] + \' <button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button></div>\');\n\n      }\n    },\n    error: function(xhr, ajaxOptions, thrownError) {\n      alert(thrownError + \"\\r\\n\" + xhr.statusText + \"\\r\\n\" + xhr.responseText);\n    }\n  });\n}\n\nfunction closePayment(a) {\n  var data = $(a).data(),\n          url = \'{{ catalog }}index.php?route=api/order/tabby_close&api_token={{ api_token }}&transaction_id=\' + data.transactionId;\n  $.ajax({\n    url: url,\n    type: \'post\',\n    dataType: \'json\',\n    beforeSend: function() {\n      $(\'.void\').button(\'loading\');\n    },\n    complete: function() {\n      $(\'.void\').button(\'reset\');\n    },\n    success: function(json) {\n      $(\'.alert-dismissible\').remove();\n\n      if (json[\'error\']) {\n        $(\'#tabbyPayment\').parent().before(\'<div class=\"alert alert-danger alert-dismissible\"><i class=\"fa fa-exclamation-circle\"></i> \' + json[\'error\'] + \' <button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button></div>\');\n      }\n\n      if (json[\'success\']) {\n        $(\'#history\').load(\'index.php?route=sale/order/history&user_token={{ user_token }}&order_id={{ order_id }}\');\n        $(\'#tabbyPayment\').parent().load(\'index.php?route=extension/payment/tabby_paylater/order&user_token={{ user_token }}&order_id={{ order_id }}\');\n\n        $(\'#tabbyPayment\').parent().before(\'<div class=\"alert alert-success alert-dismissible\"><i class=\"fa fa-check-circle\"></i> \' + json[\'success\'] + \' <button type=\"button\" class=\"close\" data-dismiss=\"alert\">&times;</button></div>\');\n\n      }\n    },\n    error: function(xhr, ajaxOptions, thrownError) {\n      alert(thrownError + \"\\r\\n\" + xhr.statusText + \"\\r\\n\" + xhr.responseText);\n    }\n  });\n}\n\nfunction getTabbyTransaction() {\n  var data = $(\'#tabbyPayment\').data(),\n      url = \'{{ catalog }}index.php?route=api/order/tabby_info&api_token={{ api_token }}&transaction_id=\' + data.transactionId;\n  $.ajax({\n    url: url,\n    type: \'post\',\n    dataType: \'json\',\n    success: function(json) {\n      if (json.length > 0) {\n        $.post(\'index.php?route=extension/payment/tabby_paylater/order&user_token={{ user_token }}\', {txn: JSON.stringify(json)}, function (html) {\n          $(\'#tabbyPayment\').parent().html(html);\n        });\n      }\n    },\n    error: function(xhr, ajaxOptions, thrownError) {\n      alert(thrownError + \"\\r\\n\" + xhr.statusText + \"\\r\\n\" + xhr.responseText);\n    }\n  });\n}\n$(document).ready(function() {\n    getTabbyTransaction();\n});\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"admin/controller/sale/order.php\">\n        <operation>\n            <search><![CDATA[$data[\'date_added\'] = date($this->language->get(\'date_format_short\'), strtotime($order_info[\'date_added\']));]]></search>\n            <add position=\"before\"><![CDATA[\n			$data[\'config_tabby_capture\'] = $this->config->get(\'module_tabby_capture_on\');\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/api/order.php\">\n        <operation>\n            <search><![CDATA[	public function history() {]]></search>\n            <add position=\"before\"><![CDATA[\n	public function tabby_info() {\n		$this->load->model(\'extension/module/tabby\');\n		$result = $this->model_extension_module_tabby->getTabbyTransaction($this->request->get[\'transaction_id\']);\n		$out = array(\n			\'id\'         => $result->id,\n			\'created_at\' => $result->created_at,\n			\'status\'     => $result->status,\n			\'amount\'     => $result->amount,\n			\'currency\'   => $result->currency,\n			\'order\'      => array(\'reference_id\' => $result->order->reference_id),\n			\'captures\'   => $result->captures,\n			\'refunds\'    => $result->refunds,\n		);\n\n		$json = json_encode($out);\n\n		$this->response->addHeader(\'Content-Type: application/json\');\n		$this->response->setOutput(json_encode($json));\n	}\n\n	public function tabby_capture() {\n		$json = array();\n\n		$this->load->language(\'extension/payment/tabby\');\n\n		$this->load->model(\'extension/module/tabby\');\n		$result = $this->model_extension_module_tabby->capture($this->request->get[\'transaction_id\'], $this->request->post[\'amount\']);\n\n		if ($result[\'error\']) {\n			$json[\'success\'] = false;\n			$json[\'error\'] = $result[\'message\'];\n		} else {\n			$json[\'success\'] = $this->language->get(\'text_success\');\n			$json[\'error\'] = false;\n		}\n\n		$this->response->addHeader(\'Content-Type: application/json\');\n		$this->response->setOutput(json_encode($json));\n	}\n\n	public function tabby_refund() {\n		$json = array();\n\n		$this->load->language(\'extension/payment/tabby\');\n\n		$this->load->model(\'extension/module/tabby\');\n		$result = $this->model_extension_module_tabby->refund($this->request->get[\'transaction_id\'], $this->request->post[\'amount\']);\n\n		if ($result[\'error\']) {\n			$json[\'success\'] = false;\n			$json[\'error\'] = $result[\'message\'];\n		} else {\n			$json[\'success\'] = $this->language->get(\'text_success\');\n			$json[\'error\'] = false;\n		}\n\n		$this->response->addHeader(\'Content-Type: application/json\');\n		$this->response->setOutput(json_encode($json));\n	}\n\n	public function tabby_close() {\n		$json = array();\n\n		$this->load->language(\'extension/payment/tabby\');\n\n		$this->load->model(\'extension/module/tabby\');\n		$result = $this->model_extension_module_tabby->close($this->request->get[\'transaction_id\']);\n\n		if ($result[\'error\']) {\n			$json[\'success\'] = false;\n			$json[\'error\'] = $result[\'message\'];\n		} else {\n			$json[\'success\'] = $this->language->get(\'text_success\');\n			$json[\'error\'] = false;\n		}\n\n		$this->response->addHeader(\'Content-Type: application/json\');\n		$this->response->setOutput(json_encode($json));\n	}\n\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/product/product.php\">\n        <operation>\n            <search><![CDATA[			$discounts = $this->model_catalog_product->getProductDiscounts($this->request->get[\'product_id\']);]]></search>\n            <add position=\"before\"><![CDATA[\n            $tabby_promo = $this->config->get(\'module_tabby_promo\');\n            if (is_null($tabby_promo) || $tabby_promo) {\n                $data[\'tabby_promo_enabled\'] = true;\n                $data[\'price_amount\'] = $data[\'price\']\n                    ? $this->tax->calculate($data[\'special\'] ? $product_info[\'special\'] : $product_info[\'price\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\'))\n                    : false;\n                if ($data[\'price_amount\']) $data[\'price_amount\'] = $this->currency->format($data[\'price_amount\'], $this->session->data[\'currency\'], \'\', false);\n                $max_price = $this->config->get(\'module_tabby_promo_limit\');\n                if ($max_price && $max_price < $data[\'price_amount\']) {\n                    $data[\'tabby_promo_enabled\'] = false; \n                }\n                $data[\'currency\'] = $this->session->data[\'currency\'];\n                $data[\'lang\'] = $this->language->get(\'code\');\n                $data[\'promo_theme\'] = $this->config->get(\'module_tabby_promo_theme\');\n            } else {\n                $data[\'tabby_promo_enabled\'] = false;\n            }\n\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/checkout/cart.php\">\n        <operation>\n            <search><![CDATA[           $data[\'modules\'] = array();]]></search>\n            <add position=\"before\"><![CDATA[\n            $tabby_cart_promo = $this->config->get(\'module_tabby_cart_promo\');\n            if (is_null($tabby_cart_promo) || $tabby_cart_promo) {\n                $data[\'tabby_cart_promo_enabled\'] = true;\n                $tabby_price = 0;\n                foreach ($totals as $total) {\n                    if ($total[\'code\'] == \'total\') $tabby_price = number_format($total[\'value\'], 2, \'.\', \'\');\n                }\n                if ($tabby_price) $tabby_price = $this->currency->format($tabby_price, $this->session->data[\'currency\'], \'\', false);\n                $data[\'tabby_price\'] = $tabby_price;\n                $max_price = $this->config->get(\'module_tabby_promo_limit\');\n                if ($max_price && $max_price < $tabby_price) {\n                    $data[\'tabby_cart_promo_enabled\'] = false; \n                }\n                $data[\'currency\'] = $this->session->data[\'currency\'];\n                $data[\'lang\'] = $this->language->get(\'code\');\n                $data[\'promo_theme\'] = $this->config->get(\'module_tabby_promo_theme\');\n            } else {\n                $data[\'tabby_cart_promo_enabled\'] = false;\n            }\n\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/checkout/payment_method.php\">\n        <operation>\n            <search><![CDATA[$this->session->data[\'payment_methods\'] = $method_data;]]></search>\n            <add position=\"before\" offset=\"1\"><![CDATA[\n        // Tabby addon\n        if (count(array_intersect([\'tabby_paylater\', \'tabby_installments\'], array_keys($method_data)))) {\n		    $this->load->model(\'extension/module/tabby\');\n		    $tabby_checkout_session = $this->model_extension_module_tabby->createSession();\n\n		    if ($tabby_checkout_session->status != \'error\' && $tabby_checkout_session->status != \'rejected\') {\n			    $this->session->data[\'tabby_checkout_session_id\'] = $tabby_checkout_session->id;\n			    $available_products = $tabby_checkout_session->configuration->available_products;\n		    } else {\n			    $available_products = new stdClass();\n		    }\n\n            foreach ($method_data as $code => $method) {\n                if ($code == \'tabby_paylater\'     && !isset($available_products->pay_later   )) unset($method_data[$code]);\n                if ($code == \'tabby_installments\' && !isset($available_products->installments)) unset($method_data[$code]);\n            }\n        }\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/model/checkout/order.php\">\n        <operation>\n            <search><![CDATA[$this->cache->delete(\'product\');]]></search>\n            <add position=\"after\"><![CDATA[\n			if ($order_status_id == 3 && $this->config->get(\'module_tabby_capture_on\') == \"shipment\") {\n				$this->load->model(\'extension/module/tabby\');\n				$transactioin_id = $this->model_extension_module_tabby->getTransactionIdByOrder($order_id);\n\n				$this->model_extension_module_tabby->capture($transactioin_id, $order_info[\'total\']);\n			}\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/view/theme/default/template/checkout/payment_method.twig\">\n        <operation>\n            <search><![CDATA[{{ payment_method.title }}]]></search>\n            <add position=\"before\"><![CDATA[\n    {% if payment_method.code == \"tabby_installments\" or payment_method.code == \"tabby_paylater\" %}\n      <img src=\"catalog/view/theme/default/image/Tabby logo special.svg\" />\n    {% endif %}\n            ]]></add>\n        </operation>\n        <operation>\n            <search><![CDATA[({{ payment_method.terms }})]]></search>\n            <add position=\"after\" offset=\"1\"><![CDATA[\n    {% if payment_method.code == \"tabby_installments\" %}\n      <div class=\"tabby-info\">\n        <button data-tabby-info=\"installments\">ⓘ</button>\n      </div>\n    {% endif %}\n    {% if payment_method.code == \"tabby_paylater\" %}\n      <div class=\"tabby-info\">\n        <button data-tabby-info=\"payLater\" class=\"tabby-info\">ⓘ</button>\n      </div>\n    {% endif %}\n            ]]></add>\n        </operation>\n        <operation>\n            <search><![CDATA[{% if text_agree %}]]></search>\n            <add position=\"before\"><![CDATA[\n<style>\n  #collapse-payment-method .radio {\n    display: flex;\n  }\n  #collapse-payment-method .radio input[type=radio]{\n    position: unset;\n  }\n  #collapse-payment-method .radio img {\n    margin-right: 5px;\n  }\n  .tabby-info {\n    display: inline-block;\n    vertical-align: top;\n  }\n  .tabby-info button {\n    position: relative;\n    height: 100%;\n    margin-left: 15px;\n    opacity: 0;\n    z-index: 1;\n  }\n  .tabby-info:after {\n    position: relative;\n    content: url(\"catalog/view/theme/default/image/Info.svg\");\n    right: 42px;\n  }\n</style>\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/view/theme/*/template/product/product.twig\">\n        <operation>\n            <search><![CDATA[{% if options %}]]></search>\n            <add position=\"before\"><![CDATA[\n          {% if tabby_promo_enabled %}\n          <div id=\"tabbyPromo\"></div>\n<script type=\"text/javascript\" src=\"https://checkout.tabby.ai/tabby-promo.js\"></script>\n<script type=\"text/javascript\">\n$(document).ready(function() {\n    new TabbyPromo({\n        selector: \'#tabbyPromo\',\n        currency: \'{{ currency }}\',\n        price: \'{{ price_amount }}\',\n        lang: \'{{ lang }}\',\n        theme: \'{{ promo_theme }}\',\n        source: \'product\'\n    });\n});\n</script>\n          {% endif %}\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/view/theme/*/template/checkout/cart.twig\">\n        <operation>\n            <search><![CDATA[<div class=\"buttons]]></search>\n            <add position=\"before\" offset=\"2\"><![CDATA[\n          {% if tabby_cart_promo_enabled %}\n          <div id=\"tabbyPromo\"></div>\n<script type=\"text/javascript\" src=\"https://checkout.tabby.ai/tabby-promo.js\" defer></script>\n<script type=\"text/javascript\">\n$(document).ready(function() {\n    new TabbyPromo({\n        selector: \'#tabbyPromo\',\n        currency: \'{{ currency }}\',\n        price: \'{{ tabby_price }}\',\n        lang: \'{{ lang }}\',\n        theme: \'{{ promo_theme }}\',\n        source: \'cart\'\n    });\n});\n</script>\n          {% endif %}\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"system/library/template/Twig/Template.php\">\n        <operation>\n            <search><![CDATA[if (isset($object->$item) || array_key_exists((string) $item, $object)) {]]></search>\n            <add position=\"replace\"><![CDATA[\n            if (isset($object->$item) || property_exists($object, (string) $item)) {\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/extension/module/xtensions/checkout/xpayment_method.php\">\n        <operation>\n            <search><![CDATA[$this->session->data[\'payment_methods\'] = $method_data;]]></search>\n            <add position=\"before\" offset=\"1\"><![CDATA[\n        // Tabby addon\n        if (count(array_intersect([\'tabby_paylater\', \'tabby_installments\'], array_keys($method_data)))) {\n            $this->load->model(\'extension/module/tabby\');\n            $tabby_checkout_session = $this->model_extension_module_tabby->createSession();\n\n            if ($tabby_checkout_session->status != \'error\' && $tabby_checkout_session->status != \'rejected\') {\n                $this->session->data[\'tabby_checkout_session_id\'] = $tabby_checkout_session->id;\n                $available_products = $tabby_checkout_session->configuration->available_products;\n            } else {\n                $available_products = new stdClass();\n            }\n\n            foreach ($method_data as $code => $method) {\n                if ($code == \'tabby_paylater\'     && !isset($available_products->pay_later   )) unset($method_data[$code]);\n                if ($code == \'tabby_installments\' && !isset($available_products->installments)) unset($method_data[$code]);\n            }\n        }\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/model/journal3/checkout.php\">\n        <operation>\n            <search><![CDATA[$this->session->data[\'payment_methods\'] = $method_data;]]></search>\n            <add position=\"before\" offset=\"1\"><![CDATA[\n        // Tabby addon\n        if (count(array_intersect([\'tabby_paylater\', \'tabby_installments\'], array_keys($method_data)))) {\n            $this->load->model(\'extension/module/tabby\');\n            $tabby_checkout_session = $this->model_extension_module_tabby->createSession();\n\n            if ($tabby_checkout_session->status != \'error\' && $tabby_checkout_session->status != \'rejected\') {\n                $this->session->data[\'tabby_checkout_session_id\'] = $tabby_checkout_session->id;\n                $available_products = $tabby_checkout_session->configuration->available_products;\n            } else {\n                $available_products = new stdClass();\n            }\n\n            foreach ($method_data as $code => $method) {\n                if ($code == \'tabby_paylater\'     && !isset($available_products->pay_later   )) unset($method_data[$code]);\n                if ($code == \'tabby_installments\' && !isset($available_products->installments)) unset($method_data[$code]);\n            }\n        }\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/journal3/checkout.php\">\n        <operation>\n            <search><![CDATA[private function getCheckoutData($data) {]]></search>\n            <add position=\"after\"><![CDATA[\n        // Tabby addon\n        $method_data = $this->session->data[\'payment_methods\'];\n        if (count(array_intersect([\'tabby_paylater\', \'tabby_installments\'], array_keys($method_data)))) {\n            $this->load->model(\'extension/module/tabby\');\n            $tabby_checkout_session = $this->model_extension_module_tabby->createSession();\n\n            if ($tabby_checkout_session->status != \'error\' && $tabby_checkout_session->status != \'rejected\') {\n                $this->session->data[\'tabby_checkout_session_id\'] = $tabby_checkout_session->id;\n                $available_products = $tabby_checkout_session->configuration->available_products;\n            } else {\n                $available_products = new stdClass();\n            }\n\n            foreach ($method_data as $code => $method) {\n                if ($code == \'tabby_paylater\'     && !isset($available_products->pay_later   )) unset($method_data[$code]);\n                if ($code == \'tabby_installments\' && !isset($available_products->installments)) unset($method_data[$code]);\n            }\n            $this->session->data[\'payment_methods\'] = $method_data;\n        }\n            ]]></add>\n        </operation>\n    </file>\n</modification>\n', 0, '2021-11-13 01:47:10'),
(14, 20, 'SMSAWebService', 'smsa_express', 'N2R TECHNOLOGIES', '5.1', 'http://www.n2rtechnologies.com', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<modification>\r\n	<name>SMSAWebService</name>\r\n    <code>smsa_express</code>\r\n    <version>5.1</version>\r\n    <author>N2R TECHNOLOGIES</author>\r\n    <link>http://www.n2rtechnologies.com</link>\r\n\r\n    <file path=\"admin/controller/sale/order.php\">\r\n        <operation error=\"log\">\r\n            <search>\r\n                <![CDATA[$this->load->model(\'setting/extension\');]]>\r\n            </search>\r\n            <add position=\"before\"><![CDATA[if ($this->user->hasPermission(\'access\', \'extension/shipping/smsa\')) {\r\n            $content = $this->load->controller(\'extension/shipping/smsa/shipment\');\r\n            \r\n\r\n            if ($content) {\r\n            \r\n            $data[\'tabs\'][] = array(\r\n            \'code\' => \'smsa\',\r\n            \'title\' => \'SMSA Express\',\r\n            \'content\' => $content\r\n            );\r\n            }\r\n            }]]></add>\r\n        </operation>\r\n    </file>\r\n    <file path=\"admin/view/template/sale/order_info.twig\">           \r\n        <operation error=\"skip\">\r\n            <search><![CDATA[<div id=\"history\"></div>]]></search>\r\n            <add position=\"before\"><![CDATA[<div id=\"smsa\"></div>]]></add>\r\n        </operation>\r\n        <operation error=\"skip\">\r\n            <search><![CDATA[{{ footer }}]]></search>\r\n            <add position=\"before\"><![CDATA[                  \r\n        <script type=\"text/javascript\">\r\n            $(\'#smsa\').load(\'index.php?route=extension/shipping/smsa/shipment&user_token={{ user_token }}&order_id={{ order_id }}\');\r\n        </script>]]>\r\n            </add>\r\n        </operation>\r\n    </file>\r\n    <file path=\"catalog/model/account/order.php\">           \r\n        <operation error=\"skip\">\r\n            <search><![CDATA[public function getTotalOrderVouchersByOrderId($order_id) {]]></search>\r\n            <add position=\"before\"><![CDATA[\r\n    public function getConsignment($order_id) {\r\n        $query = $this->db->query(\"SELECT * FROM `\" . DB_PREFIX . \"smsa` WHERE order_id = \'\" . (int)$order_id . \"\' ORDER BY date_added DESC \");\r\n\r\n        return $query->row;\r\n    }]]>\r\n            </add>\r\n        </operation>            \r\n    </file>\r\n    <file path=\"catalog/controller/account/order.php\">           \r\n        <operation error=\"skip\">\r\n            <search><![CDATA[$voucher_total = $this->model_account_order->getTotalOrderVouchersByOrderId($result[\'order_id\']);]]></search>\r\n            <add position=\"after\"><![CDATA[$consignment = $this->model_account_order->getConsignment($result[\'order_id\']);]]>\r\n            </add>\r\n        </operation>\r\n        <operation error=\"skip\">\r\n            <search><![CDATA[\'view\'       => $this->url->link(\'account/order/info\', \'order_id=\' . $result[\'order_id\'], true),]]></search>\r\n            <add position=\"after\"><![CDATA[\'awb_number\'       => (isset($consignment[\'awb_number\']) && $consignment[\'awb_number\'] ? $consignment[\'awb_number\'] : \'\'),\r\n                \'track\'       => (isset($consignment[\'awb_number\']) && $consignment[\'awb_number\'] ? $this->url->link(\'extension/shipping/smsa/trackShipment\', \'awb_number=\' . $consignment[\'awb_number\'], true) : \'\'),]]>\r\n            </add>\r\n        </operation>            \r\n    </file>\r\n    <file path=\"catalog/view/theme/*/template/account/order_list.twig\">           \r\n        <operation error=\"skip\">\r\n            <search><![CDATA[<td class=\"text-right\"><a href=\"{{ order.view }}\" data-toggle=\"tooltip\" title=\"{{ button_view }}\" class=\"btn btn-info\"><i class=\"fa fa-eye\"></i></a></td>]]></search>\r\n            <add position=\"replace\"><![CDATA[<td class=\"text-right\">{% if order.track %}<a class=\"btn btn-primary agree\" href=\"{{ order.track }}\" data-toggle=\"tooltip\" title=\"Track Order\" class=\"btn btn-primary\"><i class=\"fa fa-paper-plane-o\"></i></a>{% endif %} {% if order.awb_number %}<a target=\"_blank\" href=\"/awb/{{ order.awb_number }}.pdf\" data-toggle=\"tooltip\" title=\"Label\" class=\"btn btn-primary\"><i class=\"fa fa-download\"></i></a>{% endif %} <a href=\"{{ order.view }}\" data-toggle=\"tooltip\" title=\"{{ button_view }}\" class=\"btn btn-primary\"><i class=\"fa fa-eye\"></i></a></td>]]>\r\n            </add>\r\n        </operation>          \r\n    </file>\r\n    <file path=\"catalog/view/theme/journal2/template/account/order_list.twig\">           \r\n        <operation error=\"skip\">\r\n            <search><![CDATA[<td class=\"text-right\"><a href=\"{{ order.view }}\" data-toggle=\"tooltip\" title=\"{{ button_view }}\" class=\"btn btn-info btn-primary\"><i class=\"fa fa-eye\"></i></a></td>]]></search>\r\n            <add position=\"replace\"><![CDATA[<td class=\"text-right\"> {% if order.track %}<a class=\"btn btn-primary agree\" href=\"{{ order.track }}\" data-toggle=\"tooltip\" title=\"Track Order\" class=\"btn btn-primary\"><i class=\"fa fa-paper-plane-o\"></i></a>{% endif %} {% if order.awb_number %}<a target=\"_blank\" href=\"/awb/{{ order.awb_number }}.pdf\" data-toggle=\"tooltip\" title=\"Label\" class=\"btn btn-primary\"><i class=\"fa fa-download\"></i></a>{% endif %} <a href=\"{{ order.view }}\" data-toggle=\"tooltip\" title=\"{{ button_view }}\" class=\"btn btn-primary\"><i class=\"fa fa-eye\"></i></a></td>]]>\r\n            </add>\r\n        </operation>          \r\n    </file>\r\n</modification>', 0, '2022-01-24 13:39:29'),
(15, 21, '#ocmod.space | Equal Sign', 'equal-sign', 'Andrii Burkatskyi aka underr', '2.3.1', 'https://git.io/JfjkZ', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n\n<!--\nThis file is subject to the terms and conditions defined in the \"LICENSE.txt\"\nfile, which is part of this source code package and is also available on the\npage: https://raw.githubusercontent.com/ocmod-space/license/main/LICENSE.txt.\n-->\n\n<modification>\n	<name>#ocmod.space | Equal Sign</name>\n	<code>equal-sign</code>\n	<version>2.3.1</version>\n	<author>Andrii Burkatskyi aka underr</author>\n	<link>https://git.io/JfjkZ</link>\n\n	<file path=\"system/library/cart/cart.php\" error=\"log\">\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$stock = true;]]>\n			</search>\n			<add position=\"after\">\n				<![CDATA[			/// << Equal Sign\n			$has_eql_price = false;\n			$has_eql_points = false;\n			$has_eql_weight = false;\n			/// << Equal Sign]]>\n			</add>\n		</operation>\n\n<!--  Add equals sign -->\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_value_query->row[\'price_prefix\'] == \'+\']]>\n			</search>\n			<add position=\"replace\">\n				<![CDATA[$option_value_query->row[\'price_prefix\'] == \'+\' || $option_value_query->row[\'price_prefix\'] == \'=\']]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_value_query->row[\'points_prefix\'] == \'+\']]>\n			</search>\n			<add position=\"replace\">\n				<![CDATA[$option_value_query->row[\'points_prefix\'] == \'+\' || $option_value_query->row[\'points_prefix\'] == \'=\']]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_value_query->row[\'weight_prefix\'] == \'+\']]>\n			</search>\n			<add position=\"replace\">\n				<![CDATA[$option_value_query->row[\'weight_prefix\'] == \'+\' || $option_value_query->row[\'weight_prefix\'] == \'=\']]>\n			</add>\n		</operation>\n\n<!-- Add sum fixes -->\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_value_query->row[\'price_prefix\'] == \'+\' || $option_value_query->row[\'price_prefix\'] == \'=\']]>\n			</search>\n			<add position=\"after\">\n				<![CDATA[										if ($option_value_query->row[\'price\'] != 0 && $option_value_query->row[\'price_prefix\'] == \'=\') {\n											$has_eql_price = true;\n										}\n				]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_value_query->row[\'points_prefix\'] == \'+\' || $option_value_query->row[\'points_prefix\'] == \'=\']]>\n			</search>\n			<add position=\"after\">\n				<![CDATA[										if ($option_value_query->row[\'points\']  != 0 && $option_value_query->row[\'points_prefix\'] == \'=\') {\n											$has_eql_points = true;\n										}\n				]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_value_query->row[\'weight_prefix\'] == \'+\' || $option_value_query->row[\'weight_prefix\'] == \'=\']]>\n			</search>\n			<add position=\"after\">\n				<![CDATA[										if ($option_value_query->row[\'weight\'] != 0 && $option_value_query->row[\'weight_prefix\'] == \'=\') {\n											$has_eql_weight = true;\n										}\n				]]>\n			</add>\n		</operation>\n\n<!--  -->\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$product_data[] = array(]]>\n			</search>\n			<add position=\"before\">\n				<![CDATA[\n				/// << Equal Sign\n				if ($has_eql_price) {\n					$option_price -= $price;\n				}\n\n				if ($product_query->row[\'points\'] && $has_eql_points) {\n					$option_points -= $product_query->row[\'points\'];\n				}\n\n				if ($has_eql_weight) {\n					$option_weight -= $product_query->row[\'weight\'];\n				}\n				/// << Equal Sign\n				]]>\n			</add>\n		</operation>\n	</file>\n\n	<file path=\"admin/controller/sale/order.php\" error=\"log\">\n		<operation error=\"log\" info=\"Fix\">\n			<ignoreif regex=\"false\"><![CDATA[$option_weight = 0;]]></ignoreif>\n			<search>\n				<![CDATA[$option_weight = \'\';]]>\n			</search>\n			<add position=\"replace\">\n				<![CDATA[$option_weight = 0;]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_weight = 0;]]>\n			</search>\n			<add position=\"after\">\n				<![CDATA[					$has_eql_weight = false;  /// Equal Sign]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[$option_weight -= $product_option_value_info[\'weight\'];]]>\n			</search>\n			<add position=\"after\">\n				<![CDATA[\n								/// << Equal Sign\n								} elseif ($product_option_value_info[\'weight_prefix\'] == \'=\') {\n									$option_weight += $product_option_value_info[\'weight\'];\n\n								/// << Equal Sign\n								]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\" info=\"preliminary fix for OC 2.1.x\">\n			<ignoreif regex=\"false\" info=\"for 2.1.x\"><![CDATA[(float)$option_weight]]></ignoreif>\n			<search>\n				<![CDATA[$this->weight->format(($product_info[\'weight\'] + $option_weight)]]>\n			</search>\n			<add position=\"replace\">\n				<![CDATA[$this->weight->format(($product_info[\'weight\'] + (float)$option_weight)]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<search>\n				<![CDATA[(float)$option_weight]]>\n			</search>\n			<add position=\"replace\">\n				<![CDATA[(!empty($has_eql_weight) ? (float)$option_weight - $product_info[\'weight\'] : (float)$option_weight)]]>\n			</add>\n		</operation>\n	</file>\n\n	<file path=\"admin/view/template/catalog/product_form.*\" error=\"log\" info=\"oc v2.3.x.x\">\n\n<!-- OC 2.1+ -->\n		<operation error=\"log\">\n	    	<ignoreif regex=\"false\" info=\"for 2.1.x\"><![CDATA[{{ header }}]]></ignoreif>\n			<search>\n		  		<![CDATA[<?php if ($product_option_value[\'price_prefix\'] == \'-\') { ?>]]>\n				</search>\n		  	<add position=\"before\">\n				<![CDATA[                                  <?php if ($product_option_value[\'price_prefix\'] == \'=\') { ?>\n                                  <option value=\"=\" selected=\"selected\">=</option>\n                                  <?php } else { ?>\n                                  <option value=\"=\">=</option>\n                                  <?php } ?>]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<ignoreif regex=\"false\" info=\"for 2.1.x\"><![CDATA[{{ header }}]]></ignoreif>\n			<search>\n		  		<![CDATA[<?php if ($product_option_value[\'points_prefix\'] == \'-\') { ?>]]>\n				</search>\n		  	<add position=\"before\">\n				<![CDATA[                                  <?php if ($product_option_value[\'points_prefix\'] == \'=\') { ?>\n                                  <option value=\"=\" selected=\"selected\">=</option>\n                                  <?php } else { ?>\n                                  <option value=\"=\">=</option>\n                                  <?php } ?>]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<ignoreif regex=\"false\" info=\"for 2.1.x\"><![CDATA[{{ header }}]]></ignoreif>\n			<search>\n		  		<![CDATA[<?php if ($product_option_value[\'weight_prefix\'] == \'-\') { ?>]]>\n				</search>\n		  	<add position=\"before\">\n				<![CDATA[                                  <?php if ($product_option_value[\'weight_prefix\'] == \'=\') { ?>\n                                  <option value=\"=\" selected=\"selected\">=</option>\n                                  <?php } else { ?>\n                                  <option value=\"=\">=</option>\n                                  <?php } ?>]]>\n			</add>\n		</operation>\n\n<!-- OC 3.0+ -->\n		<operation error=\"log\">\n			<ignoreif regex=\"false\" info=\"for 3.0.x\"><![CDATA[<?php echo $header; ?>]]></ignoreif>\n			<search>\n				<![CDATA[{% if product_option_value.price_prefix == \'-\' %}]]>\n				</search>\n			<add position=\"before\">\n				<![CDATA[\n								{% if product_option_value.price_prefix == \'=\' %}\n\n\n								<option value=\"=\" selected=\"selected\">=</option>\n\n\n								  {% else %}\n\n\n								<option value=\"=\">=</option>\n\n\n								  {% endif %}\n						]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<ignoreif regex=\"false\" info=\"for 3.0.x\"><![CDATA[<?php echo $header; ?>]]></ignoreif>\n			<search>\n				<![CDATA[{% if product_option_value.points_prefix == \'-\' %}]]>\n			</search>\n			<add position=\"before\">\n				<![CDATA[\n								  {% if product_option_value.points_prefix == \'=\' %}\n\n\n								<option value=\"=\" selected=\"selected\">=</option>\n\n\n								  {% else %}\n\n\n								<option value=\"=\">=</option>\n\n\n								  {% endif %}\n						]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<ignoreif regex=\"false\" info=\"for 3.0.x\"><![CDATA[<?php echo $header; ?>]]></ignoreif>\n			<search>\n				<![CDATA[{% if product_option_value.weight_prefix == \'-\' %}]]>\n			</search>\n			<add position=\"before\">\n				<![CDATA[\n								  {% if product_option_value.weight_prefix == \'=\' %}\n\n\n								<option value=\"=\" selected=\"selected\">=</option>\n\n\n								  {% else %}\n\n\n								<option value=\"=\">=</option>\n\n\n								  {% endif %}\n							]]>\n			</add>\n		</operation>\n\n		<operation error=\"log\">\n			<!-- <ignoreif regex=\"false\" info=\"for 3.0.x\"><![CDATA[<?php echo $header; ?>]]></ignoreif> -->\n			<search>\n				<![CDATA[<option value=\"+\">+</option>\';]]>\n			</search>\n			<add position=\"after\">\n				<![CDATA[  html += \'    <option value=\"=\">=</option>\';]]>\n			</add>\n		</operation>\n\n	</file>\n</modification>\n', 1, '2022-01-24 13:39:43'),
(16, 22, 'Default timezone for PHP and Database', 'timezone', 'Amit Dholiya', '1.0', '', '<?xml version=\'1.0\' encoding=\'utf-8\'?>\n<modification>\n  <name>Default timezone for PHP and Database</name>\n  <code>timezone</code>\n  <version>1.0</version>\n  <author>Amit Dholiya</author>\n  <link></link>\n\n  <file path=\"system/library/db.php\">\n    <operation>\n      <search regex=\"true\"><![CDATA[~(.*this->)(.*)(->query.*)~]]></search>\n      <add position=\"replace\"><![CDATA[\n//tri mod start\n$query = $this->$2->query(\"SELECT * FROM \" . DB_PREFIX . \"setting WHERE `code` = \'module_timezone\'\");\n\nif ($query->num_rows) {\n  $status = $timezone = 0;\n\n  foreach ($query->rows as $row) {\n    if ($row[\'key\'] == \'module_timezone_timezone\') $timezone = $row[\'value\'];\n    if ($row[\'key\'] == \'module_timezone_status\') $status = $row[\'value\'];\n  }\n\n  if ($status && $timezone) {\n    date_default_timezone_set($timezone);\n\n    $now = new DateTime();\n    $mins = $now->getOffset() / 60;\n    $sgn = ($mins < 0 ? -1 : 1);\n    $mins = abs($mins);\n    $hrs = floor($mins / 60);\n    $mins -= $hrs * 60;\n    $offset = sprintf(\'%+d:%02d\', $hrs * $sgn, $mins);\n    $this->$2->query(\"SET time_zone = \'\" . $offset . \"\'\");\n  }\n}\n//tri mod end\n$1$2$3\n      ]]></add>\n    </operation>\n  </file>\n</modification>\n', 1, '2022-01-24 13:40:32'),
(17, 23, 'Aramex Module', '#OFM07', 'Aramex team', '3.0.0.0', 'https://www.aramex.com/developers/', '<modification>\n	<name>Aramex Module</name>\n	<version>3.0.0.0</version>\n	<code>#OFM07</code>\n	<author>Aramex team</author>\n	<link>https://www.aramex.com/developers/</link>\n	<file path=\"system/library/template/twig.php\">\n		<operation>\n			<search ><![CDATA[$file = DIR_TEMPLATE . $filename . \'.twig\';]]></search>\n			<add position=\"replace\"><![CDATA[\n				$file = modification(DIR_TEMPLATE . $filename . \'.twig\');\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/controller/sale/order.php\">\n		<operation>\n			<search ><![CDATA[$data[\'invoice\'] = $this->url->link(\'sale/order/invoice\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&order_id=\' . (int)$this->request->get[\'order_id\'], true);]]></search>\n			<add position=\"after\"><![CDATA[$data[\'aramex_sipment\'] = $this->url->link(\'extension/shipping/aramex/aramex_create_shipment\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&order_id=\' . (int)$this->request->get[\'order_id\'], true);\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/view/template/sale/order_info.twig\">\n		<operation>\n			<search ><![CDATA[<ul class=\"breadcrumb\">]]></search>\n			<add position=\"before\"><![CDATA[\n				<div class=\"pull-right\" style=\"margin-right:5px;\"><a href= {{ aramex_sipment }}   class=\"btn btn-info\">Aramex Shipment</a></div>\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/controller/common/column_left.php\">\n		<operation>\n			<search ><![CDATA[if ($sale) {]]></search>\n			<add position=\"before\"><![CDATA[\n			$sale[] = array(\n					\'name\'	   => \"Aramex Bulk Schedule Pickup\",\n					\'href\'     => $this->url->link(\'extension/shipping/aramex/aramex_bulk_schedule_pickup\', \'user_token=\' . $this->session->data[\'user_token\'], true),\n                                        \'children\' => array()\n					 		\n				);\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/controller/account/order.php\">\n		<operation>\n			<search ><![CDATA[$data[\'histories\'] = array();]]></search>\n			<add position=\"after\"><![CDATA[\n										$this->load->model(\'extension/shipping/aramexmodel\');\n										$checkAWB = $this->model_extension_shipping_aramexmodel->checkAWB($this->request->get[\'order_id\']);\n										if($checkAWB)\n										{\n											$data[\'track_url\'] = $this->url->link(\'account/aramex_traking\', \'order_id=\' . $this->request->get[\'order_id\'], true);\n										}else{\n										$data[\'track_url\'] = \"\";\n										}\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/view/theme/*/template/account/order_info.twig\">\n		<operation>\n			<search ><![CDATA[<?php echo $text_history; ?>]]></search>\n			<add position=\"after\"><![CDATA[\n							{% if track_url  and  track_url is not empty\n									%}\n									<a href={{ track_url }} class=\"btn btn-primary\" >Track Aramex Shipments</a>\n							{% endif %}\n	\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/view/theme/*/template/checkout/register.twig\">\n		<operation>\n			<search ><![CDATA[<div class=\"row\">]]></search>\n			<add position=\"before\"><![CDATA[\n												{{ apilocationvalidator }}\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/view/theme/*/template/checkout/shipping_address.twig\">\n		<operation>\n			<search ><![CDATA[<form class=\"form-horizontal\">]]></search>\n			<add position=\"before\"><![CDATA[\n												{{ apilocationvalidator }}\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/view/theme/*/template/checkout/payment_address.twig\">\n		<operation>\n			<search ><![CDATA[<form class=\"form-horizontal\">]]></search>\n			<add position=\"before\"><![CDATA[\n												{{ apilocationvalidator }}\n			]]></add>\n		</operation>\n	</file>	\n		<file path=\"catalog/view/theme/*/template/common/header.twig\">\n		<operation>\n			<search ><![CDATA[<script src=\"catalog/view/javascript/bootstrap/js/bootstrap.min.js\" type=\"text/javascript\"></script>]]></search>\n			<add position=\"replace\"><![CDATA[	]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/view/theme/*/template/common/header.twig\">\n		<operation>\n			<search ><![CDATA[<script src=\"catalog/view/javascript/common.js\" type=\"text/javascript\"></script>]]></search>\n			<add position=\"after\"><![CDATA[\n			<script src=\"catalog/view/javascript/aramex/jqueryui/jquery-ui.js\" type=\"text/javascript\"></script>\n			<script src=\"catalog/view/javascript/bootstrap/js/bootstrap.min.js\" type=\"text/javascript\"></script>			\n			<link href=\"catalog/view/javascript/aramex/jqueryui/jquery-ui.css\" rel=\"stylesheet\">\n\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/controller/checkout/register.php\">\n		<operation>\n			<search ><![CDATA[$data[\'shipping_required\'] = $this->cart->hasShipping();]]></search>\n			<add position=\"after\"><![CDATA[\n                $data[\'apilocationvalidator\'] = $this->load->controller(\'extension/shipping/apilocationvalidator\');\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"catalog/controller/checkout/shipping_address.php\">\n		<operation>\n			<search ><![CDATA[$data[\'countries\'] = $this->model_localisation_country->getCountries();]]></search>\n			<add position=\"after\"><![CDATA[\n                $data[\'apilocationvalidator\'] = $this->load->controller(\'extension/shipping/apilocationvalidatorshipping\');\n			]]></add>\n		</operation>\n	</file>		\n	<file path=\"catalog/controller/checkout/payment_address.php\">\n		<operation>\n			<search ><![CDATA[$data[\'countries\'] = $this->model_localisation_country->getCountries();]]></search>\n			<add position=\"after\"><![CDATA[\n                $data[\'apilocationvalidator\'] = $this->load->controller(\'extension/shipping/apilocationvalidatorbilling\');\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/checkout/success.php\">\n		<operation>\n			<search ><![CDATA[$this->load->language(\'checkout/success\');]]></search>\n			<add position=\"after\"><![CDATA[\nif(isset($this->session->data[\'order_id\'])){\n                				if($this->config->get(\'shippping_aramex_auto_create_shipment\')==1 && $this->config->get(\'shipping_aramex_status\') ==1){\n\n								$this->load->model(\'extension/shipping/aramexmodel\');\n								$this->model_extension_shipping_aramexmodel->create($this->session->data[\'order_id\']);\n								}\n}\n			]]></add>\n		</operation>\n	</file>\n	\n	<file path=\"catalog/controller/product/product.php\">\n		<operation>\n			<search ><![CDATA[$data[\'description\'] = html_entity_decode($product_info[\'description\'], ENT_QUOTES, \'UTF-8\');]]></search>\n			<add position=\"after\"><![CDATA[\n                $data[\'aramexcalculator\'] = $this->load->controller(\'extension/shipping/aramexcalculator\');\n			]]></add>\n		</operation>\n	</file>		\n	<file path=\"catalog/view/theme/*/template/product/product.twig\">\n		<operation>\n			<search ><![CDATA[<div id=\"product\">]]></search>\n			<add position=\"before\"><![CDATA[\n												{{ aramexcalculator }}\n			]]></add>\n		</operation>\n	</file>		\n</modification>', 0, '2022-01-24 13:42:51'),
(18, 24, 'MyFatoorah', 'MyFatoorah', 'MyFatoorah Plugin Team', '2.0.0.2', 'https://myfatoorah.com/', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <code>MyFatoorah</code>\n    <name>MyFatoorah</name>\n    <version>2.0.0.2</version>\n    <author>MyFatoorah Plugin Team</author>\n    <link>https://myfatoorah.com/</link>\n    \n    <file path=\"catalog/controller/checkout/payment_method.php\">\n        <operation>\n            <search><![CDATA[\n					$method = $this->{\'model_extension_payment_\' . $result[\'code\']}->getMethod($this->session->data[\'payment_address\'], $total);\n            ]]></search>\n            <add position=\"replace\"><![CDATA[\n					if ( $this->session->data[\'shipping_method\'][\'code\'] == \'myfatoorah.dhl\' || $this->session->data[\'shipping_method\'][\'code\'] == \'myfatoorah.aramex\'){\n						if ($result[\'code\'] != \'myfatoorah_pg\' && $result[\'code\'] != \'myfatoorah_v2\' &&  $result[\'code\'] != \'myfatoorah_direct\' && $result[\'code\'] != \'myfatoorah_embedded\'){\n						    continue;\n						}\n					}\n					$method = $this->{\'model_extension_payment_\' . $result[\'code\']}->getMethod($this->session->data[\'payment_address\'], $total);\n					if (isset($method[\'error\'])) {\n						$payment_method_error[] = $method[\'error\'];\n						continue;\n		    			}\n            ]]></add>\n        </operation>\n        \n        <operation>\n            <search><![CDATA[\n			$data[\'error_warning\'] = \'\';\n            ]]></search>\n            <add position=\"replace\"><![CDATA[\n			$data[\'error_warning\'] = isset($payment_method_error) ? implode(\'<br>\', $payment_method_error) : \'\';\n            ]]></add>\n        </operation>\n    </file>\n</modification>\n', 1, '2022-01-24 13:43:04'),
(19, 25, 'Tap Payment', 'tap', 'Waqas Zeeshan', '2.0', '', '<modification>\n    <name>Tap Payment</name>\n    <code>tap</code>\n    <version>2.0</version>\n    <author>Waqas Zeeshan</author>\n</modification>\n', 1, '2022-01-24 13:43:17');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(20, 27, 'Hyperpay Mod - Add icon to payment_method', 'Hyperpay Mod', 'Hyperpay(https://www.hyperpay.com)', '3.x', 'https://www.hyperpay.com/', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n	<name>Hyperpay Mod - Add icon to payment_method</name>\n	<version>3.x</version>\n	<code>Hyperpay Mod</code>\n	<author>Hyperpay(https://www.hyperpay.com)</author>\n	<link>https://www.hyperpay.com/</link>\n\n\n   <file path=\"catalog/view/theme/*/template/checkout/payment_method.twig\">\n		<operation error=\"log\">\n			<search><![CDATA[{{ payment_method.title }}]]></search>\n			<add position=\"after\"><![CDATA[\n				{% if payment_method.icon %}\n                <img width=\"60\" height=\"30\" src=\"{{ payment_method.icon }}\" />\n                {% endif %}\n				]]></add>\n		</operation>\n	</file>\n\n <file path=\"system/library/template/twig.php\" error=\"skip\" info=\"fix Core Opencart twig files modification\">\n	 <operation>\n		 <search><![CDATA[$file = DIR_TEMPLATE . $filename . \'.twig\';]]></search>\n		 <add position=\"replace\"><![CDATA[$file = modification( DIR_TEMPLATE . $filename . \'.twig\' );\n		 if( class_exists(\'VQMod\') ) {\n			 $file = \\VQMod::modCheck($file);\n		 }\n		 ]]></add>\n	 </operation>\n </file>\n\n</modification>\n', 1, '2022-01-24 14:05:02'),
(21, 29, 'X-Shipping Pro', 'xshippingpro', 'OpenCartMart', '3.2.2', 'http://www.opencartmart.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <name>X-Shipping Pro</name>\n    <code>xshippingpro</code>\n    <version>3.2.2</version>\n    <author>OpenCartMart</author>\n    <link>http://www.opencartmart.com</link>\n    <file path=\"catalog/controller/extension/module/xtensions/checkout/xfooter.php\">\n        <operation error=\"skip\">\n            <search><![CDATA[ $this->load->model(\'catalog/information\'); ]]></search>\n            <add position=\"before\"><![CDATA[\n                  $ocm = ($ocm = $this->registry->get(\'ocm_front\')) ? $ocm : new OCM\\Front($this->registry);\n                  $data[\'_ocm_script\'] = $ocm->getScript();\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/view/theme/*/template/extension/module/xtensions/checkout/xfooter.twig\">\n      <operation error=\"skip\">\n        <search><![CDATA[ </body> ]]></search>\n        <add position=\"before\"><![CDATA[\n            {{ _ocm_script }}\n        ]]></add>\n      </operation>\n   </file>\n       <file path=\"catalog/controller/common/footer.php\">\n        <operation error=\"log\">\n            <ignoreif regex=\"true\"><![CDATA[ /ocm->getScript/ ]]></ignoreif>\n            <search index=\"0\"><![CDATA[ $this->load->model(\'catalog/information\'); ]]></search>\n            <add position=\"before\"><![CDATA[\n                  $ocm = ($ocm = $this->registry->get(\'ocm_front\')) ? $ocm : new OCM\\Front($this->registry);\n                  $data[\'_ocm_script\'] = $ocm->getScript();\n            ]]></add>\n        </operation>\n    </file>\n   <!--  d_twig taints OC 2.x tpl with twig  -->\n   <file path=\"catalog/view/theme/*/template/common/footer.twi*\">\n      <operation>\n        <ignoreif regex=\"true\"><![CDATA[ /_ocm_script/ ]]></ignoreif>\n        <search><![CDATA[ </body> ]]></search>\n        <add position=\"before\"><![CDATA[\n            {{_ocm_script}}\n        ]]></add>\n      </operation>\n   </file>\n</modification>', 1, '2022-01-24 14:30:07'),
(22, 30, 'Product Quick View', 'md_product_quick_view', 'MagDevel', '1.5.0 (OC 3.0)', 'https://magdevel.com', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<modification>\n<name>Product Quick View</name>\n<version>1.5.0 (OC 3.0)</version>\n<author>MagDevel</author>\n<link>https://magdevel.com</link>\n<code>md_product_quick_view</code>\n\n\n<file path=\"catalog/controller/common/header.php\">\n<operation>\n<search><![CDATA[$data[\'styles\'] = $this->document->getStyles();]]></search>\n<add position=\"before\" error=\"skip\"><![CDATA[\n        // Product Quick View BEGIN\n        $data[\'pqv_status\'] = $this->config->get(\'module_product_quick_view_status\');\n        if ($data[\'pqv_status\']) {\n            $pqv_data = $this->load->controller(\'extension/module/product_quick_view\');\n            $pqv_data = str_replace(array(\"\\r\", \"\\n\"), \"\", $pqv_data);\n            $data[\'pqv_data\'] = preg_replace(\'/\\s\\s+/\', \'\', $pqv_data);\n        }\n        // Product Quick View END\n]]></add>\n</operation>\n</file>\n\n\n<file path=\"catalog/view/theme/*/template/common/header.twig\">\n<operation>\n<search><![CDATA[</head>]]></search>\n<add position=\"before\"><![CDATA[\n{% if (pqv_status) %} \n<!-- Product Quick View BEGIN -->\n{{ pqv_data }}\n<!-- Product Quick View END -->\n{% endif %}\n]]></add>\n</operation>\n</file>\n\n\n<file path=\"catalog/model/catalog/product.php\">\n<operation>\n<search><![CDATA[\'weight\'                  => $product_option_value[\'weight\'],]]></search>\n<add position=\"before\"><![CDATA[\n        \'points\'        => $product_option_value[\'points\'],\n        \'points_prefix\' => $product_option_value[\'points_prefix\'],\n]]></add>\n</operation>\n</file>\n\n\n<file path=\"catalog/view/theme/*/template/product/*.twig\">\n<operation>\n<search><![CDATA[<div class=\"image\">]]></search>\n<add position=\"before\"><![CDATA[\n        {% if (product and product.product_id) %}\n        <div class=\"product-quick-view-data\" data-pid=\"{{ product.product_id }}\"></div>\n        {% endif %}\n]]></add>\n</operation>\n</file>\n\n\n<file path=\"catalog/view/theme/*/template/extension/module/*.twig\">\n<operation>\n<search><![CDATA[<div class=\"image\">]]></search>\n<add position=\"before\"><![CDATA[\n        {% if (product and product.product_id) %}\n        <div class=\"product-quick-view-data\" data-pid=\"{{ product.product_id }}\"></div>\n        {% endif %}\n]]></add>\n</operation>\n</file>\n\n</modification>\n', 1, '2022-03-26 03:01:52'),
(24, 0, 'd_twig_manager', 'd_twig_manager', 'Dreamvention', '2.0.0', 'http://dreamvention.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <name>d_twig_manager</name>\n    <code>d_twig_manager</code>\n    <description>Adds support for twig templating engine</description>\n    <version>2.0.0</version>\n    <author>Dreamvention</author>\n    <link>http://dreamvention.com</link>\n    <file path=\"system/engine/loader.php\">\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[$template = new Template($this->registry->get(\'config\')->get(\'template_engine\'));]]></search>\n            <add position=\"replace\"><![CDATA[\n            //d_twig_manager.xml\n            $template = new Template($this->registry->get(\'config\')->get(\'template_engine\'), $this->registry);\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"system/library/template.php\">\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[public function __construct($adaptor) {]]></search>\n            <add position=\"replace\"><![CDATA[\n            //d_twig_manager.xml\n            public function __construct($adaptor, $registry) {\n            ]]></add>\n        </operation>\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[$this->adaptor = new $class();]]></search>\n            <add position=\"replace\"><![CDATA[\n            //d_twig_manager.xml\n            $this->adaptor = new $class($registry);\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"system/library/template/twig.php\">\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[private $data = array();]]></search>\n            <add position=\"after\"><![CDATA[\n            //d_twig_manager.xml\n            private $registry = array();\n            ]]></add>\n        </operation>\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[public function __construct() {]]></search>\n            <add position=\"replace\"><![CDATA[\n            //d_twig_manager.xml\n            public function __construct($registry) {\n            ]]></add>\n        </operation>\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[\\Twig_Autoloader::register();]]></search>\n            <add position=\"after\"><![CDATA[\n            //d_twig_manager.xml\n            $this->registry = $registry;\n            ]]></add>\n        </operation>\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[$this->twig = new \\Twig_Environment($loader, $config);]]></search>\n            <add position=\"after\"><![CDATA[\n            //d_twig_manager.xml\n            if (file_exists(DIR_SYSTEM . \'library/template/Twig/Extension/DTwigManager.php\')) {\n                $this->twig->addExtension(new \\Twig_Extension_DTwigManager($this->registry));\n            }\n            ]]></add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/event/theme.php\">\n        <operation error=\"skip\" info=\"\">\n            <search><![CDATA[$twig = new \\Twig_Environment($loader, $config);]]></search>\n            <add position=\"after\"><![CDATA[\n            //d_twig_manager.xml\n            if (file_exists(DIR_SYSTEM . \'library/template/Twig/Extension/DTwigManager.php\')) {\n                $twig->addExtension(new Twig_Extension_DTwigManager($this->registry));\n            }\n            ]]></add>\n        </operation>\n    </file>\n</modification>', 1, '2022-03-26 04:58:04');
INSERT INTO `oc_module` (`module_id`, `name`, `code`, `setting`) VALUES
(28, 'منتجات مميزة - صفحة البداية', 'featured', '{\"name\":\"منتجات مميزة - صفحة البداية\",\"product\":[\"43\",\"40\",\"42\",\"30\"],\"limit\":\"4\",\"width\":\"200\",\"height\":\"200\",\"status\":\"1\"}'),
(27, 'سلايد شو - صفحة البداية', 'slideshow', '{\"name\":\"\\u0633\\u0644\\u0627\\u064a\\u062f \\u0634\\u0648 - \\u0635\\u0641\\u062d\\u0629 \\u0627\\u0644\\u0628\\u062f\\u0627\\u064a\\u0629\",\"banner_id\":\"7\",\"width\":\"1440\",\"height\":\"500\",\"status\":\"1\"}'),
(32, ' ليك خصم 200 ريال لما تشترى ب 500 ريال', 'productcategory', '{\"name\":\" \\u0644\\u064a\\u0643 \\u062e\\u0635\\u0645 200 \\u0631\\u064a\\u0627\\u0644 \\u0644\\u0645\\u0627 \\u062a\\u0634\\u062a\\u0631\\u0649 \\u0628 500 \\u0631\\u064a\\u0627\\u0644\",\"category\":[\"75\"],\"limit\":\"8\",\"width\":\"260\",\"height\":\"260\",\"status\":\"1\"}'),
(33, 'وسائل الدفع', 'newbanner', '{\"name\":\"\\u0648\\u0633\\u0627\\u0626\\u0644 \\u0627\\u0644\\u062f\\u0641\\u0639\",\"banner_id\":\"14\",\"width\":\"41\",\"height\":\"23\",\"status\":\"1\"}'),
