INSERT INTO `oc_product_description` (`product_id`, `language_id`, `name`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(1, 2, 'اسم المنتج', 'يمكن عرض وصف المنتج ، جنبًا إلى جنب مع أي علامة تبويب أخرى كعلامات تبويب أو أكورديون أو كتل مرئية بالكامل بتنسيق الشبكة أو واحدة تحت الأخرى. يمكنك مزج ومطابقة علامات التبويب والكتل بأي ترتيب وفي أي موضع. يمكن أيضًا إعداد كل علامة تبويب كارتباط والإشارة إلى صفحات أخرى أو فتح وحدات منبثقة. يتوفر أيضًا محتوى الكتلة القابل للطي الاختياري &quot;إظهار المزيد&quot; كخيار للأوصاف الكبيرة والطويلة أو المحتوى المخصص.', '', 'اسم المنتج', '', ''),
(2, 2, 'اسم المنتج', '&lt;p&gt;يمكن عرض وصف المنتج ، جنبًا إلى جنب مع أي علامة تبويب أخرى كعلامات تبويب أو أكورديون أو كتل مرئية بالكامل بتنسيق الشبكة أو واحدة تحت الأخرى. يمكنك مزج ومطابقة علامات التبويب والكتل بأي ترتيب وفي أي موضع. يمكن أيضًا إعداد كل علامة تبويب كارتباط والإشارة إلى صفحات أخرى أو فتح وحدات منبثقة. يتوفر أيضًا محتوى الكتلة القابل للطي الاختياري &quot;إظهار المزيد&quot; كخيار للأوصاف الكبيرة والطويلة أو المحتوى المخصص.&lt;br&gt;&lt;/p&gt;', '', 'اسم المنتج', '', ''),
